INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hyperlane-xyz/hyperlane-monorepo/investigate-stuck-messages', 'community', 'hyperlane-xyz', 'hyperlane-monorepo', 'hyperlane-xyz/hyperlane-monorepo', 'investigate-stuck-messages', 0, 0, 60, '2026-03-08T01:57:15.309Z', '2026-03-08T02:02:27.200Z', '2c12df2a52c8e020ad99cdfaefec86e0ac9350f10fcb85d864b7115700fede26', '{"id":"hyperlane-xyz/hyperlane-monorepo/investigate-stuck-messages","name":"investigate-stuck-messages","description":{"en":"The investigate-stuck-messages skill queries the relayer API to investigate stuck messages, their retry counts, and error reasons, benefiting developers and users alike.","zh":"investigate-stuck-messages 技能用于调查卡住的消息，包括重试次数和错误原因。它可以帮助开发者解决应用程序上下文中的消息问题","ja":"investigate-stuck-messages スキルは、スタックしたメッセージを調査し、リトライ回数とエラー理由を提供します。開発者は、アプリケーションのコンテキストでメッセージの問題を解決できます","ko":"investigate-stuck-messages 기능은 메시지 문제를 조사하고 재시도 횟수 및 오류 이유를 제공합니다. 개발자는 애플리케이션 컨텍스트에서 메시지 문제를 해결할 수 있습니다","es":"Investiga mensajes atascados con Hyperlane. Esta habilidad utiliza la API de relayer para investigar mensajes atascados, contar reintentos y razones de error.","fr":"Investigue les messages bloqués avec Hyperlane. Cette compétence utilise l''API de relayer pour investiguer les messages bloqués, compter les réessais et les raisons d''erreur.","de":"Untersuchen Sie feststeckende Nachrichten mit Hyperlane. Diese Fähigkeit verwendet die Relayer-API, um feststeckende Nachrichten, Wiederholungszähler und Fehlergründe zu untersuchen.","pt":"Investigue mensagens presas com a API do relayer e descubra as razões de erro e contagens de retry para melhorar a entrega de mensagens","ru":"Расследуйте заблокированные сообщения с помощью API релейера и узнайте причины ошибок и счетчики повторных попыток для улучшения доставки сообщений","ar":"تحقق من الرسائل العالقة باستخدام واجهة برمجة التطبيقات للراسل واكتشف أسباب الأخطاء وعوائد المحاولات لتحسين تسليم الرسائل"},"seo":{"title":{"en":"investigate-stuck-messages: Query Relayer API for Stuck M...","zh":"investigate-stuck-messages 故障排除指南","ja":"investigate-stuck-messages のトラブルシューティングガイド","ko":"investigate-stuck-messages 문제 해결 설정 가이드","es":"Guía de configuración para investigar mensajes atascados ...","fr":"Guide de configuration pour investiguer les messages bloq...","de":"Einrichtungsanleitung für die Untersuchung von feststecke...","pt":"Guia de Configuração para Investigar Mensagens Presas com...","ru":"Настройка ИИ Агентов для Расследования Заблокированных Со...","ar":"دليل إعداد أدوات الذكاء الاصطناعي لتحقيق الرسائل العالقة"},"description":{"en":"Get to the bottom of stuck messages with investigate-stuck-messages. Query relayer API, retry counts, and error reasons. Learn how to use it now!","zh":"了解 investigate-stuck-messages 技能，查询 relayer API 以调查卡住的消息、重试次数和错误原因","ja":"investigate-stuck-messages スキルを使用して、リレーヤー API を照会し、スタックしたメッセージ、リトライ回数、エラー理由を調査します","ko":"investigate-stuck-messages 기능을 사용하여 릴레이어 API를 쿼리하여 메시지 문제, 재시도 횟수 및 오류 이유를 조사합니다","es":"Aprende a investigar mensajes atascados con Hyperlane. Consulta nuestra guía para solucionar problemas de mensajería","fr":"Découvrez comment investiguer les messages bloqués avec Hyperlane. Consultez notre guide pour résoudre les problèmes de messagerie","de":"Erfahren Sie, wie Sie feststeckende Nachrichten mit Hyperlane untersuchen. Lesen Sie unsere Anleitung, um Probleme mit der Nachrichtenübermittlung zu beheben","pt":"Aprenda a investigar mensagens presas com a API do relayer e descubra as razões de erro e contagens de retry","ru":"Узнайте, как расследовать заблокированные сообщения с помощью API релейера и узнайте причины ошибок и счетчики повторных попыток","ar":"تعلم كيفية تحقيق الرسائل العالقة باستخدام واجهة برمجة التطبيقات للراسل واكتشف أسباب الأخطاء وعوائد المحاولات"},"definition":{"en":"investigate-stuck-messages is a skill that enables querying the relayer API to diagnose and 