INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hyperlane-xyz/hyperlane-monorepo/investigate-stuck-messages', 'investigate-stuck-messages', 'hyperlane-xyz', 'hyperlane-monorepo', 'community', 'investigate-stuck-messages hyperlane-xyz hyperlane-monorepo community The investigate-stuck-messages skill queries the relayer API to investigate stuck messages, their retry counts, and error reasons, benefiting developers and users alike. investigate-stuck-messages 技能用于调查卡住的消息，包括重试次数和错误原因。它可以帮助开发者解决应用程序上下文中的消息问题 investigate-stuck-messages スキルは、スタックしたメッセージを調査し、リトライ回数とエラー理由を提供します。開発者は、アプリケーションのコンテキストでメッセージの問題を解決できます investigate-stuck-messages 기능은 메시지 문제를 조사하고 재시도 횟수 및 오류 이유를 제공합니다. 개발자는 애플리케이션 컨텍스트에서 메시지 문제를 해결할 수 있습니다 Investiga mensajes atascados con Hyperlane. Esta habilidad utiliza la API de relayer para investigar mensajes atascados, contar reintentos y razones de error. Investigue les messages bloqués avec Hyperlane. Cette compétence utilise l''API de relayer pour investiguer les messages bloqués, compter les réessais et les raisons d''erreur. Untersuchen Sie feststeckende Nachrichten mit Hyperlane. Diese Fähigkeit verwendet die Relayer-API, um feststeckende Nachrichten, Wiederholungszähler und Fehlergründe zu untersuchen. Investigue mensagens presas com a API do relayer e descubra as razões de erro e contagens de retry para melhorar a entrega de mensagens Расследуйте заблокированные сообщения с помощью API релейера и узнайте причины ошибок и счетчики повторных попыток для улучшения доставки сообщений تحقق من الرسائل العالقة باستخدام واجهة برمجة التطبيقات للراسل واكتشف أسباب الأخطاء وعوائد المحاولات لتحسين تسليم الرسائل how to use investigate-stuck-messages investigate-stuck-messages setup guide relayer API query for stuck messages investigate-stuck-messages vs traditional debugging methods investigate-stuck-messages install for AI agents what is investigate-stuck-messages investigate-stuck-messages alternative for message queue debugging investigate-stuck-messages for Hyperlane core contracts debugging stuck messages with investigate-stuck-messages investigate-stuck-messages relayer API 卡住的消息 重试次数 错误原因 AI工具 故障排除 Queries relayer API to investigate stuck messages Provides retry counts and error reasons for stuck messages Supports alert-based triggers for known app context relayer queue length Handles user request triggers for specific app contexts or chains Delivers insights into stuck messages, including queue length and retry counts investigate-stuck-messages is a skill that enables querying the relayer API to diagnose and resolve stuck messages, providing insights into retry counts and error reasons.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yoloshii/mcp-code-execution-enhanced/simple-fetch', 'community', 'yoloshii', 'mcp-code-execution-enhanced', 'yoloshii/mcp-code-execution-enhanced', 'simple-fetch', 0, 0, 60, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:27.993Z', '8bbbb60d9783b4d11a232447d7d7f38843f5f44494eb8b3b2b7365f90460c808', '{"id":"yoloshii/mcp-code-execution-enhanced/simple-fetch","name":"simple-fetch","description":{"en":"The simple-fetch skill demonstrates the minimal CLI-based pattern for fetching content from a URL, benefiting developers who need to create custom skills for AI agents.","zh":"Simple Fetch技能是一种框架无关的MCP代码执行技能，提供99.6%的令牌减少和多种传输方式","ja":"Simple Fetchスキルは、AIエージェントを使用したコンテンツ取得を最適化するためのフレームワーク無関係のMCPコード実行スキルです","ko":"Simple Fetch Skill은 프레임워크 독립형 MCP 코드 실행 기술로 99.6%의 토큰 감소와 여러 전송 방식을 제공합니다","es":"Simple-fetch es un patrón de habilidad básico para fetch de contenido de URL con MCP y CLI","fr":"Simple-fetch est un modèle de compétence de base pour la récupération de contenu à partir d''une URL avec MCP et CLI","de":"Simple-fetch ist ein grundlegendes Skill-Muster für das Abrufen von Inhalten aus einer URL mit MCP und CLI","pt":"O Simple Fetch é uma ferramenta de extração de conteúdo que demonstra o padrão de habilidade mínimo baseado em CLI. Ele aceita argumentos de linha de comando e retorna resultados.","ru":"ИИ Агент Simple Fetch - это инструмент для извлечения контента, демонстрирующий минимальный шаблон навыка на основе CLI. Он принимает аргументы командной строки и возвращает результаты.","ar":"العميل البسيط للحصول على المحتوى هو أداة لاستخراج المحتوى التي تظهر النمط الأدنى للمهارة المستندة إلى سطر الأوامر. يقبل الحجج سطر الأوامر وي返ي النتائج"},"seo":{"title":{"en":"simple-fetch: CLI-based Skill Setup Guide | AI Agent Skill","zh":"简单抓取（Simple Fetch）技能：AI工具快速集成指南","ja":"Simple Fetchスキル：AIエージェントを使用したコンテンツ取得ベストプラクティス",