INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yoloshii/mcp-code-execution-enhanced/simple-fetch', 'simple-fetch', 'yoloshii', 'mcp-code-execution-enhanced', 'community', 'simple-fetch yoloshii mcp-code-execution-enhanced community The simple-fetch skill demonstrates the minimal CLI-based pattern for fetching content from a URL, benefiting developers who need to create custom skills for AI agents. Simple Fetch技能是一种框架无关的MCP代码执行技能，提供99.6%的令牌减少和多种传输方式 Simple Fetchスキルは、AIエージェントを使用したコンテンツ取得を最適化するためのフレームワーク無関係のMCPコード実行スキルです Simple Fetch Skill은 프레임워크 독립형 MCP 코드 실행 기술로 99.6%의 토큰 감소와 여러 전송 방식을 제공합니다 Simple-fetch es un patrón de habilidad básico para fetch de contenido de URL con MCP y CLI Simple-fetch est un modèle de compétence de base pour la récupération de contenu à partir d''une URL avec MCP et CLI Simple-fetch ist ein grundlegendes Skill-Muster für das Abrufen von Inhalten aus einer URL mit MCP und CLI O Simple Fetch é uma ferramenta de extração de conteúdo que demonstra o padrão de habilidade mínimo baseado em CLI. Ele aceita argumentos de linha de comando e retorna resultados. ИИ Агент Simple Fetch - это инструмент для извлечения контента, демонстрирующий минимальный шаблон навыка на основе CLI. Он принимает аргументы командной строки и возвращает результаты. العميل البسيط للحصول على المحتوى هو أداة لاستخراج المحتوى التي تظهر النمط الأدنى للمهارة المستندة إلى سطر الأوامر. يقبل الحجج سطر الأوامر وي返ي النتائج how to use simple-fetch simple-fetch setup guide what is simple-fetch simple-fetch alternative simple-fetch vs Claude Code simple-fetch install simple-fetch CLI arguments MCP tool fetch__fetch custom skill creation with simple-fetch Simple Fetch技能 AI工具 MCP代码执行 令牌减少 多种传输方式 沙箱化 CLI参数 Accepts CLI arguments (--url) for customizable fetching Calls the MCP tool (fetch__fetch) for content retrieval Returns the result of the fetch operation Serves as a template for creating custom skills Optimized for Claude Code and framework-agnostic simple-fetch is a demonstration skill that shows the basic skill pattern for fetching content from a URL using CLI arguments and MCP tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('matteocervelli/llms/tech-stack-evaluator', 'community', 'matteocervelli', 'llms', 'matteocervelli/llms', 'tech-stack-evaluator', 0, 0, 60, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:30.432Z', '1e5f304e6a3adf61b4c4196db9504b0b4bcd205a259d497b247b877650c36c1e', '{"id":"matteocervelli/llms/tech-stack-evaluator","name":"tech-stack-evaluator","description":{"en":"The tech-stack-evaluator skill provides systematic evaluation of technical stack requirements and compatibility for feature implementations, benefiting developers and project managers.","zh":"tech-stack-evaluator是一种技术栈评估工具，提供系统化的技术栈要求和兼容性评估。它分析现有的项目技术，推荐合适的库和框架，并评估性能影响","ja":"tech-stack-evaluatorはテクニカルスタック評価ツールであり、テクニカルスタックの要件と互換性を体系的に評価します。既存のプロジェクト技術を分析し、適切なライブラリやフレームワークを推奨し、パフォーマンスの影響を評価します","ko":"tech-stack-evaluator는 기술 스택 평가 도구로, 기술 스택 요구 사항과 호환성을 체계적으로 평가합니다. 기존 프로젝트 기술을 분석하여 적합한 라이브러리 및 프레임워크를 추천하고 성능 영향도를 평가합니다","es":"tech-stack-evaluator es una herramienta de evaluación de pilas tecnológicas que analiza la compatibilidad y recomienda bibliotecas y frameworks adecuados para tus proyectos","fr":"tech-stack-evaluator est un outil d''évaluation de stacks technologiques qui analyse la compatibilité et recommande des bibliothèques et des frameworks adaptés à vos projets","de":"tech-stack-evaluator ist ein Tool zur Bewertung von Technologie-Stacks, das die Kompatibilität analysiert und geeignete Bibliotheken und Frameworks für Ihre Projekte empfiehlt","pt":"O tech-stack-evaluator é uma ferramenta de avaliação de pilha tecnológica que analisa requisitos e compatibilidade.","ru":"ИИ Агент tech-stack-evaluator является инструментом для оценки технологического стека, анализирующим требования и совместимость.","ar":"tech-stack-evaluator هو أداة لتقييم حزمة التكنولوجيا التي تحلل المتطلبات والتوافق"},"seo":{"title":{"en":"tech-stack-evaluator: Technical Compatibility Setup Guide...","zh":"tech-stack-evaluator 技术栈评估工具配置指南","ja":"tech-stack-evaluator AIエージェントのテクニカルスタック評価セットアップガイド","ko":"tech-stack-evaluator 기술 스택 평가 도구 설정 가이드","es":"Guía de Configuración de tech-stack-evaluator para Evalua...","fr":"Guide de Configuration de tech-stack-evaluator pour l''Éva...","de":"Konfigurationsleitfaden für tech-stack-evaluator zur Bewe...","pt":"Guia de Configuração do tech-stack-evaluator para Avaliaç...","ru":"Настройка ИИ Агента tech-stack-evaluator для Оценки Техно...","ar":"دليل إعداد تقييم حزمة التكنولوجيا مع tech-stack-evaluator"},"description":{"en":"Discover how to evaluate technical stack requirements with tech-stack-evaluator. Learn to assess compatibility and recommend frameworks - get started now!","zh":"了解tech-stack-evaluator的功能和特点，发现如何评估技术栈要求和兼容性，以及推荐合适的库和框架","ja":"tech-stack-evaluator AIエージェントの機能と特徴を紹介。テクニカルスタックの要件と互換性を評価し、適切なライブラリやフレームワークを推奨します","ko":"tech-stack-evaluator 기술 스택 평가 도구의 기능과 특징을 소개합니다. 기술 스택 요구 사항과 호환성을 평가하고 적합한 라이브러리 및 프레임워크를 추천합니다","es":"Aprende a evaluar y optimizar tus pilas tecnológicas con tech-stack-evaluator, una herramienta de evaluación de compatibilidad y recomendación de bibliotecas...","fr":"Découvrez comment évaluer et optimiser vos stacks technologiques avec tech-stack-evaluator, un outil d''évaluation de la compatibilité et de recommandation de...","de":"Erfahren Sie, wie Sie Ihre Technologie-Stacks mit tech-stack-evaluator bewerten und optimieren können, einem Tool zur Bewertung der Kompatibilität und Empfeh...","pt":"Aprenda a configurar o tech-stack-evaluator para avaliar requisitos de pilha tecnológica e garantir compatibilidade e desempenho.","ru":"Узнайте, как настроить ИИ Агент tech-stack-evaluator для оценки требований технологического стека и обеспечения совместимости и производительности.","ar":"تعرف على كيفية إعداد تقييم حزمة التكنولوجيا باستخدام tech-stack-evaluator لضمان التوافق والأداء"},"definition":{"en":"tech-stack-evaluator is a centralized LLM configuration and documentation management system for building skills and managing MCP servers with multi-LLM support.","zh":"tech-stack-evaluator是一种用于评估技术栈要求和兼容性的工具","ja":"tech-stack-evaluatorはテクニカルスタックの要件と互換性を評価するためのツールです","ko":"tech-stack-evaluator는 기술 스택 요구 사항과 호환성을 평가하기 위한 도구입니다","es":"tech-stack-evaluator es una herramienta de evaluación de pilas tecnológicas que ayuda a los desarrolladores a evaluar y optimizar sus tecnologías","fr":"tech-stack-evaluator est un outil d''évaluation de stacks technologiques qui aide les développeurs à évaluer et optimiser leurs technologies","de":"tech-stack-evaluator ist ein Tool zur Bewertung von Technologie-Stacks, das Entwicklern hilft, ihre Technologien zu bewerten und zu optimieren","pt":"O que é tech-stack-evaluator? Uma ferramenta de avaliação de pilha tecnológica para projetos.","ru":"Что такое ИИ Агент tech-stack-evaluator? Инструмент для оценки технологического стека проектов.","ar":"ما هو tech-stack-evaluator؟ أداة لتقييم حزمة التكنولوجيا لمشاريع"},"features":{"en":["Analyzes existing project technology for compatibility","Recommends appropriate libraries and frameworks","Assesses performance implications of technical stack choices","Supports multi-LLM configuration including Claude Code, Codex, and OpenCode","Auto-activates for technical stack evaluations and recommendations","Manages MCP servers for efficient skill and command execution"],"zh":["支持多LLM（Claude Code、Codex、OpenCode）","提供技术栈要求和兼容性评估","推荐合适的库和框架","评估性能影响","支持MCP服务器管理"],"ja":["複数のLLM（Claude Code、Codex、OpenCode）をサポート","テクニカルスタックの要件と互換性を評価","適切なライブラリやフレームワークを推奨","パフォーマンスの影響を評価","MCPサーバーの管理をサポート"],"ko":["다중 LLM（Claude Code、Codex、OpenCode） 지원","기술 스택 요구 사항과 호환성을 평가","적합한 라이브러리 및 프레임워크 추천","성능 영향도 평가","MCP 서버 관리 지원"],"es":["Evaluación de la compatibilidad de pilas tecnológicas","Recomendación de bibliotecas y frameworks adecuados","Análisis de implicaciones de rendimiento","Soporte para múltiples LLM (Claude Code, Codex, OpenCode)","Gestión centralizada de configuraciones y documentación"],"fr":["Évaluation de la compatibilité des stacks technologiques","Recommandation de bibliothèques et de frameworks adaptés","Analyse des implications de performances","Prise en charge de plusieurs LLM (Claude Code, Codex, OpenCode)","Gestion centralisée des configurations et de la documentation"],"de":["Bewertung der Kompatibilität von Technologie-Stacks","Empfehlung von geeigneten Bibliotheken und Frameworks","Analyse der Leistungsimplikationen","Unterstützung für mehrere LLM (Claude Code, Codex, OpenCode)","Zentrale Verwaltung von Konfigurationen und Dokumentation"],"pt":["Avaliação de requisitos de pilha tecnológica","Análise de compatibilidade de tecnologias","Recomendação de bibliotecas e frameworks","Avaliação de implicações de desempenho","Suporte a múltiplos LLM (Claude Code, Codex, OpenCode)"],"ru":["Оценка требований технологического стека","Анализ совместимости технологий","Рекомендация библиотек и фреймворков","Оценка влияния на производительность","Поддержка нескольких LLM (Claude Code, Codex, OpenCode)"],"ar":["تقييم متطلبات حزمة التكنولوجيا","تحليل التوافق التكنولوجي","توصية بالمكتبات والإطارات","تقييم الآثار على الأداء","دعم متعدد LLM (Claude Code, Codex, OpenCode)"]},"keywords":{"en":["how to use tech-stack-evaluator","tech-stack-evaluator setup guide","what is tech-stack-evaluator","tech-stack-evaluator alternative","tech-stack-evaluator vs Claude Code","tech-stack-evaluator install","multi-LLM support","MCP server management","technical stack compatibility"],"zh":["tech-stack-evaluator","技术栈评估","LLM配置","MCP服务器管理","库和框架推荐","性能影响评估","AI工具","技术栈要求"],"ja":["tech-stack-evaluator","テクニカルスタック評価","LLM設定","MCPサーバー管理","ライブラリやフレームワークの推奨","パフォーマンスの影響評価","AIエージェント","テクニカルスタックの要件"],"ko":["tech-stack-evaluator","기술 스택 평가","LLM 설정","MCP 서버 관리","라이브러리 및 프레임워크 추천","성능 영향도 평가","AI 도구","기술 스택 요구 사항"],"es":["evaluación de pilas tecnológicas","recomendación de bibliotecas","análisis de compatibilidad","optimización de rendimiento","herramientas de desarrollo","tech-stack-evaluator","IA Agentes","desarrollo de software"],"fr":["évaluation de stacks technologiques","recommandation de bibliothèques","analyse de compatibilité","optimisation de performances","outils de développement","tech-stack-evaluator","Agents IA","développement de logiciels"],"de":["Bewertung von Technologie-Stacks","Empfehlung von Bibliotheken","Analyse der Kompatibilität","Optimierung der Leistung","Entwicklungstools","tech-stack-evaluator","KI-Agents","Software-Entwicklung"],"pt":["tech-stack-evaluator","avaliação de pilha tecnológica","compatibilidade de tecnologias","recomendação de bibliotecas","desempenho de projetos","LLM","Claude Code","Codex","OpenCode"],"ru":["ИИ Агент tech-stack-evaluator","оценка технологического стека","совместимость технологий","рекомендация библиотек","производительность проектов","LLM","Claude Code","Codex","OpenCode"],"ar":["tech-stack-evaluator","تقييم حزمة التكنولوجيا","التوافق التكنولوجي","توصية بالمكتبات","أداء المشاريع","LLM","كلود كود","كودكس","أوبن كود"]}},"owner":"matteocervelli","repo":"llms","repoPath":"matteocervelli/llms","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"tech-stack-evaluator","description":"Auto-activates during requirements analysis to evaluate technical stack","bodyPreview":"## Purpose\n\nThe **tech-stack-evaluator** skill provides systematic evaluation of technical stack requirements and compatibility for feature implementations. It analyzes existing project technology, recommends appropriate libraries/frameworks, assesses compatibility, and identifies performance implications.\n\n## When to Use\n\nThis skill auto-activates when you:\n- Evaluate technical stack requirements\n- Assess technology compatibility\n- Recommend frameworks or libraries\n- Analyze performance implica","body":"## Purpose\n\nThe **tech-stack-evaluator** skill provides systematic evaluation of technical stack requirements and compatibility for feature implementations. It analyzes existing project technology, recommends appropriate libraries/frameworks, assesses compatibility, and identifies performance implications.\n\n## When to Use\n\nThis skill auto-activates when you:\n- Evaluate technical stack requirements\n- Assess technology compatibility\n- Recommend frameworks or libraries\n- Analyze performance implications\n- Check language/framework suitability\n- Review dependency compatibility\n- Evaluate migration needs\n- Assess scalability of technology choices\n\n## Provided Capabilities\n\n### 1. Technology Stack Analysis\n- Identify current project stack (language, framework, libraries)\n- Evaluate stack maturity and support\n- Check version compatibility\n- Assess ecosystem health\n\n### 2. Library/Framework Recommendation\n- Recommend appropriate libraries for requirements\n- Compare alternatives\n- Evaluate pros/cons\n- Check community support and maintenance\n\n### 3. Compatibility Assessment\n- Check compatibility with existing stack\n- Identify version conflicts\n- Assess breaking changes\n- Evaluate upgrade paths\n\n### 4. Performance Analysis\n- Evaluate performance characteristics\n- Identify bottlenecks\n- Assess scalability\n- Consider resource requirements\n\n### 5. Technology Constraints\n- Identify platform limitations\n- Check deployment constraints\n- Assess infrastructure requirements\n- Evaluate licensing constraints\n\n## Usage Guide\n\n### Step 1: Identify Current Project Stack\n\nCheck project configuration files:\n\n**Python Projects**:\n```bash\n# Check Python version and dependencies\npython --version\ncat requirements.txt\ncat pyproject.toml\ncat setup.py\ncat Pipfile\n\n# Check installed packages\npip list\n```\n\n**TypeScript/JavaScript Projects**:\n```bash\n# Check Node version and dependencies\nnode --version\ncat package.json\ncat package-lock.json\ncat yarn.lock\n```\n\n**Rust Projects**:\n```bash\n# Check Rust version and dependencies\nrustc --version\ncat Cargo.toml\ncat Cargo.lock\n```\n\n**Document Current Stack**:\n```markdown\n## Current Project Stack\n\n### Language & Runtime\n- **Language**: Python 3.11\n- **Package Manager**: uv\n- **Virtual Environment**: venv\n\n### Framework\n- **Web Framework**: FastAPI 0.104.0\n- **ORM**: SQLAlchemy 2.0.23\n- **Validation**: Pydantic 2.5.0\n\n### Key Dependencies\n- `httpx`: 0.25.2 (HTTP client)\n- `redis`: 5.0.1 (Caching)\n- `pytest`: 7.4.3 (Testing)\n\n### Infrastructure\n- **Database**: PostgreSQL 15\n- **Cache**: Redis 7\n- **Server**: Uvicorn\n```\n\n### Step 2: Analyze Feature Requirements\n\nBased on extracted requirements, identify technology needs:\n\n**Example Requirements**:\n- \"Real-time data synchronization\" → WebSockets, async I/O\n- \"File processing\" → File handling libraries\n- \"API integration\" → HTTP client\n- \"Data validation\" → Validation library\n- \"Background tasks\" → Task queue\n\n**Technology Mapping**:\n```markdown\n## Technology Requirements\n\n| Requirement | Technology Need | Current Support | Gap |\n|-------------|----------------|-----------------|-----|\n| Real-time updates | WebSockets | ✅ FastAPI supports | None |\n| Data validation | Schema validation | ✅ Pydantic | None |\n| Background tasks | Task queue | ❌ No task queue | Need Celery/RQ |\n| File uploads | File handling | ✅ Built-in | None |\n| PDF generation | PDF library | ❌ No PDF lib | Need reportlab |\n```\n\n### Step 3: Recommend Technologies\n\nUse `tech-stack-matrix.md` to match requirements with technologies:\n\n**Python Recommendations**:\n\n**Web Frameworks**:\n- **FastAPI**: Modern, async, auto-docs (recommended for APIs)\n- **Django**: Full-featured, ORM included (for full web apps)\n- **Flask**: Lightweight, flexible (for simple apps)\n\n**Database Libraries**:\n- **SQLAlchemy**: Powerful ORM, wide DB support\n- **Django ORM**: Tightly integrated with Django\n- **asyncpg**: Async PostgreSQL driver (high performance)\n\n**Validation**:\n- **Pydantic**: Type-based validation, FastAPI integration\n- **marshmallow**: Schema validation, serialization\n- **cerberus**: Lightweight validation\n\n**HTTP Clients**:\n- **httpx**: Modern, async support (recommended)\n- **requests**: Synchronous, widely used\n- **aiohttp**: Async HTTP client/server\n\n**Task Queues**:\n- **Celery**: Mature, feature-rich\n- **RQ** (Redis Queue): Simple, Redis-based\n- **Dramatiq**: Simple, reliable\n\n**Testing**:\n- **pytest**: Most popular, plugin ecosystem\n- **unittest**: Built-in, standard library\n- **hypothesis**: Property-based testing\n\n### Step 4: Evaluate Compatibility\n\nCheck for compatibility issues:\n\n**Version Compatibility**:\n```python\n# Example: Check Python version requirements\nimport sys\nif sys.version_info < (3, 10):\n    raise RuntimeError(\"Requires Python 3.10+\")\n```\n\n**Dependency Conflicts**:\n```bash\n# Check for dependency conflicts\npip check\n\n# Analyze dependency tree\npip-tree\npipdeptree\n```\n\n**Compatibility Matrix**:\n```markdown\n## Compatibility Assessment\n\n### Python Version Compatibility\n- **Current**: Python 3.11\n- **Required**: Python 3.10+ (for new libraries)\n- **Status**: ✅ Compatible\n\n### Framework Compatibility\n| Library | Required Version | Current Version | Compatible | Notes |\n|---------|-----------------|-----------------|------------|-------|\n| FastAPI | ≥0.100.0 | 0.104.0 | ✅ | Compatible |\n| Pydantic | ≥2.0.0 | 2.5.0 | ✅ | Compatible |\n| SQLAlchemy | ≥2.0.0 | 2.0.23 | ✅ | Compatible |\n| New: Celery | ≥5.3.0 | - | ✅ | No conflicts |\n| New: reportlab | ≥4.0.0 | - | ✅ | No conflicts |\n\n### Breaking Changes\n- None identified for proposed libraries\n```\n\n### Step 5: Assess Performance Implications\n\nEvaluate performance characteristics using `language-feature-map.md`:\n\n**Performance Considerations**:\n\n**Async I/O** (Python asyncio, FastAPI):\n- **Pros**: High concurrency, efficient I/O handling\n- **Cons**: Complexity, requires async-aware libraries\n- **Use When**: Many concurrent connections, I/O-bound operations\n\n**Database Performance**:\n- **ORM Overhead**: SQLAlchemy adds ~10-20% overhead vs raw SQL\n- **Mitigation**: Use bulk operations, eager loading, query optimization\n\n**Caching Strategy**:\n- **Redis**: In-memory, microsecond latency\n- **Application Cache**: In-process, nanosecond latency\n- **Recommendation**: Use Redis for shared cache, application cache for read-heavy data\n\n**Serialization**:\n- **JSON**: Standard, slow for large payloads\n- **MessagePack**: Binary, 2-3x faster than JSON\n- **Protobuf**: Schema-based, fastest, smallest\n\n```markdown\n## Performance Assessment\n\n### Expected Performance Characteristics\n- **API Response Time**: <200ms (target), FastAPI typically achieves 50-100ms\n- **Database Query Time**: <50ms (with proper indexing)\n- **Caching Hit Rate**: >80% (target)\n- **Concurrent Users**: 1000+ (FastAPI handles well with async)\n\n### Performance Optimizations\n1. **Use Connection Pooling**: SQLAlchemy connection pool (size=20)\n2. **Implement Caching**: Redis for frequently accessed data\n3. **Async I/O**: Use httpx async client for external APIs\n4. **Database Indexing**: Add indexes on frequently queried columns\n5. **Background Processing**: Use Celery for heavy computations\n\n### Performance Risks\n- **Risk**: Large file uploads could block event loop\n  - **Mitigation**: Use streaming uploads, background processing\n- **Risk**: N+1 query problem with ORM\n  - **Mitigation**: Use eager loading (joinedload, selectinload)\n```\n\n### Step 6: Identify Constraints\n\nDocument technical constraints:\n\n**Platform Constraints**:\n```markdown\n## Technical Constraints\n\n### Platform Requirements\n- **OS**: Linux (Ubuntu 22.04+) or macOS\n- **Python**: 3.10+ (for match statements, improved typing)\n- **Database**: PostgreSQL 14+ (for JSON improvements)\n- **Memory**: 2GB minimum, 4GB recommended\n- **Storage**: 10GB for application + dependencies\n\n### Deployment Constraints\n- **Container**: Docker-compatible\n- **Environment**: Supports environment variables\n- **Network**: Outbound HTTPS required for external APIs\n- **Ports**: 8000 (application), 5432 (database), 6379 (Redis)\n\n### Licensing Constraints\n- All proposed libraries use permissive licenses (MIT, Apache 2.0, BSD)\n- No GPL dependencies (avoid copyleft)\n- Commercial use permitted\n\n### Development Constraints\n- **IDE**: VS Code, PyCharm (type checking support)\n- **Type Checking**: mypy required in CI/CD\n- **Code Formatting**: Black, isort\n- **Testing**: pytest with 80%+ coverage\n```\n\n### Step 7: Compare Alternatives\n\nWhen multiple options exist, create comparison:\n\n```markdown\n## Technology Alternatives\n\n### Task Queue Comparison\n\n| Feature | Celery | RQ | Dramatiq |\n|---------|--------|----|---------|\n| **Maturity** | High (2009) | Medium (2011) | Medium (2016) |\n| **Complexity** | High | Low | Low |\n| **Broker** | RabbitMQ/Redis | Redis only | RabbitMQ/Redis |\n| **Performance** | High | Medium | High |\n| **Monitoring** | Flower | RQ Dashboard | Basic |\n| **Learning Curve** | Steep | Gentle | Gentle |\n| **Recommendation** | ⭐ Enterprise | ⭐ Simple | ⭐ Middle ground |\n\n**Recommendation**: Use RQ for this project\n- **Reasoning**: Already using Redis, simple requirements, faster learning curve\n- **Trade-off**: Less features than Celery, but sufficient for current needs\n```\n\n### Step 8: Create Technology Recommendation\n\nSynthesize findings into recommendation:\n\n```markdown\n## Technology Stack Recommendation\n\n### New Libraries to Add\n\n1. **RQ (Redis Queue)** - Background Task Processing\n   - **Version**: 1.15.1+\n   - **Purpose**: Process file uploads, send emails asynchronously\n   - **Justification**: Simple, integrates with existing Redis, sufficient for needs\n   - **Alternative Considered**: Celery (too complex for current requirements)\n\n2. **reportlab** - PDF Generation\n   - **Version**: 4.0.7+\n   - **Purpose**: Generate PDF reports\n   - **Justification**: Mature, feature-rich, good documentation\n   - **Alternative Considered**: WeasyPrint (CSS-based, but slower)\n\n3. **httpx** - Async HTTP Client\n   - **Version**: 0.25.2+ (already using, version OK)\n   - **Purpose**: Make async external API calls\n   - **Justification**: Modern, async support, timeout handling\n   - **Alternative Considered**: aiohttp (more complex API)\n\n### No Changes Required\n\n- **FastAPI**: Current framework suitable for requirements\n- **Pydantic**: Current validation library sufficient\n- **SQLAlchemy**: Current ORM handles database needs\n- **pytest**: Current testing framework adequate\n\n### Version Updates\n\nNone required - all current versions compatible with new libraries\n\n### Compatibility Verification\n\n✅ All proposed libraries compatible with:\n- Python 3.11\n- FastAPI 0.104.0\n- Existing dependency versions\n\n### Performance Impact\n\n**Expected Improvements**:\n- Background tasks don''t block API responses (+50% perceived responsiveness)\n- Async external API calls improve throughput (+30% under load)\n\n**Minimal Overhead**:\n- RQ: <5% overhead for task queuing\n- reportlab: Only used on-demand for PDF generation\n```\n\n## Best Practices\n\n### 1. Prefer Existing Stack\n- Leverage technologies already in use\n- Avoid introducing new languages/frameworks without strong justification\n- Consider team familiarity\n\n### 2. Evaluate Maturity\n- Prefer mature, well-maintained libraries\n- Check last update date (< 6 months ideal)\n- Review GitHub stars, issues, contributors\n- Check PyPI downloads for Python packages\n\n### 3. Consider Ecosystem\n- Strong community support\n- Good documentation\n- Active development\n- Compatible with existing tools\n\n### 4. Performance Testing\n- Benchmark critical paths\n- Load test under realistic conditions\n- Profile to find bottlenecks\n- Measure, don''t assume\n\n### 5. Future-Proofing\n- Choose actively maintained libraries\n- Prefer libraries with stable APIs\n- Consider migration paths\n- Avoid deprecated technologies\n\n### 6. Security Considerations\n- Check for known vulnerabilities (CVEs)\n- Evaluate security track record\n- Consider security features\n- Review security advisories\n\n## Resources\n\n### tech-stack-matrix.md\nComprehensive matrix of:\n- Popular libraries by category\n- Framework comparisons\n- Performance characteristics\n- Compatibility notes\n- Use case recommendations\n\n### language-feature-map.md\nLanguage-specific features:\n- Python async/await capabilities\n- TypeScript type system features\n- Rust ownership model\n- Performance characteristics\n- Best practices\n\n## Example Usage\n\n### Input (Feature Requirements)\n```\nFeature: User notification system\n- Send email notifications\n- In-app real-time notifications\n- Background processing for bulk sends\n- Track delivery status\n```\n\n### Output (Tech Stack Evaluation)\n```markdown\n## Technical Stack Evaluation\n\n### Current Stack Analysis\n- **Language**: Python 3.11 ✅\n- **Framework**: FastAPI 0.104.0 ✅ (WebSocket support for real-time)\n- **Database**: PostgreSQL 15 ✅\n- **Cache**: Redis 7 ✅\n\n### Required Technologies\n\n1. **Task Queue**: RQ 1.15.1\n   - **Purpose**: Background email sending\n   - **Justification**: Integrates with existing Redis, simple API\n   - **Performance**: Handles 1000+ tasks/minute\n\n2. **Email Library**: python-email-validator + SMTP\n   - **Purpose**: Email validation and sending\n   - **Justification**: Standard library sufficient, no extra dependencies\n   - **Alternative**: SendGrid (if high volume needed)\n\n3. **WebSocket**: FastAPI built-in\n   - **Purpose**: Real-time in-app notifications\n   - **Justification**: Already supported by FastAPI\n   - **Performance**: Handles 10,000+ concurrent connections\n\n4. **Notification Storage**: PostgreSQL (existing)\n   - **Purpose**: Store notification history\n   - **Justification**: Existing database, JSON column support\n   - **Performance**: Adequate with proper indexing\n\n### Compatibility Assessment\n✅ All technologies compatible with existing stack\n✅ No version conflicts\n✅ No breaking changes required\n\n### Performance Expectations\n- **Email Send**: 100-200ms (backgrounded via RQ)\n- **Real-time Push**: <50ms via WebSocket\n- **Database Write**: <10ms\n- **Overall**: <200ms API response (tasks queued)\n\n### Recommendation\n**Proceed with proposed stack** - all requirements met with minimal additions\n```\n\n## Integration\n\nThis skill is used by:\n- **analysis-specialist** agent during Phase 1: Requirements Analysis\n- Activates automatically when agent evaluates tech stack\n- Provides technology assessment for analysis document generation\n\n---\n\n**Version**: 2.0.0\n**Auto-Activation**: Yes (when evaluating tech stack)\n**Phase**: 1 (Requirements Analysis)\n**Created**: 2025-10-29"},"lastSynced":"2026-03-08T02:02:30.432Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing systematic evaluation of technical stack requirements and compatibility for feature implementations.","zh":"非常适合需要系统评估技术栈要求和兼容性的开发代理，用于特性实现。","ja":"開発エージェントが技術スタックの要件と互換性を体系的に評価する必要がある場合に最も適しています。","ko":"기술 스택 요구 사항과 호환성을 체계적으로 평가해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una evaluación sistemática de los requisitos y la compatibilidad de la pila técnica para implementaciones de características.","fr":"Parfait pour les agents de développement ayant besoin d''une évaluation systématique des exigences et de la compatibilité de la pile technique pour les implémentations de fonctionnalités.","de":"Perfekt für Entwicklungssagenten, die eine systematische Bewertung der Anforderungen und der Kompatibilität des Technikstacks für Feature-Implementierungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de avaliação sistemática dos requisitos da pilha técnica e da compatibilidade para implementações de recursos.","ru":"Идеально для Агентов разработки, которым требуется систематическая оценка требований технологического стека и совместимости для реализации функций.","ar":"مثالي لعمليات تطوير الوكلاء التي تحتاج إلى تقييم منهجي لمتطلبات الحزمة التقنية والتوافق لتنفيذ الميزات."},"recommendation":{"en":"Empowers agents to analyze existing project technology, recommend appropriate libraries and frameworks, assess compatibility, and identify performance implications using technical stack evaluation protocols.","zh":"赋予代理分析现有项目技术，推荐适当的库和框架，评估兼容性，并使用技术栈评估协议识别性能影响。","ja":"エージェントが既存のプロジェクト技術を分析し、適切なライブラリやフレームワークを推奨し、互換性を評価し、技術スタック評価プロトコルを使用してパフォーマンスの影響を特定することを可能にします。","ko":"에이전트가 기존 프로젝트 기술을 분석하고 적절한 라이브러리 또는 프레임워크를 추천하며 호환성을 평가하고 기술 스택 평가 프로토콜을 사용하여 성능 영향을 식별할 수 있습니다.","es":"Habilita a los agentes a analizar la tecnología del proyecto existente, recomendar bibliotecas y frameworks adecuados, evaluar la compatibilidad e identificar las implicaciones de rendimiento utilizando protocolos de evaluación de la pila técnica.","fr":"Permet aux agents d''analyser la technologie du projet existant, de recommander des bibliothèques et des frameworks appropriés, d''évaluer la compatibilité et d''identifier les implications de performance en utilisant des protocoles d''évaluation de la pile technique.","de":"Ermöglicht es den Agenten, die bestehende Projekttechnologie zu analysieren, geeignete Bibliotheken und Frameworks zu empfehlen, die Kompatibilität zu bewerten und die Leistungsimplikationen unter Verwendung von Technikstack-Bewertungsprotokollen zu identifizieren.","pt":"Habilita os agentes a analisar a tecnologia do projeto existente, recomendar bibliotecas e frameworks apropriados, avaliar a compatibilidade e identificar implicações de desempenho usando protocolos de avaliação da pilha técnica.","ru":"Наделяет агентов возможностью анализировать существующую технологию проекта, рекомендовать подходящие библиотеки и фреймворки, оценивать совместимость и определять последствия для производительности с помощью протоколов оценки технологического стека.","ar":"يمنح الوكلاء القدرة على تحليل التكنولوجيا الحالية للمشروع ، وتوصية المكتبات والإطارات المناسبة ، وتقييم التوافق وتحديد الآثار على الأداء باستخدام بروتوكولات تقييم الحزمة التقنية."},"useCases":{"en":["Evaluating technical stack requirements for new feature implementations","Assessing technology compatibility for project integrations","Recommending frameworks or libraries for optimized performance"],"zh":["为新特性实现评估技术栈要求","为项目集成评估技术兼容性","为优化性能推荐框架或库"],"ja":["新しい機能の実装のために技術スタックの要件を評価する","プロジェクト統合のために技術の互換性を評価する","最適化されたパフォーマンスのためにフレームワークまたはライブラリを推奨する"],"ko":["새로운 기능 구현을 위한 기술 스택 요구 사항 평가","프로젝트 통합을 위한 기술 호환성 평가","최적의 성능을 위한 프레임워크 또는 라이브러리 추천"],"es":["Evaluación de los requisitos de la pila técnica para nuevas implementaciones de características","Evaluación de la compatibilidad tecnológica para integraciones de proyectos","Recomendación de frameworks o bibliotecas para un rendimiento optimizado"],"fr":["Évaluation des exigences de la pile technique pour de nouvelles implémentations de fonctionnalités","Évaluation de la compatibilité technologique pour les intégrations de projets","Recommandation de frameworks ou de bibliothèques pour un rendement optimisé"],"de":["Bewertung der Anforderungen des Technikstacks für neue Feature-Implementierungen","Bewertung der Technologiekompatibilität für Projektintegrationen","Empfehlung von Frameworks oder Bibliotheken für ein optimiertes Leistungsniveau"],"pt":["Avaliar os requisitos da pilha técnica para novas implementações de recursos","Avaliar a compatibilidade da tecnologia para integrações de projeto","Recomendar frameworks ou bibliotecas para desempenho otimizado"],"ru":["Оценка требований технологического стека для новых реализаций функций","Оценка совместимости технологии для интеграций проекта","Рекомендация фреймворков или библиотек для оптимизированной производительности"],"ar":["تقييم متطلبات الحزمة التقنية لتنفيذات الميزات الجديدة","تقييم توافق التكنولوجيا لمشاريع التكامل","توصية بالإطارات أو المكتبات من أجل أداء محسّن"]},"limitations":{"en":["Requires access to project technology stack information","Limited to evaluating compatibility and performance implications"],"zh":["需要访问项目技术栈信息","仅限于评估兼容性和性能影响"],"ja":["プロジェクト技術スタック情報へのアクセスが必要","互換性とパフォーマンスの影響の評価のみに限定"],"ko":["프로젝트 기술 스택 정보에 대한 액세스가 필요함","호환성 및 성능 영향의 평가에만 제한"],"es":["Requiere acceso a la información de la pila técnica del proyecto","Limitado a la evaluación de la compatibilidad y las implicaciones de rendimiento"],"fr":["Nécessite l''accès aux informations de la pile technique du projet","Limité à l''évaluation de la compatibilité et des implications de performance"],"de":["Benötigt Zugriff auf die Informationen des Technikstacks des Projekts","Begrenzt auf die Bewertung der Kompatibilität und der Leistungsimplikationen"],"pt":["Exige acesso às informações da pilha técnica do projeto","Limitado à avaliação da compatibilidade e das implicações de desempenho"],"ru":["Требует доступа к информации технологического стека проекта","Ограничен оценкой совместимости и последствий для производительности"],"ar":["يتطلب الوصول إلى معلومات حزمة التكنولوجيا للمشروع","محدود بتقييم التوافق والآثار على الأداء"]},"version":4},"contentHash":"1e5f304e6a3adf61b4c4196db9504b0b4bcd205a259d497b247b877650c36c1e","qualityScore":60}');
