INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matteocervelli/llms/tech-stack-evaluator', 'tech-stack-evaluator', 'matteocervelli', 'llms', 'community', 'tech-stack-evaluator matteocervelli llms community The tech-stack-evaluator skill provides systematic evaluation of technical stack requirements and compatibility for feature implementations, benefiting developers and project managers. tech-stack-evaluator是一种技术栈评估工具，提供系统化的技术栈要求和兼容性评估。它分析现有的项目技术，推荐合适的库和框架，并评估性能影响 tech-stack-evaluatorはテクニカルスタック評価ツールであり、テクニカルスタックの要件と互換性を体系的に評価します。既存のプロジェクト技術を分析し、適切なライブラリやフレームワークを推奨し、パフォーマンスの影響を評価します tech-stack-evaluator는 기술 스택 평가 도구로, 기술 스택 요구 사항과 호환성을 체계적으로 평가합니다. 기존 프로젝트 기술을 분석하여 적합한 라이브러리 및 프레임워크를 추천하고 성능 영향도를 평가합니다 tech-stack-evaluator es una herramienta de evaluación de pilas tecnológicas que analiza la compatibilidad y recomienda bibliotecas y frameworks adecuados para tus proyectos tech-stack-evaluator est un outil d''évaluation de stacks technologiques qui analyse la compatibilité et recommande des bibliothèques et des frameworks adaptés à vos projets tech-stack-evaluator ist ein Tool zur Bewertung von Technologie-Stacks, das die Kompatibilität analysiert und geeignete Bibliotheken und Frameworks für Ihre Projekte empfiehlt O tech-stack-evaluator é uma ferramenta de avaliação de pilha tecnológica que analisa requisitos e compatibilidade. ИИ Агент tech-stack-evaluator является инструментом для оценки технологического стека, анализирующим требования и совместимость. tech-stack-evaluator هو أداة لتقييم حزمة التكنولوجيا التي تحلل المتطلبات والتوافق how to use tech-stack-evaluator tech-stack-evaluator setup guide what is tech-stack-evaluator tech-stack-evaluator alternative tech-stack-evaluator vs Claude Code tech-stack-evaluator install multi-LLM support MCP server management technical stack compatibility tech-stack-evaluator 技术栈评估 LLM配置 MCP服务器管理 库和框架推荐 性能影响评估 AI工具 技术栈要求 Analyzes existing project technology for compatibility Recommends appropriate libraries and frameworks Assesses performance implications of technical stack choices Supports multi-LLM configuration including Claude Code, Codex, and OpenCode Auto-activates for technical stack evaluations and recommendations Manages MCP servers for efficient skill and command execution tech-stack-evaluator is a centralized LLM configuration and documentation management system for building skills and managing MCP servers with multi-LLM support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rayven122/tumiki/tumiki-manager-architecture', 'community', 'rayven122', 'tumiki', 'rayven122/tumiki', 'tumiki-manager-architecture', 0, 0, 60, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:31.186Z', 'd4ed01781e7867744450d4da848977235c69def894ee422035d8f07c0684a1a9', '{"id":"rayven122/tumiki/tumiki-manager-architecture","name":"tumiki-manager-architecture","description":{"en":"The tumiki-manager-architecture skill helps developers manage monorepos with a feature-based structure, leveraging Server Components and Server Actions for improved performance. It benefits developers working with complex projects.","zh":"Tumiki Manager Architecture是一种基于Feature-Based、RSC-First和Server Actions的AIエージェント架构，旨在提升开发效率和性能","ja":"Tumiki Manager Architectureは、Feature-Based、RSC-First、Server Actionsを活用したAIエージェントアーキテクチャで、開発効率とパフォーマンスを向上させる","ko":"Tumiki Manager Architecture는 Feature-Based, RSC-First, Server Actions를 기반으로 하는 AI 에이전트 아키텍처로, 개발 효율과 성능을 향상","es":"tumiki-manager-architecture es una arquitectura de monorepo basada en características que utiliza tecnologías como React y Server Actions","fr":"tumiki-manager-architecture est une architecture de monorepo basée sur les fonctionnalités qui utilise des technologies comme React et Server Actions","de":"tumiki-manager-architecture ist eine feature-basierte Monorepo-Architektur, die Technologien wie React und Server Actions verwendet","pt":"O tumiki-manager-architecture é uma arquitetura de monorepo baseada em recursos que combina features/, Server Components e Server Actions para melhorar o desempenho da aplicação","ru":"tumiki-manager-architecture - это архитектура монорепозитория на основе функций, которая объединяет features/, Server Components и Server Actions для улучшения производительности приложения","ar":"تُمثّل tumiki-manager-architecture هندسة مونوريبو تعتمد على الميزات التي تجمع بين features/، Server Components و Server Actions لتحسين أداء التطبيق"},"seo":{"title":{"en":"tumiki-manager-architecture: Monorepo Setup Guide | AI Ag...","zh":"Tumiki Manager Architecture Setup Guide - AIエージェント最佳实践","ja":"Tumiki Manager Architecture ベストプラクティス - AIエージェントの導入","ko":"Tumiki Manager Architecture 설정 가이드 - AI 에이전트 개발 최적화","es":"Guía de configuración de tumiki-manager-architecture para...","fr":"Guide d''installation de tumiki-manager-architecture pour ...","de":"Einrichtungsleitfaden für tumiki-manager-architecture-Ent...","pt":"Guia de Configuração do tumiki-manager-architecture para ...","ru":"Руководство по настройке tumiki-manager-architecture для ...","ar":"دليل إعداد tumiki-manager-architecture للمطوّرين"},"description":{"en":"Discover how tumiki-manager-architecture simplifies monorepo management with feature-based structure, Server Components, and Server Actions. Learn how to set...","zh":"了解Tumiki Manager Architecture的特点和优势，包括Feature-Based、RSC-First和Server Actions等技术，提升AIエージェント开发效率","ja":"Tumiki Manager Architectureの特徴とメリットを紹介。Feature-Based、RSC-First、Server Actionsなどの技術を活用してAIエージェント開発を効率化","ko":"Tumiki Manager Architecture의 주요 특징과 장점을 살펴보세요. Feature-Based, RSC-First, Server Actions 등의 기술을 이용하여 AI 에이전트 개발을 최적화","es":"Aprende a configurar tumiki-manager-architecture con tecnologías como React, RSC-First y Server Actions para mejorar el rendimiento","fr":"Découvrez comment configurer tumiki-manager-architecture avec des technologies comme React, RSC-First et Server Actions pour améliorer les performances","de":"Erfahren Sie, wie Sie tumiki-manager-architecture mit Technologien wie React, RSC-First und Server Actions einrichten, um die Leistung zu verbessern","pt":"Aprenda a configurar o tumiki-manager-architecture com recursos como features/, Server Components e Server Actions para melhorar o desempenho da sua aplicação","ru":"Узнайте, как настроить tumiki-manager-architecture с функциями seperti features/, Server Components и Server Actions для улучшения производительности вашего ...","ar":"تعرف على كيفية إعداد tumiki-manager-architecture باستخدام ميزات مثل features/، Server Components و Server Actions لتحسين أداء تطبيقك"},"definition":{"en":"tumiki-manager-architecture is a monorepo management approach using a feature-based structure, Server Components, and Server Actions for efficient project organization and development.","zh":"Tumiki Manager Architecture是一种AIエージェント架构，采用Feature-Based、RSC-First和Server Actions等技术","ja":"Tumiki Manager Architectureは、Feature-Based、RSC-First、Server Actionsなどの技術を採用したAIエージェントアーキテクチャ","ko":"Tumiki Manager Architecture는 Feature-Based, RSC-First, Server Actions 등을採用한 AI 에이전트 아키텍처","es":"tumiki-manager-architecture es un enfoque de arquitectura de monorepo que combina características de React, RSC-First y Server Actions","fr":"tumiki-manager-architecture est une approche d''architecture de monorepo qui combine des fonctionnalités de React, RSC-First et Server Actions","de":"tumiki-manager-architecture ist ein Ansatz für die Monorepo-Architektur, der Funktionen von React, RSC-First und Server Actions kombiniert","pt":"tumiki-manager-architecture é uma arquitetura de monorepo que combina recursos como features/ e Server Components para melhorar o desempenho","ru":"tumiki-manager-architecture - это архитектура монорепозитория, которая объединяет функции seperti features/ и Server Components для улучшения производительности","ar":"تُمثّل tumiki-manager-architecture هندسة مونوريبو تجمع بين ميزات مثل features/ و Server Components لتحسين الأداء"},"features":{"en":["Uses a feature-based structure with `features/` directory for domain-level cohesion","Employs Server Components as the default for improved performance","Utilizes Server Actions for simplified form processing","Supports package splitting via Turborepo for efficient dependency management","Leverages RSC-First approach for optimized Server Component usage","Follows Bulletproof React principles for robust and maintainable code"],"zh":["基于Feature-Based的结构","采用RSC-First的Server Components","支持Server Actions","使用Turborepo的包分割","集成Bulletproof React和Next.js 15+"],"ja":["Feature-Based構造","RSC-FirstのServer Components","Server Actionsのサポート","Turborepoのパッケージ分割","Bulletproof ReactとNext.js 15+の統合"],"ko":["Feature-Based 구조","RSC-First의 Server Components","Server Actions 지원","Turborepo의 패키지 분할","Bulletproof React와 Next.js 15+의 통합"],"es":["Estructura de características con `features/`","Server Components como tecnología de renderizado por defecto","Server Actions para el procesamiento de formularios","División de paquetes con Turborepo","Compatibilidad con Bulletproof React y Next.js 15+"],"fr":["Structure de fonctionnalités avec `features/`","Composants serveur comme technologie de rendu par défaut","Actions serveur pour le traitement de formulaires","Division de paquets avec Turborepo","Compatibilité avec Bulletproof React et Next.js 15+"],"de":["Feature-Struktur mit `features/`","Server-Komponenten als Standard-Rendering-Technologie","Server-Aktionen für die Formularverarbeitung","Paket-Trennung mit Turborepo","Kompatibilität mit Bulletproof React und Next.js 15+"],"pt":["Estrutura de features/ para organização de código","Server Components como padrão para melhorar o desempenho","Server Actions para simplificar o processamento de formulários","Divisão de pacotes com Turborepo para melhor gerenciamento","Integração com React e Next.js para desenvolvimento de aplicações web"],"ru":["Структура features/ для организации кода","Server Components как стандарт для улучшения производительности","Server Actions для упрощения обработки форм","Разделение пакетов с Turborepo для лучшего управления","Интеграция с React и Next.js для разработки веб-приложений"],"ar":["هيكل features/ لتنظيم الكود","Server Components ك padrão لتحسين الأداء","Server Actions لتسهيل معالجة النماذج","تقسيم الحزم مع Turborepo لإدارة أفضل","التكامل مع React و Next.js لتطوير تطبيقات الويب"]},"keywords":{"en":["how to use tumiki-manager-architecture","tumiki-manager-architecture setup guide","tumiki-manager-architecture vs monorepo","tumiki-manager-architecture install","what is tumiki-manager-architecture","tumiki-manager-architecture alternative","tumiki-manager-architecture and Server Components","tumiki-manager-architecture monorepo management","tumiki-manager-architecture RSC-First approach","tumiki-manager-architecture Turborepo integration"],"zh":["AIエージェント","Tumiki Manager Architecture","Feature-Based","RSC-First","Server Actions","Turborepo","Bulletproof React","Next.js 15+","AI开发","架构设计"],"ja":["AIエージェント","Tumiki Manager Architecture","Feature-Based","RSC-First","Server Actions","Turborepo","Bulletproof React","Next.js 15+","AI開発","アーキテクチャ設計"],"ko":["AI 에이전트","Tumiki Manager Architecture","Feature-Based","RSC-First","Server Actions","Turborepo","Bulletproof React","Next.js 15+","AI 개발","아키텍처 설계"],"es":["tumiki-manager-architecture","arquitectura de monorepo","React","RSC-First","Server Actions","desarrollo de software","configuración de tumiki-manager-architecture","mejora del rendimiento"],"fr":["tumiki-manager-architecture","architecture de monorepo","React","RSC-First","Actions serveur","développement de logiciels","configuration de tumiki-manager-architecture","amélioration des performances"],"de":["tumiki-manager-architecture","Monorepo-Architektur","React","RSC-First","Server-Aktionen","Software-Entwicklung","Einrichtung von tumiki-manager-architecture","Leistungsverbesserung"],"pt":["tumiki-manager-architecture","arquitetura de monorepo","features/","Server Components","Server Actions","Turborepo","React","Next.js","desenvolvimento de aplicações web"],"ru":["tumiki-manager-architecture","архитектура монорепозитория","features/","Server Components","Server Actions","Turborepo","React","Next.js","разработка веб-приложений"],"ar":["tumiki-manager-architecture","هندسة مونوريبو","features/","Server Components","Server Actions","Turborepo","React","Next.js","تطوير تطبيقات الويب"]}},"owner":"rayven122","repo":"tumiki","repoPath":"rayven122/tumiki","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"tumiki-manager-architecture","description":"|","bodyPreview":"# Manager Feature-Based Monorepo Architecture\n\n**Feature-Based + RSC-First + Server Actions**\n\n## 設計の特徴\n\n| 要素                         | 採用元            | 目的                     |\n| ---------------------------- | ----------------- | ------------------------ |\n| `features/` 構造             | Bulletproof React | ドメイン単位の凝集       |\n| Server Components デフォルト | RSC-First         | パフォーマンス向上       |\n| Server Actions               | Next.js 15+       | フォーム処理のシンプル化 |\n| パッケージ分割               | Turborepo","body":"# Manager Feature-Based Monorepo Architecture\n\n**Feature-Based + RSC-First + Server Actions**\n\n## 設計の特徴\n\n| 要素                         | 採用元            | 目的                     |\n| ---------------------------- | ----------------- | ------------------------ |\n| `features/` 構造             | Bulletproof React | ドメイン単位の凝集       |\n| Server Components デフォルト | RSC-First         | パフォーマンス向上       |\n| Server Actions               | Next.js 15+       | フォーム処理のシンプル化 |\n| パッケージ分割               | Turborepo         | 共通ロジックの再利用     |\n\n## モノレポ構造\n\n```text\ntumiki/\n├── apps/\n│   ├── manager/              # Next.js フロントエンド\n│   │   └── src/\n│   │       ├── app/          # ルーティング\n│   │       ├── features/     # ドメイン機能\n│   │       ├── components/   # アプリ固有UI\n│   │       ├── hooks/\n│   │       ├── lib/\n│   │       └── config/\n│   │\n│   └── mcp-proxy/            # APIサーバー\n│\n├── packages/\n│   ├── ui/                   # 共通UIコンポーネント\n│   ├── ai/                   # AI SDK統合\n│   ├── shared/               # 共通ユーティリティ\n│   ├── db/                   # Prisma + DB\n│   ├── keycloak/             # 認証\n│   ├── mailer/               # メール\n│   ├── oauth-token-manager/  # OAuthトークン\n│   └── slack/                # Slack統合\n│\n└── tooling/                  # ビルド設定\n```\n\n## apps/manager 内部構造\n\n```text\napps/manager/src/\n├── app/                      # Next.js App Router（ルーティングのみ）\n│   ├── [orgSlug]/\n│   │   ├── agents/\n│   │   ├── mcps/\n│   │   ├── dashboard/\n│   │   └── ...\n│   ├── api/\n│   │   └── trpc/\n│   └── layout.tsx\n│\n├── features/                 # ドメイン単位で完結\n│   ├── agents/\n│   │   ├── components/       # UI（Server/Client混在）\n│   │   ├── actions/          # Server Actions\n│   │   ├── hooks/            # Client hooks\n│   │   ├── api/              # tRPCルーター\n│   │   ├── types/\n│   │   └── index.ts          # 公開API\n│   ├── mcps/\n│   ├── organization/\n│   ├── chat/\n│   └── dashboard/\n│\n├── components/               # アプリ固有の共通コンポーネント\n├── hooks/                    # アプリ固有の共通フック\n├── lib/                      # ユーティリティ\n├── config/                   # 設定\n└── types/                    # アプリ固有の型\n```\n\n## Feature 内部構造\n\n```text\nfeatures/{domain}/\n├── components/               # UI コンポーネント\n│   ├── AgentCard.tsx         # Server Component\n│   ├── AgentList.tsx         # Server Component\n│   └── CreateAgentForm.tsx   # ''use client''\n│\n├── actions/                  # Server Actions\n│   ├── createAgent.ts        # ''use server''\n│   └── deleteAgent.ts\n│\n├── hooks/                    # Client側ロジック\n│   └── useAgentForm.ts\n│\n├── api/                      # tRPCルーター\n│   └── router.ts\n│\n├── types/                    # 型定義\n│   └── index.ts\n│\n└── index.ts                  # 公開API\n```\n\n## 依存関係ルール\n\n```text\napp/ → features/ → components/, hooks/, lib/, types/\n           ↓\n    packages/ (@tumiki/ui, @tumiki/ai, @tumiki/db, ...)\n```\n\n### 禁止される依存\n\n| From          | To           | 理由                                    |\n| ------------- | ------------ | --------------------------------------- |\n| `features/A`  | `features/B` | Feature間の直接依存禁止                 |\n| `packages/`   | `apps/`      | パッケージはアプリに依存しない          |\n| `components/` | `features/`  | 共通コンポーネントはFeatureに依存しない |\n\n### Feature間で共通ロジックが必要な場合\n\n1. **共通化**: `lib/` または `packages/` に抽出\n2. **上位レイヤー**: `app/` レベルで統合\n\n## Server Components vs Client Components\n\n| 種類                     | 用途                          |\n| ------------------------ | ----------------------------- |\n| Server（デフォルト）     | データ取得、一覧表示          |\n| Client（`''use client''`） | フォーム、モーダル、hooks使用 |\n\n## コード例\n\n### Server Component\n\n```typescript\n// features/agents/components/AgentList.tsx\n// ''use client'' なし = Server Component\n\nimport { db } from \"@tumiki/db\";\nimport { Card } from \"@tumiki/ui\";\nimport { AgentCard } from \"./AgentCard\";\nimport { CreateAgentButton } from \"./CreateAgentButton\";\n\ntype Props = {\n  organizationId: string;\n};\n\nexport const AgentList = async ({ organizationId }: Props) => {\n  const agents = await db.agent.findMany({\n    where: { organizationId },\n    orderBy: { createdAt: \"desc\" },\n  });\n\n  return (\n    <div>\n      <div className=\"flex justify-between mb-4\">\n        <h2 className=\"text-xl font-bold\">エージェント一覧</h2>\n        <CreateAgentButton />\n      </div>\n      <div className=\"grid gap-4\">\n        {agents.map((agent) => (\n          <AgentCard key={agent.id} agent={agent} />\n        ))}\n      </div>\n    </div>\n  );\n};\n```\n\n### Client Component\n\n```typescript\n// features/agents/components/CreateAgentForm.tsx\n\"use client\";\n\nimport { useActionState } from \"react\";\nimport { Button, Input, Label } from \"@tumiki/ui\";\nimport { createAgentAction } from \"../actions/createAgent\";\n\nexport const CreateAgentForm = () => {\n  const [state, formAction, pending] = useActionState(createAgentAction, null);\n\n  return (\n    <form action={formAction}>\n      <div>\n        <Label htmlFor=\"name\">エージェント名</Label>\n        <Input id=\"name\" name=\"name\" required />\n      </div>\n\n      {state?.error && <p className=\"text-destructive\">{state.error}</p>}\n\n      <Button type=\"submit\" disabled={pending}>\n        {pending ? \"作成中...\" : \"作成\"}\n      </Button>\n    </form>\n  );\n};\n```\n\n### Server Action\n\n```typescript\n// features/agents/actions/createAgent.ts\n\"use server\";\n\nimport { revalidatePath } from \"next/cache\";\nimport { redirect } from \"next/navigation\";\nimport { db } from \"@tumiki/db\";\nimport { auth } from \"@/lib/auth\";\nimport { z } from \"zod\";\n\nconst schema = z.object({\n  name: z.string().min(1, \"名前は必須です\"),\n});\n\ntype ActionState = { error?: string } | null;\n\nexport const createAgentAction = async (\n  _prevState: ActionState,\n  formData: FormData,\n): Promise<ActionState> => {\n  const session = await auth();\n  if (!session?.user) {\n    return { error: \"認証が必要です\" };\n  }\n\n  const parsed = schema.safeParse({\n    name: formData.get(\"name\"),\n  });\n\n  if (!parsed.success) {\n    return { error: parsed.error.errors[0]?.message };\n  }\n\n  const agent = await db.agent.create({\n    data: {\n      name: parsed.data.name,\n      organizationId: session.user.organizationId,\n      status: \"active\",\n    },\n  });\n\n  revalidatePath(\"/[orgSlug]/agents\");\n  redirect(`/${session.user.orgSlug}/agents/${agent.slug}`);\n};\n```\n\n### Page\n\n```typescript\n// app/[orgSlug]/agents/page.tsx\n// Server Component\n\nimport { AgentList } from \"@/features/agents\";\nimport { getOrganization } from \"@/features/organization\";\n\ntype Props = {\n  params: Promise<{ orgSlug: string }>;\n};\n\nconst AgentsPage = async ({ params }: Props) => {\n  const { orgSlug } = await params;\n  const org = await getOrganization(orgSlug);\n\n  return (\n    <div className=\"container py-6\">\n      <h1 className=\"text-2xl font-bold mb-6\">エージェント管理</h1>\n      <AgentList organizationId={org.id} />\n    </div>\n  );\n};\n\nexport default AgentsPage;\n```\n\n### Feature index.ts\n\n```typescript\n// features/agents/index.ts\n\n// Components\nexport { AgentCard } from \"./components/AgentCard\";\nexport { AgentList } from \"./components/AgentList\";\nexport { CreateAgentForm } from \"./components/CreateAgentForm\";\n\n// Actions\nexport { createAgentAction } from \"./actions/createAgent\";\nexport { deleteAgentAction } from \"./actions/deleteAgent\";\n\n// Hooks\nexport { useAgentForm } from \"./hooks/useAgentForm\";\n\n// Types\nexport type { Agent, CreateAgentInput } from \"./types\";\n\n// API (tRPC)\nexport { agentRouter } from \"./api/router\";\n```\n\n## tRPC ルーター統合\n\n### Feature 内のルーター定義\n\n```typescript\n// features/agents/api/router.ts\n\nimport { createTRPCRouter, protectedProcedure } from \"@/lib/trpc\";\nimport { z } from \"zod\";\nimport { db } from \"@tumiki/db\";\n\nexport const agentRouter = createTRPCRouter({\n  list: protectedProcedure\n    .input(z.object({ organizationId: z.string() }))\n    .query(async ({ input }) => {\n      return db.agent.findMany({\n        where: { organizationId: input.organizationId },\n      });\n    }),\n\n  getById: protectedProcedure\n    .input(z.object({ id: z.string() }))\n    .query(async ({ input }) => {\n      return db.agent.findUnique({ where: { id: input.id } });\n    }),\n});\n```\n\n### Server Actions vs tRPC 使い分け\n\n| ユースケース                 | 推奨                               |\n| ---------------------------- | ---------------------------------- |\n| フォーム送信                 | Server Actions                     |\n| ページ初期データ             | 直接DBクエリ（Server Component内） |\n| クライアントからの動的クエリ | tRPC                               |\n| リアルタイム更新             | tRPC + React Query                 |\n\n## パッケージ間依存関係\n\n```text\napps/manager\n├── @tumiki/ui\n├── @tumiki/ai\n├── @tumiki/shared\n├── @tumiki/db\n└── @tumiki/keycloak\n\napps/mcp-proxy\n├── @tumiki/ai\n├── @tumiki/shared\n└── @tumiki/db\n```\n\n**ルール:**\n\n- `apps/` は `packages/` に依存可能\n- `packages/` は `apps/` に依存禁止\n- `packages/` 間は下位パッケージにのみ依存\n\n## Feature 一覧\n\n| Feature        | 説明               | サブ機能                   |\n| -------------- | ------------------ | -------------------------- |\n| `agents`       | AIエージェント管理 | 作成、実行、スケジュール   |\n| `mcps`         | MCPサーバー管理    | 追加、設定、ツール更新     |\n| `organization` | 組織管理           | メンバー、ロール、グループ |\n| `chat`         | チャット機能       | メッセージ、履歴           |\n| `dashboard`    | ダッシュボード     | 統計、アクティビティ       |\n| `notification` | 通知機能           | -                          |\n| `feedback`     | フィードバック     | -                          |\n\n## ファイル命名規則\n\n| 種類           | 規則                 | 例                    |\n| -------------- | -------------------- | --------------------- |\n| コンポーネント | PascalCase           | `AgentCard.tsx`       |\n| Server Action  | camelCase            | `createAgent.ts`      |\n| フック         | camelCase + use      | `useAgentForm.ts`     |\n| tRPCルーター   | camelCase + router   | `router.ts`           |\n| 型定義         | PascalCase           | `types/index.ts`      |\n| テスト         | 元ファイル名 + .test | `createAgent.test.ts` |\n| EE機能         | 元ファイル名 + .ee   | `create.ee.ts`        |\n\n## チェックリスト\n\n### Feature 移行完了条件\n\n- [ ] `features/{domain}/` ディレクトリ作成\n- [ ] `components/` にUIコンポーネント配置\n- [ ] `actions/` にServer Actions配置\n- [ ] `api/router.ts` にtRPCルーター定義\n- [ ] `index.ts` で公開APIエクスポート\n- [ ] `app/` からのimport更新\n- [ ] テスト通過\n\n### 品質チェック\n\n- [ ] `pnpm typecheck` 成功\n- [ ] `pnpm lint` 成功\n- [ ] `pnpm test` 成功\n- [ ] `pnpm build` 成功\n"},"lastSynced":"2026-03-08T02:02:31.186Z","agentAnalysis":{"suitability":{"en":"Ideal for Monorepo Management Agents requiring feature-based structure and performance optimization through Server Components and Server Actions.","zh":"适用于需要基于特性结构和通过服务器组件和服务器操作进行性能优化的单体仓库管理代理。","ja":"機能ベースの構造とサーバーコンポーネントおよびサーバーアクションを介したパフォーマンス最適化を必要とするモノレポ管理エージェントに最適です。","ko":"기능 기반 구조 및 서버 컴포넌트 및 서버 액션을 통해 성능 최적화를 요구하는 모노레포 관리 에이전트에 적합합니다.","es":"Ideal para agentes de gestión de Monorepo que requieren una estructura basada en características y optimización del rendimiento a través de componentes de servidor y acciones de servidor.","fr":"Idéal pour les agents de gestion de Monorepo nécessitant une structure basée sur les fonctionnalités et l''optimisation des performances via des composants serveur et des actions serveur.","de":"Ideal für Monorepo-Management-Agenten, die eine featurebasierte Struktur und Leistungsoptimierung durch Server-Komponenten und Server-Aktionen erfordern.","pt":"Ideal para Agentes de Gerenciamento de Monorepo que exigem estrutura baseada em recursos e otimização de desempenho por meio de Componentes de Servidor e Ações de Servidor.","ru":"Идеально подходит для агентов управления монорепозиторием, требующих структуры на основе функций и оптимизации производительности с помощью компонентов сервера и действий сервера.","ar":"مثالي لعميل إدارة مونوريبو الذي يتطلب هيكلا قائمًا على الميزة وتحسين الأداء من خلال مكونات الخادم وإجراءات الخادم."},"recommendation":{"en":"Empowers agents to manage complex monorepos with a feature-based structure, leveraging Server Components for improved performance and Server Actions for simplified form processing, utilizing libraries like Turborepo for package splitting.","zh":"赋予代理管理具有功能基于结构的复杂单体仓库的能力，利用服务器组件提高性能，利用服务器操作简化表单处理，并利用Turborepo等库进行包拆分。","ja":"機能ベースの構造を持つ複雑なモノレポを管理するエージェントを可能にし、サーバーコンポーネントを使用してパフォーマンスを向上させ、サーバーアクションを使用してフォーム処理を簡素化します。また、Turborepoなどのライブラリを使用してパッケージの分割を実現します。","ko":"기능 기반 구조를 가진 복잡한 모노레포를 관리할 수 있는 에이전트를 가능하게 하며, 서버 컴포넌트를 사용하여 성능을 향상시키고, 서버 액션을 사용하여 폼 처리를 간소화하며, Turborepo 등의 라이브러리를 사용하여 패키지 분할을 실현합니다.","es":"Habilita a los agentes a gestionar monorepos complejos con una estructura basada en características, aprovechando componentes de servidor para una mejor rendimiento y acciones de servidor para un procesamiento de formularios simplificado, utilizando bibliotecas como Turborepo para la división de paquetes.","fr":"Permet aux agents de gérer des monorepos complexes avec une structure basée sur les fonctionnalités, en exploitant les composants serveur pour améliorer les performances et les actions serveur pour un traitement de formulaires simplifié, en utilisant des bibliothèques comme Turborepo pour la division de packages.","de":"Ermächtigt Agenten, komplexe Monorepos mit einer featurebasierten Struktur zu verwalten, indem Server-Komponenten für verbesserte Leistung und Server-Aktionen für vereinfachte Formularverarbeitung genutzt werden, unter Verwendung von Bibliotheken wie Turborepo für die Paketverteilung.","pt":"Habilita os agentes a gerenciar monorepos complexos com uma estrutura baseada em recursos, aproveitando Componentes de Servidor para melhorar o desempenho e Ações de Servidor para processamento de formulários simplificado, utilizando bibliotecas como Turborepo para divisão de pacotes.","ru":"Наделяет агентов возможностью управлять сложными монорепозиториями со структурой на основе функций, используя компоненты сервера для улучшения производительности и действия сервера для упрощения обработки форм, используя библиотеки seperti Turborepo для разделения пакетов.","ar":"يمنح العميل khảية إدارة مونوريبو معقدة بهيكل قائم على الميزة، مستفيدا من مكونات الخادم لتحسين الأداء وإجراءات الخادم لمعالجة الاستمارات المبسطة، باستخدام مكتبات مثل Turborepo لتقسيم الحزم."},"useCases":{"en":["Organizing large codebases into domain-unit features","Optimizing monorepo performance with Server Components and Server Actions","Streamlining form processing with Next.js 15+ Server Actions"],"zh":["将大型代码库组织成域单位功能","使用服务器组件和服务器操作优化单体仓库性能","使用Next.js 15+服务器操作简化表单处理"],"ja":["大規模なコードベースをドメイン単位の機能に整理する","サーバーコンポーネントとサーバーアクションを使用してモノレポのパフォーマンスを最適化する","Next.js 15+サーバーアクションを使用してフォーム処理を簡素化する"],"ko":["대형 코드베이스를 도메인 단위 기능으로 조직화하는 것","서버 컴포넌트 및 서버 액션을 사용하여 모노레포 성능을 최적화하는 것","Next.js 15+ 서버 액션을 사용하여 폼 처리를 간소화하는 것"],"es":["Organizar grandes bases de código en características de unidad de dominio","Optimizar el rendimiento de monorepo con componentes de servidor y acciones de servidor","Simplificar el procesamiento de formularios con Next.js 15+ acciones de servidor"],"fr":["Organiser de grandes bases de code en fonctionnalités d''unité de domaine","Optimiser les performances de monorepo avec des composants serveur et des actions serveur","Simplifier le traitement de formulaires avec Next.js 15+ actions serveur"],"de":["Große Codebasen in domaineinheitenbasierte Funktionen organisieren","Monorepo-Leistung mit Server-Komponenten und Server-Aktionen optimieren","Formularverarbeitung mit Next.js 15+ Server-Aktionen vereinfachen"],"pt":["Organizar grandes bases de código em recursos de unidade de domínio","Otimizar o desempenho do monorepo com Componentes de Servidor e Ações de Servidor","Simplificar o processamento de formulários com Next.js 15+ Ações de Servidor"],"ru":["Организация больших кодовых баз в функциональные единицы домена","Оптимизация производительности монорепозитория с помощью компонентов сервера и действий сервера","Упрощение обработки форм с помощью Next.js 15+ действий сервера"],"ar":["تنظيم قواعد بيانات كبيرة في وحدات ميزة домين","تحسين أداء مونوريبو باستخدام مكونات الخادم وإجراءات الخادم","تبسيط معالجة الاستمارات باستخدام Next.js 15+ إجراءات الخادم"]},"limitations":{"en":["Requires understanding of monorepo architecture","Limited to projects utilizing Server Components and Server Actions","Dependent on Turborepo for package management"],"zh":["需要了解单体仓库架构","仅限于使用服务器组件和服务器操作的项目","依赖Turborepo进行包管理"],"ja":["モノレポのアーキテクチャを理解する必要がある","サーバーコンポーネントとサーバーアクションを使用するプロジェクトに限定される","Turborepoに依存してパッケージ管理を行う"],"ko":["모노레포 아키텍처를 이해해야 함","서버 컴포넌트 및 서버 액션을 사용하는 프로젝트에 제한됨","Turborepo에 의존하여 패키지 관리를 수행함"],"es":["Requiere comprensión de la arquitectura de monorepo","Limitado a proyectos que utilizan componentes de servidor y acciones de servidor","Dependiente de Turborepo para la gestión de paquetes"],"fr":["Nécessite une compréhension de l''architecture de monorepo","Limité aux projets utilisant des composants serveur et des actions serveur","Dépendant de Turborepo pour la gestion de packages"],"de":["Benötigt Verständnis der Monorepo-Architektur","Begrenzt auf Projekte, die Server-Komponenten und Server-Aktionen verwenden","Abhängig von Turborepo für die Paketverwaltung"],"pt":["Exige compreensão da arquitetura de monorepo","Limitado a projetos que utilizam Componentes de Servidor e Ações de Servidor","Dependente de Turborepo para gerenciamento de pacotes"],"ru":["Требует понимания архитектуры монорепозитория","Ограничен проектами, использующими компоненты сервера и действия сервера","Зависит от Turborepo для управления пакетами"],"ar":["يتطلب فهمًا لهيكل مونوريبو","محدود بمشاريع تستخدم مكونات الخادم وإجراءات الخادم","يعتمد على Turborepo لإدارة الحزم"]},"version":4},"contentHash":"d4ed01781e7867744450d4da848977235c69def894ee422035d8f07c0684a1a9","qualityScore":60}');
