INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wtthornton/TappsCodingAgents/tester', 'tester', 'wtthornton', 'TappsCodingAgents', 'community', 'tester wtthornton TappsCodingAgents community The Tester skill enables senior QA engineers to create comprehensive tests, ensuring code quality and reliability. It specializes in test generation, execution, and coverage reporting Tester是一种代码质量和可靠性测试解决方案，使用自动化测试和代码分析 Testerはコード品質と信頼性のためのテストフレームワークです Tester는 코드 품질과 신뢰성을 위한 테스트 솔루션입니다 El agente Tester es un experto en pruebas de SDLC que utiliza Context7 KB cache y pytest para garantizar la calidad del código L''agent Tester est un expert en tests de SDLC qui utilise Context7 KB cache et pytest pour garantir la qualité du code Der Tester Agent ist ein Experte für SDLC-Tests, der Context7 KB cache und pytest verwendet, um die Codequalität zu gewährleisten O agente Tester é um especialista em testes de código que cria testes abrangentes e manuteníveis. Ele utiliza pytest e Context7 KB cache para garantir a qualidade do código ИИ Агент Tester - это специалист по тестированию кода, который создает комплексные и поддерживаемые тесты. Он использует pytest и Context7 KB cache для обеспечения качества кода المحقق هو خبير في اختبارات الكود الذي يخلق اختبارات شاملة وقابلة للصيانة. يستخدم pytest و Context7 KB cache لضمان جودة الكود how to use tester tester setup guide tester alternative tester vs pytest what is tester tester install comprehensive test generation test coverage reporting tester for AI agents Tester AIエージェント 代码质量测试 自动化测试 Pytest 代码覆盖率 Context7 KB缓存 测试框架 最佳实践 Generates unit and integration tests from code analysis Runs pytest test suites for efficient test execution Tracks and reports test coverage for optimal code quality Utilizes Context7 KB cache for test framework documentation Follows project test patterns for maintainable tests Tester is a coding SDLC skill that facilitates comprehensive testing, including test generation, execution, and coverage reporting, for ensuring code quality and reliability');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HouseGarofalo/claude-code-base/azure-functions', 'community', 'HouseGarofalo', 'claude-code-base', 'HouseGarofalo/claude-code-base', 'azure-functions', 0, 0, 60, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.251Z', '958aa85bc40106add82dfd4eeb5366d9846eaeea46c290991de79080b11a2a38', '{"id":"HouseGarofalo/claude-code-base/azure-functions","name":"azure-functions","description":{"en":"The azure-functions skill enables developers to build serverless applications with Azure Functions, supporting event-driven computing and triggers like HTTP, timer, and queue triggers.","zh":"Azure Functions 是一个无服务器计算平台，支持事件驱动计算","ja":"Azure Functions は、サーバーレス コンピューティング プラットフォームであり、イベント ドリブン コンピューティングをサポートします","ko":"Azure Functions는 서버리스 컴퓨팅 플랫폼으로 이벤트 드리븐 컴퓨팅을 지원합니다","es":"Azure Functions es una plataforma de computación en la nube que permite crear aplicaciones serverless con triggers y bindings personalizables.","fr":"Azure Functions est une plateforme de calcul en nuage qui permet de créer des applications sans serveur avec des déclencheurs et des liaisons personnalisables.","de":"Azure Functions ist eine Cloud-Computing-Plattform, die die Erstellung serverloser Anwendungen mit anpassbaren Triggern und Bindungen ermöglicht.","pt":"O Azure Functions é uma plataforma de computação de eventos que permite criar aplicativos serverless. Aprenda a usar triggers, durable functions e function binding.","ru":"Azure Functions — это платформа для событийных вычислений, которая позволяет создавать серверные приложения. Узнайте, как использовать триггеры, долгосрочные функции и привязку функций.","ar":"وظيفة Azure هي منصة حسابية للأحداث التي تسمح بإنشاء تطبيقات بدون خادم. تعلم كيفية استخدام التriggers، الدوال المستدامة وربط الوظائف."},"seo":{"title":{"en":"Azure Functions: Serverless Setup Guide | AI Agent Skill","zh":"Azure Functions_S