INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HouseGarofalo/claude-code-base/azure-functions', 'azure-functions', 'HouseGarofalo', 'claude-code-base', 'community', 'azure-functions HouseGarofalo claude-code-base community The azure-functions skill enables developers to build serverless applications with Azure Functions, supporting event-driven computing and triggers like HTTP, timer, and queue triggers. Azure Functions 是一个无服务器计算平台，支持事件驱动计算 Azure Functions は、サーバーレス コンピューティング プラットフォームであり、イベント ドリブン コンピューティングをサポートします Azure Functions는 서버리스 컴퓨팅 플랫폼으로 이벤트 드리븐 컴퓨팅을 지원합니다 Azure Functions es una plataforma de computación en la nube que permite crear aplicaciones serverless con triggers y bindings personalizables. Azure Functions est une plateforme de calcul en nuage qui permet de créer des applications sans serveur avec des déclencheurs et des liaisons personnalisables. Azure Functions ist eine Cloud-Computing-Plattform, die die Erstellung serverloser Anwendungen mit anpassbaren Triggern und Bindungen ermöglicht. O Azure Functions é uma plataforma de computação de eventos que permite criar aplicativos serverless. Aprenda a usar triggers, durable functions e function binding. Azure Functions — это платформа для событийных вычислений, которая позволяет создавать серверные приложения. Узнайте, как использовать триггеры, долгосрочные функции и привязку функций. وظيفة Azure هي منصة حسابية للأحداث التي تسمح بإنشاء تطبيقات بدون خادم. تعلم كيفية استخدام التriggers، الدوال المستدامة وربط الوظائف. how to use azure functions azure functions setup guide azure functions vs aws lambda azure functions install what is azure functions azure functions alternative azure functions tutorial azure functions best practices azure functions serverless computing Azure Functions 无服务器计算 事件驱动计算 HTTP 触发器 Durable Functions 函数绑定 Azure Storage 资源组 Creates a function app with Azure Functions Supports HTTP trigger, timer trigger, and queue trigger Enables durable functions and orchestration Uses function binding and function.json configuration Initializes storage account with az storage account create command azure-functions is a comprehensive project template for building serverless applications with Azure Functions, supporting event-driven computing and various triggers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cdeistopened/OpenEd-Vault/video-caption-creation', 'community', 'cdeistopened', 'OpenEd-Vault', 'cdeistopened/OpenEd-Vault', 'video-caption-creation', 0, 0, 60, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.409Z', 'e53e5243f0911099e7c2e260b933a6725f0113e752df23b27ff0100234f03029', '{"id":"cdeistopened/OpenEd-Vault/video-caption-creation","name":"video-caption-creation","description":{"en":"The video-caption-creation skill generates on-screen text that adds context to audio, making it perfect for developers creating short-form videos. It helps developers create text that stops scrolls and boosts engagement.","zh":"视频字幕创建技能是短视频中最重要的视觉元素，能够在1秒内停止用户的滑动","ja":"動画キャプションは短形式動画における最重要の視覚要素であり、1秒以内にユーザーのスクロールを停止","ko":"비디오 자막은 短형動画에서 가장 중요한 시각적 요소로, 1초 이내에 사용자의 스크롤을 정지","es":"La creación de subtítulos de video es crucial para llamar la atención del usuario. Nuestra guía te muestra cómo hacerlo con Agentes de IA.","fr":"La création de légendes vidéo est essentielle pour capter l''attention de l''utilisateur. Notre guide vous explique comment le faire avec des Outils d''IA.","de":"Die Erstellung von Videountertiteln ist entscheidend, um die Aufmerksamkeit des Benutzers zu gewinnen. Unser Leitfaden zeigt Ihnen, wie Sie dies mit KI-Tools erreichen können.","pt":"Crie legendas de vídeo que param a rolagem com a ajuda de ferramentas de IA. Adicione contexto e faça com que os espectadores parem","ru":"Создайте видеокапшены, которые останавливают прокрутку с помощью ИИ агентов. Добавьте контекст и заставьте зрителей остановиться","ar":"إنشاء تعليقات على الفيديو التي توقف الإمتداد باستخدام أدوات الذكاء الاصطناعي. أضف السياق واجعلهم يتوقفون"},"seo":{"title":{"en":"video-caption-creation: On-Screen Text Generation Setup G...","zh":"AI视频字幕创建工具：实现吸引人的短视频","ja":"動画キャプション作成AIエージェント：スクロール停止の第一要素","ko":"AI 비디오 자막 생성 도구: 스크롤 정지의 핵심 요소","es":"Guía de configuración para la creación de subtítulos de v...","fr":"Configurer la création de légendes vidéo avec des Outils ...","de":"Einrichtungsleitfaden für die Erstellung von Videounterti...","pt":"Guia de Configuração de Criação de Legendas de Vídeo com ...","ru":"Настройка Создания Видеокапшенов с Помощью ИИ Агентов","ar":"دليل إعداد إنشاء التعليقات على الفيديو باستخدام أدوات الذ..."},"description":{"en":"Unlock the power of on-screen text in short-form videos with video-caption-creation. Learn how to create captivating captions that stop scrolls and boost eng...","zh":"利用视频字幕创建技能，打造吸引人的短视频，提高用户停留时间","ja":"動画キャプション作成AIエージェントを使用して、スクロール停止の効果的な動画を作成","ko":"AI 비디오 자막 생성 도구를 사용하여 스크롤 정지의 핵심 요소를 구현","es":"Aprende a crear subtítulos de video efectivos con nuestra guía sobre Agentes de IA para desarrolladores","fr":"Découvrez comment configurer la création de légendes vidéo avec des Outils d''IA pour améliorer l''expérience utilisateur","de":"Entdecken Sie, wie Sie mit KI-Tools effektive Videountertitel erstellen und die Benutzererfahrung verbessern können","pt":"Aprenda a criar legendas de vídeo atraentes com a ajuda de ferramentas de IA. Descubra como melhorar a experiência do usuário com texto em tela","ru":"Узнайте, как создавать привлекательные видеокапшены с помощью ИИ агентов. Улучшите пользовательский опыт с помощью текста на экране","ar":"تعلم كيفية إنشاء تعليقات على الفيديو جذابة باستخدام أدوات الذكاء الاصطناعي. تحسين تجربة المستخدم مع النص على الشاشة"},"definition":{"en":"video-caption-creation is a skill that generates on-screen text for short-form videos, following the Complementarity Principle to add context to audio and stop scrolls","zh":"视频字幕创建技能：一种AI工具，用于生成短视频中吸引人的字幕","ja":"動画キャプション作成AIエージェント：短形式動画用のキャプションを生成するAIツール","ko":"비디오 자막 생성 도구：短형動画用의 자막을 생성하는 AI툴","es":"La creación de subtítulos de video es el proceso de generar texto que se muestra en la pantalla para proporcionar contexto adicional a los videos.","fr":"La création de légendes vidéo est le processus de génération de texte qui s''affiche à l''écran pour fournir un contexte supplémentaire aux vidéos.","de":"Die Erstellung von Videountertiteln ist der Prozess der Generierung von Text, der auf dem Bildschirm angezeigt wird, um zusätzlichen Kontext für Videos bereitzustellen.","pt":"A criação de legendas de vídeo é a capacidade de gerar texto em tela que adiciona contexto e chama a atenção do espectador","ru":"Создание видеокапшенов - это способность генерировать текст на экране, который добавляет контекст и привлекает внимание зрителя","ar":"إنشاء التعليقات على الفيديو هو القدرة على توليد نص على الشاشة الذي يضيف السياق ويلفت انتباه المشاهد"},"features":{"en":["Generates on-screen text based on the Complementarity Principle","Creates text that adds context to audio, not labeling or repeating it","Supports the creation of short-form videos with engaging captions","Follows the central insight that on-screen text should do the primary work of stopping a scroll","Replaces previous version SKILL_v1_archive.md with improved functionality","Utilizes the concept of Triple Word Score for text generation"],"zh":["基于Complementarity Principle的字幕生成","支持短视频字幕的创建","能够在1秒内停止用户的滑动","集成了Triple Word Score算法","支持多语言字幕生成"],"ja":["Complementarity Principleに基づくキャプション生成","短形式動画用のキャプション作成をサポート","1秒以内にユーザーのスクロールを停止","Triple Word Scoreアルゴリズムを統合","多言語キャプション生成をサポート"],"ko":["Complementarity Principle 기반의 자막 생성","단편 동영상 자막 생성 지원","1초 이내에 사용자의 스크롤을 정지","Triple Word Score 알고리즘 통합","다국어 자막 생성 지원"],"es":["Aplicación del principio de complementariedad para agregar contexto adicional a los videos","Uso de texto en pantalla para captar la atención del usuario en menos de 1 segundo","Compatibilidad con la versión 2 del escritor de subtítulos y ganchos en pantalla","Incorporación de la puntuación triple de palabras para mejorar la efectividad de los subtítulos"],"fr":["Application du principe de complémentarité pour ajouter du contexte supplémentaire aux vidéos","Utilisation de texte à l''écran pour capter l''attention de l''utilisateur en moins de 1 seconde","Compatibilité avec la version 2 de l''outil d''écriture de légendes et de crochets à l''écran","Intégration de la notation triple de mots pour améliorer l''efficacité des légendes"],"de":["Anwendung des Komplementaritätsprinzips, um zusätzlichen Kontext für Videos bereitzustellen","Verwendung von Text auf dem Bildschirm, um die Aufmerksamkeit des Benutzers in weniger als 1 Sekunde zu gewinnen","Kompatibilität mit der Version 2 des Videountertitel- und On-Screen-Hook-Tools","Einbindung der Triple-Wort-Punktzahl, um die Effektivität der Untertitel zu verbessern"],"pt":["Geração de texto em tela com base no princípio da complementaridade","Criação de legendas que não repetem o áudio, mas adicionam contexto","Uso de tecnologias de IA para melhorar a experiência do usuário","Integração com React e Python para desenvolvedores","Compatibilidade com CLI para linha de comando"],"ru":["Генерация текста на экране на основе принципа дополнения","Создание видеокапшенов, которые не повторяют аудио, но добавляют контекст","Использование технологий ИИ для улучшения пользовательского опыта","Интеграция с React и Python для разработчиков","Совместимость с CLI для командной строки"],"ar":["توليد نص على الشاشة dựa على مبدأ التكميل","إنشاء تعليقات على الفيديو التي لا تتكرر الصوت، ولكن تضيف السياق","استخدام تقنيات الذكاء الاصطناعي لتحسين تجربة المستخدم","التكامل مع React و Python للمطورين","التوافق مع CLI لسطر الأوامر"]},"keywords":{"en":["how to use video-caption-creation","what is video-caption-creation","video-caption-creation alternative","video-caption-creation vs caption generators","video-caption-creation install","video-caption-creation setup guide","on-screen text generation for short-form videos","Complementarity Principle in video captions","Triple Word Score for text generation"],"zh":["AI视频字幕创建","短视频字幕生成","Complementarity Principle","Triple Word Score","视频营销工具","AI营销解决方案","短视频制作工具"],"ja":["動画キャプション作成AIエージェント","短形式動画キャプション生成","Complementarity Principle","Triple Word Score","動画マーケティングツール","AIマーケティングソリューション","短形式動画制作ツール"],"ko":["AI 비디오 자막 생성","단편 동영상 자막 생성","Complementarity Principle","Triple Word Score","비디오 마케팅 도구","AI 마케팅 솔루션","단편 동영상 제작 도구"],"es":["creación de subtítulos de video","Agentes de IA","desarrollo de video","subtítulos de video efectivos","principio de complementariedad","puntuación triple de palabras","version 2 del escritor de subtítulos"],"fr":["création de légendes vidéo","Outils d''IA","développement de vidéo","légendes vidéo efficaces","principe de complémentarité","notation triple de mots","version 2 de l''outil d''écriture de légendes"],"de":["Erstellung von Videountertiteln","KI-Tools","Vide_entwicklung","effektive Videountertitel","Komplementaritätsprinzip","Triple-Wort-Punktzahl","Version 2 des Videountertitel- und On-Screen-Hook-Tools"],"pt":["criação de legendas de vídeo","ferramentas de IA para vídeo","texto em tela","princípio da complementaridade","React","Python","CLI","desenvolvimento de vídeo","experiência do usuário"],"ru":["создание видеокапшенов","инструменты ИИ для видео","текст на экране","принцип дополнения","React","Python","CLI","разработка видео","пользовательский опыт"],"ar":["إنشاء التعليقات على الفيديو","أدوات الذكاء الاصطناعي للفيديو","نص على الشاشة","مبدأ التكميل","React","Python","CLI","تطوير الفيديو","تجربة المستخدم"]}},"owner":"cdeistopened","repo":"OpenEd-Vault","repoPath":"cdeistopened/OpenEd-Vault","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"video-caption-creation","description":"Create on-screen text hooks and captions for short-form video clips. Built around the Complementarity Principle - on-screen text should ADD to what the viewer hears, not repeat it. Includes podcast clip workflow, hook categories, and Triple Word Score optimization.","bodyPreview":"# Video Caption & On-Screen Hook Writer (v2)\n\nOn-screen text is the #1 visual element in short-form video. It does the PRIMARY work of stopping a scroll. A viewer sees the text and decides in <1 second whether to stop. This skill creates the text that makes them stop.\n\n**Previous version:** `SKILL_v1_archive.md` (basic Triple Word Score, retired Feb 2026)\n\n---\n\n## The Complementarity Principle\n\n**The central insight:** On-screen text should NOT label or repeat the audio. It should ADD context th","body":"# Video Caption & On-Screen Hook Writer (v2)\n\nOn-screen text is the #1 visual element in short-form video. It does the PRIMARY work of stopping a scroll. A viewer sees the text and decides in <1 second whether to stop. This skill creates the text that makes them stop.\n\n**Previous version:** `SKILL_v1_archive.md` (basic Triple Word Score, retired Feb 2026)\n\n---\n\n## The Complementarity Principle\n\n**The central insight:** On-screen text should NOT label or repeat the audio. It should ADD context that makes the audio land harder. The gap between what you read and what you hear creates curiosity.\n\nThis works exactly like title + thumbnail on YouTube: together they create a fuller picture than either alone. Andrew Muto: *\"You read the title, and then the thumbnail is offering you a little extra.\"*\n\n**Bad (labeling):** On-screen says \"Kids know.\" → Audio is about teacher dissatisfaction. Vague label, no gap.\n\n**Good (complementary):** On-screen says \"A kindergartner can tell\" → Audio reveals that 55% of teachers want to quit, and every morning a five-year-old walks into a classroom and senses it. The childlike framing + the adult data = productive tension.\n\n### The 6 Complementarity Patterns\n\n| Pattern | On-Screen Text Does | Audio Does | Why It Works |\n|---------|---------------------|------------|--------------|\n| **Question → Answer** | Asks a question | Delivers the answer | Open loop the viewer must close |\n| **Problem → Solution** | Names a pain point | Provides the fix | Viewer self-identifies, stays for relief |\n| **Framework → Content** | Names a strategy/concept | Explains what it means | \"What IS that?\" curiosity |\n| **Credential → Insight** | Establishes authority | Delivers the revelation | Trust signal makes content land harder |\n| **Teaser → Payoff** | Hints at what''s coming | Completes the thought | Narrative tension drives completion |\n| **Reframe → Evidence** | Challenges an assumption | Provides the proof | Cognitive dissonance demands resolution |\n\n### How Complementarity Works in Practice\n\n**Audio says:** *\"If we think that our public system''s path to victory will be to trap families, you''ve lost the argument.\"*\n\nThe text should NOT repeat \"you''ve lost the argument\" or \"trap families\" as a label. Instead, it adds a new layer:\n- **Question → Answer:** \"Schools trap families?\" - opens a loop the audio closes\n- **Reframe → Evidence:** \"You''re defunding yourself\" - adds a provocative angle the audio then explains\n- **Credential → Insight:** \"CEO of 80 microschools explains why...\" - trust signal that makes the bold claim land harder\n\n**Audio says:** *\"In a big school, kids just feel lost. So they retreat to the screen. Then we ban the screen, and they''re like, I''m still lost.\"*\n\nGood complementarity adds a new frame:\n- \"Why phone bans don''t work\" - reframes around the cultural conversation\n- \"80 schools. Zero phone problems.\" - credential that implies they solved it\n- \"In a big school, kids just feel lost. So they retreat to the screen. Then we ban the screen, and they''re like - I''m still lost.\" - sometimes the FULL quote IS the hook (see Length Variety below)\n\n---\n\n## The First-3-Words Test\n\nThe first 3 words someone reads do 80% of the work. Before finalizing any hook, check:\n\n**What are the first 3 words?**\n\n- \"A kindergartner can\" → Curiosity (can what?)\n- \"Schools trap families\" → Shock (they do?)\n- \"55% of teachers\" → Specificity (tells me this is data)\n- \"Why phone bans\" → Promise (I''m about to learn something)\n\n**Weak first 3 words:**\n- \"Here''s what happens\" → Generic, could be anything\n- \"Check this out\" → Zero information\n- \"In this clip\" → Meta, breaks immersion\n- \"You need to\" → Commanding without earning attention\n\n**Front-load the punch.** Move the most surprising, specific, or provocative word as close to position 1 as possible.\n\n---\n\n## Length Variety (Critical)\n\n**Every set of 3-4 hook options MUST include different lengths.** This is non-negotiable. If all your hooks are 3-5 word punchy phrases, you''re in a rut.\n\n| Length | Word Count | When It Works | Example |\n|--------|-----------|---------------|---------|\n| **Punchy** | 2-4 words | Stats, named frameworks, provocative labels | \"Homework is a scam\" |\n| **Statement** | 5-8 words | Reframes, challenges, credential leads | \"His parents almost cut off his entire career\" |\n| **Narrative** | 9-15 words | Story setups, scenario hooks, before/after | \"I tried every AI tool so you don''t have to\" |\n| **Full quote** | 15+ words | When the quote itself IS the hook (rare, powerful) | \"Kids learn to walk at different ages... so why do we make every kid learn algebra at the same age?\" |\n\n**The trap:** AI defaults to short and punchy because it pattern-matches \"hook = headline.\" Fight this. Some of the best-performing on-screen text is conversational and long.\n\n---\n\n## Proven Hook Library\n\nThese are original examples from research into viral short-form content. They''re organized by format/archetype. **Preserve the originals** - they have more texture than anything we''d rewrite. Use framework fitting at runtime to adapt them to specific content.\n\n### Results and Transformation\n\n| Framework | Proven Example | Lever |\n|-----------|---------------|-------|\n| \"How I [result]\" | \"How I hit 100k views in 7 days\" | Social proof + utility |\n| \"[Before] vs [After]\" | \"My $10M company vs my first $100 sale\" | Rags-to-riches narrative |\n| \"The one [niche] tip that changed everything\" | \"The one lighting tip that fixed my videos\" | High-ROI promise |\n| \"I did [action] so you don''t have to\" | \"I tried every AI tool so you don''t have to\" | Utility + time-saving |\n| \"How to [goal] with zero [pain point]\" | \"How to build an app with zero coding\" | Barrier removal |\n\n### Curiosity Gap and Contrarian\n\n| Framework | Proven Example | Lever |\n|-----------|---------------|-------|\n| \"Stop doing [action] if you want [result]\" | \"Stop doing bench press if you want chest growth\" | Pattern interrupt + urgency |\n| \"You''ve been [action] wrong your whole life\" | \"You''ve been folding your shirts all wrong\" | Challenges assumptions |\n| \"What they don''t want you to know about [topic]\" | \"What banks don''t want you to know about debt\" | Forbidden knowledge |\n| \"Everyone is wrong about [topic]\" | \"Everyone is wrong about passive income\" | Cognitive dissonance |\n| \"This mistake cost me [amount]\" | \"This one mistake cost me $2,300\" | Financial stakes |\n\n### Authority and \"Secret\"\n\n| Framework | Proven Example | Lever |\n|-----------|---------------|-------|\n| \"No one talks about this in [industry]\" | \"No one talks about this in the creator economy\" | Exclusivity |\n| \"I probably shouldn''t share this, but...\" | \"I probably shouldn''t share this airline loophole\" | Insider access |\n| \"The biggest secret about [topic]\" | \"The biggest secret about starting a business\" | Curiosity gap |\n| \"3 [tools/things] that feel illegal to know\" | \"3 AI tools that feel illegal to know\" | Rule-breaking novelty |\n| \"I wish I knew this [time] ago\" | \"I wish I knew this before I turned 30\" | Wisdom through regret |\n\n### Question and Relatability\n\n| Framework | Proven Example | Lever |\n|-----------|---------------|-------|\n| \"If you''re a [identity], watch this\" | \"If you''re a SaaS founder, watch this\" | Self-identification |\n| \"Do you struggle with [problem]?\" | \"Do you struggle with falling asleep?\" | Pain point |\n| \"Can you guess what happens if you [action]?\" | \"Can you guess what happens if you quit sugar?\" | Suspense |\n| \"Are you making this mistake in [action]?\" | \"Are you making this mistake in your morning routine?\" | Fear of error |\n| \"If you''ve ever...\" | \"If you''ve ever unbuttoned your jeans at dinner...\" | Hyper-specificity |\n\n### Education/Parenting Originals (from Andrew Muto research)\n\nThese are proven hooks from education creators - closer to our audience:\n\n**Short punchy:**\n- \"Homework is a scam\"\n- \"Your kid''s C+ is fine\"\n- \"Your ADHD kid isn''t broken\"\n\n**Statement length:**\n- \"Screen time isn''t the problem. Boredom is.\"\n- \"Neurodivergent kids aren''t the problem. The system is.\"\n- \"5 Signs Your Kid Doesn''t Actually Hate Math\"\n\n**Narrative length:**\n- \"Kids don''t hate math. They hate how it''s taught.\"\n- \"Edison was kicked out of school for being ''too curious''\"\n- \"They said homeschooled kids won''t socialize. Have you met public schoolers?\"\n- \"His kids skipped school for 100 days. Here''s what happened.\"\n- \"Finland banned homework below age 10. Now they''re #1 in education.\"\n\n**Full quote / conversational:**\n- \"My kids socialize with humans of all ages, not just 24 kids born the same year\"\n- \"Kids learn to walk at different ages... so why do we make every kid learn algebra at the same age?\"\n- \"Things I don''t explain to strangers anymore: Why my kids aren''t in school\"\n\n### Podcast Clip Archetypes (from research report)\n\n| Archetype | Role | Trigger | Example |\n|-----------|------|---------|---------|\n| **The Teacher** | Provide fast, actionable value | Utility + expertise | \"3 ways to make your next video go viral\" |\n| **The Investigator** | Reveal a hidden truth | Exclusivity + FOMO | \"No one''s talking about this - but it changes everything\" |\n| **The Contrarian** | Challenge popular belief | Cognitive dissonance | \"Hashtags don''t actually help your reach. Here''s why\" |\n| **The Fortuneteller** | Hint at transformation | Aspiration + reward | \"Here''s what happened when I quit caffeine for 30 days\" |\n| **The Experimenter** | Share trial results | Curiosity + relatability | \"I posted 3 times a day for a week. Here''s what happened\" |\n\n---\n\n## Framework Fitting at Runtime\n\nThe Proven Hook Library above contains TEMPLATES. When generating hooks for a specific clip, use framework fitting:\n\n1. **Read the clip transcript** - find the hookable moment\n2. **Scan the library** - which framework fits this moment?\n3. **Adapt the framework** to the specific content, preserving the format''s proven structure\n4. **Vary the length** - each set of 3-4 options should span at least 2 different length categories\n\n**Example:** If the clip is about a microschool founder who discovered mixed-age classrooms work:\n- Punchy: \"The Trojan horse classroom\" (Named Framework)\n- Statement: \"Teachers hate this. Then something flips.\" (Curiosity Gap)\n- Narrative: \"She put 3 grades in one room. Teachers hated it. Then something flipped.\" (Fortuneteller)\n- Full quote: \"The mixed-age classroom can be a Trojan horse to introduce a totally different way of teaching.\" (when the quote itself is gold)\n\n---\n\n## Podcast Clip On-Screen Hook Workflow\n\nThis is the step-by-step process for generating hooks from podcast transcript clips. Used by the podcast-production skill at Step 4.\n\n### Step 1: Identify the Hookable Moment\n\nScan the clip transcript for one of these triggers (SURP framework):\n- **S**urprising fact or statistic (\"55% of teachers want to leave\")\n- **U**nexpected quote or bold statement (\"you''ve lost the argument\")\n- **R**elatable problem (\"kids feel lost, so they retreat to the screen\")\n- **P**rovocative opinion (\"our path to victory will be to trap families\")\n\nThe hookable moment is usually NOT the first sentence of the clip. Find the single line that would make someone stop scrolling if they saw it as a headline.\n\n### Step 2: Determine the Complementarity Pattern\n\nAsk: What would ADD the most to what the viewer hears?\n\n| If the audio... | Best pattern | On-screen text should... |\n|-----------------|-------------|------------------------|\n| Makes a bold claim | Reframe → Evidence | Challenge the assumption the claim disproves |\n| Tells a story | Teaser → Payoff | Hint at the ending without revealing it |\n| Cites data/stats | Question → Answer | Ask the question the stat answers |\n| Introduces a framework | Framework → Content | Name the framework |\n| Gives advice | Problem → Solution | Name the problem the advice solves |\n| Shares credentials | Credential → Insight | Lead with the credential |\n\n### Step 3: Generate 3-4 Hook Options\n\nFor each clip, write 3-4 options with LENGTH VARIETY. Each set should span at least 2 different length categories (punchy, statement, narrative, full quote).\n\nScan the Proven Hook Library for a matching framework. Adapt the framework to this specific content while preserving the format''s proven structure.\n\n### Step 4: Apply Quality Gates\n\nFor each option, check:\n- [ ] **First-3-Words Test:** First 3 words carry the punch?\n- [ ] **McDonald''s Test:** Someone at McDonald''s understands instantly?\n- [ ] **Scroll Test:** Would I personally stop scrolling?\n- [ ] **Gap Test:** Text + audio create a gap, not a repeat?\n- [ ] **Grandmother Test:** My grandmother gets what this is about?\n\n### Step 5: Mark Recommended Pick\n\nSelect one recommended option and explain WHY in one sentence. The rationale should reference the complementarity - how the text and audio work together.\n\n---\n\n## Identifying Hookable Moments in Transcripts\n\nWhen scanning a full transcript (before clips are selected), look for:\n\n**Tier 1: Almost always hookable**\n- Specific statistics (\"55% of teachers want to leave\")\n- Named concepts or frameworks the speaker coined\n- Moments that contradict popular belief\n- Emotional peaks (speaker''s voice changes, pace quickens)\n- Universal pain points (\"every parent knows...\")\n\n**Tier 2: Often hookable**\n- Personal confessions or vulnerable moments\n- \"I should probably not say this, but...\"\n- Origin stories (how they started, what went wrong)\n- Direct statements that take a side\n\n**Tier 3: Rarely hookable (avoid)**\n- Agreement moments (\"yeah, totally, I think so too\")\n- Background context / scene-setting\n- Nuanced, heavily-caveated statements\n- Inside baseball (jargon-heavy industry talk)\n\n**The whole transcript matters.** The strongest moment might be at minute 48. Don''t mine just the first half.\n\n---\n\n## The Triple Word Score System\n\nFour signals must align so algorithms AND humans immediately know \"this is for me\":\n\n### 1. Audio Transcript (MOST IMPORTANT)\n- What the speaker says out loud - algorithms auto-transcribe this\n- Topic words must appear in first 10 seconds\n- Core terminology repeated naturally throughout\n\n### 2. On-Screen Text Hook\n- Visual overlay using complementarity principle (above)\n- NOT a repetition of the audio - an addition to it\n- Lead with topic words in the hook\n\n### 3. Caption Copy\n- Post description with topic-relevant keywords\n- Opens with a topic-relevant phrase\n- Provides context the algorithm needs\n\n### 4. Strategic Hashtags\n- 10-12 total (optimal range)\n- Broad → Mid → Specific → Niche → Audience → Platform\n- Example: #Education #Parenting #Homeschool #Microschools #SchoolChoice #HomeschoolMom #Shorts\n\n**When all four align, the algorithm recognizes the topic immediately and serves it to the right people.**\n\n---\n\n## Caption Writing\n\n### Short-Form Platforms (Same Caption Everywhere)\n\n**Applies to:** YouTube Shorts, Instagram Reels, TikTok, Facebook Reels\n\nOne caption per clip. Don''t write platform-specific versions (waste of time, same audience).\n\n**Format:**\n```\n[Verbatim quote or key insight from clip - 1-2 sentences]\n[Context: who the speaker is and why it matters - 1 sentence]\n\n#Hashtags (10-12)\n```\n\n**Optional X Variant:**\nShorter, more conversational. Include @handles. Drop the context sentence.\n\n### Caption Quality Check\n- [ ] Opens with the strongest line from the clip\n- [ ] Includes guest name and title\n- [ ] Hashtags span broad to niche\n- [ ] Under 150 characters for the hook portion\n- [ ] No emojis in body (rare exceptions for social captions)\n\n---\n\n## Output Format\n\nWhen this skill is invoked (standalone or from podcast-production), produce this per clip:\n\n```markdown\n### [Clip Name]\n\n**Timestamp range:** [MM:SS-MM:SS]\n\n**On-screen hook options:**\n1. \"[Hook text]\" *\n2. \"[Hook text]\"\n3. \"[Hook text]\"\n4. \"[Hook text]\"\n\n(* = recommended pick. List 3-4 options. Star goes on the strongest.)\n\n**Caption (FB, TikTok, IG, LinkedIn):**\n[Caption text]\n\n**X variant:**\n[Shorter caption with @handles]\n```\n\n**Keep it clean.** No category labels, no rationale paragraphs. The hooks should speak for themselves. Use the complementarity principle and quality gates internally when generating, but the output is just the options with a star.\n\n---\n\n## Sub-Agent Prompt Template\n\nWhen podcast-production invokes this skill at Step 4, use this prompt:\n\n```\nYou are generating on-screen text hooks for podcast clips.\n\nEpisode: [Guest Name]\nWorking directory: [path to prep/]\n\nRead the following files:\n- SOURCE.md (full transcript for context)\n- EDITOR_HANDOFF.md (clips already selected in Sections 3 & 4)\n\nFor EACH clip in Sections 3 and 4, generate 3-4 on-screen hook options.\nMark the recommended pick with an asterisk (*).\n\nOutput format per clip:\n1. \"Hook text\" *\n2. \"Hook text\"\n3. \"Hook text\"\n4. \"Hook text\"\n\nNo category labels. No rationale paragraphs. Just the options with a star.\n\nInternal rules (apply these but don''t show them in output):\n- On-screen text ADDS to audio, never repeats it (Complementarity Principle)\n- Apply the First-3-Words Test to every option\n- Apply McDonald''s Test (instantly understandable)\n- VARY THE LENGTH across options: at least one short punchy (2-5 words), one statement (6-8 words), and one narrative or full-quote (9+ words). Do NOT default to all short punchy hooks.\n- Scan the Proven Hook Library in the skill for matching frameworks\n- Framework fit the proven templates to the specific content\n\nWrite the hooks directly into the EDITOR_HANDOFF.md clip sections.\n```\n\n---\n\n## Exemplar Channels (Study These)\n\n### Podcast Clip Masters\n- **Diary of a CEO** (@doac.clips) - Animated text, credential leads, emotional transitions. Opens with guest in chair + text hook. Text builds anticipation without giving away payoff.\n- **My First Million** (clips channel) - Entrepreneurship hooks, \"how to\" + numbers format\n- **Huberman Lab** (Essentials) - Dense science distilled to protocols. Direct promise hooks.\n- **Lex Fridman Clips** - Topic-based text overlays for philosophical conversations\n\n### Education/Parenting Creators\n- **Dr. Becky Kennedy** (@drbeckyatgoodinside, 3M) - Named strategy hooks (\"The REPAIR Strategy\"), problem → solution format\n- **Big Little Feelings** (@biglittlefeelings, 3.6M) - \"When your toddler refuses to...\" pain point hooks\n- **Busy Toddler** (@busytoddler, 2.4M) - Action-oriented \"This LEGO hack will...\"\n- **@thatcalteacherlife** (508K) - Working parents + homeschool\n- **@deal_family** (352K) - Second-gen homeschool mom\n- **@littlefenders** (132K) - \"Redefining learning + parenting / Educating kids with AI / Unschooling / ADHD Mom\"\n\n### Key Patterns from Top Performers\n1. **Text = Question, Audio = Answer** (Dr. Becky)\n2. **Text = Named Framework, Audio = Explanation** (Dr. Becky)\n3. **Text = Credential, Audio = Insight** (DOAC)\n4. **Text = Problem, Audio = Solution** (Big Little Feelings)\n5. **Text = Teaser, Audio = Payoff** (DOAC)\n\n---\n\n## Common Mistakes\n\n- **All hooks the same length:** The #1 mistake. If every option is 3-5 word punchy headlines, you haven''t explored the full range. Mix punchy with narrative with full-quote.\n- **Labeling instead of complementing:** \"Kids know.\" is a label. \"A kindergartner can tell\" is a hook.\n- **Giving away the payoff in text:** If the text reveals the full insight, there''s no reason to watch.\n- **Generic first 3 words:** \"Here''s what happens\" could be anything. \"55% of teachers\" is specific.\n- **Only one hook per clip:** Always generate 3-4. The first idea is rarely the best.\n- **Rewriting proven templates instead of adapting them:** The original examples have texture. Framework fit them to your content at runtime - don''t pre-sanitize the library.\n- **Hooks that need the clip to make sense:** The hook must work for a silent, scrolling viewer who hasn''t heard a word yet.\n- **Fancy vocabulary:** \"Pedagogical paradigm shift\" fails the McDonald''s test. \"Schools are broken\" passes.\n\n---\n\n## Related Skills\n\n- `podcast-production` - Invokes this skill at Step 4 (on-screen hook generation)\n- `short-form-video` - Full production workflow (this skill handles text only)\n- `text-content` - For text-only social posts (LinkedIn, X, not video)\n- `youtube-title-creator` - Title + thumbnail (same complementarity principle, different application)\n- `cold-open-creator` - Cold opens use [SWOOSH] transitions, not hooks\n\n---\n\n## Research References\n\n- `Short-Form Video Text Hook Strategies.md` - Comprehensive report on hook psychology, typography, retention\n- Andrew Muto notes: `Studio/_archive/Archive/Andrew Muto/` - Complementarity, McDonald''s test, 15-min rule, hook categories\n- Podcast-production skill improvement notes: `Studio/Podcast Studio/Amar-Kumar/prep/SKILL_IMPROVEMENT_NOTES.md`\n\n---\n\n*Rewritten Feb 6, 2026 after Amar Kumar podcast session. Incorporates complementarity principle, first-3-words test, 6 hook categories, SURP framework, and worked examples from real clips.*\n"},"lastSynced":"2026-03-08T02:02:40.409Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing advanced video caption generation capabilities to boost engagement.","zh":"非常适合需要高级视频字幕生成功能以提升参与度的内容创作智能体。","ja":"エンゲージメントを高める高度なビデオキャプション生成機能を必要とするコンテンツ制作エージェントに最適です。","ko":"참여도를 높이기 위해 고급 비디오 자막 생성 기능이 필요한 콘텐츠 제작 에이전트에 완벽합니다.","es":"Perfecto para agentes de creación de contenido que necesitan capacidades avanzadas de generación de subtítulos de video para aumentar la participación.","fr":"Parfait pour les agents de création de contenu ayant besoin de capacités avancées de génération de légendes de vidéo pour améliorer l''engagement.","de":"Perfekt für Content Creation Agents, die erweiterte Videountertitel-Generierungsfunktionen benötigen, um die Interaktion zu steigern.","pt":"Perfeito para Agentes de Criação de Conteúdo que necessitam de capacidades avançadas de geração de legendas de vídeo para impulsionar o engajamento.","ru":"Идеально подходит для агентов по созданию контента, которым необходимы продвинутые возможности генерации подписей к видео для повышения вовлеченности.","ar":"مثالي لوكلاء إنشاء المحتوى الذين يحتاجون إلى إمكانيات متقدمة لإنشاء نصوص الفيديو لتعزيز المشاركة."},"recommendation":{"en":"Empowers agents to generate attention-grabbing on-screen text that adds context to audio, utilizing the Complementarity Principle to create captivating video captions, and supports short-form video development with enhanced visual elements.","zh":"赋能智能体生成吸引注意力的屏幕文本，为音频添加上下文，利用互补性原则创建引人入胜的视频字幕，并通过增强的视觉元素支持短视频开发。","ja":"オーディオにコンテキストを追加する注目を集めるオンスクリーンテキストを生成し、相補性の原則を利用して魅力的なビデオキャプションを作成し、強化されたビジュアル要素でショートフォームビデオ開発をサポートするようにエージェントを強化します。","ko":"오디오에 컨텍스트를 추가하는 주목을 끄는 온스크린 텍스트를 생성하고, 상보성 원리를 활용하여 매력적인 비디오 자막을 만들며, 향상된 시각적 요소로 숏폼 비디오 개발을 지원하도록 에이전트에 권한을 부여합니다.","es":"Habilita a los agentes a generar texto en pantalla atractivo que agrega contexto a audio, utilizando el Principio de Complementariedad para crear subtítulos de video atractivos, y admite el desarrollo de videos de formato corto con elementos visuales mejorados.","fr":"Permet aux agents de générer un texte à l''écran accrocheur qui ajoute du contexte à l''audio, en utilisant le Principe de Complémentarité pour créer des légendes de vidéo accrocheuses, et prend en charge le développement de vidéos de format court avec des éléments visuels améliorés.","de":"Ermächtigt die Agenten, auffälligen On-Screen-Text zu generieren, der Kontext zu Audio hinzufügt, indem das Komplementaritätsprinzip verwendet wird, um fesselnde Videountertitel zu erstellen, und unterstützt die Entwicklung von Kurzvideos mit verbesserten visuellen Elementen.","pt":"Habilita os agentes a gerar texto na tela que chama a atenção e adiciona contexto ao áudio, utilizando o Princípio da Complementaridade para criar legendas de vídeo cativantes, e suporta o desenvolvimento de vídeos em formato curto com elementos visuais aprimorados.","ru":"Наделяет агентов возможностью генерировать текст на экране, который привлекает внимание и добавляет контекст к аудио, используя Принцип дополнительности для создания увлекательных видео-подписей, и поддерживает разработку коротких видеороликов с улучшенными визуальными элементами.","ar":"يتمكن الوكلاء من generar نص على الشاشة الذي يلفت الانتباه ويضيف السياق إلى الصوت، مستخدمين مبدأ التكامل لإنشاء نصوص فيديو جذابة، ودعم تطوير فيديوهات قصيرة مع عناصر بصرية محسنة."},"useCases":{"en":["Automating video caption creation for social media platforms","Generating on-screen text that stops scrolls and increases viewer engagement","Creating contextual text that complements audio in short-form videos"],"zh":["为社交媒体平台自动化视频字幕创建","生成能够停止滚动并增加观众参与度的屏幕文本","在短视频中创建与音频互补的上下文文本"],"ja":["ソーシャルメディアプラットフォーム向けのビデオキャプション作成の自動化","スクロールを停止させ視聴者エンゲージメントを高めるオンスクリーンテキストの生成","ショートフォームビデオでオーディオを補完するコンテキストテキストの作成"],"ko":["소셜 미디어 플랫폼을 위한 비디오 자막 생성 자동화","스크롤을 멈추고 시청자 참여를 증가시키는 온스크린 텍스트 생성","숏폼 비디오에서 오디오를 보완하는 컨텍스트 텍스트 생성"],"es":["Automatización de la creación de subtítulos de video para plataformas de redes sociales","Generación de texto en pantalla que detiene los desplazamientos y aumenta la participación del espectador","Creación de texto contextual que complementa el audio en videos de formato corto"],"fr":["Automatisation de la création de légendes de vidéo pour les plateformes de médias sociaux","Génération de texte à l''écran qui arrête les défilements et augmente l''engagement du spectateur","Création de texte contextuel qui complète l''audio dans les vidéos de format court"],"de":["Automatisierung der Erstellung von Videountertiteln für soziale Medienplattformen","Generierung von On-Screen-Text, der Scrollvorgänge stoppt und die Zuschauerbeteiligung erhöht","Erstellung von Kontext-Text, der Audio in Kurzvideos ergänzt"],"pt":["Automatizar a criação de legendas de vídeo para plataformas de mídia social","Gerar texto na tela que para a rolagem e aumenta o engajamento do visualizador","Criar texto contextual que complementa o áudio em vídeos em formato curto"],"ru":["Автоматизация создания подписей к видео для социальных медиа-платформ","Генерация текста на экране, который останавливает прокрутку и увеличивает вовлеченность зрителя","Создание контекстного текста, который дополняет аудио в коротких видеороликах"],"ar":["تأتميم إنشاء نصوص الفيديو للمنصات الإعلامية الاجتماعية","توليد نص على الشاشة الذي يوقف التمرير ويزيد من مشاركة المشاهد","إنشاء نص سياقي يكمّل الصوت في فيديوهات قصيرة"]},"limitations":{"en":["Requires understanding of the Complementarity Principle","Optimized for short-form video content","May require additional development for long-form video support"],"zh":["需要理解互补性原则","针对短视频内容进行了优化","可能需要对长篇视频支持进行额外开发"],"ja":["相補性の原則の理解が必要","ショートフォームビデオコンテンツに最適化されている","ロングフォームビデオサポートには追加の開発が必要な場合がある"],"ko":["상보성 원리에 대한 이해가 필요함","숏폼 비디오 콘텐츠에 최적화됨","롱폼 비디오 지원을 위해 추가 개발이 필요할 수 있음"],"es":["Requiere comprensión del Principio de Complementariedad","Optimizado para contenido de video de formato corto","Puede requerir desarrollo adicional para admitir videos de largo formato"],"fr":["Nécessite une compréhension du Principe de Complémentarité","Optimisé pour le contenu de vidéo de format court","Peut nécessiter un développement supplémentaire pour prendre en charge les vidéos de long format"],"de":["Erfordert Verständnis des Komplementaritätsprinzips","Optimiert für Kurzvideo-Inhalte","Kann zusätzliche Entwicklung für die Unterstützung von Langvideo-Inhalten erfordern"],"pt":["Requer entendimento do Princípio da Complementaridade","Otimizado para conteúdo de vídeo em formato curto","Pode requerer desenvolvimento adicional para suportar vídeos em formato longo"],"ru":["Требует понимания Принципа дополнительности","Оптимизирован для контента коротких видеороликов","Может потребовать дополнительной разработки для поддержки длинных видеороликов"],"ar":["يتطلب فهم مبدأ التكامل","مُحسّن ل내容 الفيديو القصير","يمكن أن يتطلب تطويرًا إضافيًا لدعم فيديوهات طويلة"]},"version":4},"contentHash":"e53e5243f0911099e7c2e260b933a6725f0113e752df23b27ff0100234f03029","qualityScore":60}');
