INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cdeistopened/OpenEd-Vault/video-caption-creation', 'video-caption-creation', 'cdeistopened', 'OpenEd-Vault', 'community', 'video-caption-creation cdeistopened OpenEd-Vault community The video-caption-creation skill generates on-screen text that adds context to audio, making it perfect for developers creating short-form videos. It helps developers create text that stops scrolls and boosts engagement. 视频字幕创建技能是短视频中最重要的视觉元素，能够在1秒内停止用户的滑动 動画キャプションは短形式動画における最重要の視覚要素であり、1秒以内にユーザーのスクロールを停止 비디오 자막은 短형動画에서 가장 중요한 시각적 요소로, 1초 이내에 사용자의 스크롤을 정지 La creación de subtítulos de video es crucial para llamar la atención del usuario. Nuestra guía te muestra cómo hacerlo con Agentes de IA. La création de légendes vidéo est essentielle pour capter l''attention de l''utilisateur. Notre guide vous explique comment le faire avec des Outils d''IA. Die Erstellung von Videountertiteln ist entscheidend, um die Aufmerksamkeit des Benutzers zu gewinnen. Unser Leitfaden zeigt Ihnen, wie Sie dies mit KI-Tools erreichen können. Crie legendas de vídeo que param a rolagem com a ajuda de ferramentas de IA. Adicione contexto e faça com que os espectadores parem Создайте видеокапшены, которые останавливают прокрутку с помощью ИИ агентов. Добавьте контекст и заставьте зрителей остановиться إنشاء تعليقات على الفيديو التي توقف الإمتداد باستخدام أدوات الذكاء الاصطناعي. أضف السياق واجعلهم يتوقفون how to use video-caption-creation what is video-caption-creation video-caption-creation alternative video-caption-creation vs caption generators video-caption-creation install video-caption-creation setup guide on-screen text generation for short-form videos Complementarity Principle in video captions Triple Word Score for text generation AI视频字幕创建 短视频字幕生成 Complementarity Principle Triple Word Score 视频营销工具 AI营销解决方案 短视频制作工具 Generates on-screen text based on the Complementarity Principle Creates text that adds context to audio, not labeling or repeating it Supports the creation of short-form videos with engaging captions Follows the central insight that on-screen text should do the primary work of stopping a scroll Replaces previous version SKILL_v1_archive.md with improved functionality Utilizes the concept of Triple Word Score for text generation video-caption-creation is a skill that generates on-screen text for short-form videos, following the Complementarity Principle to add context to audio and stop scrolls');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('outseta/outseta-vibe-coding-CMS/convex', 'community', 'outseta', 'outseta-vibe-coding-CMS', 'outseta/outseta-vibe-coding-CMS', 'convex', 0, 0, 60, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.649Z', '6359ffba973884ddcfb4b14a7d4059bf56033e396fde231b829c1d5a0260abba', '{"id":"outseta/outseta-vibe-coding-CMS/convex","name":"convex","description":{"en":"Convex is a Proof of Concept project that demonstrates the integration of Outseta for authentication, CRM, and billing, benefiting developers and AI agents. It provides a framework for building custom functions and HTTP endpoints.","zh":"Convex 项目是一个 Proof of Concept，展示了 Outseta 的集成，用于身份验证、CRM 和计费","ja":"Convex プロジェクトは、Outseta の統合を示す Proof of Concept で、認証、CRM、請求書を提供します","ko":"Convex 프로젝트는 Outseta의 통합을 보여주는 개념 증명입니다. 인증, CRM, 청구를 제공합니다","es":"Convex es un proyecto de prueba de concepto que demuestra la integración de Outseta para autenticación, CRM y facturación. Aprende a utilizar la sintaxis de función y los puntos de conexión HTTP","fr":"Convex est un projet de preuve de concept qui démontre l''intégration d''Outseta pour l''authentification, la gestion de la relation client et la facturation. Découvrez la syntaxe de fonction et les points de terminaison HTTP","de":"Convex ist ein Proof-of-Concept-Projekt, das die Integration von Outseta für Authentifizierung, CRM und Abrechnung demonstriert. Erfahren Sie, wie Sie die Funktions-Syntax und die HTTP-Endpunkte verwenden","pt":"O Convex é uma prova de conceito que demonstra a integração com Outseta para autenticação, CRM e faturamento. Aprenda a criar funções e endpoints HTTP com o novo sintaxe de função.","ru":"Convex - это доказательство концепции, демонстрирующее интеграцию с Outseta для аутентификации, CRM и выставления счетов. Узнайте, как создавать функции и HTTP-конечные точки с новым синтаксисом функций.","ar":"Convex هو برهان مفهوم يظهر تكامل Outseta للتحقق من الهوية وإدارة علاقات العملاء وعمليات الفواتير. تعلم كيفية إنشاء الدوال ونقاط النهاية HTTP باستخدام بناء الجملة الجديد للوظيفة."},"seo":{"title":{"en":"Convex: Setup Guide for AI Agents | AI Agent Skill","zh":"Convex_SETUP_GUIDE","ja":"Convex_セットアップガイド","ko":"Convex_설치_가이드","es":"Convex: Guía de configuración para desarrolladores","fr":"Convex: Guide de démarrage pour les développeurs","de":"Convex: Einrichtungsleitfaden für Entwickler","pt":"Convex: Guia de Configuração de Funções e Endpoints HTTP","ru":"Convex: Руководство по настройке функций и HTTP-конечных ...","ar":"Convex: دليل إعداد الدوال ونقاط النهاية HTTP"},"description":{"en":"Discover how to integrate Outseta with Convex for authentication, CRM, and billing. Learn the best practices for using Convex functions and HTTP endpoints.","zh":"Convex 技术指南：了解 Convex 函数语法和 HTTP 端点定义","ja":"Convex 技術ガイド：Convex 関数の構文と HTTP エンドポイントの定義について","ko":"Convex 기술 가이드: Convex 함수 문법과 HTTP 엔드포인트 정의","es":"Aprende a integrar Outseta con Convex para autenticación, CRM y facturación. Descubre las mejores prácticas para desarrolladores","fr":"Découvrez comment intégrer Outseta avec Convex pour l''authentification, la gestion de la relation client et la facturation. Conseils pour les développeurs","de":"Erfahren Sie, wie Sie Outseta mit Convex für Authentifizierung, CRM und Abrechnung integrieren. Entwickler-Tipps und -Tricks","pt":"Aprenda a integrar o Convex com Outseta para autenticação, CRM e faturamento, e descubra as melhores práticas para criar funções e endpoints HTTP","ru":"Узнайте, как интегрировать Convex с Outseta для аутентификации, CRM и выставления счетов, и откройте для себя лучшие практики создания функций и HTTP-конечны...","ar":"تعلم كيفية دمج Convex مع Outseta للتحقق من الهوية وإدارة علاقات العملاء وعمليات الفواتير، واكتشف أفضل الممارسات لإنشاء الدوال ونقاط النهاية HTTP"},"definition":{"en":"Convex is a project that integrates Outseta for authentication, CRM, and billing, using technologies like TypeScript and Convex values.","zh":"Convex 是一个使用 TypeScript 和 Convex 值的函数语法","ja":"Convex は、TypeScript と Convex 値を使用した関数の構文です","ko":"Convex는 TypeScript와 Convex 값을 사용하는 함수 문법입니다","es":"Convex es un proyecto de prueba de concepto que integra Outseta para autenticación, CRM y facturación","fr":"Convex est un projet de preuve de concept qui intègre Outseta pour l''authentification, la gestion de la relation client et la facturation","de":"Convex ist ein Proof-of-Concept-Projekt, das Outseta für Authentifizierung, CRM und Abrechnung integriert","pt":"O Convex é uma tecnologia que permite a integração com Outseta para autenticação, CRM e faturamento, utilizando um novo sintaxe de função para criar funções e endpoints HTTP.","ru":"Convex - это технология, позволяющая интегрироваться с Outseta для аутентификации, CRM и выставления счетов, используя новый синтаксис функций для создания функций и HTTP-конечных точек.","ar":"Convex هو تقنية تتيح التكامل مع Outseta للتحقق من الهوية وإدارة علاقات العملاء وعمليات الفواتير، باستخدام بناء الجملة الجديد للوظيفة لإنشاء الدوال ونقاط النهاية HTTP."},"features":{"en":["Uses new function syntax for Convex functions with TypeScript","Defines HTTP endpoints in convex/http.ts with httpAction decorator","Supports Convex values with v.null() and v.other() functions","Allows for custom function body implementation with async handlers","Requires import of query from ./_generated/server for function creation"],"zh":["使用新函数语法","HTTP 端点定义","支持 TypeScript","Convex 值集成","Outseta 身份验证和 CRM 集成"],"ja":["新しい関数の構文を使用","HTTP エンドポイントの定義","TypeScript をサポート","Convex 値の統合","Outseta 認証と CRM の統合"],"ko":["새로운 함수 문법 사용","HTTP 엔드포인트 정의","TypeScript 지원","Convex 값 통합","Outseta 인증 및 CRM 통합"],"es":["Sintaxis de función para Convex","Puntos de conexión HTTP con decorador httpAction","Integración con Outseta para autenticación","Gestión de la relación client con Outseta","Facturación con Outseta","Uso de TypeScript para el desarrollo"],"fr":["Syntaxe de fonction pour Convex","Points de terminaison HTTP avec décorateur httpAction","Intégration avec Outseta pour l''authentification","Gestion de la relation client avec Outseta","Facturation avec Outseta","Utilisation de TypeScript pour le développement"],"de":["Funktions-Syntax für Convex","HTTP-Endpunkte mit httpAction-Decorator","Integration mit Outseta für Authentifizierung","Kundenbeziehungsmanagement mit Outseta","Abrechnung mit Outseta","Verwendung von TypeScript für die Entwicklung"],"pt":["Integração com Outseta para autenticação, CRM e faturamento","Novo sintaxe de função para criar funções e endpoints HTTP","Definição de endpoints HTTP em `convex/http.ts` com decorador `httpAction`","Utilização de `query` e `v` para criar funções e manipular valores","Suporte a autenticação e autorização com Outseta"],"ru":["Интеграция с Outseta для аутентификации, CRM и выставления счетов","Новый синтаксис функций для создания функций и HTTP-конечных точек","Определение HTTP-конечных точек в `convex/http.ts` с декоратором `httpAction`","Использование `query` и `v` для создания функций и манипулирования значениями","Поддержка аутентификации и авторизации с Outseta"],"ar":["التكامل مع Outseta للتحقق من الهوية وإدارة علاقات العملاء وعمليات الفواتير","بناء الجملة الجديد للوظيفة لإنشاء الدوال ونقاط النهاية HTTP","تحديد نقاط النهاية HTTP في `convex/http.ts` مع مُزين `httpAction`","استخدام `query` و `v` لإنشاء الدوال وتنفيذ القيم","دعم التحقق من الهوية والتصريح مع Outseta"]},"keywords":{"en":["how to use convex","convex setup guide","convex alternative to Outseta","convex vs authentication platforms","convex install with TypeScript","what is convex in AI agents","convex HTTP endpoint syntax","convex function syntax example"],"zh":["Convex 函数语法","Convex HTTP 端点","TypeScript Convex","Convex 值","Outseta 集成","AIエージェントConvex"],"ja":["Convex 関数の構文","Convex HTTP エンドポイント","TypeScript Convex","Convex 値","Outseta 統合","AIエージェント Convex"],"ko":["Convex 함수 문법","Convex HTTP 엔드포인트","TypeScript Convex","Convex 값","Outseta 통합","AI 에이전트 Convex"],"es":["Convex","Outseta","autenticación","CRM","facturación","TypeScript","desarrollo de software","integración de API","puntos de conexión HTTP","decorador httpAction"],"fr":["Convex","Outseta","authentification","gestion de la relation client","facturation","TypeScript","développement de logiciels","intégration d''API","points de terminaison HTTP","décorateur httpAction"],"de":["Convex","Outseta","Authentifizierung","Kundenbeziehungsmanagement","Abrechnung","TypeScript","Software-Entwicklung","API-Integration","HTTP-Endpunkte","httpAction-Decorator"],"pt":["Convex","Outseta","autenticação","CRM","faturamento","funções","endpoints HTTP","sintaxe de função","query","v","httpAction"],"ru":["Convex","Outseta","аутентификация","CRM","выставление счетов","функции","HTTP-конечные точки","синтаксис функций","query","v","httpAction"],"ar":["Convex","Outseta","التحقق من الهوية","إدارة علاقات العملاء","عمليات الفواتير","الدوال","نقاط النهاية HTTP","بناء الجملة الجديد للوظيفة","query","v","httpAction"]}},"owner":"outseta","repo":"outseta-vibe-coding-CMS","repoPath":"outseta/outseta-vibe-coding-CMS","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"convex","description":"Database and Backend logic","bodyPreview":"# Convex guidelines\n\n## Function guidelines\n\n### New function syntax\n\n- ALWAYS use the new function syntax for Convex functions. For example:\n\n```typescript\nimport { query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nexport const f = query({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    // Function body\n  },\n});\n```\n\n### Http endpoint syntax\n\n- HTTP endpoints are defined in `convex/http.ts` and require an `httpAction` decorator. For example:\n\n```types","body":"# Convex guidelines\n\n## Function guidelines\n\n### New function syntax\n\n- ALWAYS use the new function syntax for Convex functions. For example:\n\n```typescript\nimport { query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\nexport const f = query({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    // Function body\n  },\n});\n```\n\n### Http endpoint syntax\n\n- HTTP endpoints are defined in `convex/http.ts` and require an `httpAction` decorator. For example:\n\n```typescript\nimport { httpRouter } from \"convex/server\";\nimport { httpAction } from \"./_generated/server\";\nconst http = httpRouter();\nhttp.route({\n  path: \"/echo\",\n  method: \"POST\",\n  handler: httpAction(async (ctx, req) => {\n    const body = await req.bytes();\n    return new Response(body, { status: 200 });\n  }),\n});\n```\n\n- HTTP endpoints are always registered at the exact path you specify in the `path` field. For example, if you specify `/api/someRoute`, the endpoint will be registered at `/api/someRoute`.\n\n### Validators\n\n- Below is an example of an array validator:\n\n```typescript\nimport { mutation } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport default mutation({\n  args: {\n    simpleArray: v.array(v.union(v.string(), v.number())),\n  },\n  handler: async (ctx, args) => {\n    //...\n  },\n});\n```\n\n- Below is an example of a schema with validators that codify a discriminated union type:\n\n```typescript\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  results: defineTable(\n    v.union(\n      v.object({\n        kind: v.literal(\"error\"),\n        errorMessage: v.string(),\n      }),\n      v.object({\n        kind: v.literal(\"success\"),\n        value: v.number(),\n      }),\n    ),\n  ),\n});\n```\n\n- Always use the `v.null()` validator when returning a null value. Below is an example query that returns a null value:\n\n```typescript\nimport { query } from \"./_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const exampleQuery = query({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    console.log(\"This query returns a null value\");\n    return null;\n  },\n});\n```\n\n- Here are the valid Convex types along with their respective validators:\n  Convex Type | TS/JS type | Example Usage | Validator for argument validation and schemas | Notes |\n  | ----------- | ------------| -----------------------| -----------------------------------------------| ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|\n  | Id | string | `doc._id` | `v.id(tableName)` | |\n  | Null | null | `null` | `v.null()` | JavaScript''s `undefined` is not a valid Convex value. Functions the return `undefined` or do not return will return `null` when called from a client. Use `null` instead. |\n  | Int64 | bigint | `3n` | `v.int64()` | Int64s only support BigInts between -2^63 and 2^63-1. Convex supports `bigint`s in most modern browsers. |\n  | Float64 | number | `3.1` | `v.number()` | Convex supports all IEEE-754 double-precision floating point numbers (such as NaNs). Inf and NaN are JSON serialized as strings. |\n  | Boolean | boolean | `true` | `v.boolean()` |\n  | String | string | `\"abc\"` | `v.string()` | Strings are stored as UTF-8 and must be valid Unicode sequences. Strings must be smaller than the 1MB total size limit when encoded as UTF-8. |\n  | Bytes | ArrayBuffer | `new ArrayBuffer(8)` | `v.bytes()` | Convex supports first class bytestrings, passed in as `ArrayBuffer`s. Bytestrings must be smaller than the 1MB total size limit for Convex types. |\n  | Array | Array | `[1, 3.2, \"abc\"]` | `v.array(values)` | Arrays can have at most 8192 values. |\n  | Object | Object | `{a: \"abc\"}` | `v.object({property: value})` | Convex only supports \"plain old JavaScript objects\" (objects that do not have a custom prototype). Objects can have at most 1024 entries. Field names must be nonempty and not start with \"$\" or \"_\". |\n| Record      | Record      | `{\"a\": \"1\", \"b\": \"2\"}` | `v.record(keys, values)`                       | Records are objects at runtime, but can have dynamic keys. Keys must be only ASCII characters, nonempty, and not start with \"$\" or \"\\_\". |\n\n### Function registration\n\n- Use `internalQuery`, `internalMutation`, and `internalAction` to register internal functions. These functions are private and aren''t part of an app''s API. They can only be called by other Convex functions. These functions are always imported from `./_generated/server`.\n- Use `query`, `mutation`, and `action` to register public functions. These functions are part of the public API and are exposed to the public Internet. Do NOT use `query`, `mutation`, or `action` to register sensitive internal functions that should be kept private.\n- You CANNOT register a function through the `api` or `internal` objects.\n- ALWAYS include argument and return validators for all Convex functions. This includes all of `query`, `internalQuery`, `mutation`, `internalMutation`, `action`, and `internalAction`. If a function doesn''t return anything, include `returns: v.null()` as its output validator.\n- If the JavaScript implementation of a Convex function doesn''t have a return value, it implicitly returns `null`.\n\n### Function calling\n\n- Use `ctx.runQuery` to call a query from a query, mutation, or action.\n- Use `ctx.runMutation` to call a mutation from a mutation or action.\n- Use `ctx.runAction` to call an action from an action.\n- ONLY call an action from another action if you need to cross runtimes (e.g. from V8 to Node). Otherwise, pull out the shared code into a helper async function and call that directly instead.\n- Try to use as few calls from actions to queries and mutations as possible. Queries and mutations are transactions, so splitting logic up into multiple calls introduces the risk of race conditions.\n- All of these calls take in a `FunctionReference`. Do NOT try to pass the callee function directly into one of these calls.\n- When using `ctx.runQuery`, `ctx.runMutation`, or `ctx.runAction` to call a function in the same file, specify a type annotation on the return value to work around TypeScript circularity limitations. For example,\n\n```\nexport const f = query({\n  args: { name: v.string() },\n  returns: v.string(),\n  handler: async (ctx, args) => {\n    return \"Hello \" + args.name;\n  },\n});\n\nexport const g = query({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    const result: string = await ctx.runQuery(api.example.f, { name: \"Bob\" });\n    return null;\n  },\n});\n```\n\n### Function references\n\n- Function references are pointers to registered Convex functions.\n- Use the `api` object defined by the framework in `convex/_generated/api.ts` to call public functions registered with `query`, `mutation`, or `action`.\n- Use the `internal` object defined by the framework in `convex/_generated/api.ts` to call internal (or private) functions registered with `internalQuery`, `internalMutation`, or `internalAction`.\n- Convex uses file-based routing, so a public function defined in `convex/example.ts` named `f` has a function reference of `api.example.f`.\n- A private function defined in `convex/example.ts` named `g` has a function reference of `internal.example.g`.\n- Functions can also registered within directories nested within the `convex/` folder. For example, a public function `h` defined in `convex/messages/access.ts` has a function reference of `api.messages.access.h`.\n\n### Api design\n\n- Convex uses file-based routing, so thoughtfully organize files with public query, mutation, or action functions within the `convex/` directory.\n- Use `query`, `mutation`, and `action` to define public functions.\n- Use `internalQuery`, `internalMutation`, and `internalAction` to define private, internal functions.\n\n### Pagination\n\n- Paginated queries are queries that return a list of results in incremental pages.\n- You can define pagination using the following syntax:\n\n```ts\nimport { v } from \"convex/values\";\nimport { query, mutation } from \"./_generated/server\";\nimport { paginationOptsValidator } from \"convex/server\";\nexport const listWithExtraArg = query({\n  args: { paginationOpts: paginationOptsValidator, author: v.string() },\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"messages\")\n      .filter((q) => q.eq(q.field(\"author\"), args.author))\n      .order(\"desc\")\n      .paginate(args.paginationOpts);\n  },\n});\n```\n\nNote: `paginationOpts` is an object with the following properties:\n\n- `numItems`: the maximum number of documents to return (the validator is `v.number()`)\n- `cursor`: the cursor to use to fetch the next page of documents (the validator is `v.union(v.string(), v.null())`)\n- A query that ends in `.paginate()` returns an object that has the following properties: - page (contains an array of documents that you fetches) - isDone (a boolean that represents whether or not this is the last page of documents) - continueCursor (a string that represents the cursor to use to fetch the next page of documents)\n\n## Validator guidelines\n\n- `v.bigint()` is deprecated for representing signed 64-bit integers. Use `v.int64()` instead.\n- Use `v.record()` for defining a record type. `v.map()` and `v.set()` are not supported.\n\n## Schema guidelines\n\n- Always define your schema in `convex/schema.ts`.\n- Always import the schema definition functions from `convex/server`.\n- System fields are automatically added to all documents and are prefixed with an underscore. The two system fields that are automatically added to all documents are `_creationTime` which has the validator `v.number()` and `_id` which has the validator `v.id(tableName)`.\n- Always include all index fields in the index name. For example, if an index is defined as `[\"field1\", \"field2\"]`, the index name should be \"by_field1_and_field2\".\n- Index fields must be queried in the same order they are defined. If you want to be able to query by \"field1\" then \"field2\" and by \"field2\" then \"field1\", you must create separate indexes.\n\n## Typescript guidelines\n\n- You can use the helper typescript type `Id` imported from ''./\\_generated/dataModel'' to get the type of the id for a given table. For example if there is a table called ''users'' you can use `Id<''users''>` to get the type of the id for that table.\n- If you need to define a `Record` make sure that you correctly provide the type of the key and value in the type. For example a validator `v.record(v.id(''users''), v.string())` would have the type `Record<Id<''users''>, string>`. Below is an example of using `Record` with an `Id` type in a query:\n\n```ts\nimport { query } from \"./_generated/server\";\nimport { Doc, Id } from \"./_generated/dataModel\";\n\nexport const exampleQuery = query({\n  args: { userIds: v.array(v.id(\"users\")) },\n  returns: v.record(v.id(\"users\"), v.string()),\n  handler: async (ctx, args) => {\n    const idToUsername: Record<Id<\"users\">, string> = {};\n    for (const userId of args.userIds) {\n      const user = await ctx.db.get(\"users\", userId);\n      if (user) {\n        idToUsername[user._id] = user.username;\n      }\n    }\n\n    return idToUsername;\n  },\n});\n```\n\n- Be strict with types, particularly around id''s of documents. For example, if a function takes in an id for a document in the ''users'' table, take in `Id<''users''>` rather than `string`.\n- Always use `as const` for string literals in discriminated union types.\n- When using the `Array` type, make sure to always define your arrays as `const array: Array<T> = [...];`\n- When using the `Record` type, make sure to always define your records as `const record: Record<KeyType, ValueType> = {...};`\n- Always add `@types/node` to your `package.json` when using any Node.js built-in modules.\n\n## Full text search guidelines\n\n- A query for \"10 messages in channel ''#general'' that best match the query ''hello hi'' in their body\" would look like:\n\nconst messages = await ctx.db\n.query(\"messages\")\n.withSearchIndex(\"search_body\", (q) =>\nq.search(\"body\", \"hello hi\").eq(\"channel\", \"#general\"),\n)\n.take(10);\n\n## Query guidelines\n\n- Do NOT use `filter` in queries. Instead, define an index in the schema and use `withIndex` instead.\n- Convex queries do NOT support `.delete()`. Instead, `.collect()` the results, iterate over them, and call `ctx.db.delete(row._id)` on each result.\n- Use `.unique()` to get a single document from a query. This method will throw an error if there are multiple documents that match the query.\n- When using async iteration, don''t use `.collect()` or `.take(n)` on the result of a query. Instead, use the `for await (const row of query)` syntax.\n\n### Ordering\n\n- By default Convex always returns documents in ascending `_creationTime` order.\n- You can use `.order(''asc'')` or `.order(''desc'')` to pick whether a query is in ascending or descending order. If the order isn''t specified, it defaults to ascending.\n- Document queries that use indexes will be ordered based on the columns in the index and can avoid slow table scans.\n\n## Mutation guidelines\n\n- Use `ctx.db.replace` to fully replace an existing document. This method will throw an error if the document does not exist. Syntax: `await ctx.db.replace(''tasks'', taskId, { name: ''Buy milk'', completed: false })`\n- Use `ctx.db.patch` to shallow merge updates into an existing document. This method will throw an error if the document does not exist. Syntax: `await ctx.db.patch(''tasks'', taskId, { completed: true })`\n\n## Action guidelines\n\n- Always add `\"use node\";` to the top of files containing actions that use Node.js built-in modules.\n- Never use `ctx.db` inside of an action. Actions don''t have access to the database.\n- Below is an example of the syntax for an action:\n\n```ts\nimport { action } from \"./_generated/server\";\n\nexport const exampleAction = action({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    console.log(\"This action does not return anything\");\n    return null;\n  },\n});\n```\n\n## Scheduling guidelines\n\n### Cron guidelines\n\n- Only use the `crons.interval` or `crons.cron` methods to schedule cron jobs. Do NOT use the `crons.hourly`, `crons.daily`, or `crons.weekly` helpers.\n- Both cron methods take in a FunctionReference. Do NOT try to pass the function directly into one of these methods.\n- Define crons by declaring the top-level `crons` object, calling some methods on it, and then exporting it as default. For example,\n\n```ts\nimport { cronJobs } from \"convex/server\";\nimport { internal } from \"./_generated/api\";\nimport { internalAction } from \"./_generated/server\";\n\nconst empty = internalAction({\n  args: {},\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    console.log(\"empty\");\n  },\n});\n\nconst crons = cronJobs();\n\n// Run `internal.crons.empty` every two hours.\ncrons.interval(\"delete inactive users\", { hours: 2 }, internal.crons.empty, {});\n\nexport default crons;\n```\n\n- You can register Convex functions within `crons.ts` just like any other file.\n- If a cron calls an internal function, always import the `internal` object from ''\\_generated/api'', even if the internal function is registered in the same file.\n\n## File storage guidelines\n\n- Convex includes file storage for large files like images, videos, and PDFs.\n- The `ctx.storage.getUrl()` method returns a signed URL for a given file. It returns `null` if the file doesn''t exist.\n- Do NOT use the deprecated `ctx.storage.getMetadata` call for loading a file''s metadata.\n\n                    Instead, query the `_storage` system table. For example, you can use `ctx.db.system.get` to get an `Id<\"_storage\">`.\n\n```\nimport { query } from \"./_generated/server\";\nimport { Id } from \"./_generated/dataModel\";\n\ntype FileMetadata = {\n    _id: Id<\"_storage\">;\n    _creationTime: number;\n    contentType?: string;\n    sha256: string;\n    size: number;\n}\n\nexport const exampleQuery = query({\n    args: { fileId: v.id(\"_storage\") },\n    returns: v.null(),\n    handler: async (ctx, args) => {\n        const metadata: FileMetadata | null = await ctx.db.system.get(\"_storage\", args.fileId);\n        console.log(metadata);\n        return null;\n    },\n});\n```\n\n- Convex storage stores items as `Blob` objects. You must convert all items to/from a `Blob` when using Convex storage.\n\n# Examples:\n\n## Example: chat-app\n\n### Task\n\n```\nCreate a real-time chat application backend with AI responses. The app should:\n- Allow creating users with names\n- Support multiple chat channels\n- Enable users to send messages to channels\n- Automatically generate AI responses to user messages\n- Show recent message history\n\nThe backend should provide APIs for:\n1. User management (creation)\n2. Channel management (creation)\n3. Message operations (sending, listing)\n4. AI response generation using OpenAI''s GPT-4\n\nMessages should be stored with their channel, author, and content. The system should maintain message order\nand limit history display to the 10 most recent messages per channel.\n\n```\n\n### Analysis\n\n1. Task Requirements Summary:\n\n- Build a real-time chat backend with AI integration\n- Support user creation\n- Enable channel-based conversations\n- Store and retrieve messages with proper ordering\n- Generate AI responses automatically\n\n2. Main Components Needed:\n\n- Database tables: users, channels, messages\n- Public APIs for user/channel management\n- Message handling functions\n- Internal AI response generation system\n- Context loading for AI responses\n\n3. Public API and Internal Functions Design:\n   Public Mutations:\n\n- createUser:\n  - file path: convex/index.ts\n  - arguments: {name: v.string()}\n  - returns: v.object({userId: v.id(\"users\")})\n  - purpose: Create a new user with a given name\n- createChannel:\n  - file path: convex/index.ts\n  - arguments: {name: v.string()}\n  - returns: v.object({channelId: v.id(\"channels\")})\n  - purpose: Create a new channel with a given name\n- sendMessage:\n  - file path: convex/index.ts\n  - arguments: {channelId: v.id(\"channels\"), authorId: v.id(\"users\"), content: v.string()}\n  - returns: v.null()\n  - purpose: Send a message to a channel and schedule a response from the AI\n\nPublic Queries:\n\n- listMessages:\n  - file path: convex/index.ts\n  - arguments: {channelId: v.id(\"channels\")}\n  - returns: v.array(v.object({\n    \\_id: v.id(\"messages\"),\n    \\_creationTime: v.number(),\n    channelId: v.id(\"channels\"),\n    authorId: v.optional(v.id(\"users\")),\n    content: v.string(),\n    }))\n  - purpose: List the 10 most recent messages from a channel in descending creation order\n\nInternal Functions:\n\n- generateResponse:\n  - file path: convex/index.ts\n  - arguments: {channelId: v.id(\"channels\")}\n  - returns: v.null()\n  - purpose: Generate a response from the AI for a given channel\n- loadContext:\n  - file path: convex/index.ts\n  - arguments: {channelId: v.id(\"channels\")}\n  - returns: v.array(v.object({\n    \\_id: v.id(\"messages\"),\n    \\_creationTime: v.number(),\n    channelId: v.id(\"channels\"),\n    authorId: v.optional(v.id(\"users\")),\n    content: v.string(),\n    }))\n- writeAgentResponse:\n  - file path: convex/index.ts\n  - arguments: {channelId: v.id(\"channels\"), content: v.string()}\n  - returns: v.null()\n  - purpose: Write an AI response to a given channel\n\n4. Schema Design:\n\n- users\n  - validator: { name: v.string() }\n  - indexes: <none>\n- channels\n  - validator: { name: v.string() }\n  - indexes: <none>\n- messages\n  - validator: { channelId: v.id(\"channels\"), authorId: v.optional(v.id(\"users\")), content: v.string() }\n  - indexes\n    - by_channel: [\"channelId\"]\n\n5. Background Processing:\n\n- AI response generation runs asynchronously after each user message\n- Uses OpenAI''s GPT-4 to generate contextual responses\n- Maintains conversation context using recent message history\n\n### Implementation\n\n#### package.json\n\n```typescript\n{\n  \"name\": \"chat-app\",\n  \"description\": \"This example shows how to build a chat app without authentication.\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\n    \"convex\": \"^1.31.2\",\n    \"openai\": \"^4.79.0\"\n  },\n  \"devDependencies\": {\n    \"typescript\": \"^5.7.3\"\n  }\n}\n```\n\n#### tsconfig.json\n\n```typescript\n{\n  \"compilerOptions\": {\n    \"target\": \"ESNext\",\n    \"lib\": [\"DOM\", \"DOM.Iterable\", \"ESNext\"],\n    \"skipLibCheck\": true,\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true,\n    \"forceConsistentCasingInFileNames\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Bundler\",\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"allowImportingTsExtensions\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\"\n  },\n  \"exclude\": [\"convex\"],\n  \"include\": [\"**/src/**/*.tsx\", \"**/src/**/*.ts\", \"vite.config.ts\"]\n}\n```\n\n#### convex/index.ts\n\n```typescript\nimport {\n  query,\n  mutation,\n  internalQuery,\n  internalMutation,\n  internalAction,\n} from \"./_generated/server\";\nimport { v } from \"convex/values\";\nimport OpenAI from \"openai\";\nimport { internal } from \"./_generated/api\";\n\n/**\n * Create a user with a given name.\n */\nexport const createUser = mutation({\n  args: {\n    name: v.string(),\n  },\n  returns: v.id(\"users\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"users\", { name: args.name });\n  },\n});\n\n/**\n * Create a channel with a given name.\n */\nexport const createChannel = mutation({\n  args: {\n    name: v.string(),\n  },\n  returns: v.id(\"channels\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"channels\", { name: args.name });\n  },\n});\n\n/**\n * List the 10 most recent messages from a channel in descending creation order.\n */\nexport const listMessages = query({\n  args: {\n    channelId: v.id(\"channels\"),\n  },\n  returns: v.array(\n    v.object({\n      _id: v.id(\"messages\"),\n      _creationTime: v.number(),\n      channelId: v.id(\"channels\"),\n      authorId: v.optional(v.id(\"users\")),\n      content: v.string(),\n    }),\n  ),\n  handler: async (ctx, args) => {\n    const messages = await ctx.db\n      .query(\"messages\")\n      .withIndex(\"by_channel\", (q) => q.eq(\"channelId\", args.channelId))\n      .order(\"desc\")\n      .take(10);\n    return messages;\n  },\n});\n\n/**\n * Send a message to a channel and schedule a response from the AI.\n */\nexport const sendMessage = mutation({\n  args: {\n    channelId: v.id(\"channels\"),\n    authorId: v.id(\"users\"),\n    content: v.string(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    const channel = await ctx.db.get(args.channelId);\n    if (!channel) {\n      throw new Error(\"Channel not found\");\n    }\n    const user = await ctx.db.get(args.authorId);\n    if (!user) {\n      throw new Error(\"User not found\");\n    }\n    await ctx.db.insert(\"messages\", {\n      channelId: args.channelId,\n      authorId: args.authorId,\n      content: args.content,\n    });\n    await ctx.scheduler.runAfter(0, internal.index.generateResponse, {\n      channelId: args.channelId,\n    });\n    return null;\n  },\n});\n\nconst openai = new OpenAI();\n\nexport const generateResponse = internalAction({\n  args: {\n    channelId: v.id(\"channels\"),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    const context = await ctx.runQuery(internal.index.loadContext, {\n      channelId: args.channelId,\n    });\n    const response = await openai.chat.completions.create({\n      model: \"gpt-4o\",\n      messages: context,\n    });\n    const content = response.choices[0].message.content;\n    if (!content) {\n      throw new Error(\"No content in response\");\n    }\n    await ctx.runMutation(internal.index.writeAgentResponse, {\n      channelId: args.channelId,\n      content,\n    });\n    return null;\n  },\n});\n\nexport const loadContext = internalQuery({\n  args: {\n    channelId: v.id(\"channels\"),\n  },\n  returns: v.array(\n    v.object({\n      role: v.union(v.literal(\"user\"), v.literal(\"assistant\")),\n      content: v.string(),\n    }),\n  ),\n  handler: async (ctx, args) => {\n    const channel = await ctx.db.get(args.channelId);\n    if (!channel) {\n      throw new Error(\"Channel not found\");\n    }\n    const messages = await ctx.db\n      .query(\"messages\")\n      .withIndex(\"by_channel\", (q) => q.eq(\"channelId\", args.channelId))\n      .order(\"desc\")\n      .take(10);\n\n    const result = [];\n    for (const message of messages) {\n      if (message.authorId) {\n        const user = await ctx.db.get(message.authorId);\n        if (!user) {\n          throw new Error(\"User not found\");\n        }\n        result.push({\n          role: \"user\" as const,\n          content: `${user.name}: ${message.content}`,\n        });\n      } else {\n        result.push({ role: \"assistant\" as const, content: message.content });\n      }\n    }\n    return result;\n  },\n});\n\nexport const writeAgentResponse = internalMutation({\n  args: {\n    channelId: v.id(\"channels\"),\n    content: v.string(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.insert(\"messages\", {\n      channelId: args.channelId,\n      content: args.content,\n    });\n    return null;\n  },\n});\n```\n\n#### convex/schema.ts\n\n```typescript\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  channels: defineTable({\n    name: v.string(),\n  }),\n\n  users: defineTable({\n    name: v.string(),\n  }),\n\n  messages: defineTable({\n    channelId: v.id(\"channels\"),\n    authorId: v.optional(v.id(\"users\")),\n    content: v.string(),\n  }).index(\"by_channel\", [\"channelId\"]),\n});\n```\n\n#### convex/tsconfig.json\n\n```typescript\n{\n  /* This TypeScript project config describes the environment that\n   * Convex functions run in and is used to typecheck them.\n   * You can modify it, but some settings required to use Convex.\n   */\n  \"compilerOptions\": {\n    /* These settings are not required by Convex and can be modified. */\n    \"allowJs\": true,\n    \"strict\": true,\n    \"moduleResolution\": \"Bundler\",\n    \"jsx\": \"react-jsx\",\n    \"skipLibCheck\": true,\n    \"allowSyntheticDefaultImports\": true,\n\n    /* These compiler options are required by Convex */\n    \"target\": \"ESNext\",\n    \"lib\": [\"ES2021\", \"dom\"],\n    \"forceConsistentCasingInFileNames\": true,\n    \"module\": \"ESNext\",\n    \"isolatedModules\": true,\n    \"noEmit\": true\n  },\n  \"include\": [\"./**/*\"],\n  \"exclude\": [\"./_generated\"]\n}\n```\n\n#### src/App.tsx\n\n```typescript\nexport default function App() {\n  return <div>Hello World</div>;\n}\n```\n"},"lastSynced":"2026-03-08T02:02:40.649Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing custom HTTP endpoint and authentication integration with Outseta.","zh":"非常适合需要自定义HTTP端点和与Outseta集成的身份验证的全栈Agent。","ja":"OutsetaとのカスタムHTTPエンドポイントおよび認証の統合が必要なフルスタックエージェントに最適。","ko":"Outseta와의 커스텀 HTTP 엔드ポイント 및 인증 통합이 필요한 풀스택 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Full Stack que necesitan un punto de conexión HTTP personalizado y una integración de autenticación con Outseta.","fr":"Parfait pour les agents Full Stack ayant besoin d''un point de terminaison HTTP personnalisé et d''une intégration d''authentification avec Outseta.","de":"Perfekt für Full-Stack-Agents, die eine benutzerdefinierte HTTP-Endpunkt- und Authentifizierungsintegration mit Outseta benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de endpoint HTTP personalizado e integração de autenticação com Outseta.","ru":"Идеально подходит для агентов Full Stack, которым необходимы пользовательские конечные точки HTTP и интеграция аутентификации с Outseta.","ar":"مثالي للموكلين الكاملين الذين يحتاجون إلى نهاية HTTP مخصصة وتكامل مصادقة مع Outseta."},"recommendation":{"en":"Empowers agents to build custom functions and HTTP endpoints using the Convex framework, providing a robust authentication system with Outseta and leveraging libraries like Convex Values for flexible data handling.","zh":"赋予代理人使用Convex框架构建自定义函数和HTTP端点的能力，提供强大的Outseta身份验证系统，并利用Convex Values等库进行灵活的数据处理。","ja":"Convexフレームワークを使用してカスタム関数とHTTPエンドポイントを構築するエージェントの能力を強化し、Outsetaとの堅牢な認証システムを提供し、Convex Valuesなどのライブラリを使用して柔軟なデータ処理を行います。","ko":"Convex 프레임워크를 사용하여 커스텀 함수와 HTTP 엔드포인트를 구축하는 에이전트의 능력을 강화하여 Outseta와의 강력한 인증 시스템을 제공하고 Convex Values 등의 라이브러리를 사용하여 유연한 데이터 처리를 수행합니다.","es":"Habilita a los agentes a construir funciones personalizadas y puntos de conexión HTTP utilizando el framework Convex, proporcionando un sistema de autenticación robusto con Outseta y aprovechando bibliotecas como Convex Values para un manejo de datos flexible.","fr":"Permet aux agents de créer des fonctions personnalisées et des points de terminaison HTTP en utilisant le framework Convex, fournissant un système d''authentification robuste avec Outseta et exploitant des bibliothèques comme Convex Values pour un traitement de données flexible.","de":"Ermöglicht es Agents, benutzerdefinierte Funktionen und HTTP-Endpunkte mit dem Convex-Framework zu erstellen, wodurch ein robustes Authentifizierungssystem mit Outseta bereitgestellt wird und Bibliotheken wie Convex Values für flexibles Datenhandling genutzt werden.","pt":"Permite que os agentes construam funções personalizadas e pontos de extremidade HTTP usando o framework Convex, fornecendo um sistema de autenticação robusto com Outseta e aproveitando bibliotecas como Convex Values para manipulação de dados flexível.","ru":"Позволяет агентам создавать пользовательские функции и конечные точки HTTP с помощью фреймворка Convex, обеспечивая надежную систему аутентификации с Outseta и использует библиотеки, такие как Convex Values, для гибкой обработки данных.","ar":"يمكن للموكلين بناء دوال مخصصة ونقاط نهاية HTTP باستخدام إطار Convex، مع توفير نظام مصادقة قوي مع Outseta وتعزيز المكتبات مثل Convex Values لمعالجة البيانات المرنة."},"useCases":{"en":["Building custom authentication workflows with Outseta","Creating server-side functions with Convex query syntax","Defining HTTP endpoints with the httpAction decorator"],"zh":["使用Outseta构建自定义身份验证工作流","使用Convex查询语法创建服务器端函数","使用httpAction修饰符定义HTTP端点"],"ja":["Outsetaを使用したカスタム認証ワークフローの構築","Convexクエリ構文を使用したサーバーサイド関数の作成","httpActionデコレータを使用したHTTPエンドポイントの定義"],"ko":["Outseta를 사용한 커스텀 인증 워크플로우 구축","Convex 쿼리 구문을 사용한 서버측 함수 생성","httpAction 데코레이터를 사용한 HTTP 엔드포인트 정의"],"es":["Crear flujos de trabajo de autenticación personalizados con Outseta","Crear funciones del lado del servidor con la sintaxis de consulta de Convex","Definir puntos de conexión HTTP con el decorador httpAction"],"fr":["Créer des flux de travail d''authentification personnalisés avec Outseta","Créer des fonctions côté serveur avec la syntaxe de requête Convex","Définir des points de terminaison HTTP avec le décorateur httpAction"],"de":["Erstellen benutzerdefinierter Authentifizierungs-Workflows mit Outseta","Erstellen von Server-seitigen Funktionen mit der Convex-Abfragesyntax","Definieren von HTTP-Endpunkten mit dem httpAction-Decorator"],"pt":["Construir fluxos de trabalho de autenticação personalizados com Outseta","Criar funções do lado do servidor com sintaxe de consulta Convex","Definir pontos de extremidade HTTP com o decorador httpAction"],"ru":["Создание пользовательских рабочих процессов аутентификации с Outseta","Создание функций на стороне сервера с синтаксисом запроса Convex","Определение конечных точек HTTP с помощью декоратора httpAction"],"ar":["بناء تدفقات عمل مصادقة مخصصة مع Outseta","إنشاء دوال على جانب الخادم باستخدام بناء جملة استعلام Convex","تحديد نقاط نهاية HTTP باستخدام زينر httpAction"]},"limitations":{"en":["Requires Convex and Outseta setup","Must use new function syntax for Convex functions","Limited to TypeScript environment"],"zh":["需要Convex和Outseta设置","必须使用新的函数语法来编写Convex函数","仅限于TypeScript环境"],"ja":["ConvexとOutsetaの設定が必要","Convex関数には新しい関数構文を使用する必要がある","TypeScript環境でのみ使用可能"],"ko":["Convex와 Outseta 설정이 필요합니다.","Convex 함수를 작성할 때는 새로운 함수 구문을 사용해야 합니다.","TypeScript 환경에서만 사용할 수 있습니다."],"es":["Requiere configuración de Convex y Outseta","Debe utilizar la nueva sintaxis de función para funciones Convex","Limitado al entorno de TypeScript"],"fr":["Nécessite une configuration de Convex et Outseta","Doit utiliser la nouvelle syntaxe de fonction pour les fonctions Convex","Limité à l''environnement TypeScript"],"de":["Benötigt Convex- und Outseta-Setup","Muss die neue Funktions-Syntax für Convex-Funktionen verwenden","Begrenzt auf die TypeScript-Umgebung"],"pt":["Requer configuração do Convex e Outseta","Deve usar a nova sintaxe de função para funções Convex","Limitado ao ambiente TypeScript"],"ru":["Требуется настройка Convex и Outseta","Должен использовать новую синтаксис функций для функций Convex","Ограничен средой TypeScript"],"ar":["يتطلب إعداد Convex و Outseta","يجب استخدام بناء الجملة الجديد للوظائف للوظائف Convex","محدود بالبيئة TypeScript"]},"version":4},"contentHash":"6359ffba973884ddcfb4b14a7d4059bf56033e396fde231b829c1d5a0260abba","qualityScore":60}');
