INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('outseta/outseta-vibe-coding-CMS/convex', 'convex', 'outseta', 'outseta-vibe-coding-CMS', 'community', 'convex outseta outseta-vibe-coding-CMS community Convex is a Proof of Concept project that demonstrates the integration of Outseta for authentication, CRM, and billing, benefiting developers and AI agents. It provides a framework for building custom functions and HTTP endpoints. Convex 项目是一个 Proof of Concept，展示了 Outseta 的集成，用于身份验证、CRM 和计费 Convex プロジェクトは、Outseta の統合を示す Proof of Concept で、認証、CRM、請求書を提供します Convex 프로젝트는 Outseta의 통합을 보여주는 개념 증명입니다. 인증, CRM, 청구를 제공합니다 Convex es un proyecto de prueba de concepto que demuestra la integración de Outseta para autenticación, CRM y facturación. Aprende a utilizar la sintaxis de función y los puntos de conexión HTTP Convex est un projet de preuve de concept qui démontre l''intégration d''Outseta pour l''authentification, la gestion de la relation client et la facturation. Découvrez la syntaxe de fonction et les points de terminaison HTTP Convex ist ein Proof-of-Concept-Projekt, das die Integration von Outseta für Authentifizierung, CRM und Abrechnung demonstriert. Erfahren Sie, wie Sie die Funktions-Syntax und die HTTP-Endpunkte verwenden O Convex é uma prova de conceito que demonstra a integração com Outseta para autenticação, CRM e faturamento. Aprenda a criar funções e endpoints HTTP com o novo sintaxe de função. Convex - это доказательство концепции, демонстрирующее интеграцию с Outseta для аутентификации, CRM и выставления счетов. Узнайте, как создавать функции и HTTP-конечные точки с новым синтаксисом функций. Convex هو برهان مفهوم يظهر تكامل Outseta للتحقق من الهوية وإدارة علاقات العملاء وعمليات الفواتير. تعلم كيفية إنشاء الدوال ونقاط النهاية HTTP باستخدام بناء الجملة الجديد للوظيفة. how to use convex convex setup guide convex alternative to Outseta convex vs authentication platforms convex install with TypeScript what is convex in AI agents convex HTTP endpoint syntax convex function syntax example Convex 函数语法 Convex HTTP 端点 TypeScript Convex Convex 值 Outseta 集成 AIエージェントConvex Uses new function syntax for Convex functions with TypeScript Defines HTTP endpoints in convex/http.ts with httpAction decorator Supports Convex values with v.null() and v.other() functions Allows for custom function body implementation with async handlers Requires import of query from ./_generated/server for function creation Convex is a project that integrates Outseta for authentication, CRM, and billing, using technologies like TypeScript and Convex values.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hotriluan/alkana_kpi/research', 'community', 'hotriluan', 'alkana_kpi', 'hotriluan/alkana_kpi', 'research', 0, 0, 60, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:42.933Z', 'd7eed88b8d795e30c8c17661998aeffc1246d8caac283f935f27a3382a1bc36b', '{"id":"hotriluan/alkana_kpi/research","name":"research","description":{"en":"The research skill enables AI agents to conduct systematic investigations by defining scope and evaluating sources, benefiting developers and researchers.","zh":"研究技能遵循YAGNI、KISS和DRY原则，提供系统信息方法，包括范围定义和评估标准","ja":"研究スキルは、YAGNI、KISS、DRY原則に従い、範囲定義や評価基準を含む体系的な情報方法を提供します","ko":"연구 스킬은 YAGNI, KISS, DRY 원칙을 따르며, 범위 정의 및 평가 기준을 포함한 체계적인 정보 방법을 제공합니다","es":"La investigación en Alkana KPI implica la definición del alcance, la identificación de términos clave y la evaluación de fuentes. Nuestro enfoque sigue los principios YAGNI, KISS y DRY.","fr":"La recherche dans Alkana KPI implique la définition de la portée, l''identification des termes clés et l''évaluation des sources. Notre approche suit les principes YAGNI, KISS et DRY.","de":"Die Forschung in Alkana KPI umfasst die Definition des Umfangs, die Identifizierung von Schlüsselbegriffen und die Bewertung von Quellen. Unser Ansatz folgt den Prinzipien YAGNI, KISS und DRY.","pt":"Pesquisa eficaz com YAGNI, KISS e DRY para desenvolvedores de aplicativos Alkana KPI. Defina o escopo e avalie fontes com critérios claros.","ru":"Эффективное исследование с YAGNI, KISS и DRY для разработчиков приложений Alkana KPI и ИИ Агентов. Определите объем и оцените источники по четким критериям.","ar":"بحث فعال باستخدام YAGNI و KISS و DRY لمطوري تطبيقات Alkana KPI وأدوات الذكاء الاصطناعي. حدد نطاق البحث وقيم المصادر وفقًا لمعايير واضحة."},"seo":{"title":{"en":"Research: Systematic Information Setup Guide | AI Agent S...","zh":"研究设置指南：Alkana KPI 应用","ja":"研究のベストプラクティス：AIエージェントによるAlkana KPIアプリケーション","ko":"연구 설정 가이드: Alkana KPI 애플리케이션","es":"Guía de Configuración de Investigación para Alkana KPI","fr":"Guide de Configuration de la Recherche pour Alkana KPI","de":"Einrichtungsleitfaden für Forschung in Alkana KPI","pt":"Guia de Configuração de Pesquisa para Desenvolvedores","ru":"Настройка Исследования для Разработчиков ИИ Агентов","ar":"دليل إعداد البحث لل مطورين أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient research with YAGNI, KISS, and DRY principles. Learn how to scope definition and systematic information for AI agents.","zh":"了解研究的系统信息方法，包括范围定义、评估标准和边界设置，以便在Alkana KPI应用中进行高效研究","ja":"AIエージェントを使用した研究のための、範囲定義、評価基準、境界設定などを含む体系的な情報方法を学びます","ko":"Alkana KPI 애플리케이션에서 효율적인 연구를 수행하기 위한 연구의 시스템 정보 방법, 즉 범위 정의, 평가 기준 및 경계 설정 등을 포함하여 학습합니다","es":"Aprende a configurar y utilizar la investigación en Alkana KPI con nuestros expertos en desarrollo. Mejora tus habilidades con nuestro enfoque práctico.","fr":"Découvrez comment configurer et utiliser la recherche dans Alkana KPI avec nos experts en développement. Améliorez vos compétences avec notre approche pratique.","de":"Erfahren Sie, wie Sie die Forschung in Alkana KPI konfigurieren und nutzen können. Verbessern Sie Ihre Fähigkeiten mit unserem praktischen Ansatz.","pt":"Aprenda a configurar a pesquisa com YAGNI, KISS e DRY para desenvolvedores de aplicativos Alkana KPI","ru":"Узнайте, как настроить исследование с YAGNI, KISS и DRY для разработчиков приложений Alkana KPI и ИИ Агентов","ar":"تعلم كيفية إعداد البحث باستخدام YAGNI و KISS و DRY لمطوري تطبيقات Alkana KPI وأدوات الذكاء الاصطناعي"},"definition":{"en":"Research is a systematic methodology following YAGNI, KISS, and DRY principles to investigate key terms and concepts.","zh":"研究是指系统信息方法，包括范围定义、评估标准和边界设置，以便在Alkana KPI应用中进行高效研究","ja":"研究とは、AIエージェントを使用したAlkana KPIアプリケーションで効率的な研究を行うための、範囲定義、評価基準、境界設定などを含む体系的な情報方法","ko":"연구는 Alkana KPI 애플리케이션에서 효율적인 연구를 수행하기 위한 체계적인 정보 방법으로, 범위 정의, 평가 기준 및 경계 설정 등을 포함합니다","es":"La investigación es el proceso de definir el alcance y evaluar fuentes para obtener información precisa.","fr":"La recherche est le processus de définition de la portée et d''évaluation des sources pour obtenir des informations précises.","de":"Die Forschung ist der Prozess der Definition des Umfangs und der Bewertung von Quellen, um genaue Informationen zu erhalten.","pt":"Pesquisa é o processo de definição de escopo e avaliação de fontes para obter informações precisas","ru":"Исследование - это процесс определения объема и оценки источников для получения точной информации","ar":"البحث هو عملية تحديد نطاق البحث وتقييم المصادر للحصول على معلومات دقيقة"},"features":{"en":["Defines research scope by identifying key terms and concepts","Determines recency requirements for information","Establishes evaluation criteria for sources","Sets boundaries for research depth","Applies YAGNI, KISS, and DRY principles for efficient research","Conducts systematic information gathering and analysis"],"zh":["遵循YAGNI、KISS和DRY原则","范围定义和评估标准","系统信息方法","边界设置","高效研究"],"ja":["YAGNI、KISS、DRY原則に従った設計","範囲定義と評価基準","体系的な情報方法","境界設定","効率的な研究"],"ko":["YAGNI, KISS, DRY 원칙을 따름","범위 정의 및 평가 기준","체계적인 정보 방법","경계 설정","효율적인 연구"],"es":["Definición del alcance de la investigación","Identificación de términos clave y conceptos","Evaluación de fuentes según criterios establecidos","Aplicación de los principios YAGNI, KISS y DRY","Determinación de la recencia de la información"],"fr":["Définition de la portée de la recherche","Identification des termes clés et des concepts","Évaluation des sources selon des critères établis","Application des principes YAGNI, KISS et DRY","Détermination de la récence de l''information"],"de":["Definition des Umfangs der Forschung","Identifizierung von Schlüsselbegriffen und Konzepten","Bewertung von Quellen nach festgelegten Kriterien","Anwendung der Prinzipien YAGNI, KISS und DRY","Festlegung der Aktualität der Informationen"],"pt":["Definição de escopo de pesquisa com identificação de termos-chave","Avaliação de fontes com critérios de recência e profundidade","Aplicação dos princípios YAGNI, KISS e DRY para pesquisa eficaz","Estabelecimento de boundaries para a profundidade da pesquisa","Utilização de critérios de avaliação para fontes de informação"],"ru":["Определение объема исследования с идентификацией ключевых терминов","Оценка источников по критериям актуальности и глубины","Применение принципов YAGNI, KISS и DRY для эффективного исследования","Установление границ для глубины исследования","Использование критериев оценки для источников информации"],"ar":["تحديد نطاق البحث مع تحديد المصطلحات الرئيسية","تقييم المصادر وفقًا لمعايير الحداثة والعمق","تطبيق مبادئ YAGNI و KISS و DRY للبحث الفعال","تحديد الحدود لنطاق البحث","استخدام معايير التقييم للمصادر المعلوماتية"]},"keywords":{"en":["how to use research methodology","what is research in AI","research alternative for AI agents","research vs traditional investigation","research setup guide for developers","research install for AI systems"],"zh":["研究设置","Alkana KPI应用","系统信息方法","范围定义","评估标准","边界设置","高效研究","AI工具","AI研究"],"ja":["研究の設定","AIエージェント","Alkana KPIアプリケーション","体系的な情報方法","範囲定義","評価基準","境界設定","効率的な研究","AIツール","AI研究"],"ko":["연구 설정","Alkana KPI 애플리케이션","체계적인 정보 방법","범위 정의","평가 기준","경계 설정","효율적인 연구","AI 도구","AI 연구"],"es":["investigación en Alkana KPI","configuración de la investigación","definición del alcance","evaluación de fuentes","principios YAGNI, KISS y DRY","desarrollo de habilidades","herramientas de investigación","agentes de inteligencia artificial"],"fr":["recherche dans Alkana KPI","configuration de la recherche","définition de la portée","évaluation des sources","principes YAGNI, KISS et DRY","développement de compétences","outils de recherche","agents d''intelligence artificielle"],"de":["Forschung in Alkana KPI","Konfiguration der Forschung","Definition des Umfangs","Bewertung von Quellen","Prinzipien YAGNI, KISS und DRY","Entwicklung von Fähigkeiten","Forschungstools","Künstliche Intelligenz Agenten"],"pt":["pesquisa eficaz","YAGNI","KISS","DRY","desenvolvimento de aplicativos","Alkana KPI","pesquisa de desenvolvedores","otimização de pesquisa","melhores práticas de pesquisa"],"ru":["эффективное исследование","YAGNI","KISS","DRY","разработка приложений","Alkana KPI","исследование для разработчиков","оптимизация исследования","лучшие практики исследования","ИИ Агенты"],"ar":["بحث فعال","YAGNI","KISS","DRY","تطوير التطبيقات","Alkana KPI","بحث المطورين","تحسين البحث","أفضل الممارسات البحثية","أدوات الذكاء الاصطناعي"]}},"owner":"hotriluan","repo":"alkana_kpi","repoPath":"hotriluan/alkana_kpi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.314Z","topics":[],"category":"community","skillMd":{"name":"research","description":"[CK] Research technical solutions, analyze architectures, gather requirements thoroughly. Use for technology evaluation, best practices research, solution design, scalability/security/maintainability analysis.","bodyPreview":"# Research\n\n## Research Methodology\n\nAlways honoring **YAGNI**, **KISS**, and **DRY** principles.\n**Be honest, be brutal, straight to the point, and be concise.**\n\n### Phase 1: Scope Definition\n\nFirst, you will clearly define the research scope by:\n- Identifying key terms and concepts to investigate\n- Determining the recency requirements (how current must information be)\n- Establishing evaluation criteria for sources\n- Setting boundaries for the research depth\n\n### Phase 2: Systematic Informatio","body":"# Research\n\n## Research Methodology\n\nAlways honoring **YAGNI**, **KISS**, and **DRY** principles.\n**Be honest, be brutal, straight to the point, and be concise.**\n\n### Phase 1: Scope Definition\n\nFirst, you will clearly define the research scope by:\n- Identifying key terms and concepts to investigate\n- Determining the recency requirements (how current must information be)\n- Establishing evaluation criteria for sources\n- Setting boundaries for the research depth\n\n### Phase 2: Systematic Information Gathering\n\nYou will employ a multi-source research strategy:\n\n1. **Search Strategy**:\n   - **Gemini Toggle**: Check `.claude/.ck.json` (or `~/.claude/.ck.json`) for `skills.research.useGemini` (default: `true`). If `false`, skip Gemini and use WebSearch.\n   - **Gemini Model**: Read from `.claude/.ck.json`: `gemini.model` (default: `gemini-3-flash-preview`)\n   - If `useGemini` is enabled and `gemini` bash command is available, execute `gemini -y -m <gemini.model> \"...your search prompt...\"` bash command (timeout: 10 minutes) and save the output using `Report:` path from `## Naming` section (including all citations).\n   - If `useGemini` is disabled or `gemini` bash command is not available, use `WebSearch` tool.\n   - Run multiple `gemini` bash commands or `WebSearch` tools in parallel to search for relevant information.\n   - Craft precise search queries with relevant keywords\n   - Include terms like \"best practices\", \"2024\", \"latest\", \"security\", \"performance\"\n   - Search for official documentation, GitHub repositories, and authoritative blogs\n   - Prioritize results from recognized authorities (official docs, major tech companies, respected developers)\n   - **IMPORTANT:** You are allowed to perform at most **5 researches (max 5 tool calls)**, user might request less than this amount, **strictly respect it**, think carefully based on the task before performing each related research topic.\n\n2. **Deep Content Analysis**:\n   - When you found a potential Github repository URL, use `docs-seeker` skill to find read it.\n   - Focus on official documentation, API references, and technical specifications\n   - Analyze README files from popular GitHub repositories\n   - Review changelog and release notes for version-specific information\n\n3. **Video Content Research**:\n   - Prioritize content from official channels, recognized experts, and major conferences\n   - Focus on practical demonstrations and real-world implementations\n\n4. **Cross-Reference Validation**:\n   - Verify information across multiple independent sources\n   - Check publication dates to ensure currency\n   - Identify consensus vs. controversial approaches\n   - Note any conflicting information or debates in the community\n\n### Phase 3: Analysis and Synthesis\n\nYou will analyze gathered information by:\n- Identifying common patterns and best practices\n- Evaluating pros and cons of different approaches\n- Assessing maturity and stability of technologies\n- Recognizing security implications and performance considerations\n- Determining compatibility and integration requirements\n\n### Phase 4: Report Generation\n\n**Notes:**\n- Research reports are saved using `Report:` path from `## Naming` section.\n- If `## Naming` section is not available, ask main agent to provide the output path.\n\nYou will create a comprehensive markdown report with the following structure:\n\n```markdown\n# Research Report: [Topic]\n\n## Executive Summary\n[2-3 paragraph overview of key findings and recommendations]\n\n## Research Methodology\n- Sources consulted: [number]\n- Date range of materials: [earliest to most recent]\n- Key search terms used: [list]\n\n## Key Findings\n\n### 1. Technology Overview\n[Comprehensive description of the technology/topic]\n\n### 2. Current State & Trends\n[Latest developments, version information, adoption trends]\n\n### 3. Best Practices\n[Detailed list of recommended practices with explanations]\n\n### 4. Security Considerations\n[Security implications, vulnerabilities, and mitigation strategies]\n\n### 5. Performance Insights\n[Performance characteristics, optimization techniques, benchmarks]\n\n## Comparative Analysis\n[If applicable, comparison of different solutions/approaches]\n\n## Implementation Recommendations\n\n### Quick Start Guide\n[Step-by-step getting started instructions]\n\n### Code Examples\n[Relevant code snippets with explanations]\n\n### Common Pitfalls\n[Mistakes to avoid and their solutions]\n\n## Resources & References\n\n### Official Documentation\n- [Linked list of official docs]\n\n### Recommended Tutorials\n- [Curated list with descriptions]\n\n### Community Resources\n- [Forums, Discord servers, Stack Overflow tags]\n\n### Further Reading\n- [Advanced topics and deep dives]\n\n## Appendices\n\n### A. Glossary\n[Technical terms and definitions]\n\n### B. Version Compatibility Matrix\n[If applicable]\n\n### C. Raw Research Notes\n[Optional: detailed notes from research process]\n```\n\n## Quality Standards\n\nYou will ensure all research meets these criteria:\n- **Accuracy**: Information is verified across multiple sources\n- **Currency**: Prioritize information from the last 12 months unless historical context is needed\n- **Completeness**: Cover all aspects requested by the user\n- **Actionability**: Provide practical, implementable recommendations\n- **Clarity**: Use clear language, define technical terms, provide examples\n- **Attribution**: Always cite sources and provide links for verification\n\n## Special Considerations\n\n- When researching security topics, always check for recent CVEs and security advisories\n- For performance-related research, look for benchmarks and real-world case studies\n- When investigating new technologies, assess community adoption and support levels\n- For API documentation, verify endpoint availability and authentication requirements\n- Always note deprecation warnings and migration paths for older technologies\n\n## Output Requirements\n\nYour final report must:\n1. Be saved using the `Report:` path from `## Naming` section with a descriptive filename\n2. Include a timestamp of when the research was conducted\n3. Provide clear section navigation with a table of contents for longer reports\n4. Use code blocks with appropriate syntax highlighting\n5. Include diagrams or architecture descriptions where helpful (in mermaid or ASCII art)\n6. Conclude with specific, actionable next steps\n\n**IMPORTANT:** Sacrifice grammar for the sake of concision when writing reports.\n**IMPORTANT:** In reports, list any unresolved questions at the end, if any.\n\n**Remember:** You are not just collecting information, but providing strategic technical intelligence that enables informed decision-making. Your research should anticipate follow-up questions and provide comprehensive coverage of the topic while remaining focused and practical."},"lastSynced":"2026-03-08T02:02:42.933Z","agentAnalysis":{"suitability":{"en":"Ideal for Knowledge Agents requiring systematic investigation capabilities through scope definition and source evaluation.","zh":"非常适合需要通过定义范围和信息源评估来获得系统性调查能力的知识代理。","ja":"範囲定義と情報源評価を通じて体系的な調査能力を必要とするナレッジエージェントに最適です。","ko":"범위 정의 및 소스 평가를 통한 체계적인 조사 기능이 필요한 지식 에이전트에 이상적입니다.","es":"Ideal para Agentes de Conocimiento que requieren capacidades de investigación sistemática a través de la definición de alcance y evaluación de fuentes.","fr":"Idéal pour les Agents de Connaissance nécessitant des capacités d''enquête systématique via la définition de la portée et l''évaluation des sources.","de":"Ideal für Wissensagenten, die systematische Untersuchungsfähigkeiten durch Definitions- und Quellenbewertung erfordern.","pt":"Ideal para Agentes de Conhecimento que requerem capacidades de investigação sistemática por meio de definição de escopo e avaliação de fontes.","ru":"Идеально для агентов знаний, требующих системных возможностей расследования через определение объема и оценку источников.","ar":"مثالية للوكلاء المعرفيين الذين يحتاجون إلى قدرات تحقيق منهجية من خلال تعريف النطاق وتقييم المصادر."},"recommendation":{"en":"Empowers agents to conduct thorough research by applying YAGNI, KISS, and DRY principles, utilizing key terms, recency requirements, and evaluation criteria for sources, while setting research depth boundaries through protocols like systematic information analysis.","zh":"通过应用 YAGNI、KISS 和 DRY 原则，利用关键术语、时效性要求和信息源评估标准，使代理能够进行彻底的研究，同时通过系统性信息分析等协议设定研究深度边界。","ja":"YAGNI、KISS、DRY の原則を適用し、キーワード、情報の鮮度要件、情報源の評価基準を利用して、エージェントが徹底的な調査を実施できるようにします。また、体系的な情報分析などのプロトコルを通じて調査の深さの境界を設定します。","ko":"YAGNI, KISS, DRY 원칙을 적용하고 핵심 용어, 최신성 요구사항 및 소스에 대한 평가 기준을 활용하여 에이전트가 철저한 연구를 수행할 수 있도록 합니다. 또한 체계적 정보 분석과 같은 프로토콜을 통해 연구 깊이 경계를 설정합니다.","es":"Habilita a los agentes a realizar investigaciones exhaustivas aplicando los principios YAGNI, KISS y DRY, utilizando términos clave, requisitos de recencia y criterios de evaluación para fuentes, y estableciendo límites de profundidad de investigación a través de protocolos como el análisis sistemático de información.","fr":"Permet aux agents de mener des recherches approfondies en appliquant les principes YAGNI, KISS et DRY, en utilisant des termes clés, des exigences de récence et des critères d''évaluation pour les sources, et en définissant les limites de profondeur de recherche via des protocoles tels que l''analyse systématique d''information.","de":"Ermächtigt die Agenten, gründliche Recherchen durchzuführen, indem die YAGNI-, KISS- und DRY-Prinzipien angewendet werden, Schlüsselbegriffe, Aktualitätsanforderungen und Bewertungskriterien für Quellen genutzt werden und die Recherchetiefengrenzen durch Protokolle wie die systematische Informationsanalyse festgelegt werden.","pt":"Habilita os agentes a realizar pesquisas aprofundadas aplicando os princípios YAGNI, KISS e DRY, utilizando termos-chave, requisitos de recência e critérios de avaliação para fontes, ao mesmo tempo definindo limites de profundidade de pesquisa por meio de protocolos como análise sistemática de informações.","ru":"Наделяет агентов возможностью проводить тщательное исследование, применяя принципы YAGNI, KISS и DRY, используя ключевые термины, требования новизны и критерии оценки источников, а также устанавливая границы глубины исследования через протоколы, такие как системный анализ информации.","ar":"تمكّن الوكلاء من إجراء بحث شامل من خلال تطبيق مبادئ YAGNI و KISS و DRY، واستخدام المصطلحات الرئيسية ومتطلبات الحديثة ومعايير التقييم للمصادر، مع تحديد حدود عمق البحث من خلال بروتوكولات مثل التحليل المنهجي للمعلومات."},"useCases":{"en":["Defining research scope for key concepts","Evaluating source credibility based on recency and criteria","Conducting systematic information analysis for in-depth research"],"zh":["为关键概念定义研究范围","基于时效性和标准评估信息源的可信度","为深入研究进行系统性信息分析"],"ja":["主要概念の調査範囲を定義する","鮮度と基準に基づいて情報源の信頼性を評価する","詳細な調査のために体系的な情報分析を実施する"],"ko":["핵심 개념에 대한 연구 범위 정의","최신성 및 기준에 기반한 소스 신뢰성 평가","심층 연구를 위한 체계적 정보 분석 수행"],"es":["Definir el alcance de la investigación para conceptos clave","Evaluar la credibilidad de las fuentes en función de la recencia y los criterios","Realizar un análisis sistemático de información para una investigación en profundidad"],"fr":["Définir la portée de la recherche pour les concepts clés","Évaluer la crédibilité des sources en fonction de la récence et des critères","Effectuer une analyse systématique d''information pour une recherche en profondeur"],"de":["Forschungsumfang für Schlüsselkonzepte definieren","Glaubwürdigkeit von Quellen anhand von Aktualität und Kriterien bewerten","Systematische Informationsanalyse für eine tiefere Recherche durchführen"],"pt":["Definir escopo de pesquisa para conceitos-chave","Avaliar credibilidade de fontes com base na recência e nos critérios","Realizar análise sistemática de informações para pesquisas aprofundadas"],"ru":["Определение области исследования для ключевых концепций","Оценка достоверности источников на основе новизны и критериев","Проведение системного анализа информации для углубленного исследования"],"ar":["تحديد نطاق البحث للمفاهيم الرئيسية","تقييم مصداقية المصادر بناءً على الحديثة والمعايير","إجراء تحليل منهجي للمعلومات من أجل بحث متعمق"]},"limitations":{"en":["Requires clear scope definition","Dependent on quality and availability of sources","Bound by research depth boundaries"],"zh":["需要清晰的范围定义","依赖于信息源的质量和可用性","受研究深度边界的限制"],"ja":["明確な範囲定義が必要","情報源の品質と可用性に依存する","調査の深さの境界によって制限される"],"ko":["명확한 범위 정의가 필요함","소스의 품질과 가용성에 의존함","연구 깊이 경계에 의해 제한됨"],"es":["Requiere una definición clara del alcance","Depende de la calidad y disponibilidad de las fuentes","Limitado por los límites de profundidad de la investigación"],"fr":["Nécessite une définition claire de la portée","Dépend de la qualité et de la disponibilité des sources","Limité par les limites de profondeur de la recherche"],"de":["Benötigt eine klare Definitions- und Umfangsabgrenzung","Hängt von der Qualität und Verfügbarkeit der Quellen ab","Durch Recherchetiefengrenzen eingeschränkt"],"pt":["Exige definição clara de escopo","Depende da qualidade e disponibilidade de fontes","Limitado por limites de profundidade de pesquisa"],"ru":["Требует четкого определения объема","Зависит от качества и доступности источников","Ограничен границами глубины исследования"],"ar":["يتطلب تعريفًا واضحًا للنطاق","يعتمد على جودة ومتاحة للمصادر","محدود بحدود عمق البحث"]},"version":4},"contentHash":"d7eed88b8d795e30c8c17661998aeffc1246d8caac283f935f27a3382a1bc36b","qualityScore":60}');
