INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hotriluan/alkana_kpi/research', 'research', 'hotriluan', 'alkana_kpi', 'community', 'research hotriluan alkana_kpi community The research skill enables AI agents to conduct systematic investigations by defining scope and evaluating sources, benefiting developers and researchers. 研究技能遵循YAGNI、KISS和DRY原则，提供系统信息方法，包括范围定义和评估标准 研究スキルは、YAGNI、KISS、DRY原則に従い、範囲定義や評価基準を含む体系的な情報方法を提供します 연구 스킬은 YAGNI, KISS, DRY 원칙을 따르며, 범위 정의 및 평가 기준을 포함한 체계적인 정보 방법을 제공합니다 La investigación en Alkana KPI implica la definición del alcance, la identificación de términos clave y la evaluación de fuentes. Nuestro enfoque sigue los principios YAGNI, KISS y DRY. La recherche dans Alkana KPI implique la définition de la portée, l''identification des termes clés et l''évaluation des sources. Notre approche suit les principes YAGNI, KISS et DRY. Die Forschung in Alkana KPI umfasst die Definition des Umfangs, die Identifizierung von Schlüsselbegriffen und die Bewertung von Quellen. Unser Ansatz folgt den Prinzipien YAGNI, KISS und DRY. Pesquisa eficaz com YAGNI, KISS e DRY para desenvolvedores de aplicativos Alkana KPI. Defina o escopo e avalie fontes com critérios claros. Эффективное исследование с YAGNI, KISS и DRY для разработчиков приложений Alkana KPI и ИИ Агентов. Определите объем и оцените источники по четким критериям. بحث فعال باستخدام YAGNI و KISS و DRY لمطوري تطبيقات Alkana KPI وأدوات الذكاء الاصطناعي. حدد نطاق البحث وقيم المصادر وفقًا لمعايير واضحة. how to use research methodology what is research in AI research alternative for AI agents research vs traditional investigation research setup guide for developers research install for AI systems 研究设置 Alkana KPI应用 系统信息方法 范围定义 评估标准 边界设置 高效研究 AI工具 AI研究 Defines research scope by identifying key terms and concepts Determines recency requirements for information Establishes evaluation criteria for sources Sets boundaries for research depth Applies YAGNI, KISS, and DRY principles for efficient research Conducts systematic information gathering and analysis Research is a systematic methodology following YAGNI, KISS, and DRY principles to investigate key terms and concepts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('LRYuChi/TAHZAN-ARCHIVE/senior-qa', 'community', 'LRYuChi', 'TAHZAN-ARCHIVE', 'LRYuChi/TAHZAN-ARCHIVE', 'senior-qa', 0, 0, 60, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:43.872Z', '56333175357e063431866673bd24df8b84638d9239ae32c31469468d5fa65bd6', '{"id":"LRYuChi/TAHZAN-ARCHIVE/senior-qa","name":"senior-qa","description":{"en":"The senior-qa skill provides a complete toolkit for senior QA engineers, offering automated scripts for test suite generation, coverage analysis, and E2E test scaffolding. It benefits developers and testers seeking to streamline their testing workflows.","zh":"Senior Qa 技能是一套用于高级 QA 的工具包，包括自动化测试套件生成、覆盖率分析和端到端测试脚手架等功能","ja":"Senior Qa スキルは、高度な QA を実現するためのツールキットであり、テストスイートの自動生成、カバレッジ分析、E2E テストのスケルトン作成などを提供します","ko":"Senior Qa 기능은 고급 QA를 위한 완전한 도구 키트이며 자동화된 테스트 스위트 생성, 커버리지 분석 및 E2E 테스트 스캐폴딩 등을 제공합니다","es":"Senior QA es una herramienta de automatización que proporciona scripts de Python para generar suites de pruebas, analizar cobertura y crear estructuras de pruebas de extremo a extremo","fr":"Senior QA est un outil d''automatisation qui fournit des scripts Python pour générer des suites de tests, analyser la couverture et créer des structures de tests de bout en bout","de":"Senior QA ist ein Automatisierungstool, das Python-Skripte zur Generierung von Test-Suiten, Analyse von Abdeckung und Erstellung von End-to-End-Teststrukturen bietet","pt":"O Senior QA é um conjunto de ferramentas para testes automatizados, incluindo gerador de Conjunto de Testes, Analisador de Cobertura e Estruturador de Testes de Ponta a Ponta","ru":"Senior QA - это набор инструментов для автоматизированного тестирования, включающий генератор набора тестов, анализатор покрытия и создатель тестов от начала до конца","ar":"المسؤول القuido Senior QA هو مجموعة من الأدوات للاختبار الآلي، بما في ذلك مولد مجموعة الاختبار، ومحلل التغطية، ومخطط اختبار من النهاية إلى النهاية"},"seo":{"title":{"en":"senior-qa: Automated Testing Toolkit for AI Agents | AI A...","zh":"Senior Qa 设置指南：自动化测试套件生成","ja":"Senior Qa のベストプラクティス：AIエージェントによるテスト自動化","ko":"Senior Qa 사용자 가이드: 자동화된 테스트 스위트 생성","es":"Guía de configuración de Senior QA con herramientas de au...","fr":"Guide de mise en place de Senior QA avec des outils d''aut...","de":"Senior QA-Setup-Anleitung mit Automatisierungstools","pt":"Guia de Configuração do Senior QA: Ferramentas Modernas p...","ru":"Настройка Senior QA: Полный Комплект Инструментов для Тес...","ar":"إعداد المسؤول القuido Senior QA: أدوات حديثة للاختبار"},"description":{"en":"Unlock efficient testing with senior-qa! Discover how to automate test suites, analyze coverage, and scaffold E2E tests with Python scripts","zh":"Senior Qa 技能提供自动化测试套件生成、覆盖率分析和端到端测试脚手架等功能","ja":"Senior Qa スキルは、テストスイートの自動生成、カバレッジ分析、E2E テストのスケルトン作成などを提供します","ko":"Senior Qa 기능은 자동화된 테스트 스위트 생성, 커버리지 분석 및 E2E 테스트 스캐폴딩 등을 제공합니다","es":"Aprende a utilizar Senior QA con scripts de automatización para generar suites de pruebas, analizar cobertura y crear estructuras de pruebas de extremo a ext...","fr":"Découvrez comment utiliser Senior QA avec des scripts d''automatisation pour générer des suites de tests, analyser la couverture et créer des structures de te...","de":"Erfahren Sie, wie Sie Senior QA mit Automatisierungsskripten verwenden, um Test-Suiten zu generieren, Abdeckung zu analysieren und End-to-End-Teststrukturen ...","pt":"Aprenda a configurar o Senior QA com as melhores práticas e ferramentas modernas para testes automatizados","ru":"Узнайте, как настроить Senior QA с современными инструментами и лучшими практиками для автоматизированного тестирования","ar":"تعرف على كيفية إعداد المسؤول القuido Senior QA باستخدام الأدوات الحديثة وأفضل الممارسات للاختبار الآلي"},"definition":{"en":"senior-qa is a comprehensive testing toolkit that leverages Python scripts to automate testing processes, including test suite generation, coverage analysis, and E2E test scaffolding","zh":"Senior Qa 是一种用于高级 QA 的自动化测试工具","ja":"Senior Qa は、高度な QA を実現するための自動テストツールです","ko":"Senior Qa 는 고급 QA를 위한 자동화된 테스트 도구입니다","es":"Senior QA es un conjunto de herramientas de automatización para pruebas de software que incluye scripts de Python para generar suites de pruebas y analizar cobertura","fr":"Senior QA est un ensemble d''outils d''automatisation pour les tests de logiciels qui inclut des scripts Python pour générer des suites de tests et analyser la couverture","de":"Senior QA ist ein Satz von Automatisierungstools für Softwaretests, der Python-Skripte zur Generierung von Test-Suiten und Analyse von Abdeckung enthält","pt":"O que é Senior QA? É um conjunto de ferramentas para testes automatizados com scripts Python","ru":"Что такое Senior QA? Это набор инструментов для автоматизированного тестирования с скриптами Python","ar":"ما هو المسؤول القuido Senior QA? هو مجموعة من الأدوات للاختبار الآلي مع سكريبتات Python"},"features":{"en":["Automated test suite generation using python scripts/test_suite_generator.py","Coverage analysis with python scripts/coverage_analyzer.py","E2E test scaffolding using python scripts/e2e_test_scaffolder.py","Support for customizable testing options via command-line arguments","Integration with Python for seamless testing automation"],"zh":["自动化测试套件生成","覆盖率分析","端到端测试脚手架","Python 脚本支持","CLI 接口"],"ja":["テストスイートの自動生成","カバレッジ分析","E2E テストのスケルトン作成","Python スクリプトのサポート","CLI インターフェース"],"ko":["자동화된 테스트 스위트 생성","커버리지 분석","E2E 테스트 스캐폴딩","Python 스크립트 지원","CLI 인터페이스"],"es":["Generación de suites de pruebas con scripts de Python","Análisis de cobertura con scripts de Python","Creación de estructuras de pruebas de extremo a extremo con scripts de Python","Uso de herramientas de automatización para mejorar la eficiencia de las pruebas","Compatibilidad con scripts de Python para personalizar las pruebas","Integración con herramientas de desarrollo para un flujo de trabajo más efi