INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('LRYuChi/TAHZAN-ARCHIVE/senior-qa', 'senior-qa', 'LRYuChi', 'TAHZAN-ARCHIVE', 'community', 'senior-qa LRYuChi TAHZAN-ARCHIVE community The senior-qa skill provides a complete toolkit for senior QA engineers, offering automated scripts for test suite generation, coverage analysis, and E2E test scaffolding. It benefits developers and testers seeking to streamline their testing workflows. Senior Qa 技能是一套用于高级 QA 的工具包，包括自动化测试套件生成、覆盖率分析和端到端测试脚手架等功能 Senior Qa スキルは、高度な QA を実現するためのツールキットであり、テストスイートの自動生成、カバレッジ分析、E2E テストのスケルトン作成などを提供します Senior Qa 기능은 고급 QA를 위한 완전한 도구 키트이며 자동화된 테스트 스위트 생성, 커버리지 분석 및 E2E 테스트 스캐폴딩 등을 제공합니다 Senior QA es una herramienta de automatización que proporciona scripts de Python para generar suites de pruebas, analizar cobertura y crear estructuras de pruebas de extremo a extremo Senior QA est un outil d''automatisation qui fournit des scripts Python pour générer des suites de tests, analyser la couverture et créer des structures de tests de bout en bout Senior QA ist ein Automatisierungstool, das Python-Skripte zur Generierung von Test-Suiten, Analyse von Abdeckung und Erstellung von End-to-End-Teststrukturen bietet O Senior QA é um conjunto de ferramentas para testes automatizados, incluindo gerador de Conjunto de Testes, Analisador de Cobertura e Estruturador de Testes de Ponta a Ponta Senior QA - это набор инструментов для автоматизированного тестирования, включающий генератор набора тестов, анализатор покрытия и создатель тестов от начала до конца المسؤول القuido Senior QA هو مجموعة من الأدوات للاختبار الآلي، بما في ذلك مولد مجموعة الاختبار، ومحلل التغطية، ومخطط اختبار من النهاية إلى النهاية how to use senior-qa senior-qa alternative senior-qa setup guide what is senior-qa senior-qa vs testing frameworks senior-qa install automated testing with senior-qa senior-qa tutorial senior-qa best practices Senior Qa 自动化测试 测试套件生成 覆盖率分析 端到端测试 Python 脚本 CLI 接口 AI エージェント Automated test suite generation using python scripts/test_suite_generator.py Coverage analysis with python scripts/coverage_analyzer.py E2E test scaffolding using python scripts/e2e_test_scaffolder.py Support for customizable testing options via command-line arguments Integration with Python for seamless testing automation senior-qa is a comprehensive testing toolkit that leverages Python scripts to automate testing processes, including test suite generation, coverage analysis, and E2E test scaffolding');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Kjdragan/universal_agent/agent-browser', 'community', 'Kjdragan', 'universal_agent', 'Kjdragan/universal_agent', 'agent-browser', 0, 0, 60, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:45.886Z', '9c4e7cf452e67986807fd58bc5068bad462b4ea4ca818a8e23456d15931938d0', '{"id":"Kjdragan/universal_agent/agent-browser","name":"agent-browser","description":{"en":"The agent-browser skill enables developers to automate browser interactions, capturing interactive elements and performing actions like clicking and filling inputs. It benefits developers working with AI agents.","zh":"agent-browser 是一个浏览器自动化工具，支持打开页面、获取交互元素、点击和填充表单等功能","ja":"agent-browser はブラウザ自動化ツールで、ページを開き、インタラクティブ要素を取得し、クリックしてフォームを埋めることができます","ko":"agent-browser는 브라우저 자동화 도구로 페이지를 열고 상호 작용 요소를 가져와 클릭하고 양식을 채울 수 있습니다","es":"El agent-browser es una herramienta de automatización de navegador que permite interactuar con elementos web mediante comandos CLI","fr":"L''agent-browser est un outil d''automatisation de navigation qui permet d''interagir avec des éléments web à l''aide de commandes CLI","de":"Der agent-browser ist ein Browser-Automatisierungstool, das die Interaktion mit Web-Elementen über CLI-Befehle ermöglicht","pt":"O agent-browser é uma ferramenta de automação de navegador que permite executar comandos como open, snapshot, click e fill","ru":"ИИ Агент agent-browser - это инструмент для автоматизации браузера, который позволяет выполнять команды open, snapshot, click и fill","ar":"وحدات الإيجاد الآلي agent-browser هي أداة لتutomazione المتصفح التي تسمح بتنفيذ أوامر مثل open و snapshot و click و fill"},"seo":{"title":{"en":"agent-browser: Browser Automation Setup Guide | AI Agent ...","zh":"AIエージェント工具：agent-browser 自动化浏览器设置指南","ja":"AIエージェント：agent-browser ブラウザ自動化セットアップガイド","ko":"AI 에이전트 도구: agent-browser 브라우저 자동화 설정 가이드","es":"Guía de configuración de agent-browser para automatizació...","fr":"Guide de démarrage rapide pour l''agent-browser de navigat...","de":"Einrichtungsleitfaden für agent-browser zur Browser-Autom...","pt":"Guia de Configuração do agent-browser para Automação de N...","ru":"ИИ Агенты: Настройка agent-browser для Автоматизации Брау...","ar":"دليل إعداد وحدات الإيجاد الآلي agent-browser لتutomazione..."},"description":{"en":"Unlock efficient browser automation with agent-browser. Learn how to navigate, snapshot, and interact with web pages using commands like ''agent-browser open''...","zh":"使用 agent-browser 实现浏览器自动化，轻松打开页面、获取交互元素、点击和填充表单","ja":"agent-browser を使用してブラウザ自動化を実現します。ページを開き、インタラクティブ要素を取得し、クリックしてフォームを埋めます","ko":"agent-browser를 사용하여 브라우저 자동화를 구현합니다. 페이지를 열고 상호 작용 요소를 가져와 클릭하고 양식을 채웁니다","es":"Aprende a utilizar agent-browser para automatizar tareas en el navegador con comandos como ''open'', ''snapshot'' y ''click''","fr":"Découvrez comment utiliser l''agent-browser pour automatiser les tâches de navigation avec des commandes telles que ''open'', ''snapshot'' et ''click''","de":"Erfahren Sie, wie Sie agent-browser verwenden, um Aufgaben im Browser mit Befehlen wie ''open'', ''snapshot'' und ''click'' zu automatisieren","pt":"Aprenda a utilizar o agent-browser para automação de navegador com comandos como open, snapshot, click e fill","ru":"Узнайте, как использовать agent-browser для автоматизации браузера с командами open, snapshot, click и fill","ar":"تعلم كيفية استخدام وحدات الإيجاد الآلي agent-browser لتutomazione المتصفح بأوامر مثل open و snapshot و click و fill"},"definition":{"en":"agent-browser is a browser automation tool that allows developers to navigate, snapshot, and interact with web pages using specific commands and references","zh":"agent-browser 是一个命令行界面（CLI）工具，用于自动化浏览器操作","ja":"agent-browser はコマンドラインインターフェース（CLI）ツールで、ブラウザ操作を自動化するために使用されます","ko":"agent-browser는 명령줄 인터페이스（CLI） 도구로 브라우저 작업을 자동화하는 데 사용됩니다","es":"El agent-browser es una herramienta de automatización de navegador que utiliza comandos CLI para interactuar con elementos web","fr":"L''agent-browser est un outil d''automatisation de navigation qui utilise des commandes CLI pour interagir avec des éléments web","de":"Der agent-browser ist ein Browser-Automatisierungstool, das CLI-Befehle verwendet, um mit Web-Elementen zu interagieren","pt":"O agent-browser é uma ferramenta de automação de navegador que executa comandos via linha de comando","ru":"ИИ Агент agent-browser - это инструмент для автоматизации браузера, который выполняет команды через командную строку","ar":"وحدات الإيجاد الآلي agent-browser هي أداة لتutomazione المتصفح التي تنفذ أوامر عبر سطر الأوامر"},"features":{"en":["Navigates to web pages using ''agent-browser open <url>'' command","Captures interactive elements with references like ''@e1'' and ''@e2'' using ''agent-browser snapshot -i''","Performs click actions on elements by reference using ''agent-browser click @e1''","Fills input fields by reference using ''agent-browser fill @e2 \"text\"''","Closes the browser instance using ''agent-browser close'' command"],"zh":["支持打开页面：`agent-browser open <url>`","支持获取交互元素：`agent-browser snapshot -i`","支持点击元素：`agent-browser click @e1`","支持填充表单：`agent-browser fill @e2 \"text\"`"],"ja":["ページを開くことをサポート：`agent-browser open <url>`","インタラクティブ要素を取得することをサポート：`agent-browser snapshot -i`","要素をクリックすることをサポート：`agent-browser click @e1`","フォームを埋めることをサポート：`agent-browser fill @e2 \"text\"`"],"ko":["페이지를 여는 것을 지원：`agent-browser open <url>`","상호 작용 요소를 가져오는 것을 지원：`agent-browser snapshot -i`","요소를 클릭하는 것을 지원：`agent-browser click @e1`","양식을 채우는 것을 지원：`agent-browser fill @e2 \"text\"`"],"es":["Automatización de navegación con comandos CLI","Captura de elementos web con ''snapshot''","Interacción con elementos web mediante ''click'' y ''fill''","Soporte para referencias de elementos web (@e1, @e2)","Cierre del navegador con ''close''"],"fr":["Automatisation de la navigation avec des commandes CLI","Capture d''éléments web avec ''snapshot''","Interaction avec des éléments web via ''click'' et ''fill''","Prise en charge des références d''éléments web (@e1, @e2)","Fermeture du navigateur avec ''close''"],"de":["Automatisierung der Navigation mit CLI-Befehlen","Aufnahme von Web-Elementen mit ''snapshot''","Interaktion mit Web-Elementen über ''click'' und ''fill''","Unterstützung für Web-Element-Referenzen (@e1, @e2)","Schließen des Browsers mit ''close''"],"pt":["Abre URLs com o comando open","Captura elementos interativos com o comando snapshot","Clica em elementos com o comando click","Preenche inputs com o comando fill","Fecha o navegador com o comando close"],"ru":["Открывает URL-адреса с помощью команды open","Создает снимки интерактивных элементов с помощью команды snapshot","Кликает на элементы с помощью команды click","Заполняет поля ввода с помощью команды fill","Закрывает браузер с помощью команды close"],"ar":["فتح عناوين URL باستخدام أمر open","التقط عناصر تفاعلية باستخدام أمر snapshot","نقر على عناصر باستخدام أمر click","ملء المدخلات باستخدام أمر fill","إغلاق المتصفح باستخدام أمر close"]},"keywords":{"en":["how to use agent-browser","agent-browser setup guide","browser automation with agent-browser","agent-browser alternative","agent-browser vs selenium","agent-browser install","what is agent-browser","agent-browser documentation","agent-browser tutorial"],"zh":["agent-browser","浏览器自动化","命令行界面","CLI","自动化工具","AIエージェント工具","浏览器操作自动化"],"ja":["agent-browser","ブラウザ自動化","コマンドラインインターフェース","CLI","自動化ツール","AIエージェント","ブラウザ操作自動化"],"ko":["agent-browser","브라우저 자동화","명령줄 인터페이스","CLI","자동화 도구","AI 에이전트 도구","브라우저 작업 자동화"],"es":["agent-browser","automatización de navegador","comandos CLI","herramientas de automatización","interacción con elementos web","referencias de elementos web","Herramientas de AI para desarrolladores","agentes de automatización"],"fr":["agent-browser","automatisation de navigation","commandes CLI","outils d''automatisation","interaction avec des éléments web","références d''éléments web","Outils d''IA pour les développeurs","agents d''automatisation"],"de":["agent-browser","Browser-Automatisierung","CLI-Befehle","Automatisierungstools","Interaktion mit Web-Elementen","Web-Element-Referenzen","AI-Tools für Entwickler","Automatisierungsagenten"],"pt":["agent-browser","automação de navegador","comandos de linha de comando","open","snapshot","click","fill","close","ferramentas de automação"],"ru":["ИИ Агенты","автоматизация браузера","командная строка","open","snapshot","click","fill","close","инструменты автоматизации"],"ar":["وحدات الإيجاد الآلي","تutomazione المتصفح","سطر الأوامر","open","snapshot","click","fill","close","أدوات التutomazione"]}},"owner":"Kjdragan","repo":"universal_agent","repoPath":"Kjdragan/universal_agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"agent-browser","description":"Automates browser interactions for web testing, form filling, screenshots, and data extraction. Use when the user needs to navigate websites, interact with web pages, fill forms, take screenshots, test web applications, or extract information from web pages.","bodyPreview":"# Browser Automation with agent-browser\n\n## Quick start\n\n```bash\nagent-browser open <url>        # Navigate to page\nagent-browser snapshot -i       # Get interactive elements with refs\nagent-browser click @e1         # Click element by ref\nagent-browser fill @e2 \"text\"   # Fill input by ref\nagent-browser close             # Close browser\n```\n\n## Core workflow\n\n1. Navigate: `agent-browser open <url>`\n2. Snapshot: `agent-browser snapshot -i` (returns elements with refs like `@e1`, `@e2`)\n3. Intera","body":"# Browser Automation with agent-browser\n\n## Quick start\n\n```bash\nagent-browser open <url>        # Navigate to page\nagent-browser snapshot -i       # Get interactive elements with refs\nagent-browser click @e1         # Click element by ref\nagent-browser fill @e2 \"text\"   # Fill input by ref\nagent-browser close             # Close browser\n```\n\n## Core workflow\n\n1. Navigate: `agent-browser open <url>`\n2. Snapshot: `agent-browser snapshot -i` (returns elements with refs like `@e1`, `@e2`)\n3. Interact using refs from the snapshot\n4. Re-snapshot after navigation or significant DOM changes\n\n## Commands\n\n### Navigation\n```bash\nagent-browser open <url>      # Navigate to URL\nagent-browser back            # Go back\nagent-browser forward         # Go forward\nagent-browser reload          # Reload page\nagent-browser close           # Close browser\n```\n\n### Snapshot (page analysis)\n```bash\nagent-browser snapshot            # Full accessibility tree\nagent-browser snapshot -i         # Interactive elements only (recommended)\nagent-browser snapshot -c         # Compact output\nagent-browser snapshot -d 3       # Limit depth to 3\nagent-browser snapshot -s \"#main\" # Scope to CSS selector\n```\n\n### Interactions (use @refs from snapshot)\n```bash\nagent-browser click @e1           # Click\nagent-browser dblclick @e1        # Double-click\nagent-browser focus @e1           # Focus element\nagent-browser fill @e2 \"text\"     # Clear and type\nagent-browser type @e2 \"text\"     # Type without clearing\nagent-browser press Enter         # Press key\nagent-browser press Control+a     # Key combination\nagent-browser keydown Shift       # Hold key down\nagent-browser keyup Shift         # Release key\nagent-browser hover @e1           # Hover\nagent-browser check @e1           # Check checkbox\nagent-browser uncheck @e1         # Uncheck checkbox\nagent-browser select @e1 \"value\"  # Select dropdown\nagent-browser scroll down 500     # Scroll page\nagent-browser scrollintoview @e1  # Scroll element into view\nagent-browser drag @e1 @e2        # Drag and drop\nagent-browser upload @e1 file.pdf # Upload files\n```\n\n### Get information\n```bash\nagent-browser get text @e1        # Get element text\nagent-browser get html @e1        # Get innerHTML\nagent-browser get value @e1       # Get input value\nagent-browser get attr @e1 href   # Get attribute\nagent-browser get title           # Get page title\nagent-browser get url             # Get current URL\nagent-browser get count \".item\"   # Count matching elements\nagent-browser get box @e1         # Get bounding box\n```\n\n### Check state\n```bash\nagent-browser is visible @e1      # Check if visible\nagent-browser is enabled @e1      # Check if enabled\nagent-browser is checked @e1      # Check if checked\n```\n\n### Data Extraction Best Practices\n- **Prefer `innerText`**: Dynamic sites often obfuscate class names (e.g., `css-1234`). Use `document.body.innerText` to get all text and parse it with your LLM context.\n- **Use `snapshot -i`**: This uses the accessibility tree which is more stable than HTML structure, especially for interactive elements.\n- **Avoid complex selectors**: Selectors like `div > div:nth-child(3)` are brittle. If you must use JS, try robust queries like `document.querySelectorAll(''a[href*=\"showtime\"]'')`.\n- **Fallback**: If a JS extraction returns `[]`, immediately fallback to getting the whole page text.\n\n\n### Screenshots & PDF\n```bash\nagent-browser screenshot          # Screenshot to stdout\nagent-browser screenshot path.png # Save to file\nagent-browser screenshot --full   # Full page\nagent-browser pdf output.pdf      # Save as PDF\n```\n\n### Video recording\n```bash\nagent-browser record start ./demo.webm    # Start recording (uses current URL + state)\nagent-browser click @e1                   # Perform actions\nagent-browser record stop                 # Stop and save video\nagent-browser record restart ./take2.webm # Stop current + start new recording\n```\nRecording creates a fresh context but preserves cookies/storage from your session. If no URL is provided, it automatically returns to your current page. For smooth demos, explore first, then start recording.\n\n### Wait\n```bash\nagent-browser wait @e1                     # Wait for element\nagent-browser wait 2000                    # Wait milliseconds\nagent-browser wait --text \"Success\"        # Wait for text\nagent-browser wait --url \"**/dashboard\"    # Wait for URL pattern\nagent-browser wait --load networkidle      # Wait for network idle\nagent-browser wait --fn \"window.ready\"     # Wait for JS condition\n```\n\n### Mouse control\n```bash\nagent-browser mouse move 100 200      # Move mouse\nagent-browser mouse down left         # Press button\nagent-browser mouse up left           # Release button\nagent-browser mouse wheel 100         # Scroll wheel\n```\n\n### Semantic locators (alternative to refs)\n```bash\nagent-browser find role button click --name \"Submit\"\nagent-browser find text \"Sign In\" click\nagent-browser find label \"Email\" fill \"user@test.com\"\nagent-browser find first \".item\" click\nagent-browser find nth 2 \"a\" text\n```\n\n### Browser settings\n```bash\nagent-browser set viewport 1920 1080      # Set viewport size\nagent-browser set device \"iPhone 14\"      # Emulate device\nagent-browser set geo 37.7749 -122.4194   # Set geolocation\nagent-browser set offline on              # Toggle offline mode\nagent-browser set headers ''{\"X-Key\":\"v\"}'' # Extra HTTP headers\nagent-browser set credentials user pass   # HTTP basic auth\nagent-browser set media dark              # Emulate color scheme\n```\n\n### Cookies & Storage\n```bash\nagent-browser cookies                     # Get all cookies\nagent-browser cookies set name value      # Set cookie\nagent-browser cookies clear               # Clear cookies\nagent-browser storage local               # Get all localStorage\nagent-browser storage local key           # Get specific key\nagent-browser storage local set k v       # Set value\nagent-browser storage local clear         # Clear all\n```\n\n### Network\n```bash\nagent-browser network route <url>              # Intercept requests\nagent-browser network route <url> --abort      # Block requests\nagent-browser network route <url> --body ''{}''  # Mock response\nagent-browser network unroute [url]            # Remove routes\nagent-browser network requests                 # View tracked requests\nagent-browser network requests --filter api    # Filter requests\n```\n\n### Tabs & Windows\n```bash\nagent-browser tab                 # List tabs\nagent-browser tab new [url]       # New tab\nagent-browser tab 2               # Switch to tab\nagent-browser tab close           # Close tab\nagent-browser window new          # New window\n```\n\n### Frames\n```bash\nagent-browser frame \"#iframe\"     # Switch to iframe\nagent-browser frame main          # Back to main frame\n```\n\n### Dialogs\n```bash\nagent-browser dialog accept [text]  # Accept dialog\nagent-browser dialog dismiss        # Dismiss dialog\n```\n\n### JavaScript\n```bash\nagent-browser eval \"document.title\"   # Run JavaScript\n```\n\n## Example: Form submission\n\n```bash\nagent-browser open https://example.com/form\nagent-browser snapshot -i\n# Output shows: textbox \"Email\" [ref=e1], textbox \"Password\" [ref=e2], button \"Submit\" [ref=e3]\n\nagent-browser fill @e1 \"user@example.com\"\nagent-browser fill @e2 \"password123\"\nagent-browser click @e3\nagent-browser wait --load networkidle\nagent-browser snapshot -i  # Check result\n```\n\n## Example: Authentication with saved state\n\n```bash\n# Login once\nagent-browser open https://app.example.com/login\nagent-browser snapshot -i\nagent-browser fill @e1 \"username\"\nagent-browser fill @e2 \"password\"\nagent-browser click @e3\nagent-browser wait --url \"**/dashboard\"\nagent-browser state save auth.json\n\n# Later sessions: load saved state\nagent-browser state load auth.json\nagent-browser open https://app.example.com/dashboard\n```\n\n## Sessions (parallel browsers)\n\n```bash\nagent-browser --session test1 open site-a.com\nagent-browser --session test2 open site-b.com\nagent-browser session list\n```\n\n## JSON output (for parsing)\n\nAdd `--json` for machine-readable output:\n```bash\nagent-browser snapshot -i --json\nagent-browser get text @e1 --json\n```\n\n## Debugging\n\n```bash\nagent-browser open example.com --headed              # Show browser window\nagent-browser console                                # View console messages\nagent-browser errors                                 # View page errors\nagent-browser record start ./debug.webm   # Record from current page\nagent-browser record stop                            # Save recording\nagent-browser open example.com --headed  # Show browser window\nagent-browser --cdp 9222 snapshot        # Connect via CDP\nagent-browser console                    # View console messages\nagent-browser console --clear            # Clear console\nagent-browser errors                     # View page errors\nagent-browser errors --clear             # Clear errors\nagent-browser highlight @e1              # Highlight element\nagent-browser trace start                # Start recording trace\nagent-browser trace stop trace.zip       # Stop and save trace\n```\n"},"lastSynced":"2026-03-08T02:02:45.886Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Automation Agents needing to interact with dynamic web pages and perform complex browser actions.","zh":"适用于需要与动态网页交互并执行复杂浏览器操作的Web Automation Agents。","ja":"Web Automation Agentsが動的Webページとやり取りし、複雑なブラウザ操作を実行する必要がある場合に適しています。","ko":"동적 웹 페이지와 상호 작용하고 복잡한 브라우저 작업을 수행해야 하는 Web Automation Agents에 적합합니다.","es":"Ideal para agentes de automatización web que necesitan interactuar con páginas web dinámicas y realizar acciones de navegador complejas.","fr":"Idéal pour les agents d''automatisation web qui ont besoin d''interagir avec des pages web dynamiques et d''effectuer des actions de navigateur complexes.","de":"Ideal für Web-Automatisierungsagenten, die mit dynamischen Webseiten interagieren und komplexe Browser-Aktionen ausführen müssen.","pt":"Ideal para Agentes de Automação Web que precisam interagir com páginas web dinâmicas e realizar ações de navegador complexas.","ru":"Идеально подходит для Веб-Агентов, которым необходимо взаимодействовать с динамическими веб-страницами и выполнять сложные действия браузера.","ar":"مثالي للوكلاء الذكيين للويب الذين يحتاجون إلى التفاعل مع صفحات الويب الديناميكية وإجراء إجراءات متقدمة للمتصفح."},"recommendation":{"en":"Empowers agents to automate browser interactions using snapshot capabilities, capturing interactive elements and performing actions like clicking and filling inputs via refs, leveraging protocols like HTTP and HTML elements.","zh":"赋予代理人使用快照功能自动执行浏览器交互，捕获交互元素并执行点击和填充输入等操作，利用HTTP和HTML元素等协议。","ja":"スナップショット機能を使用してブラウザの相互作用を自動化し、インタラクティブな要素をキャプチャし、クリックや入力の埋め込みなどのアクションを実行することができ、HTTPやHTML要素などのプロトコルを利用することができます。","ko":"스냅샷 기능을 사용하여 브라우저 상호 작용을 자동화하고 상호 작용 요소를 캡처하여 클릭 및 입력 채우기와 같은 작업을 수행하며, HTTP 및 HTML 요소와 같은 프로토콜을 활용할 수 있습니다.","es":"Habilita a los agentes a automatizar las interacciones del navegador utilizando capacidades de instantánea, capturando elementos interactivos y realizando acciones como hacer clic y rellenar entradas vía refs, aprovechando protocolos como HTTP y elementos HTML.","fr":"Permet aux agents d''automatiser les interactions de navigateur en utilisant des fonctionnalités de capture d''écran, en capturant des éléments interactifs et en effectuant des actions comme le clic et le remplissage des entrées via des refs, en exploitant des protocoles comme HTTP et des éléments HTML.","de":"Ermöglicht es Agenten, Browser-Interaktionen zu automatisieren, indem sie Momentaufnahmefunktionen verwenden, interaktive Elemente erfassen und Aktionen wie Klicken und Ausfüllen von Eingaben über refs ausführen, indem sie Protokolle wie HTTP und HTML-Elemente nutzen.","pt":"Habilita os agentes a automatizar interações de navegador usando capacidades de captura de instantâneos, capturando elementos interativos e realizando ações como clicar e preencher entradas via refs, aproveitando protocolos como HTTP e elementos HTML.","ru":"Позволяет агентам автоматизировать взаимодействия браузера с помощью возможностей создания снимков, захватывая интерактивные элементы и выполняя действия, такие как клики и заполнение вводов через refs, используя протоколы, такие как HTTP и HTML-элементы.","ar":"يمنح الوكلاء القدرة على توفير تفاعلات المتصفح باستخدام قدرات التقاط اللقطة، واستخدام العناصر التفاعلية وإجراء إجراءات مثل النقر وتعبئة الإدخالات عبر المراجع، واستخدام بروتوكولات مثل HTTP وعناصر HTML."},"useCases":{"en":["Automating web scraping tasks","Generating interactive web tests","Debugging web application UI issues"],"zh":["自动执行网页抓取任务","生成交互式网页测试","调试网页应用程序UI问题"],"ja":["Webスクレイピングタスクの自動化","インタラクティブなWebテストの生成","WebアプリケーションのUI問題のデバッグ"],"ko":["웹 스크레이핑 작업 자동화","대화형 웹 테스트 생성","웹 애플리케이션 UI 문제 디버깅"],"es":["Automatizar tareas de extracción web","Generar pruebas web interactivas","Depurar problemas de la interfaz de usuario de aplicaciones web"],"fr":["Automatiser les tâches d''extraction web","Générer des tests web interactifs","Déboguer les problèmes d''interface utilisateur des applications web"],"de":["Automatisierung von Web-Scraping-Aufgaben","Erzeugen interaktiver Web-Tests","Fehlerbehebung bei Benutzeroberflächenproblemen von Webanwendungen"],"pt":["Automatizar tarefas de raspagem web","Gerar testes web interativos","Depurar problemas de interface do usuário de aplicativos web"],"ru":["Автоматизация задач веб-скрапинга","Генерация интерактивных веб-тестов","Отладка проблем интерфейса пользователя веб-приложений"],"ar":["تحسين مهام حصر الويب","توليد اختبارات الويب التفاعلية","تصحيح أخطاء واجهة المستخدم لتطبيقات الويب"]},"limitations":{"en":["Requires browser instance access","Limited to HTTP and HTML interactions"],"zh":["需要浏览器实例访问","仅限于HTTP和HTML交互"],"ja":["ブラウザインスタンスへのアクセスが必要","HTTPとHTMLの相互作用のみ"],"ko":["브라우저 인스턴스 액세스가 필요함","HTTP 및 HTML 상호 작용만 가능"],"es":["Requiere acceso a una instancia de navegador","Limitado a interacciones HTTP y HTML"],"fr":["Nécessite un accès à une instance de navigateur","Limité aux interactions HTTP et HTML"],"de":["Benötigt Zugriff auf eine Browser-Instanz","Begrenzt auf HTTP- und HTML-Interaktionen"],"pt":["Requer acesso à instância do navegador","Limitado a interações HTTP e HTML"],"ru":["Требуется доступ к экземпляру браузера","Ограничен до взаимодействий HTTP и HTML"],"ar":["يتطلب الوصول إلى مثيل المتصفح","محدود بالتفاعلات HTTP و HTML"]},"version":4},"contentHash":"9c4e7cf452e67986807fd58bc5068bad462b4ea4ca818a8e23456d15931938d0","qualityScore":60}');
