INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Kjdragan/universal_agent/agent-browser', 'agent-browser', 'Kjdragan', 'universal_agent', 'community', 'agent-browser Kjdragan universal_agent community The agent-browser skill enables developers to automate browser interactions, capturing interactive elements and performing actions like clicking and filling inputs. It benefits developers working with AI agents. agent-browser 是一个浏览器自动化工具，支持打开页面、获取交互元素、点击和填充表单等功能 agent-browser はブラウザ自動化ツールで、ページを開き、インタラクティブ要素を取得し、クリックしてフォームを埋めることができます agent-browser는 브라우저 자동화 도구로 페이지를 열고 상호 작용 요소를 가져와 클릭하고 양식을 채울 수 있습니다 El agent-browser es una herramienta de automatización de navegador que permite interactuar con elementos web mediante comandos CLI L''agent-browser est un outil d''automatisation de navigation qui permet d''interagir avec des éléments web à l''aide de commandes CLI Der agent-browser ist ein Browser-Automatisierungstool, das die Interaktion mit Web-Elementen über CLI-Befehle ermöglicht O agent-browser é uma ferramenta de automação de navegador que permite executar comandos como open, snapshot, click e fill ИИ Агент agent-browser - это инструмент для автоматизации браузера, который позволяет выполнять команды open, snapshot, click и fill وحدات الإيجاد الآلي agent-browser هي أداة لتutomazione المتصفح التي تسمح بتنفيذ أوامر مثل open و snapshot و click و fill how to use agent-browser agent-browser setup guide browser automation with agent-browser agent-browser alternative agent-browser vs selenium agent-browser install what is agent-browser agent-browser documentation agent-browser tutorial agent-browser 浏览器自动化 命令行界面 CLI 自动化工具 AIエージェント工具 浏览器操作自动化 Navigates to web pages using ''agent-browser open <url>'' command Captures interactive elements with references like ''@e1'' and ''@e2'' using ''agent-browser snapshot -i'' Performs click actions on elements by reference using ''agent-browser click @e1'' Fills input fields by reference using ''agent-browser fill @e2 "text"'' Closes the browser instance using ''agent-browser close'' command agent-browser is a browser automation tool that allows developers to navigate, snapshot, and interact with web pages using specific commands and references');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Asmayaseen/hackathon-2/building-nextjs-apps', 'community', 'Asmayaseen', 'hackathon-2', 'Asmayaseen/hackathon-2', 'building-nextjs-apps', 0, 0, 60, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:51.505Z', '87a358c8f2fa84b5f9dd75a6ec31c12cb38913f1593b647e94b956e8e2839207', '{"id":"Asmayaseen/hackathon-2/building-nextjs-apps","name":"building-nextjs-apps","description":{"en":"The building-nextjs-apps skill helps developers build Next.js 16 applications with distinctive design, addressing critical breaking changes such as params and searchParams being promises.","zh":"Next.js 16 应用开发需要注意 params 和 searchParams 的 Promise 化，正确使用 async/await","ja":"Next.js 16 アプリケーション開発では、params と searchParams の Promise 化に注意し、async/await を正しく使用する必要があります","ko":"Next.js 16 애플리케이션 개발 시 params와 searchParams의 Promise화에 주의하고 async/await를 올바르게 사용해야 합니다","es":"Construye aplicaciones Next.js 16 con params y searchParams como promesas, siguiendo los patrones de diseño recomendados","fr":"Créez des applications Next.js 16 avec params et searchParams en tant que promesses, en suivant les modèles de conception recommandés","de":"Erstellen Sie Next.js 16-Anwendungen mit params und searchParams als Promises, unter Berücksichtigung der empfohlenen Designmuster","pt":"Construa aplicativos Next.js 16 corretamente com design distinto, evitando erros comuns com params e searchParams como promessas","ru":"Создайте приложения Next.js 16 правильно с уникальным дизайном, избегая распространенных ошибок с params и searchParams как промисами","ar":"ابني تطبيقات Next.js 16 بشكل صحيح مع تصميم متميز، وتجنب الأخطاء الشائعة مع params و searchParams كوعد"},"seo":{"title":{"en":"building-nextjs-apps: Next.js 16 Setup Guide | AI Agent S...","zh":"Next.js 16 应用开发设置指南","ja":"Next.js 16 アプリケーション開発ベストプラクティス","ko":"Next.js 16 애플리케이션 개발 설정 가이드","es":"Guía de configuración para building-nextjs-apps con patro...","fr":"Guide de démarrage pour building-nextjs-apps avec concept...","de":"Einrichtungsleitfaden für building-nextjs-apps mit einzig...","pt":"Guia de Configuração para Construir Aplicativos Next.js 16","ru":"Руководство по Созданию Приложений Next.js 16 с ИИ Агентами","ar":"دليل إعداد تطبيقات Next.js 16 مع أدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to build Next.js 16 applications correctly with our expert guide. Discover critical breaking changes and best practices for a seamless transition.","zh":"了解 Next.js 16 的关键breaking changes，包括 params 和 searchParams 的 Promise 化","ja":"Next.js 16 の重要なbreaking changesについて学び、params と searchParams のPromise 化をマスターしましょう","ko":"Next.js 16의 주요 breaking changes를 학습하고 params와 searchParams의 Promise화에 대해 알아보세요","es":"Aprende a construir aplicaciones Next.js 16 con el nuevo patrón de params y searchParams como promesas, evitando errores comunes","fr":"Découvrez comment créer des applications Next.js 16 avec le nouveau modèle de params et searchParams en tant que promesses, en évitant les erreurs courantes","de":"Erfahren Sie, wie Sie Next.js 16-Anwendungen mit dem neuen Muster für params und searchParams als Promises erstellen und häufige Fehler vermeiden","pt":"Aprenda a construir aplicativos Next.js 16 com design distinto e evite erros comuns com params e searchParams como promessas","ru":"Узнайте, как создать приложения Next.js 16 с уникальным дизайном и избежать распространенных ошибок с params и searchParams как промисами","ar":"تعلم كيفية بناء تطبيقات Next.js 16 مع تصميم متميز وتجنب الأخطاء الشائعة مع params و searchParams كوعد"},"definition":{"en":"building-nextjs-apps is a skill that enables developers to create Next.js 16 applications with correct implementation of params and searchParams as promises.","zh":"Next.js 16 应用开发是指使用 Next.js 16 框架构建 React 应用","ja":"Next.js 16 アプリケーション開発とは、Next.js 16 フレームワークを使用して React アプリケーションを構築すること","ko":"Next.js 16 애플리케이션 개발은 Next.js 16 프레임워크를 사용하여 React 애플리케이션을 구축하는 것을 의미합니다","es":"Building-nextjs-apps se refiere a la creación de aplicaciones web con Next.js 16, utilizando patrones de diseño distintivos y params y searchParams como promesas","fr":"Building-nextjs-apps fait référence à la création d''applications web avec Next.js 16, en utilisant des modèles de conception distinctifs et params et searchParams en tant que promesses","de":"Building-nextjs-apps bezeichnet die Erstellung von Webanwendungen mit Next.js 16, unter Verwendung einzigartiger Designmuster und params und searchParams als Promises","pt":"Construir aplicativos Next.js 16 refere-se ao processo de criar aplicações web com o framework Next.js 16","ru":"Создание приложений Next.js 16 означает процесс создания веб-приложений с использованием фреймворка Next.js 16","ar":"بناء تطبيقات Next.js 16 يعني عملية إنشاء تطبيقات الويب باستخدام إطار Next.js 16"},"features":{"en":["Builds Next.js 16 applications with correct params and searchParams implementation","Handles critical breaking changes in Next.js 16, including promise-based params and searchParams","Supports distinctive design for Next.js 16 applications","Provides best practices for a seamless transition from Next.js 15 to Next.js 16","Correctly implements async functions for Page components in Next.js 16"],"zh":["支持 Next.js 16 的 params 和 searchParams Promise 化","使用 async/await 处理 Promise","构建正确的 Next.js 16 应用","掌握 Next.js 16 的 breaking changes","优化 Next.js 16 应用的性能"],"ja":["Next.js 16 の params と searchParams の Promise 化をサポート","async/await を使用して Promise を処理","正しい Next.js 16 アプリケーションを構築","Next.js 16 の breaking changes をマスター","Next.js 16 アプリケーションのパフォーマンスを最適化"],"ko":["Next.js 16의 params와 searchParams Promise화 지원","async/await를 사용하여 Promise 처리","올바른 Next.js 16 애플리케이션 구축","Next.js 16의 breaking changes 마스터","Next.js 16 애플리케이션 성능 최적화"],"es":["Uso de params y searchParams como promesas en Next.js 16","Evitación de errores comunes en la construcción de aplicaciones","Patrones de diseño distintivos para aplicaciones web","Compatibilidad con el nuevo patrón de params y searchParams"," Mejora de la experiencia del usuario con aplicaciones web más rápidas y eficientes"],"fr":["Utilisation de params et searchParams en tant que promesses dans Next.js 16","Évitement des erreurs courantes lors de la création d''applications","Modèles de conception distinctifs pour les applications web","Compatibilité avec le nouveau modèle de params et searchParams","Amélioration de l''expérience utilisateur avec des applications web plus rapides et plus efficaces"],"de":["Verwendung von params und searchParams als Promises in Next.js 16","Vermeidung häufiger Fehler bei der Erstellung von Anwendungen","Einzigartige Designmuster für Webanwendungen","Kompatibilität mit dem neuen Muster für params und searchParams","Verbesserung der Benutzererfahrung mit schnelleren und effizienteren Webanwendungen"],"pt":["Uso de params e searchParams como promessas","Evitar erros comuns com Next.js 16","Design distinto para aplicativos web","Suporte a aplicativos Next.js 16","Melhorias de desempenho com Next.js 16","Compatibilidade com tecnologias web modernas"],"ru":["Использование params и searchParams как промисов","Избежание распространенных ошибок с Next.js 16","Уникальный дизайн для веб-приложений","Поддержка приложений Next.js 16","Улучшения производительности с Next.js 16","Совместимость с современными веб-технологиями"],"ar":["استخدام params و searchParams كوعد","تجنب الأخطاء الشائعة مع Next.js 16","تصميم متميز لتطبيقات الويب","دعم تطبيقات Next.js 16","تحسينات الأداء مع Next.js 16","التوافق مع تقنيات الويب الحديثة"]},"keywords":{"en":["how to use building-nextjs-apps","what is building-nextjs-apps","building-nextjs-apps alternative","building-nextjs-apps vs create-react-app","building-nextjs-apps install","building-nextjs-apps setup guide","Next.js 16 tutorial","params and searchParams in Next.js 16","building Next.js 16 applications with promises"],"zh":["Next.js 16","React","params","searchParams","Promise","async/await","breaking changes","AIエージェント","Next.js 16 应用开发"],"ja":["Next.js 16","React","params","searchParams","Promise","async/await","breaking changes","AIエージェント","Next.js 16 アプリケーション開発"],"ko":["Next.js 16","React","params","searchParams","Promise","async/await","breaking changes","AI 에이전트","Next.js 16 애플리케이션 개발"],"es":["building-nextjs-apps","Next.js 16","params y searchParams como promesas","patrones de diseño distintivos","errores comunes en la construcción de aplicaciones","compatibilidad con Next.js 16","mejora de la experiencia del usuario","aplicaciones web más rápidas y eficientes"],"fr":["building-nextjs-apps","Next.js 16","params et searchParams en tant que promesses","modèles de conception distinctifs","erreurs courantes lors de la création d''applications","compatibilité avec Next.js 16","amélioration de l''expérience utilisateur","applications web plus rapides et plus efficaces"],"de":["building-nextjs-apps","Next.js 16","params und searchParams als Promises","einzigartige Designmuster","häufige Fehler bei der Erstellung von Anwendungen","Kompatibilität mit Next.js 16","Verbesserung der Benutzererfahrung","schnellere und effizientere Webanwendungen"],"pt":["Next.js 16","construir aplicativos web","params e searchParams como promessas","erros comuns Next.js 16","design distinto","aplicativos Next.js 16","desenvolvimento web","tecnologias web modernas","otimização de desempenho"],"ru":["Next.js 16","создание веб-приложений","params и searchParams как промисы","распространенные ошибки Next.js 16","уникальный дизайн","приложения Next.js 16","веб-разработка","современные веб-технологии","оптимизация производительности"],"ar":["Next.js 16","بناء تطبيقات الويب","params و searchParams كوعد","أخطاء شائعة Next.js 16","تصميم متميز","تطبيقات Next.js 16","تطوير الويب","تقنيات الويب الحديثة","تحسين الأداء"]}},"owner":"Asmayaseen","repo":"hackathon-2","repoPath":"Asmayaseen/hackathon-2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.317Z","topics":[],"category":"community","skillMd":{"name":"building-nextjs-apps","description":"|","bodyPreview":"# Next.js 16 Applications\r\n\r\nBuild Next.js 16 applications correctly with distinctive design.\r\n\r\n## Critical Breaking Changes (Next.js 16)\r\n\r\n### 1. params and searchParams are Now Promises\r\n\r\n**THIS IS THE MOST COMMON MISTAKE.**\r\n\r\n```typescript\r\n// WRONG - Next.js 15 pattern (WILL FAIL)\r\nexport default function Page({ params }: { params: { id: string } }) {\r\n  return <div>ID: {params.id}</div>\r\n}\r\n\r\n// CORRECT - Next.js 16 pattern\r\nexport default async function Page({\r\n  params,\r\n}: {\r\n  param","body":"# Next.js 16 Applications\r\n\r\nBuild Next.js 16 applications correctly with distinctive design.\r\n\r\n## Critical Breaking Changes (Next.js 16)\r\n\r\n### 1. params and searchParams are Now Promises\r\n\r\n**THIS IS THE MOST COMMON MISTAKE.**\r\n\r\n```typescript\r\n// WRONG - Next.js 15 pattern (WILL FAIL)\r\nexport default function Page({ params }: { params: { id: string } }) {\r\n  return <div>ID: {params.id}</div>\r\n}\r\n\r\n// CORRECT - Next.js 16 pattern\r\nexport default async function Page({\r\n  params,\r\n}: {\r\n  params: Promise<{ id: string }>\r\n}) {\r\n  const { id } = await params\r\n  return <div>ID: {id}</div>\r\n}\r\n```\r\n\r\n### 2. Client Components Need use() Hook\r\n\r\n```typescript\r\n\"use client\"\r\nimport { use } from \"react\"\r\n\r\nexport default function ClientPage({\r\n  params,\r\n}: {\r\n  params: Promise<{ id: string }>\r\n}) {\r\n  const { id } = use(params)\r\n  return <div>ID: {id}</div>\r\n}\r\n```\r\n\r\n### 3. searchParams Also Async\r\n\r\n```typescript\r\nexport default async function Page({\r\n  searchParams,\r\n}: {\r\n  searchParams: Promise<{ page?: string }>\r\n}) {\r\n  const { page } = await searchParams\r\n  return <div>Page: {page ?? \"1\"}</div>\r\n}\r\n```\r\n\r\n---\r\n\r\n## Core Patterns\r\n\r\n### Project Setup\r\n\r\n```bash\r\nnpx create-next-app@latest my-app --typescript --tailwind --eslint\r\ncd my-app\r\n\r\n# Add shadcn/ui\r\nnpx shadcn@latest init\r\nnpx shadcn@latest add button form dialog table sidebar\r\n```\r\n\r\n### App Router Layout\r\n\r\n```typescript\r\n// app/layout.tsx\r\nexport default function RootLayout({\r\n  children,\r\n}: {\r\n  children: React.ReactNode\r\n}) {\r\n  return (\r\n    <html lang=\"en\">\r\n      <body className=\"min-h-screen\">\r\n        {children}\r\n      </body>\r\n    </html>\r\n  )\r\n}\r\n```\r\n\r\n### Dynamic Routes\r\n\r\n```typescript\r\n// app/tasks/[id]/page.tsx\r\nexport default async function TaskPage({\r\n  params,\r\n}: {\r\n  params: Promise<{ id: string }>\r\n}) {\r\n  const { id } = await params\r\n  const task = await getTask(id)\r\n\r\n  return (\r\n    <main>\r\n      <h1>{task.title}</h1>\r\n    </main>\r\n  )\r\n}\r\n```\r\n\r\n### Server Actions\r\n\r\n```typescript\r\n// app/actions.ts\r\n\"use server\"\r\n\r\nimport { revalidatePath } from \"next/cache\"\r\n\r\nexport async function createTask(formData: FormData) {\r\n  const title = formData.get(\"title\") as string\r\n\r\n  await db.insert(tasks).values({ title })\r\n\r\n  revalidatePath(\"/tasks\")\r\n}\r\n\r\n// Usage in component\r\n<form action={createTask}>\r\n  <input name=\"title\" />\r\n  <button type=\"submit\">Create</button>\r\n</form>\r\n```\r\n\r\n### API Routes\r\n\r\n```typescript\r\n// app/api/tasks/route.ts\r\nimport { NextResponse } from \"next/server\"\r\n\r\nexport async function GET() {\r\n  const tasks = await db.select().from(tasksTable)\r\n  return NextResponse.json(tasks)\r\n}\r\n\r\nexport async function POST(request: Request) {\r\n  const body = await request.json()\r\n  const task = await db.insert(tasksTable).values(body).returning()\r\n  return NextResponse.json(task, { status: 201 })\r\n}\r\n```\r\n\r\n### Middleware → proxy.ts\r\n\r\n```typescript\r\n// proxy.ts (replaces middleware.ts in Next.js 16)\r\nimport { NextRequest } from \"next/server\"\r\n\r\nexport function proxy(request: NextRequest) {\r\n  // Authentication check\r\n  const token = request.cookies.get(\"token\")\r\n  if (!token && request.nextUrl.pathname.startsWith(\"/dashboard\")) {\r\n    return Response.redirect(new URL(\"/login\", request.url))\r\n  }\r\n}\r\n\r\nexport const config = {\r\n  matcher: [\"/dashboard/:path*\"],\r\n}\r\n```\r\n\r\n---\r\n\r\n## Data Fetching\r\n\r\n### Server Component (Default)\r\n\r\n```typescript\r\n// This runs on the server - can use async/await directly\r\nasync function TaskList() {\r\n  const tasks = await fetch(\"https://api.example.com/tasks\", {\r\n    cache: \"no-store\", // SSR, or\r\n    // next: { revalidate: 60 } // ISR\r\n  }).then(r => r.json())\r\n\r\n  return (\r\n    <ul>\r\n      {tasks.map(task => <li key={task.id}>{task.title}</li>)}\r\n    </ul>\r\n  )\r\n}\r\n```\r\n\r\n### Client Component\r\n\r\n```typescript\r\n\"use client\"\r\n\r\nimport useSWR from \"swr\"\r\n\r\nconst fetcher = (url: string) => fetch(url).then(r => r.json())\r\n\r\nexport function ClientTaskList() {\r\n  const { data, error, isLoading } = useSWR(\"/api/tasks\", fetcher)\r\n\r\n  if (isLoading) return <div>Loading...</div>\r\n  if (error) return <div>Error loading tasks</div>\r\n\r\n  return (\r\n    <ul>\r\n      {data.map(task => <li key={task.id}>{task.title}</li>)}\r\n    </ul>\r\n  )\r\n}\r\n```\r\n\r\n---\r\n\r\n## Project Structure\r\n\r\n```\r\napp/\r\n├── layout.tsx           # Root layout\r\n├── page.tsx             # Home page\r\n├── globals.css          # Global styles\r\n├── api/                 # API routes\r\n│   └── tasks/route.ts\r\n├── tasks/\r\n│   ├── page.tsx         # /tasks\r\n│   └── [id]/page.tsx    # /tasks/:id\r\n├── actions.ts           # Server actions\r\n└── proxy.ts             # Request proxy (middleware)\r\ncomponents/\r\n├── ui/                  # shadcn/ui components\r\n└── task-list.tsx        # App components\r\nlib/\r\n├── db.ts                # Database connection\r\n└── utils.ts             # Utilities\r\n```\r\n\r\n---\r\n\r\n## Next.js DevTools MCP\r\n\r\nUse the next-devtools-mcp server for runtime diagnostics and development automation.\r\n\r\n### Setup\r\n\r\n```bash\r\nclaude mcp add next-devtools npx next-devtools-mcp@latest\r\n```\r\n\r\nOr in `settings.json`:\r\n\r\n```json\r\n{\r\n  \"mcpServers\": {\r\n    \"next-devtools\": {\r\n      \"type\": \"stdio\",\r\n      \"command\": \"npx\",\r\n      \"args\": [\"next-devtools-mcp@latest\"]\r\n    }\r\n  }\r\n}\r\n```\r\n\r\n### Available Tools\r\n\r\n| Tool | Purpose |\r\n|------|---------|\r\n| `init` | Establish context with available tools and best practices |\r\n| `nextjs_docs` | Search and fetch official Next.js documentation |\r\n| `browser_eval` | Automate browser testing with Playwright |\r\n| `nextjs_index` | Discover running Next.js dev servers |\r\n| `nextjs_call` | Execute MCP tools on running dev servers |\r\n| `upgrade_nextjs_16` | Automated upgrade with codemods |\r\n| `enable_cache_components` | Configure Cache Components for Next.js 16 |\r\n\r\n### Key Use Cases\r\n\r\n**1. Get Real-time Errors**\r\n\r\n```\r\n\"What build errors are there in my Next.js app?\"\r\n\"Show me TypeScript errors in the current project\"\r\n```\r\n\r\n**2. Debug Runtime Issues**\r\n\r\n```\r\n\"Check the dev server logs for errors\"\r\n\"What runtime errors are happening on the dashboard page?\"\r\n```\r\n\r\n**3. Upgrade Assistance**\r\n\r\n```\r\n\"Upgrade this project to Next.js 16\"\r\n\"Enable cache components for this app\"\r\n```\r\n\r\n**4. Documentation Lookup**\r\n\r\n```\r\n\"How do I use the Image component in Next.js 16?\"\r\n\"What''s the correct way to handle dynamic routes?\"\r\n```\r\n\r\n### Next.js 16 MCP Endpoint\r\n\r\nNext.js 16+ exposes a built-in MCP endpoint at `http://localhost:3000/_next/mcp` (or your dev server port). The devtools MCP automatically discovers and connects to running servers.\r\n\r\n---\r\n\r\n## Verification\r\n\r\nRun: `python3 scripts/verify.py`\r\n\r\nExpected: `✓ building-nextjs-apps skill ready`\r\n\r\n## If Verification Fails\r\n\r\n1. Check: references/ folder has nextjs-16-patterns.md\r\n2. **Stop and report** if still failing\r\n\r\n## Related Skills\r\n\r\n- **styling-with-shadcn** - UI components for Next.js apps\r\n- **fetching-library-docs** - Latest Next.js docs: `--library-id /vercel/next.js --topic routing`\r\n- **configuring-better-auth** - OAuth/SSO for Next.js apps\r\n\r\n## References\r\n\r\n- [references/nextjs-16-patterns.md](references/nextjs-16-patterns.md) - Complete Next.js 16 patterns\r\n- [references/frontend-design.md](references/frontend-design.md) - Aesthetic guidelines for distinctive UI\r\n- [references/datetime-patterns.md](references/datetime-patterns.md) - UTC/timezone handling for datetime-local inputs"},"lastSynced":"2026-03-08T02:02:51.505Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to build Next.js 16 applications with modern design patterns and handling critical breaking changes such as promises in params and searchParams.","zh":"非常适合需要构建Next.js 16应用程序的前端代理，使用现代设计模式，并处理关键的破坏性更改，例如params和searchParams中的promise。","ja":"Next.js 16アプリケーションをモダンなデザインパターンで構築する必要があるフロントエンドエージェントに最適です。パラメーターやSearchParamsなどの重要な破壊的な変更、Promiseを処理します。","ko":"Next.js 16 애플리케이션을 현대적인 디자인 패턴으로 구축해야 하는 프론트엔드 에이전트에게 적합합니다. params 및 searchParams의 프로미스와 같은 중요한 중단 변경 사항을 처리합니다.","es":"Perfecto para agentes Frontend que necesitan construir aplicaciones Next.js 16 con patrones de diseño modernos y manejar cambios críticos como promesas en parámetros y searchParams.","fr":"Parfait pour les agents Frontend ayant besoin de créer des applications Next.js 16 avec des modèles de conception modernes et gérer des changements critiques tels que des promesses dans les paramètres et searchParams.","de":"Optimal für Frontend-Agents, die Next.js 16-Anwendungen mit modernen Designmustern erstellen und kritische Änderungen wie Versprechen in Parametern und searchParams verwalten müssen.","pt":"Perfeito para Agentes Frontend que precisam construir aplicações Next.js 16 com padrões de design modernos e lidar com alterações críticas de quebra, como promessas em parâmetros e searchParams.","ru":"Идеально подходит для агентов Frontend, которым необходимо создавать приложения Next.js 16 с современными шаблонами проектирования и обрабатывать критические изменения, такие как обещания в параметрах и searchParams.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى بناء تطبيقات Next.js 16 باستخدام أنماط تصميم حديثة ومعالجة التغييرات الحاسمة مثل الوعد في المعلمات وsearchParams."},"recommendation":{"en":"Empowers agents to build Next.js 16 applications correctly, addressing breaking changes like params and searchParams being promises, and providing distinctive design capabilities using TypeScript and React.","zh":"赋予代理构建Next.js 16应用程序的能力，正确处理破坏性更改，例如params和searchParams为promise，并使用TypeScript和React提供独特的设计能力。","ja":"エージェントにNext.js 16アプリケーションを正しく構築する能力を与え、パラメーターやSearchParamsなどのPromiseなどの破壊的な変更に対処し、TypeScriptとReactを使用した独自の設計能力を提供します。","ko":"에이전트가 Next.js 16 애플리케이션을 올바르게 구축할 수 있는 능력을 부여하고, params 및 searchParams의 프로미스와 같은 중단 변경 사항을 처리하며, TypeScript와 React를 사용하여 고유한 디자인 능력을 제공합니다.","es":"Habilita a los agentes a crear aplicaciones Next.js 16 correctamente, abordando cambios críticos como parámetros y searchParams que son promesas, y proporcionando capacidades de diseño distintivas utilizando TypeScript y React.","fr":"Permet aux agents de créer des applications Next.js 16 correctement, en abordant les changements critiques tels que les paramètres et searchParams qui sont des promesses, et en fournissant des capacités de conception distinctives en utilisant TypeScript et React.","de":"Ermöglicht es Agents, Next.js 16-Anwendungen korrekt zu erstellen, indem sie kritische Änderungen wie Parameter und searchParams, die Versprechen sind, angehen und unterscheidende Designfähigkeiten unter Verwendung von TypeScript und React bereitstellen.","pt":"Habilita os agentes a construir aplicações Next.js 16 corretamente, abordando alterações de quebra, como parâmetros e searchParams sendo promessas, e fornecendo capacidades de design distintas usando TypeScript e React.","ru":"Наделяет агентов возможностью создавать приложения Next.js 16 правильно, решая проблемы критических изменений, таких как параметры и searchParams, являющиеся обещаниями, и предоставляя уникальные возможности проектирования с помощью TypeScript и React.","ar":"يمنح الوكلاء القدرة على بناء تطبيقات Next.js 16 بشكل صحيح، ومعالجة التغييرات الحاسمة مثل المعلمات وsearchParams التي هي وعود، وتوفير قدرات تصميم متميزة باستخدام TypeScript وReact."},"useCases":{"en":["Building Next.js 16 applications with modern design patterns","Handling critical breaking changes in Next.js 16, such as promises in params and searchParams","Generating Next.js 16 pages with asynchronous data fetching using TypeScript"],"zh":["使用现代设计模式构建Next.js 16应用程序","处理Next.js 16中的关键破坏性更改，例如params和searchParams中的promise","使用TypeScript生成Next.js 16页面，具有异步数据获取"],"ja":["モダンなデザインパターンを使用してNext.js 16アプリケーションを構築する","Next.js 16での重要な破壊的な変更、パラメーターやSearchParamsなどのPromiseを処理する","TypeScriptを使用してNext.js 16ページを生成し、非同期データ取得を実行する"],"ko":["현대적인 디자인 패턴을 사용하여 Next.js 16 애플리케이션을 구축하는 것","Next.js 16에서 중요한 중단 변경 사항, params 및 searchParams의 프로미스를 처리하는 것","TypeScript를 사용하여 Next.js 16 페이지를 생성하고, 비동기 데이터 가져오기를 수행하는 것"],"es":["Construir aplicaciones Next.js 16 con patrones de diseño modernos","Manejar cambios críticos en Next.js 16, como promesas en parámetros y searchParams","Generar páginas Next.js 16 con recuperación de datos asíncrona utilizando TypeScript"],"fr":["Créer des applications Next.js 16 avec des modèles de conception modernes","Gérer les changements critiques dans Next.js 16, tels que des promesses dans les paramètres et searchParams","Générer des pages Next.js 16 avec une récupération de données asynchrone en utilisant TypeScript"],"de":["Erstellen von Next.js 16-Anwendungen mit modernen Designmustern","Verwalten von kritischen Änderungen in Next.js 16, wie Versprechen in Parametern und searchParams","Generieren von Next.js 16-Seiten mit asynchroner Datenerfassung unter Verwendung von TypeScript"],"pt":["Construir aplicações Next.js 16 com padrões de design modernos","Lidar com alterações críticas de quebra no Next.js 16, como promessas em parâmetros e searchParams","Gerar páginas Next.js 16 com busca de dados assíncrona usando TypeScript"],"ru":["Создание приложений Next.js 16 с современными шаблонами проектирования","Обработка критических изменений в Next.js 16, таких как обещания в параметрах и searchParams","Генерация страниц Next.js 16 с асинхронной загрузкой данных с помощью TypeScript"],"ar":["بناء تطبيقات Next.js 16 باستخدام أنماط تصميم حديثة","معالجة التغييرات الحاسمة في Next.js 16، مثل الوعد في المعلمات وsearchParams","توليد صفحات Next.js 16 مع استرجاع بيانات غير متزامن باستخدام TypeScript"]},"limitations":{"en":["Requires understanding of Next.js 16 and its breaking changes","Limited to Next.js 16 applications, not compatible with earlier versions"],"zh":["需要了解Next.js 16及其破坏性更改","仅限Next.js 16应用程序，不兼容早期版本"],"ja":["Next.js 16とその破壊的な変更を理解する必要がある","Next.js 16アプリケーションに限定され、以前のバージョンとは互換性がない"],"ko":["Next.js 16 및 중단 변경 사항에 대한 이해가 필요","Next.js 16 애플리케이션에만 적용되며 이전 버전과 호환되지 않음"],"es":["Requiere comprensión de Next.js 16 y sus cambios críticos","Limitado a aplicaciones Next.js 16, no compatible con versiones anteriores"],"fr":["Nécessite une compréhension de Next.js 16 et de ses changements critiques","Limité aux applications Next.js 16, non compatible avec les versions antérieures"],"de":["Benötigt Verständnis von Next.js 16 und seinen kritischen Änderungen","Begrenzt auf Next.js 16-Anwendungen, nicht kompatibel mit früheren Versionen"],"pt":["Exige compreensão do Next.js 16 e suas alterações de quebra","Limitado a aplicações Next.js 16, não compatível com versões anteriores"],"ru":["Требует понимания Next.js 16 и его критических изменений","Ограничен приложениями Next.js 16, не совместим с предыдущими версиями"],"ar":["يتطلب فهم Next.js 16 وتغييراته الحاسمة","محدود بتطبيقات Next.js 16، غير متوافق مع الإصدارات السابقة"]},"version":4},"contentHash":"87a358c8f2fa84b5f9dd75a6ec31c12cb38913f1593b647e94b956e8e2839207","qualityScore":60}');
