INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Asmayaseen/hackathon-2/building-nextjs-apps', 'building-nextjs-apps', 'Asmayaseen', 'hackathon-2', 'community', 'building-nextjs-apps Asmayaseen hackathon-2 community The building-nextjs-apps skill helps developers build Next.js 16 applications with distinctive design, addressing critical breaking changes such as params and searchParams being promises. Next.js 16 应用开发需要注意 params 和 searchParams 的 Promise 化，正确使用 async/await Next.js 16 アプリケーション開発では、params と searchParams の Promise 化に注意し、async/await を正しく使用する必要があります Next.js 16 애플리케이션 개발 시 params와 searchParams의 Promise화에 주의하고 async/await를 올바르게 사용해야 합니다 Construye aplicaciones Next.js 16 con params y searchParams como promesas, siguiendo los patrones de diseño recomendados Créez des applications Next.js 16 avec params et searchParams en tant que promesses, en suivant les modèles de conception recommandés Erstellen Sie Next.js 16-Anwendungen mit params und searchParams als Promises, unter Berücksichtigung der empfohlenen Designmuster Construa aplicativos Next.js 16 corretamente com design distinto, evitando erros comuns com params e searchParams como promessas Создайте приложения Next.js 16 правильно с уникальным дизайном, избегая распространенных ошибок с params и searchParams как промисами ابني تطبيقات Next.js 16 بشكل صحيح مع تصميم متميز، وتجنب الأخطاء الشائعة مع params و searchParams كوعد how to use building-nextjs-apps what is building-nextjs-apps building-nextjs-apps alternative building-nextjs-apps vs create-react-app building-nextjs-apps install building-nextjs-apps setup guide Next.js 16 tutorial params and searchParams in Next.js 16 building Next.js 16 applications with promises Next.js 16 React params searchParams Promise async/await breaking changes AIエージェント Next.js 16 应用开发 Builds Next.js 16 applications with correct params and searchParams implementation Handles critical breaking changes in Next.js 16, including promise-based params and searchParams Supports distinctive design for Next.js 16 applications Provides best practices for a seamless transition from Next.js 15 to Next.js 16 Correctly implements async functions for Page components in Next.js 16 building-nextjs-apps is a skill that enables developers to create Next.js 16 applications with correct implementation of params and searchParams as promises.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dyad-sh/dyad/dyad:multi-pr-review', 'community', 'dyad-sh', 'dyad', 'dyad-sh/dyad', 'dyad:multi-pr-review', 0, 0, 60, '2026-03-08T01:57:15.319Z', '2026-03-08T02:02:56.888Z', '0573b2e9c7042a2cb78f0f7a5dd2068b0f6c0690698ebf6aab2ff1cd9ccc1a5f', '{"id":"dyad-sh/dyad/dyad:multi-pr-review","name":"dyad:multi-pr-review","description":{"en":"dyad:multi-pr-review is a local, open-source AI app builder that spawns three independent sub-agents to review code changes. It benefits power users by validating and aggregating findings through reasoned analysis.","zh":"dyad:multi-pr-review是一个本地、开源的AI应用构建工具，用于代码审查和验证","ja":"dyad:multi-pr-reviewは、コードの変更を分析し、エラーを検出するAIエージェントです","ko":"dyad:multi-pr-review는 코드 리뷰를 위한 로컬, 오픈소스 AI 애플리케이션 빌더입니다","es":"dyad:multi-pr-review es una herramienta de código abierto que utiliza agentes independientes para revisar cambios de código desde diferentes perspectivas","fr":"dyad:multi-pr-review est un outil open-source qui utilise des agents indépendants pour examiner les modifications de code depuis différentes perspectives","de":"dyad:multi-pr-review ist ein Open-Source-Tool, das unabhängige Agenten verwendet, um Code-Änderungen aus verschiedenen Perspektiven zu überprüfen","pt":"O dyad:multi-pr-review é uma ferramenta de revisão de código baseada em IA que utiliza sub-agentes para análise de código. Ele é projetado para revisar alterações de código de diferentes perspectivas","ru":"ИИ Агент dyad:multi-pr-review - это инструмент обзора кода, использующий субагентов для анализа кода. Он предназначен для обзора изменений кода с разных точек зрения","ar":"dyad:multi-pr-review هو أداة مراجعة الكود التي تستخدم وكلاء فرعية لتحليل الكود. وهي مصممة لمراجعة تعديلات الكود من منظورات مختلفة"},"seo":{"title":{"en":"dyad:multi-pr-review: Automated Code Review Setup Guide |...","zh":"dyad:multi-pr-review 代码审查工具设置指南","ja":"dyad:multi-pr-review AIエージェントのベストプラクティス","ko":"dyad:multi-pr-review 코드 리뷰 도구 사용법","es":"Guía de configuración para dyad:multi-pr-review: Revisión...","fr":"Configurer dyad:multi-pr-review: Outil d''examen de code a...","de":"Einrichtungsanleitung für dyad:multi-pr-review: Automatis...","pt":"Guia de Configuração do dyad:multi-pr-review: Ferramenta ...","ru":"Настройка ИИ Агента dyad:multi-pr-review: Инструмент Обзо...","ar":"دليل إعداد dyad:multi-pr-review: أداة مراجعة الكود"},"description":{"en":"Discover how dyad:multi-pr-review streamlines code review with 3 independent sub-agents. Learn how to set up and leverage this AI app builder for efficient c...","zh":"使用dyad:multi-pr-review进行代码审查，通过三个独立的子代理分析和验证代码变更","ja":"dyad:multi-pr-reviewを使用してコードの変更を分析し、エラーを検出しましょう","ko":"dyad:multi-pr-review를 사용하여 코드 리뷰를 자동화하고 코드 품질을 향상시키세요","es":"Aprende a configurar dyad:multi-pr-review para revisar cambios de código de forma automática y eficiente con agentes especializados","fr":"Découvrez comment configurer dyad:multi-pr-review pour examiner les modifications de code de manière automatisée et efficace avec des agents spécialisés","de":"Erfahren Sie, wie Sie dyad:multi-pr-review für die automatisierte und effiziente Überprüfung von Code-Änderungen mit spezialisierten Agenten konfigurieren","pt":"Aprenda a configurar o dyad:multi-pr-review, uma ferramenta de revisão de código baseada em IA que utiliza sub-agentes para análise de código","ru":"Узнайте, как настроить ИИ Агент dyad:multi-pr-review, инструмент обзора кода, использующий субагентов для анализа кода","ar":"تعلم كيفية إعداد dyad:multi-pr-review، أداة مراجعة الكود التي تستخدم وكلاء فرعية لتحليل الكود"},"definition":{"en":"dyad:multi-pr-review is an AI agent skill that automates code review by spawning sub-agents with specialized personas to review code changes from different perspectives.","zh":"dyad:multi-pr-review是一个代码审查工具，使用三个独立的子代理分析和验证代码变更","ja":"dyad:multi-pr-reviewは、コードの変更を分析し、エラーを検出するAIエージェントの一種です","ko":"dyad:multi-pr-review는 코드 리뷰를 위한 도구로, 세 개의 독립적인 子代理를 사용하여 코드 변화를 분석합니다","es":"dyad:multi-pr-review es un agente de inteligencia artificial que realiza revisiones de código automatizadas","fr":"dyad:multi-pr-review est un agent d''intelligence artificielle qui effectue des examens de code automatisés","de":"dyad:multi-pr-review ist ein KI-Agent, der automatisierte Code-Überprüfungen durchführt","pt":"O dyad:multi-pr-review é uma ferramenta de revisão de código baseada em IA que utiliza sub-agentes para análise de código","ru":"ИИ Агент dyad:multi-pr-review - это инструмент обзора кода, использующий субагентов для анализа кода","ar":"dyad:multi-pr-review هو أداة مراجعة الكود التي تستخدم وكلاء فرعية لتحليل الكود"},"features":{"en":["Fetches PR diff and existing comments for comprehensive review","Spawns 3 sub-agents with specialized personas using the Task tool","Utilizes a Correctness Expert sub-agent for bug, edge case, and security review","Aggregates findings through reasoned analysis for validated results","Reduces ordering bias by randomizing file order for each sub-agent"],"zh":["三个独立的子代理进行代码审查","支持代码变更的随机化排序","包含Correctness Expert、Cod等专家模式","使用Task工具进行子代理管理","支持代码错误和安全问题的检测"],"ja":["３つの独立したサブエージェントによるコードレビュー","コードの変更のランダム化された順序をサポート","Correctness Expert、Codなどの専門家モードを含む","Taskツールを使用したサブエージェントの管理","コードのエラーとセキュリティ問題の検出をサポート"],"ko":["세 개의 독립적인 子代理를 사용한 코드 리뷰","코드 변환의ランダム화된 순서 지원","Correctness Expert, Cod 등의 전문가 모드 포함","Task 툴을 사용한 子代理 관리","코드 오류 및 보안 문제検出 지원"],"es":["Revisión de código automatizada con agentes especializados","Análisis de corrección, casos límite y control de flujo","Validación y agregación de resultados a través de análisis razonados","Uso de la herramienta Task para spawnear sub-agentes","Revisión de seguridad y manejo de errores"],"fr":["Examen de code automatisé avec des agents spécialisés","Analyse de correction, de cas limites et de contrôle de flux","Validation et agrégation des résultats via une analyse raisonnée","Utilisation de l''outil Task pour faire spawn des sous-agents","Examen de sécurité et de gestion des erreurs"],"de":["Automatisierte Code-Überprüfung mit spezialisierten Agenten","Analyse von Korrektheit, Grenzfällen und Flusskontrolle","Validierung und Aggregation von Ergebnissen durch begründete Analyse","Verwendung des Task-Tools zum Spawnen von Sub-Agenten","Überprüfung von Sicherheit und Fehlern"],"pt":["Utiliza sub-agentes para análise de código","Revisa alterações de código de diferentes perspectivas","Inclui especialistas em correção, como Bugs, edge cases, control flow, segurança e tratamento de erros","Utiliza a ferramenta Task para spawnar sub-agentes","Reduz o viés de ordenação ao randomizar a ordem dos arquivos","Valida e agrega os resultados da análise"],"ru":["Использует субагентов для анализа кода","Проводит обзор изменений кода с разных точек зрения","Включает в себя специалистов по исправлению, такие как ошибки, краевые случаи, контроль потока, безопасность и обработка ошибок","Использует инструмент Task для запуска субагентов","Снижает偏с при заказе файлов","Проверяет и агрегирует результаты анализа"],"ar":["تستخدم وكلاء فرعية لتحليل الكود","ت-reviewed تعديلات الكود من منظورات مختلفة","تتضمن خبراء في تصحيح الأخطاء، مثل الأخطاء، حالات الحافة، تدفق التحكم، الأمان ومعالجة الأخطاء","تستخدم أداة Task لتشغيل الوكلاء الفرعية","تقلل من انحياز الترتيب عن طريق تعيين-files بالترتيب العشوائي","تتحقق من نتائج التحليل وتجمعها"]},"keywords":{"en":["how to use dyad:multi-pr-review","dyad:multi-pr-review alternative to Replit","dyad:multi-pr-review setup guide","what is dyad:multi-pr-review","dyad:multi-pr-review vs Bolt","dyad:multi-pr-review install for AI agents"],"zh":["代码审查工具","AI应用构建","代码变更分析","子代理管理","代码错误检测","代码安全问题","dyad:multi-pr-review","代码审查最佳实践","代码质量保证"],"ja":["AIエージェント","コードレビュー","コードの変更分析","サブエージェントの管理","コードのエラー検出","コードのセキュリティ問題","dyad:multi-pr-review","コードレビューのベストプラクティス","コード品質保証"],"ko":["코드 리뷰 도구","AI 애플리케이션 빌더","코드 변환 분석","子代理 관리","코드 오류検出","코드 보안 문제","dyad:multi-pr-review","코드 리뷰 사용법","코드 품질 향상"],"es":["dyad:multi-pr-review","herramientas de inteligencia artificial","revisión de código automatizada","agentes de código abierto","desarrollo de software","pruebas de código","análisis de código","seguridad de código","mejora de código"],"fr":["dyad:multi-pr-review","outils d''intelligence artificielle","examen de code automatisé","agents open-source","développement de logiciels","tests de code","analyse de code","sécurité de code","amélioration de code"],"de":["dyad:multi-pr-review","KI-Tools","automatisierte Code-Überprüfung","Open-Source-Agenten","Software-Entwicklung","Code-Tests","Code-Analyse","Code-Sicherheit","Code-Optimierung"],"pt":["dyad:multi-pr-review","ferramenta de revisão de código","IA","sub-agentes","análise de código","revisão de código","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент","dyad:multi-pr-review","инструмент обзора кода","субагенты","анализ кода","обзор кода","разработка программного обеспечения","инструменты разработки"],"ar":["dyad:multi-pr-review","أداة مراجعة الكود","الوكلاء الفرعية","تحليل الكود","مراجعة الكود","تطوير البرمجيات","أدوات التطوير","الذكاء الاصطناعي"]}},"owner":"dyad-sh","repo":"dyad","repoPath":"dyad-sh/dyad","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.319Z","topics":[],"category":"community","skillMd":{"name":"dyad:multi-pr-review","description":"Multi-agent code review system that spawns three independent Claude sub-agents to review PR diffs. Each agent receives files in different randomized order to reduce ordering bias. One agent focuses specifically on code health and maintainability. Issues are validated using reasoned analysis rather than simple vote counting. Reports merge verdict (YES / NOT SURE / NO). Automatically deduplicates against existing PR comments. Always posts a summary (even if no new issues), with low priority issues in a collapsible section.","bodyPreview":"# Multi-Agent PR Review\n\nThis skill spawns three independent sub-agents to review code changes from different perspectives, then validates and aggregates their findings through reasoned analysis.\n\n## Overview\n\n1. Fetch PR diff and existing comments\n2. Spawn 3 sub-agents with specialized personas using the Task tool\n   - Each agent receives files in a different randomized order to reduce ordering bias\n   - **Correctness Expert**: Bugs, edge cases, control flow, security, error handling\n   - **Cod","body":"# Multi-Agent PR Review\n\nThis skill spawns three independent sub-agents to review code changes from different perspectives, then validates and aggregates their findings through reasoned analysis.\n\n## Overview\n\n1. Fetch PR diff and existing comments\n2. Spawn 3 sub-agents with specialized personas using the Task tool\n   - Each agent receives files in a different randomized order to reduce ordering bias\n   - **Correctness Expert**: Bugs, edge cases, control flow, security, error handling\n   - **Code Health Expert**: Dead code, duplication, complexity, meaningful comments, abstractions\n   - **UX Wizard**: User experience, consistency, accessibility, error states, delight\n3. Each agent reviews and classifies issues (HIGH/MEDIUM/LOW severity)\n4. Validate issues using reasoned analysis (not just vote counting)\n5. Determine merge verdict based on confirmed issues\n6. Filter out issues already commented on (deduplication)\n7. Post findings: summary with verdict + inline comments for HIGH/MEDIUM issues\n\n## Workflow\n\n### Step 1: Determine PR Number and Repo\n\nParse the PR number and repo from the user''s input. If not provided, try to infer from the current git context:\n\n```bash\n# Get current repo\ngh repo view --json nameWithOwner -q ''.nameWithOwner''\n\n# If user provides a PR URL, extract the number\n# If user just says \"review this PR\", check for current branch PR\ngh pr view --json number -q ''.number''\n```\n\n### Step 2: Fetch PR Diff and Context\n\n**IMPORTANT:** Always save files to the current working directory (e.g. `./pr_diff.patch`), never to `/tmp/` or other directories outside the repo. In CI, only the repo working directory is accessible.\n\n```bash\n# Save the diff to current working directory (NOT /tmp/)\ngh pr diff <PR_NUMBER> --repo <OWNER/REPO> > ./pr_diff.patch\n\n# Get PR metadata\ngh pr view <PR_NUMBER> --repo <OWNER/REPO> --json title,body,files,headRefOid\n\n# Fetch existing comments to avoid duplicates\ngh api repos/<OWNER/REPO>/pulls/<PR_NUMBER>/comments --paginate\ngh api repos/<OWNER/REPO>/issues/<PR_NUMBER>/comments --paginate\n```\n\nSave the diff content and existing comments for use in the review.\n\n### Step 3: Spawn Review Agents in Parallel\n\nUse the `Task` tool to spawn 3 sub-agents **in parallel** (all in a single message with multiple Task tool calls). Each agent should be a `general-purpose` subagent.\n\n**File Ordering**: Before spawning, create 3 different orderings of the changed files (randomize/shuffle the order). Each agent gets the files in a different order to reduce ordering bias (reviewers tend to focus more on files they see first).\n\n**IMPORTANT**: Each agent''s prompt must include:\n\n1. Their role description (from the corresponding file in `references/`)\n2. The full PR diff content (inline, NOT a file path - agents cannot read files from the parent''s context)\n3. The list of existing PR comments (so they can avoid flagging already-commented issues)\n4. Instructions to output findings as structured JSON\n\n#### Agent Prompt Template\n\nFor each agent, the prompt should follow this structure:\n\n````\nYou are a code reviewer with this specialization:\n\n<role>\n[Contents of references/<role>.md - e.g., correctness-reviewer.md]\n</role>\n\nYou are reviewing PR #<NUMBER> in <REPO>: \"<PR TITLE>\"\n\n<pr_description>\n[PR body/description]\n</pr_description>\n\nHere is the diff to review (files presented in a specific order for this review):\n\n<diff>\n[Full diff content - with files in THIS agent''s randomized order]\n</diff>\n\nHere are existing PR comments (do NOT flag issues already commented on):\n\n<existing_comments>\n[Existing comment data as JSON]\n</existing_comments>\n\n## Instructions\n\n1. Read your role description carefully and review the diff from your expert perspective.\n2. For each issue you find, classify it as HIGH, MEDIUM, or LOW severity using the guidelines in your role description.\n3. Output your findings as a JSON array with this schema:\n\n```json\n[\n  {\n    \"file\": \"path/to/file.ts\",\n    \"line_start\": 42,\n    \"line_end\": 45,\n    \"severity\": \"MEDIUM\",\n    \"category\": \"category-name\",\n    \"title\": \"Brief title\",\n    \"description\": \"Clear description of the issue and its impact\",\n    \"suggestion\": \"How to fix (optional)\"\n  }\n]\n```\n\nSeverity levels:\n- HIGH: Security vulnerabilities, data loss risks, crashes, broken functionality, UX blockers\n- MEDIUM: Logic errors, edge cases, performance issues, sloppy code that hurts maintainability, UX issues that degrade the experience\n- LOW: Minor style issues, nitpicks, minor polish improvements\n\nBe thorough but focused. Only flag real issues, not nitpicks disguised as higher severity issues.\n\nIMPORTANT: Cross-reference infrastructure changes (DB migrations, new tables/columns, API endpoints, config entries) against actual usage in the diff. If a migration creates a table but no code in the PR reads from or writes to it, that''s dead infrastructure and should be flagged.\n\nOutput ONLY the JSON array, no other text.\n````\n\n### Step 4: Collect and Parse Results\n\nWait for all 3 agents to complete. Parse the JSON array from each agent''s response.\n\n### Step 5: Validate Issues with Reasoned Analysis\n\n**Do NOT use simple consensus voting (e.g., \"2+ agents agree\").** Instead, perform reasoned validation:\n\nFor each unique issue found (group similar issues by file + approximate line range):\n\n1. **Evaluate validity**: Is this a real issue or a false positive? Consider:\n   - Does the code actually have this problem?\n   - Is the reviewer misunderstanding the code''s purpose?\n   - Is this issue already handled elsewhere in the codebase?\n\n2. **Evaluate severity**: Is the severity rating correct? Consider:\n   - What''s the actual user/system impact?\n   - Is this being over- or under-rated?\n\n3. **Make a decision**:\n   - **CONFIRMED**: Issue is valid and severity is appropriate\n   - **CONFIRMED (adjusted)**: Issue is valid but severity should be changed\n   - **DROPPED**: Issue is a false positive, explain why\n\nTrack dropped issues with reasoning for the summary comment.\n\n### Step 6: Determine Merge Verdict\n\nBased on the confirmed issues, determine the verdict:\n\n- **:white_check_mark: YES - Ready to merge**: No HIGH issues, at most minor MEDIUM issues that are judgment calls\n- **:thinking: NOT SURE - Potential issues**: Has MEDIUM issues that should probably be addressed, but none are clear blockers\n- **:no_entry: NO - Do NOT merge**: Has HIGH severity issues or multiple serious MEDIUM issues that NEED to be fixed\n\n### Step 7: Deduplicate Against Existing Comments\n\nBefore posting, filter out issues that match existing PR comments:\n\n- Same file path\n- Same or nearby line number (within 3 lines)\n- Similar keywords in the issue title appear in the existing comment body\n\n### Step 8: Post GitHub Comments\n\n#### Summary Comment\n\nPost a summary comment on the PR using `gh pr comment`:\n\n```markdown\n## :mag: Dyadbot Code Review Summary\n\n**Verdict: [VERDICT EMOJI + TEXT]**\n\nReviewed by 3 independent agents: Correctness Expert, Code Health Expert, UX Wizard.\n\n### Issues Summary\n\n| Severity               | File                  | Issue                  |\n| ---------------------- | --------------------- | ---------------------- |\n| :red_circle: HIGH      | `src/auth.ts:45`      | SQL injection in login |\n| :yellow_circle: MEDIUM | `src/ui/modal.tsx:12` | Missing loading state  |\n\n<details>\n<summary>:green_circle: Low Priority Notes (X items)</summary>\n\n- **Minor naming inconsistency** - `src/helpers.ts:23`\n- **Could add hover state** - `src/button.tsx:15`\n\n</details>\n\n<details>\n<summary>:no_entry_sign: Dropped False Positives (X items)</summary>\n\n- **~~Potential race condition~~** - Dropped: State is only accessed synchronously in this context\n- **~~Missing null check~~** - Dropped: Value is guaranteed non-null by the caller''s validation\n\n</details>\n\n---\n\n_Generated by Dyadbot multi-agent code review_\n```\n\n**Always post a summary**, even if no issues are found. In that case:\n\n```markdown\n## :mag: Dyadbot Code Review Summary\n\n**Verdict: :white_check_mark: YES - Ready to merge**\n\n:white_check_mark: No issues found by multi-agent review.\n\n---\n\n_Generated by Dyadbot multi-agent code review_\n```\n\n#### Inline Comments\n\nFor each HIGH and MEDIUM issue, post an inline review comment at the relevant line using `gh api`:\n\n```bash\n# Post a review with inline comments\ngh api repos/<OWNER/REPO>/pulls/<PR_NUMBER>/reviews \\\n  -X POST \\\n  --input payload.json\n```\n\nWhere payload.json contains:\n\n```json\n{\n  \"commit_id\": \"<HEAD_SHA from PR metadata>\",\n  \"body\": \"Multi-agent review: X issue(s) found\",\n  \"event\": \"COMMENT\",\n  \"comments\": [\n    {\n      \"path\": \"src/auth.ts\",\n      \"line\": 45,\n      \"body\": \"**:red_circle: HIGH** | security\\n\\n**SQL injection in login**\\n\\nDescription of the issue...\\n\\n:bulb: **Suggestion:** Use parameterized queries\"\n    }\n  ]\n}\n```\n\n## Severity Guidelines\n\nAcross all reviewers:\n\n- **HIGH**: Security vulnerabilities, data loss risks, crashes, broken functionality, race conditions, UX blockers\n- **MEDIUM**: Logic errors, unhandled edge cases, performance issues, sloppy code that hurts maintainability, poor error messages, missing loading/empty states, accessibility gaps\n- **LOW**: Minor style issues, naming nitpicks, optional polish improvements\n\n**Philosophy**: Sloppy code that hurts maintainability is MEDIUM, not LOW. We care about code health.\n\n## File Structure\n\n```\nreferences/\n  correctness-reviewer.md  - Role description for the correctness expert\n  code-health-reviewer.md  - Role description for the code health expert\n  ux-reviewer.md           - Role description for the UX wizard\n  issue_schema.md          - JSON schema for issue output\n```\n\n## Configuration Notes\n\n- **No Python scripts needed**: This skill executes entirely through Claude Code tools\n- **No ANTHROPIC_API_KEY needed**: Sub-agents spawned via Task tool have automatic access\n- **GITHUB_TOKEN required**: For PR access and commenting (usually already configured)\n"},"lastSynced":"2026-03-08T02:02:56.888Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing multi-perspective analysis and validation of code changes.","zh":"非常适合需要多角度分析和验证代码更改的代码审查代理。","ja":"コードの変更を多角度から分析、検証する必要があるコードレビューエージェントに最適です。","ko":"코드 변경에 대한 다각도 분석 및 검증이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan análisis y validación de cambios de código desde múltiples perspectivas.","fr":"Parfait pour les agents de révision de code nécessitant une analyse et une validation des modifications de code à plusieurs perspectives.","de":"Perfekt für Code-Review-Agents, die eine Analyse und Validierung von Code-Änderungen aus mehreren Perspektiven benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise e validação de alterações de código de múltiplas perspectivas.","ru":"Идеально подходит для агентов кодового обзора, которым требуется многосторонний анализ и проверка изменений кода.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى تحليل وتأكيد التغييرات في الشفرة من عدة زوايا"},"recommendation":{"en":"Empowers agents to perform comprehensive code reviews by spawning independent sub-agents with specialized personas, such as Correctness Experts, to validate and aggregate findings through reasoned analysis using Task tool and PR diff analysis.","zh":"通过生成具有专门人格的独立子代理（如正确性专家）来验证和聚合发现，使用任务工具和PR差异分析进行推理分析，从而使代理能够进行全面代码审查。","ja":"正確性専門家などの特別なパーソナを持つ独立したサブエージェントを生成し、TaskツールとPR差分分析を使用して推論分析を行うことで、コードの変更を検証して発見を集約し、エージェントが包括的なコードレビューを実行できるようにします。","ko":"정확성 전문가와 같은 전문 인물을 가진 독립적인 하위 에이전트를 생성하고, Task 도구와 PR 차이 분석을 사용하여 추론 분석을 통해 코드의 변경 사항을 검증하고 발견을 집계하여 에이전트가 포괄적인 코드 리뷰를 수행할 수 있도록 합니다.","es":"Habilita a los agentes a realizar revisiones de código exhaustivas al generar subagentes independientes con personas especializadas, como expertos en corrección, para validar y agregar hallazgos a través de un análisis razonado utilizando la herramienta Task y el análisis de diferencias de PR.","fr":"Permet aux agents d''effectuer des révisions de code exhaustives en générant des sous-agents indépendants dotés de personnalités spécialisées, comme des experts en correction, pour valider et agréger les résultats grâce à une analyse raisonnée utilisant l''outil Task et l''analyse de différences de PR.","de":"Ermächtigt Agenten, umfassende Code-Reviews durchzuführen, indem unabhängige Subagenten mit spezialisierten Persönlichkeiten, wie Korrektheitsexperten, generiert werden, um Ergebnisse zu validieren und zu aggregieren durch eine begründete Analyse unter Verwendung des Task-Tools und der PR-Diff-Analyse.","pt":"Habilita os agentes a realizarem revisões de código abrangentes, criando sub-agentes independentes com personalidades especializadas, como especialistas em Correção, para validar e agregar conclusões por meio de análise fundamentada usando a ferramenta Task e análise de diff de PR.","ru":"Наделяет агентов возможностью проводить комплексные кодовые обзоры, создавая независимых субагентов со специализированными персонами, такими как эксперты по правильности, для проверки и агрегации результатов посредством обоснованного анализа с использованием инструмента Task и анализа PR diff.","ar":"يمنح الوكيل القدرة على إجراء مراجعات شاملة للشفرة من خلال إنشاء وكلاء فرعيين مستقلين بأشخاص متخصصة، مثل خبراء الدقة، للتحقق من المضاعفة والاستنتاجات من خلال التحليل المتعمق باستخدام أداة المهمة وتحليل الفرق PR."},"useCases":{"en":["Validating code changes for security and error handling","Automating bug detection and edge case analysis","Generating comprehensive review reports through multi-agent consensus"],"zh":["验证代码更改的安全性和错误处理","自动化BUG检测和边缘情况分析","通过多代理一致生成全面审查报告"],"ja":["セキュリティとエラーハンドリングのコード変更の検証","バグ検出とエッジケース分析の自動化","マルチエージェントのコンセンサスを通じて包括的なレビューレポートを生成"],"ko":["보안 및 오류 처리를 위한 코드 변경 사항의 검증","버그 감지 및 에지 케이스 분석의 자동화","다중 에이전트 합의를 통해 포괄적인 리뷰 보고서 생성"],"es":["Validar cambios de código para seguridad y control de errores","Automatizar la detección de errores y el análisis de casos límite","Generar informes de revisión exhaustivos a través de un consenso multiagente"],"fr":["Valider les modifications de code pour la sécurité et la gestion des erreurs","Automatiser la détection des bogues et l''analyse des cas limites","Générer des rapports de révision exhaustifs grâce à un consensus multi-agent"],"de":["Validieren von Code-Änderungen für Sicherheit und Fehlersuche","Automatisieren der Fehlererkennung und der Analyse von Randfällen","Erstellen von umfassenden Review-Berichten durch ein Multiagenten-Konsens"],"pt":["Validar alterações de código para segurança e tratamento de erros","Automatizar detecção de bugs e análise de casos limite","Gerar relatórios de revisão abrangentes por meio de consenso multi-agente"],"ru":["Проверка изменений кода на предмет безопасности и обработки ошибок","Автоматизация обнаружения ошибок и анализа граничных случаев","Генерация комплексных отчетов об обзоре посредством многоагентного консенсуса"],"ar":["التحقق من التغييرات في الشفرة لأمن وتحديد الأخطاء","تأتمة اكتشاف الأخطاء وتحليل الحالات القصوى","توليد تقارير مراجعة شاملة من خلال إجماع متعدد الوكلاء"]},"limitations":{"en":["Requires local setup and open-source AI app builder","Limited to code review use cases","Dependent on Task tool and PR diff analysis capabilities"],"zh":["需要本地设置和开源AI应用程序构建器","仅限代码审查用例","依赖于Task工具和PR差异分析功能"],"ja":["ローカル設定とオープンソースAIアプリビルダーが必要","コードレビュー用途のみ","TaskツールとPR差分分析の機能に依存"],"ko":["로컬 설정 및 오픈 소스 AI 애플리케이션 빌더가 필요","코드 리뷰 용도만 해당","Task 도구 및 PR 차이 분석 기능에 의존"],"es":["Requiere una configuración local y un constructor de aplicaciones de inteligencia artificial de código abierto","Limitado a casos de uso de revisión de código","Dependiente de las capacidades de la herramienta Task y del análisis de diferencias de PR"],"fr":["Nécessite une configuration locale et un constructeur d''applications d''intelligence artificielle open source","Limité aux cas d''utilisation de révision de code","Dépendant des capacités de l''outil Task et de l''analyse de différences de PR"],"de":["Benötigt eine lokale Einrichtung und einen Open-Source-KI-App-Builder","Begrenzt auf Code-Review-Anwendungsfälle","Abhängig von den Fähigkeiten des Task-Tools und der PR-Diff-Analyse"],"pt":["Exige configuração local e construtor de aplicativos de IA de código aberto","Limitado a casos de uso de revisão de código","Dependente das capacidades da ferramenta Task e análise de diff de PR"],"ru":["Требует локальной настройки и открытого конструктора приложений ИИ","Ограничен для случаев использования кодового обзора","Зависит от возможностей инструмента Task и анализа PR diff"],"ar":["يتطلب إعدادًا محليًا ومتخصصًا لبرامج الذكاء الاصطناعي مفتوحة المصدر","محدود لاستخدامات مراجعة الشفرة","يعتمد على إمكانات أداة المهمة وتحليل الفرق PR"]},"version":4},"contentHash":"0573b2e9c7042a2cb78f0f7a5dd2068b0f6c0690698ebf6aab2ff1cd9ccc1a5f","qualityScore":60}');
