INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dyad-sh/dyad/dyad:multi-pr-review', 'dyad:multi-pr-review', 'dyad-sh', 'dyad', 'community', 'dyad:multi-pr-review dyad-sh dyad community dyad:multi-pr-review is a local, open-source AI app builder that spawns three independent sub-agents to review code changes. It benefits power users by validating and aggregating findings through reasoned analysis. dyad:multi-pr-review是一个本地、开源的AI应用构建工具，用于代码审查和验证 dyad:multi-pr-reviewは、コードの変更を分析し、エラーを検出するAIエージェントです dyad:multi-pr-review는 코드 리뷰를 위한 로컬, 오픈소스 AI 애플리케이션 빌더입니다 dyad:multi-pr-review es una herramienta de código abierto que utiliza agentes independientes para revisar cambios de código desde diferentes perspectivas dyad:multi-pr-review est un outil open-source qui utilise des agents indépendants pour examiner les modifications de code depuis différentes perspectives dyad:multi-pr-review ist ein Open-Source-Tool, das unabhängige Agenten verwendet, um Code-Änderungen aus verschiedenen Perspektiven zu überprüfen O dyad:multi-pr-review é uma ferramenta de revisão de código baseada em IA que utiliza sub-agentes para análise de código. Ele é projetado para revisar alterações de código de diferentes perspectivas ИИ Агент dyad:multi-pr-review - это инструмент обзора кода, использующий субагентов для анализа кода. Он предназначен для обзора изменений кода с разных точек зрения dyad:multi-pr-review هو أداة مراجعة الكود التي تستخدم وكلاء فرعية لتحليل الكود. وهي مصممة لمراجعة تعديلات الكود من منظورات مختلفة how to use dyad:multi-pr-review dyad:multi-pr-review alternative to Replit dyad:multi-pr-review setup guide what is dyad:multi-pr-review dyad:multi-pr-review vs Bolt dyad:multi-pr-review install for AI agents 代码审查工具 AI应用构建 代码变更分析 子代理管理 代码错误检测 代码安全问题 dyad:multi-pr-review 代码审查最佳实践 代码质量保证 Fetches PR diff and existing comments for comprehensive review Spawns 3 sub-agents with specialized personas using the Task tool Utilizes a Correctness Expert sub-agent for bug, edge case, and security review Aggregates findings through reasoned analysis for validated results Reduces ordering bias by randomizing file order for each sub-agent dyad:multi-pr-review is an AI agent skill that automates code review by spawning sub-agents with specialized personas to review code changes from different perspectives.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deepdexfinance/deepdex-cli/deepdex-cli', 'community', 'deepdexfinance', 'deepdex-cli', 'deepdexfinance/deepdex-cli', 'deepdex-cli', 0, 0, 60, '2026-03-08T01:57:15.320Z', '2026-03-08T02:02:57.217Z', 'c2b663eb39cdacb106f700791c1d1c4ad14f87b2049b335c9c44922a134765d4', '{"id":"deepdexfinance/deepdex-cli/deepdex-cli","name":"deepdex-cli","description":{"en":"The deepdex-cli skill enables developers to work with a feature-rich trading bot for spot and perpetual trading on the DeepDex protocol. It benefits developers and traders looking for advanced trading capabilities.","zh":"DeepDex CLI 是一个高性能的 TypeScript/Bun 应用，用于在 DeepDex 协议上进行交易。它支持 Spot 和 Perpetual 交易，先进订单和子账户管理","ja":"DeepDex CLI は高性能の TypeScript/Bun アプリケーションで、DeepDex プロトコル上での取引を実行します。スポット・パーペチュアル取引、先進注文、サブアカウント管理に対応","ko":"DeepDex CLI는 높은 성능의 TypeScript/Bun 애플리케이션으로 DeepDex 프로토콜에서 거래를 수행하는 데 사용됩니다. 스폿 및 퍼펫츄얼 거래, 고급 주문, 서브 계정 관리를 지원합니다","es":"Deepdex-cli es un bot de trading de alto rendimiento para operar en el protocolo DeepDex con TypeScript y Bun","fr":"Deepdex-cli est un bot de trading haute performance pour trader sur le protocole DeepDex avec TypeScript et Bun","de":"Deepdex-cli ist ein Hochleistungs-Handelsbot für das Handeln auf dem DeepDex-Protokoll mit TypeScript und Bun","pt":"O DeepDex CLI é uma ferramenta de trading de alto desempenho em TypeScript/Bun para protocolo DeepDex, com recursos como trading spot e perpetual","ru":"DeepDex CLI - это высокопроизводительная торговая бот на TypeScript/Bun для протокола DeepDex, с функциями как спотовая и перпетуальная торговля","ar":"DeepDex CLI هو أداة تداول عالية الأداء بلغة TypeScript/Bun لبروتوكول DeepDex، مع ميزات مثل التداول النقدي والمدى"},"seo":{"title":{"en":"deepdex-cli: Comprehensive Trading Bot Setup Guide | AI A...","zh":"DeepDex CLI 交易机器人设置指南","ja":"DeepDex CLI トレーディングボットのベストプラクティス","ko":"DeepDex CLI 거래 봇 사용법 및 설정 가이드","es":"Guía de configuración de deepdex-cli para traders avanzados","fr":"Configurer deepdex-cli pour le trading haute performance","de":"Deepdex-cli Einrichtungsleitfaden für erfahrene Trader","pt":"Guia de Configuração do DeepDex CLI para Ferramentas de IA","ru":"Настройка DeepDex CLI: ИИ Агенты для Торговли","ar":"دليل إعداد DeepDex CLI لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock advanced trading capabilities with deepdex-cli. Learn how to set up and utilize this high-performance TypeScript/Bun application for trading on the De...","zh":"了解 DeepDex CLI 交易机器人的功能和特点，包括 Spot 与 Perpetual 交易、先进订单和子账户管理","ja":"DeepDex CLI トレーディングボットの機能と特徴を紹介します。スポット・パーペチュアル取引、先進注文、サブアカウント管理など","ko":"DeepDex CLI 거래 봇의 기능과 특징을 소개합니다. 스폿 및 퍼펫츄얼 거래, 고급 주문, 서브 계정 관리 등","es":"Aprende a utilizar deepdex-cli para operar en el protocolo DeepDex con órdenes de mercado y límite, gestión de subcuentas y más","fr":"Découvrez comment utiliser deepdex-cli pour trader sur le protocole DeepDex avec des ordres de marché et de limite, gestion de sous-comptes et plus","de":"Erfahren Sie, wie Sie deepdex-cli nutzen können, um auf dem DeepDex-Protokoll mit Marktaufträgen und Limitaufträgen, Subkonto-Verwaltung und mehr zu handeln","pt":"Aprenda a configurar o DeepDex CLI para maximizar suas estratégias de trading com ordens limit/market e alavancagem de até 50x","ru":"Узнайте, как настроить DeepDex CLI для tối ưuизации ваших торговых стратегий с лимит/рыночными ордерами и левериджем до 50х","ar":"تعلم كيفية إعداد DeepDex CLI لتعظيم استراتيجيات التداول الخاصة بك مع أوامر الحد/السوق والرافعة المالية حتى 50 ضعفا"},"definition":{"en":"deepdex-cli is a TypeScript/Bun application providing a comprehensive trading bot for the DeepDex protocol with features like spot and perpetual trading, advanced orders, and subaccount management.","zh":"DeepDex CLI 是一个用于在 DeepDex 协议上进行交易的命令行界面工具","ja":"DeepDex CLI は DeepDex プロトコル上での取引を実行するためのコマンドラインインターフェイスツール","ko":"DeepDex CLI는 DeepDex 프로토콜에서 거래를 수행하는 명령줄 인터페이스 도구입니다","es":"Deepdex-cli es una herramienta de trading de código abierto que permite a los traders operar en el protocolo DeepDex","fr":"Deepdex-cli est un outil de trading open source qui permet aux traders de commercer sur le protocole DeepDex","de":"Deepdex-cli ist ein Open-Source-Handelstool, das es Tradern ermöglicht, auf dem DeepDex-Protokoll zu handeln","pt":"O que é DeepDex CLI? Uma ferramenta de trading de código aberto em TypeScript/Bun para protocolo DeepDex","ru":"Что такое DeepDex CLI? Открытый торговый бот на TypeScript/Bun для протокола DeepDex","ar":"ما هو DeepDex CLI؟ أداة تداول مفتوحة المصدر بلغة TypeScript/Bun لبروتوكول DeepDex"},"features":{"en":["Spot and perpetual trading with limit/market orders and up to 50x leverage","Advanced orders including take-profit, stop-loss, post-only, and reduce-only orders","Subaccount management for isolated accounts and different strategies","Support for ETH/USDC and SOL/USDC trading pairs","Automa functionality for automated trading strategies"],"zh":["支持 Spot 和 Perpetual 交易","先进订单，包括止盈、止损、限价单和市价单","子账户管理，支持多个独立账户","高性能的 TypeScript/Bun 应用","支持最高 50 倍的杠杆"],"ja":["スポット・パーペチュアル取引に対応","先進注文、包括利益確定、損失制限、指値注文、成行注文","サブアカウント管理、複数の独立したアカウントに対応","高性能の TypeScript/Bun アプリケーション","最大 50 倍のレバレッジに対応"],"ko":["스포트 및 퍼펫츄얼 거래 지원","고급 주문, 포함한 이익 실현, 손실 제한, 지정가 주문, 시장가 주문","서브 계정 관리, 여러 개의 독립된 계정 지원","높은 성능의 TypeScript/Bun 애플리케이션","최대 50 배의 레버리지 지원"],"es":["Operaciones de spot y perpetuales con órdenes de mercado y límite","Gestión de subcuentas para estrategias de trading aisladas","Órdenes avanzadas como take-profit, stop-loss, post-only y reduce-only","Soporte para hasta 50x de apalancamiento","Implementado en TypeScript y Bun para un rendimiento óptimo"],"fr":["Opérations de spot et perpétuelles avec des ordres de marché et de limite","Gestion de sous-comptes pour des stratégies de trading isolées","Ordres avancés tels que take-profit, stop-loss, post-only et reduce-only","Support jusqu''à 50x de levier","Implémenté en TypeScript et Bun pour des performances optimales"],"de":["Spot- und Perpetual-Handel mit Marktaufträgen und Limitaufträgen","Verwaltung von Subkonten für isolierte Handelsstrategien","Erweiterte Aufträge wie Take-Profit, Stop-Loss, Post-Only und Reduce-Only","Unterstützung für bis zu 50x Hebel","Implementiert in TypeScript und Bun für optimale Leistung"],"pt":["Trading spot e perpetual com ordens limit/market","Ordens avançadas: take-profit, stop-loss, post-only, reduce-only","Gerenciamento de subcontas: contas isoladas para diferentes estratégias","Alavancagem de até 50x","Integração com protocolo DeepDex"],"ru":["Спотовая и перпетуальная торговля с лимит/рыночными ордерами","Продвинутые ордера: тейк-профит, стоп-лосс, пост-онли, редьюс-онли","Управление субаккаунтами: изолированные аккаунты для разных стратегий","Леверидж до 50х","Интеграция с протоколом DeepDex"],"ar":["التداول النقدي والمدى مع أوامر الحد/السوق","أوامر متقدمة: أخذ الربح، وقف الخسارة، نشر فقط، تقليل فقط","إدارة الحسابات الفرعية: حسابات معزولة لاستراتيجيات مختلفة","الرافعة المالية حتى 50 ضعفا","التكامل مع بروتوكول DeepDex"]},"keywords":{"en":["how to use deepdex-cli","deepdex-cli setup guide","deepdex-cli alternative","deepdex-cli vs trading bots","deepdex-cli install","what is deepdex-cli","deepdex-cli trading bot","deepdex-cli TypeScript example","deepdex-cli Bun application"],"zh":["DeepDex CLI","交易机器人","Spot 交易","Perpetual 交易","先进订单","子账户管理","TypeScript","Bun","命令行界面"],"ja":["DeepDex CLI","トレーディングボット","スポット取引","パーペチュアル取引","先進注文","サブアカウント管理","TypeScript","Bun","コマンドラインインターフェイス"],"ko":["DeepDex CLI","거래 봇","스포트 거래","퍼펫츄얼 거래","고급 주문","서브 계정 관리","TypeScript","Bun","명령줄 인터페이스"],"es":["deepdex-cli","trading bot","protocolo DeepDex","TypeScript","Bun","operaciones de spot","operaciones perpétuales","órdenes de mercado","órdenes de límite","gestión de subcuentas"],"fr":["deepdex-cli","bot de trading","protocole DeepDex","TypeScript","Bun","opérations de spot","opérations perpétuelles","ordres de marché","ordres de limite","gestion de sous-comptes"],"de":["deepdex-cli","Handelsbot","DeepDex-Protokoll","TypeScript","Bun","Spot-Handel","Perpetual-Handel","Marktaufträge","Limitaufträge","Subkonto-Verwaltung"],"pt":["DeepDex CLI","ferramentas de IA para trading","TypeScript","Bun","protocolo DeepDex","trading spot","trading perpetual","ordens limit/market","alavancagem"],"ru":["DeepDex CLI","ИИ Агенты для торговли","TypeScript","Bun","протокол DeepDex","спотовая торговля","перпетуальная торговля","лимит/рыночные ордера","леверидж"],"ar":["DeepDex CLI","أدوات الذكاء الاصطناعي للتداول","TypeScript","Bun","بروتوكول DeepDex","التداول النقدي","التداول المدى","أوامر الحد/السوق","الرافعة المالية"]}},"owner":"deepdexfinance","repo":"deepdex-cli","repoPath":"deepdexfinance/deepdex-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.320Z","topics":[],"category":"community","skillMd":{"name":"deepdex-cli","description":"High-performance CLI trading bot and MCP server for the DeepDex protocol. Enables spot/perpetual trading, wallet management, subaccount operations, and automated trading strategies. Use when building features, fixing bugs, or extending the trading bot.","bodyPreview":"# DeepDex CLI Skill\n\nA comprehensive skill for working with the DeepDex CLI trading bot, a high-performance TypeScript/Bun application for trading on the DeepDex protocol.\n\n## Project Overview\n\nDeepDex CLI is a feature-rich trading bot with:\n- **Spot & Perpetual Trading**: ETH/USDC, SOL/USDC with limit/market orders and up to 50x leverage\n- **Advanced Orders**: Take-profit, stop-loss, post-only, reduce-only orders\n- **Subaccount Management**: Isolated accounts for different strategies\n- **Automa","body":"# DeepDex CLI Skill\n\nA comprehensive skill for working with the DeepDex CLI trading bot, a high-performance TypeScript/Bun application for trading on the DeepDex protocol.\n\n## Project Overview\n\nDeepDex CLI is a feature-rich trading bot with:\n- **Spot & Perpetual Trading**: ETH/USDC, SOL/USDC with limit/market orders and up to 50x leverage\n- **Advanced Orders**: Take-profit, stop-loss, post-only, reduce-only orders\n- **Subaccount Management**: Isolated accounts for different strategies\n- **Automated Strategies**: Grid trading, DCA, momentum, funding rate arbitrage\n- **Process Manager**: Run multiple bots simultaneously with monitoring\n- **MCP Server Integration**: Expose trading tools to LLMs (Claude, etc.)\n- **Built with Bun**: Fast TypeScript runtime with zero-config setup\n\n## Directory Structure\n\n```\ndeepdex-cli/\n├── src/\n│   ├── abis/                 # Contract ABIs for blockchain interaction\n│   ├── config/               # Configuration management\n│   ├── services/             # Business logic (trading, orders, accounts)\n│   ├── types/                # TypeScript type definitions\n│   └── mcp/                  # MCP server implementation\n├── configs/                  # Example strategy configs (grid.json, dca.json, etc.)\n├── index.ts                  # CLI entry point\n├── GUIDE.md                  # Complete CLI reference\n├── package.json              # Dependencies: viem, bignumber.js, zod, etc.\n├── biome.json                # Biome linter/formatter config\n├── tsconfig.json             # TypeScript configuration\n└── bunfig.toml              # Bun runtime configuration\n```\n\n## Tech Stack\n\n- **Runtime**: Bun v1.0.0+ (fast TypeScript/JavaScript runtime)\n- **Language**: TypeScript 5+\n- **Blockchain**: viem (Ethereum client library)\n- **Validation**: zod (runtime type validation)\n- **Logging**: consola\n- **Math**: bignumber.js (arbitrary precision)\n- **Config**: dotenv (environment variables)\n- **MCP**: @modelcontextprotocol/sdk (AI model integration)\n\n## Common Commands\n\n### Development\n\n```bash\nbun install          # Install dependencies\nbun run dev          # Watch mode with auto-reload\nbun run start        # Run trading bot\nbun test            # Run tests\nbun test --watch    # Watch mode testing\nbun run lint        # Check with Biome\nbun run lint:fix    # Auto-fix with Biome\nbun run format      # Format code with Biome\n```\n\n### Wallet Management\n\n```bash\ndeepdex init                                  # Initialize wallet\ndeepdex wallet list                           # List all wallets\ndeepdex wallet info [name]                    # Display wallet address and balances\ndeepdex wallet create [name]                  # Create new wallet\ndeepdex wallet switch <name>                  # Switch active wallet\ndeepdex wallet import <private_key> [name]    # Import wallet from private key\ndeepdex wallet export [name]                  # Export private key\ndeepdex wallet transfer <amount> <token> <recipient>  # Transfer tokens\ndeepdex wallet transfer 50% USDC trading      # Transfer 50% of balance\n```\n\n### Account & Collateral\n\n```bash\ndeepdex account create                        # Create subaccount\ndeepdex account list                          # List all subaccounts\ndeepdex account info [name]                   # Display account balance and margin\ndeepdex account deposit <amount> [token]      # Deposit collateral\ndeepdex account deposit 100% USDC             # Deposit all USDC\ndeepdex account withdraw <amount> [token]     # Withdraw collateral\ndeepdex account delegate [wallet]             # Delegate hot wallet authority\ndeepdex faucet [token]                        # Get testnet tokens\n```\n\n### Market Info\n\n```bash\ndeepdex market list                           # List available trading pairs\ndeepdex market info <pair>                    # Get market details (ETH/USDC)\ndeepdex market orderbook <pair>               # Display order book\ndeepdex market price <pair>                   # Get current price\ndeepdex market funding <pair>                 # Check funding rates (perpetuals)\ndeepdex balance                               # Show portfolio balance\ndeepdex portfolio                             # Show detailed portfolio\n```\n\n### Spot Trading\n\n```bash\ndeepdex spot buy <pair> <amount> [--price] [--post-only]\ndeepdex spot buy ETH/USDC 1                   # Buy 1 ETH at market\ndeepdex spot buy ETH/USDC 1 --price 2500      # Buy with limit price\ndeepdex spot sell <pair> <amount> [--price] [--reduce-only]\ndeepdex spot sell ETH/USDC 0.5                # Sell 0.5 ETH at market\n```\n\n### Perpetual Futures\n\n```bash\ndeepdex perp long <pair> <amount> [--lev] [--price] [--tp] [--sl]\ndeepdex perp long ETH-USDC 1 --lev 10         # Long 1 ETH at 10x leverage\ndeepdex perp long ETH-USDC 25% --lev 5 --tp 2600 --sl 2400\ndeepdex perp short <pair> <amount> [--lev] [--price] [--tp] [--sl]\ndeepdex perp short SOL-USDC 10 --lev 5        # Short 10 SOL at 5x leverage\n```\n\n### Order Management\n\n```bash\ndeepdex order list                            # List open orders\ndeepdex order cancel <id>                     # Cancel specific order\ndeepdex order cancel-all                      # Cancel all orders\ndeepdex order history                         # View trade history\n```\n\n### Position Management\n\n```bash\ndeepdex position list                         # List open positions\ndeepdex position info <id>                    # Get position details\ndeepdex position close <id> [--size]          # Close position fully or partially\ndeepdex position modify <id> [--tp] [--sl]    # Update TP/SL\n```\n\n### Automated Bot (Single)\n\n```bash\ndeepdex bot start [strategy] [--config config.json]  # Start bot in foreground\ndeepdex bot start grid                        # Start default grid strategy\ndeepdex bot start momentum --config ./configs/momentum.json\ndeepdex bot status                            # Check running bot status\ndeepdex bot stop                              # Stop bot gracefully\ndeepdex bot logs [--follow]                   # View bot logs\ndeepdex bot list-strategies                   # Show available strategies\ndeepdex bot backtest <strategy> [--config]    # Backtest strategy\n```\n\n### Process Manager (Multi-Bot)\n\n```bash\ndeepdex pm ps                                 # List all running processes\ndeepdex pm start <name> <strategy> [--config] [--account]  # Start new process\ndeepdex pm start eth-grid grid --config ./configs/grid.json\ndeepdex pm start sol-dca simple --config ./configs/dca.json --account dca-bot\ndeepdex pm stop <name>                        # Gracefully stop process\ndeepdex pm restart <name>                     # Restart process\ndeepdex pm kill <name>                        # Force kill process\ndeepdex pm logs <name> [--follow] [-n 100]    # View process logs\ndeepdex pm stop-all                           # Stop all running processes\n```\n\n### Quota Management\n\n```bash\ndeepdex quota check                           # Check quota for active wallet\ndeepdex quota info [address]                  # Get quota info for address\ndeepdex quota add <address> <amount>          # Add quota to account\ndeepdex quota stats                           # Show quota statistics\n```\n\n### Cross-Chain Bridge\n\n```bash\ndeepdex bridge chains                         # List supported chains\ndeepdex bridge fees <chain> <amount> <token>  # Estimate bridge fees\ndeepdex bridge deposit <chain> <amount> <token>   # Deposit from external chain\ndeepdex bridge withdraw <chain> <amount> <token>  # Withdraw to external chain\ndeepdex bridge status <txHash>                # Check transaction status\n```\n\n### System & Config\n\n```bash\ndeepdex config show                           # Display current config\ndeepdex config set <key> <value>              # Update config value\ndeepdex config reset                          # Reset to defaults\ndeepdex history trades                        # View trade history\ndeepdex history transfers                     # View transfer history\ndeepdex health                                # Run health check\ndeepdex health --json                         # JSON format\ndeepdex health --watch                        # Watch mode with refresh\n```\n\n### Aliases\n\n```bash\ndeepdex buy <pair> <amount>   # Alias for spot buy\ndeepdex sell <pair> <amount>  # Alias for spot sell\ndeepdex long <pair> <amount>  # Alias for perp long\ndeepdex short <pair> <amount> # Alias for perp short\n```\n\n## Key Concepts\n\n### Quota System\n\nQuotas are system-level resource allocations for accounts on the DeepDex protocol. They control the rate of operations an account can perform:\n\n- **Add Quota**: Allocate quota to an account with `deepdex quota add <address> <amount>`\n- **Check Quota**: View available quota with `deepdex quota check`\n- **Query Info**: Get detailed quota information with `deepdex quota info [address]`\n- **Statistics**: View usage stats with `deepdex quota stats`\n\nQuota amounts are unsigned 32-bit integers representing operation limits or transaction throughput constraints.\n\n### Strategies\n\n1. **Simple DCA** (`simple`): Dollar-cost averaging at regular intervals\n2. **Grid Trading** (`grid`): Buy/sell at fixed intervals with inventory skewing\n3. **Momentum** (`momentum`): Trend-following with moving averages\n4. **Funding Rate Arbitrage** (`arbitrage`): Delta-neutral funding rate exploitation\n\n### Subaccounts\n\nIsolated accounts for managing different trading strategies and risk separately. Use `deepdex account create` to set up new subaccounts.\n\n### Process Manager\n\nRun multiple bots simultaneously with unique names:\n```bash\ndeepdex pm start strategy-1 grid --config ./configs/grid.json\ndeepdex pm start strategy-2 dca --config ./configs/dca.json\ndeepdex pm ps    # List running processes\n```\n\n### Making Changes\n1. **Code**: Edit TypeScript files in `src/`\n2. **Validate**: Run `bun run lint --write` to auto-fix style issues\n3. **Test**: Use `bun test` to verify functionality\n4. **Build**: The `index.ts` file is the compiled entry point\n\n### Adding Features\n- Trading strategies go in `src/services/strategies/`\n- New commands extend the CLI interface in `src/` or `index.ts`\n- MCP tools are defined in `src/mcp/`\n- Type definitions belong in `src/types/`\n\n### Environment Variables\n```bash\nDEEPDEX_WALLET_PASSWORD      # Unlock wallets for trading\nDEEPDEX_NEW_WALLET_PASSWORD  # Create new wallets\nDEEPDEX_NON_INTERACTIVE      # Fail instead of prompting (for CI/CD)\n```\n\n## Important Files\n\n- **index.ts**: CLI entry point and command dispatcher\n- **GUIDE.md**: Complete CLI reference with all commands and options\n- **src/services/**: Core trading logic (orders, accounts, strategies)\n- **src/mcp/**: Model Context Protocol server for AI integration\n- **configs/grid.json, dca.json**: Example strategy configurations\n- **src/types/**: TypeScript interfaces for trading data structures\n\n## Security & Key Storage\n\n### Keyring Integration\n\nPrivate keys are stored securely using OS-level credential storage:\n\n- **macOS**: Keychain\n- **Linux**: libsecret (GNOME) or kwallet (KDE)\n- **Windows**: Credential Manager\n\nKeys are never written to disk in plaintext. Memory is securely zeroed after use.\n\n### Environment Variables for Automation\n\n```bash\nDEEPDEX_WALLET_PASSWORD       # Unlock wallets for trading\nDEEPDEX_NEW_WALLET_PASSWORD   # Create/import wallets programmatically\nDEEPDEX_NON_INTERACTIVE       # Fail instead of prompting (for CI/CD)\n```\n\n**Automation Example:**\n```bash\n# Create bot wallet programmatically\nDEEPDEX_NEW_WALLET_PASSWORD=\"mypassword\" deepdex wallet create bot-1\n\n# Run trading command without prompts\nexport DEEPDEX_WALLET_PASSWORD=\"mypassword\"\ndeepdex account deposit 100% USDC --yes\ndeepdex bot start grid --yes\n```\n\n## Health Check System\n\nThe `deepdex health` command runs comprehensive diagnostics:\n\n**Checks:**\n- RPC connection latency and block sync\n- Oracle price feed freshness\n- Wallet gas token balance\n- Subaccount margin ratio and health\n- Bot process status and resource usage\n- Disk space and memory availability\n\n**Exit Codes:**\n- `0` = All checks passed\n- `1` = One or more warnings\n- `2` = One or more critical failures\n\n**Usage:**\n```bash\ndeepdex health                    # Run health check\ndeepdex health --json             # JSON output for parsing\ndeepdex health --watch            # Watch mode with 5s refresh\ndeepdex health --quiet            # Silent mode for scripts\n```\n\n## Common Tasks\n\n### Adding a CLI Command\nExtend the command parsing in `index.ts` or create new handler in `src/services/`.\n\n### Implementing a Strategy\nCreate a new file in `src/services/strategies/` following the existing pattern (Simple, Grid, Momentum, Arbitrage).\n\n### Debugging Trading Logic\nUse `consola` for structured logging. Check the strategy implementation in `src/services/strategies/`.\n\n### MCP Tool Integration\nAdd tools in `src/mcp/` to expose new functionality to Claude and other MCP clients.\n\n## Network\n\n- **RPC**: `https://rpc-testnet.deepdex.finance`\n- **Network**: DeepDex Testnet\n- **Contract Addresses**: Defined in `src/config/`\n\n## Resources\n\n- **Full Documentation**: See GUIDE.md for complete CLI reference\n- **Quota Guide**: See QUOTA_GUIDE.md for quota management details\n- **Example Configs**: configs/ directory contains grid.json, dca.json templates\n- **Blockchain Interaction**: viem library (https://viem.sh)\n- **Type Safety**: Zod schemas (https://zod.dev)\n"},"lastSynced":"2026-03-08T02:02:57.217Z","agentAnalysis":{"suitability":{"en":"Ideal for Trading Agents requiring advanced spot and perpetual trading capabilities on the DeepDex protocol","zh":"适用于需要在 DeepDex 协议上进行高级别的现货和永续交易的交易代理","ja":"DeepDex プロトコル上で高度なスポットおよびペアレント取引機能を必要とするトレーディングエージェントに適している","ko":"DeepDex 프로토콜에서 고급 스폿 및 퍼펫츄얼 거래 기능을 필요로 하는 트레이딩 에이전트에 적합","es":"Ideal para Agentes de Trading que requieren capacidades de trading spot y perpetual avanzadas en el protocolo DeepDex","fr":"Idéal pour les agents de trading nécessitant des capacités de trading spot et perpetual avancées sur le protocole DeepDex","de":"Ideal für Trading-Agenten, die erweiterte Spot- und Perpetual-Handelsfunktionen im DeepDex-Protokoll benötigen","pt":"Ideal para Agentes de Negociação que exigem capacidades de negociação spot e perpétua avançadas no protocolo DeepDex","ru":"Идеально для торговых агентов, требующих передовых возможностей спотовой и перпетуальной торговли на протоколе DeepDex","ar":"مثالي لوسائل التداول التي تتطلب قدرات تداول مكاني ودائم متقدمة على بروتوكول DeepDex"},"recommendation":{"en":"Empowers agents to execute high-performance trades with limit/market orders, leverage up to 50x, and advanced orders like take-profit and stop-loss using the DeepDex CLI trading bot, leveraging TypeScript and Bun for optimized performance","zh":"赋予代理执行高性能交易的能力，包括限价/市价单，最高 50 倍的杠杆，以及使用 DeepDex CLI 交易机器人和 TypeScript 及 Bun 进行优化的止盈和止损等高级订单","ja":"DeepDex CLI トレーディングボットを使用し、TypeScript と Bun で最適化されたパフォーマンスで、高性能取引を実行するエージェントを可能にし、リミット/マーケットオーダー、最大 50 倍のレバレッジ、および利益実現と損失制限などの高度なオーダー","ko":"DeepDex CLI 트레이딩 봇을 사용하고 TypeScript 및 Bun으로 최적화된 성능으로 고성능 거래를 실행할 수 있는 에이전트를 가능하게 하며, 한계/시장 주문, 최대 50배의 레버리지, 및 이익 실현 및 손실 제한과 같은 고급 주문","es":"Habilita a los agentes a ejecutar operaciones de alto rendimiento con órdenes limit/market, apalancamiento de hasta 50x y órdenes avanzadas como take-profit y stop-loss utilizando el bot de trading DeepDex CLI, aprovechando TypeScript y Bun para un rendimiento optimizado","fr":"Permet aux agents d''exécuter des transactions haute performance avec des ordres limit/marché, un effet de levier allant jusqu''à 50x et des ordres avancés tels que take-profit et stop-loss en utilisant le bot de trading DeepDex CLI, en exploitant TypeScript et Bun pour des performances optimisées","de":"Ermöglicht es Agenten, Hochleistungs-Transaktionen mit Limit-/Markt-Orders, Hebelwirkung von bis zu 50x und erweiterten Orders wie Take-Profit und Stop-Loss durchzuführen, indem sie den DeepDex-CLI-Handelsbot verwenden, der TypeScript und Bun für optimierte Leistung nutzt","pt":"Habilita agentes a executar negociações de alto desempenho com ordens limit/market, alavancagem de até 50x e ordens avançadas como take-profit e stop-loss usando o bot de negociação DeepDex CLI, aproveitando TypeScript e Bun para desempenho otimizado","ru":"Наделяет агентов возможностью выполнять высокопроизводительные торговые операции с лимитными/рыночными ордерами, кредитным плечом до 50х и расширенными ордерами, такими как тейк-профит и стоп-лосс, используя бота торговли DeepDex CLI, использующий TypeScript и Bun для оптимизированной производительности","ar":"تمكين الوكلاء من تنفيذ صفقات عالية الأداء مع أوامر الحد/السوق، والتحكم حتى 50 مرة، والأوامر المتقدمة مثل تحقيق الربح ووقف الخسارة باستخدام بوت تداول DeepDex CLI، والاستفادة من TypeScript و Bun للأداء الأمثل"},"useCases":{"en":["Executing spot and perpetual trades on ETH/USDC and SOL/USDC","Managing subaccounts for isolated trading strategies","Implementing advanced order types like post-only and reduce-only orders"],"zh":["在 ETH/USDC 和 SOL/USDC 上执行现货和永续交易","管理子账户以实现隔离的交易策略","实现高级订单类型，如仅挂单和减少仅挂单"],"ja":["ETH/USDC と SOL/USDC でスポットおよびペアレント取引を実行する","サブアカウントを管理して分離されたトレーディング戦略を実現する","ポストのみおよびリュースのみなどの高度なオーダータイプを実装する"],"ko":["ETH/USDC 및 SOL/USDC에서 스폿 및 퍼펫츄얼 거래를 실행","분리된 거래 전략을 위해 하위 계정을 관리","포스트 전용 및 줄이기 전용과 같은 고급 주문 유형을 구현"],"es":["Ejecutar operaciones spot y perpetual en ETH/USDC y SOL/USDC","Administrar subcuentas para estrategias de trading aisladas","Implementar tipos de órdenes avanzados como órdenes post-only y reduce-only"],"fr":["Exécuter des transactions spot et perpetual sur ETH/USDC et SOL/USDC","Gérer des sous-comptes pour des stratégies de trading isolées","Mettre en œuvre des types d''ordres avancés tels que les ordres post-only et reduce-only"],"de":["Durchführung von Spot- und Perpetual-Transaktionen in ETH/USDC und SOL/USDC","Verwaltung von Unterkonten für isolierte Handelsstrategien","Implementierung von erweiterten Ordertypen wie Post-only- und Reduce-only-Orders"],"pt":["Executando negociações spot e perpétuas em ETH/USDC e SOL/USDC","Gerenciando subcontas para estratégias de negociação isoladas","Implementando tipos de ordens avançados como ordens post-only e reduce-only"],"ru":["Выполнение спотовых и перпетуальных сделок на ETH/USDC и SOL/USDC","Управление субаккаунтами для изолированных торговых стратегий","Реализация расширенных типов ордеров, таких как пост-онли и редьюс-онли ордера"],"ar":["تنفيذ الصفقات المكانية والدائمة على ETH/USDC و SOL/USDC","إدارة الحسابات الفرعية لاستراتيجيات التداول المنفصلة","تطبيق أنواع أوامر متقدمة مثل أوامر منشور فقط وتقليل فقط"]},"limitations":{"en":["Requires DeepDex protocol access","Limited to spot and perpetual trading","Dependent on TypeScript and Bun for execution"],"zh":["需要 DeepDex 协议访问","仅限于现货和永续交易","依赖于 TypeScript 和 Bun 执行"],"ja":["DeepDex プロトコルへのアクセスが必要","スポットおよびペアレント取引のみ","実行には TypeScript と Bun に依存"],"ko":["DeepDex 프로토콜 액세스가 필요","스팟 및 퍼펫츄얼 거래만","실행에는 TypeScript 및 Bun에 의존"],"es":["Requiere acceso al protocolo DeepDex","Limitado a operaciones spot y perpetual","Dependiente de TypeScript y Bun para la ejecución"],"fr":["Nécessite un accès au protocole DeepDex","Limité aux transactions spot et perpetual","Dépendant de TypeScript et Bun pour l''exécution"],"de":["Benötigt Zugriff auf das DeepDex-Protokoll","Begrenzt auf Spot- und Perpetual-Transaktionen","Abhängig von TypeScript und Bun für die Ausführung"],"pt":["Exige acesso ao protocolo DeepDex","Limitado à negociação spot e perpétua","Dependente de TypeScript e Bun para execução"],"ru":["Требует доступа к протоколу DeepDex","Ограничен спотовой и перпетуальной торговлей","Зависит от TypeScript и Bun для выполнения"],"ar":["يتطلب الوصول إلى بروتوكول DeepDex","محدود بالتداول المكاني والدائم","يعتمد على TypeScript و Bun للتنفيذ"]},"version":4},"contentHash":"c2b663eb39cdacb106f700791c1d1c4ad14f87b2049b335c9c44922a134765d4","qualityScore":60}');
