INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openai/openai-agents-python/pr-draft-summary', 'pr-draft-summary', 'openai', 'openai-agents-python', 'community', 'pr-draft-summary openai openai-agents-python community The pr-draft-summary skill produces a concise summary, PR-ready title, and draft description for openai-agents-python after substantive code work. It benefits developers by simplifying the PR process. PR Draft Summary是一个轻量级的多agent工作流框架，帮助开发者提高代码审查效率 PR Draft Summaryは軽量級のマルチエージェントワークフローフレームワークで、開発者のコードレビューの効率を向上させます PR Draft Summary는 경량화된 멀티 에이전트 워크플로우 프레임워크로 개발자의 코드 리뷰 효율을 향상시킵니다 pr-draft-summary es un marco ligero para flujos de trabajo de agentes que genera un resumen conciso y un título y descripción de solicitud de extracción (PR) para su uso en openai-agents-python pr-draft-summary est un cadre léger pour les flux de travail d''agents qui génère un résumé concis et un titre et une description de demande d''extraction (PR) pour son utilisation dans openai-agents-python pr-draft-summary ist ein leichtes Framework für Multi-Agent-Workflows, das eine präzise Zusammenfassung und einen Titel und eine Beschreibung für Pull-Requests (PR) in openai-agents-python generiert O pr-draft-summary é um framework leve e poderoso para fluxos de trabalho de multi-agente, permitindo a criação de resumos concisos e títulos de PR prontos para paste Pr-draft-summary - это легкий и мощный фреймворк для многопоточных рабочих процессов, позволяющий создавать краткие резюме и заголовки PR, готовые для вставки pr-draft-summary هو إطار عمل خفيف وقوي لتدفقات العمل متعددة الوكلاء، مما يسمح بإنشاء ملخصات موجزة وأسماء PR جاهزة لللصق how to use pr-draft-summary pr-draft-summary setup guide pr-draft-summary alternative what is pr-draft-summary pr-draft-summary vs manual PR summary pr-draft-summary install for AI agents AIエージェント 多agent工作流 PR Draft Summary 代码审查 轻量级框架 Python开发 代码效率 Generates PR-ready title and draft description Produces concise summary for openai-agents-python Automates PR summary generation after substantive code work Supports runtime code, tests, examples, docs, and build/test configuration Triggers after task completion or when ready for review pr-draft-summary is a lightweight framework for generating PR-ready summaries, including a concise summary, title, and draft description, for use in multi-agent workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('axiomhq/validating-adr-compliance/validating-adr-compliance', 'community', 'axiomhq', 'validating-adr-compliance', 'axiomhq/validating-adr-compliance', 'validating-adr-compliance', 0, 0, 60, '2026-03-08T01:57:15.330Z', '2026-03-08T02:03:10.548Z', '85697f527217e0b293668d59f9329249fe7172d6d84e7fb89aa506689721430b', '{"id":"axiomhq/validating-adr-compliance/validating-adr-compliance","name":"validating-adr-compliance","description":{"en":"The validating-adr-compliance skill validates PR code against Architecture Decision Records, ensuring implementations adhere to documented architectural decisions, benefiting developers and architects.","zh":"验证ADR合规性，确保代码和实现符合架构决策记录","ja":"ADRコンプライアンスを検証し、コードと実装がアーキテクチャ設計レコードに準拠していることを確認する","ko":"ADR 규정 준수를 검증하여 코드와 구현이 아키텍처 결정 레코드에 따라 구현되는지 확인합니다","es":"Valida el código PR contra ADRs y verifica la implementación de decisiones arquitectónicas","fr":"Validez le code PR contre les ADRs et vérifiez la mise en œuvre des décisions d''architecture","de":"Überprüfen Sie den PR-Code gegen ADRs und validieren Sie die Umsetzung von Architekturentscheidungen","pt":"Valida o código PR contra Registros de Decisões de Arquitetura para garantir a conformidade","ru":"Проверяет код PR на соответствие Архитектурным Решениям","ar":"يحقق في مطابقة код PR للقرارات المعمارية"},"seo":{"title":{"en":"validating-adr-compliance: ADR Compliance Validation Setu...","zh":"AIエージェント：自动化ADR合规性验证setup指南","ja":"AIエージェント：アーキテクチャ設計レコード（ADR）コンプライアンス検証ベストプラクティス","ko":"AI 에이전트: ADR 규정 준수 검증 가이드","es":"Guía de configuración para la validación de cumplimiento ...","fr":"Guide de mise en place de la validation de conformité ADR","de":"Einrichtungsleitfaden für die Validierung der ADR-Konform...","pt":"Guia de Configuração para Validação de Conformidade ADR c...","ru":"Настройка ИИ Агентов для проверки соответствия ADR","ar":"دليل إعداد التحقق من مطابقة السجلات القرارية للبنية التحت..."},"description":{"en":"Ensure PR code aligns with Architecture Decision Records. Learn how to validate ADR compliance with our AI agent skill and improve implementation accuracy.","zh":"使用AIエージェント验证代码与ADR文档的合规性，确保架构一致性","ja":"AIエージェントを使用して、コードとADR文書のコンプライアンスを検証し、アーキテクチャの整合性を確保する","ko":"AI 에이전트를 사용하여 코드와 ADR 문서의 규정 준수를 검증하고 아키텍처 일관성을 보장합니다","es":"Aprende a validar el código PR contra Registros de Decisiones de Arquitectura (ADRs) con nuestra herramienta de validación de cumplimiento de ADR","fr":"Découvrez comment valider le code PR contre les Registres de Décisions d''Architecture (ADRs) avec notre outil de validation de conformité ADR","de":"Erfahren Sie, wie Sie den PR-Code gegen Architecture Decision Records (ADRs) mit unserem Validierungstool für ADR-Konformität überprüfen","pt":"Aprenda a validar o código PR contra Registros de Decisões de Arquitetura com nossa ferramenta de IA para garantir a conformidade","ru":"Проверьте соответствие кода PR Архитектурным Решениям с помощью нашего ИИ Агента","ar":"تعلم كيفية التحقق من مطابقة код PR للقرارات المعمارية باستخدام أدواتنا الذكية"},"definition":{"en":"validating-adr-compliance is a skill that checks PR code and related implementations against Architecture Decision Records for compliance, using oracle for deep analysis.","zh":"ADR合规性验证是指使用AIエージェント检查代码和实现是否符合架构决策记录","ja":"ADRコンプライアンス検証とは、AIエージェントを使用してコードと実装がアーキテクチャ設計レコードに準拠しているかどうかを確認すること","ko":"ADR 규정 준수 검증은 AI 에이전트를 사용하여 코드와 구현이 아키텍처 결정 레코드에 따라 구현되는지 확인하는 것을 의미합니다","es":"La validación de cumplimiento de ADR es el proceso de verificación de que el código PR se ajusta a los Registros de Decisiones de Arquitectura","fr":"La validation de conformité ADR est le processus de vérification que le code PR est conforme aux Registres de Décisions d''Architecture","de":"Die Validierung der ADR-Konformität ist der Prozess der Überprüfung, ob der PR-Code den Architecture Decision Records entspricht","pt":"Validação de conformidade ADR é o processo de verificar se o código PR atende aos Registros de Decisões de Arquitetura","ru":"Проверка соответствия ADR - это процесс проверки кода PR на соответствие Архитектурным Решениям","ar":"التحقق من مطابقة السجلات القرارية للبنية التحتية هو عملية التحقق من مطابقة код PR للقرارات المعمارية"},"features":{"en":["Validates PR code against Architecture Decision Records (ADRs) stored under `doc`","Uses oracle for deep analysis of implementation compliance","Checks code changes for alignment with documented architectural decisions","Reviews implementation details against ADR specifications","Identifies deviations from accepted architecture"],"zh":["使用Oracle进行深入分析","验证PR代码与ADR文档的合规性","检查代码变更与架构决策记录的对齐性","识别架构决策记录的偏差"],"ja":["Oracleを使用した深入分析","PRコードとADR文書のコンプライアンスを検証する","コード変更とアーキテクチャ設計レコードの整合性を確認する","アーキテクチャ設計レコードからの偏差を特定する"],"ko":["Oracle을 사용한 심층 분석","PR 코드와 ADR 문서의 규정 준수를 검증합니다","코드 변경과 아키텍처 결정 레코드의 일관성을 확인합니다","아키텍처 결정 레코드의 편차를 식별합니다"],"es":["Análisis profundo de la implementación utilizando oráculos","Verificación de la implementación de decisiones arquitectónicas","Detección de desviaciones de la arquitectura aceptada","Almacenamiento de ADRs en la ubicación `doc`","Verificación de la implementación correcta de los ADRs en el código PR"],"fr":["Analyse approfondie de la mise en œuvre à l''aide d''oracles","Vérification de la mise en œuvre des décisions d''architecture","Détection des écarts par rapport à l''architecture acceptée","Stockage des ADRs à l''emplacement `doc`","Vérification de la mise en œuvre correcte des ADRs dans le code PR"],"de":["Tiefe Analyse der Implementierung mithilfe von Orakeln","Überprüfung der Umsetzung von Architekturentscheidungen","Erkennung von Abweichungen von der akzeptierten Architektur","Speicherung von ADRs im Speicherort `doc`","Überprüfung der korrekten Umsetzung von ADRs im PR-Code"],"pt":["Análise profunda da implementação com oracle","Verificação da conformidade do código PR com Registros de Decisões de Arquitetura","Identificação de desvios da arquitetura aceita","Revisão de detalhes de implementação contra especificações ADR","Uso de CLI para automação de tarefas"],"ru":["Глубокий анализ реализации с помощью oracle","Проверка соответствия кода PR Архитектурным Решениям","Определение отклонений от принятой архитектуры","Проверка деталей реализации против спецификаций ADR","Использование CLI для автоматизации задач"],"ar":["التحليل العميق للتنفيذ باستخدام أوراكل","التحقق من مطابقة kod PR للقرارات المعمارية","تحديد الانحرافات عن البنية التحتية المقبولة","مراجعة تفاصيل التنفيذ مقابل مواصفات ADR","استخدام CLI لتسريع المهام"]},"keywords":{"en":["how to use validating-adr-compliance","validating-adr-compliance setup guide","ADR compliance validation","validating-adr-compliance alternative","validating-adr-compliance vs architecture analysis tools","validating-adr-compliance install","what is validating-adr-compliance","validating-adr-compliance for AI agents","Architecture Decision Records compliance"],"zh":["ADR合规性验证","AIエージェント","代码审查","架构决策记录","Oracle","自动化验证"],"ja":["ADRコンプライアンス検証","AIエージェント","コードレビュー","アーキテクチャ設計レコード","Oracle","自動検証"],"ko":["ADR 규정 준수 검증","AI 에이전트","코드 리뷰","아키텍처 결정 레코드","Oracle","자동 검증"],"es":["validación de cumplimiento de ADR","Registros de Decisiones de Arquitectura","análisis de implementación","oráculos","desarrollo de software","herramientas de desarrollo","AI Agentes","validación de código"],"fr":["validation de conformité ADR","Registres de Décisions d''Architecture","analyse de mise en œuvre","oracles","développement de logiciels","outils de développement","Outils d''Intelligence Artificielle","validation de code"],"de":["Validierung der ADR-Konformität","Architecture Decision Records","Implementierungsanalyse","Orakel","Softwareentwicklung","Entwicklungstools","Künstliche Intelligenz Tools","Codevalidierung"],"pt":["validação de conformidade ADR","Registros de Decisões de Arquitetura","ferramentas de IA para desenvolvimento","análise de código","automatização de tarefas","desenvolvimento de software","arquitetura de software"],"ru":["проверка соответствия ADR","Архитектурные Решения","ИИ Агенты для разработки","анализ кода","автоматизация задач","разработка программного обеспечения","архитектура программного обеспечения"],"ar":["التحقق من مطابقة السجلات القرارية للبنية التحتية","القرارات المعمارية","أدوات الذكاء الاصطناعي للبرمجة","تحليل الكود","تسريع المهام","تطوير البرمجيات","هندسة البرمجيات"]}},"owner":"axiomhq","repo":"validating-adr-compliance","repoPath":"axiomhq/validating-adr-compliance","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.330Z","topics":[],"category":"community","skillMd":{"name":"validating-adr-compliance","description":"Validates PR code against Architecture Decision Records (ADRs). Uses oracle for deep analysis of implementation compliance. Use when asked to validate a PR against an ADR, check ADR compliance, or review implementation adherence to architectural decisions.","bodyPreview":"# Validating ADR Compliance\n\nValidates that PR code and related implementations adhere to Architecture Decision Records.\n\n## When to Use\n\n- Validating a PR implements an ADR correctly\n- Checking if code changes align with documented architectural decisions\n- Reviewing implementation details against ADR specifications\n- Identifying deviations from accepted architecture\n\n## Preconditions & Assumptions\n\nBefore starting, confirm these assumptions hold:\n\n- **ADR location**: ADRs are stored under `doc","body":"# Validating ADR Compliance\n\nValidates that PR code and related implementations adhere to Architecture Decision Records.\n\n## When to Use\n\n- Validating a PR implements an ADR correctly\n- Checking if code changes align with documented architectural decisions\n- Reviewing implementation details against ADR specifications\n- Identifying deviations from accepted architecture\n\n## Preconditions & Assumptions\n\nBefore starting, confirm these assumptions hold:\n\n- **ADR location**: ADRs are stored under `doc/adr/` by default. Adjust if the repo uses a different path.\n- **Base branch**: The default comparison branch is `main` (or `origin/main`). Adjust for repos using `master` or another base.\n- **PR context**: This skill is optimized for validating a specific PR/branch vs its base.\n\nIf assumptions don''t hold, the user must provide:\n- The ADR ID or file path\n- The set of implementation files or modules to review\n\n## Workflow\n\n### Step 1: Identify the ADR\n\n**Default behavior**: Automatically detect ADRs added/modified in the current PR.\n\nRun this command to find ADRs changed in the current branch:\n```bash\ngit diff --name-only origin/main...HEAD -- doc/adr/\n```\n\nIf no ADRs found in the diff, try with `main`:\n```bash\ngit diff --name-only main...HEAD -- doc/adr/\n```\n\nUse the repository''s default branch as the base for diffs (commonly `main` or `master`). Adjust the git commands accordingly.\n\n#### Handling Multiple ADRs\n\nIf multiple ADRs are added/modified in the PR, treat each ADR separately:\n\n- Build a separate requirements checklist per ADR\n- Map implementation files to each ADR where possible\n- Produce one compliance report per ADR\n\n#### Check ADR Status\n\nWhen reading the ADR, note its **Status**:\n\n- **Accepted**: Enforce compliance—this is the primary case\n- **Superseded**: Identify the superseding ADR and validate against that instead\n- **Proposed/Draft**: Treat findings as advisory—decision is not final\n- **Deprecated**: Do not enforce; explain this ADR should not be validated\n\nIf the ADR has a `Supersedes` or `Superseded by` field, always prefer the latest ADR in the chain for compliance checks.\n\n#### Fallback Options\n\nIf no ADR in PR diff:\n\n1. User provides the ADR number (e.g., \"ADR-0052\")\n2. User references a specific ADR file\n3. Search `doc/adr/` for relevant ADRs based on PR topic keywords\n\nIf multiple candidate ADRs appear relevant based on keywords or status, present the top candidates and ask the user to confirm which ADR(s) to validate against.\n\n#### No ADR Found\n\nIf no relevant ADR is found:\n\n- Report explicitly: \"No applicable ADR identified for this PR based on doc/adr/ and provided inputs.\"\n- Ask the user to provide a specific ADR ID or confirm that no ADR validation is required\n- Do NOT fabricate compliance concerns\n\nOnce identified, read the full ADR:\n```\nRead doc/adr/XXXX-<name>.md\n```\n\n### Step 2: Extract ADR Requirements\n\nParse the ADR and extract a structured requirements table:\n\n| ID | Type | Description | Source (ADR quote/section) | Verifiability |\n|----|------|-------------|---------------------------|---------------|\n| ADR-XXXX-R1 | API | Endpoint must exist at /path | \"Decision – We add...\" | Strict |\n| ADR-XXXX-R2 | Security | Header X-Org-Id required | \"API: All requests MUST...\" | Strict |\n| ADR-XXXX-R3 | Performance | Call must be rate limited | \"Consequences – expensive...\" | Heuristic |\n\n**Requirement types**: Functional / API / Data / Performance / Security / Observability / Operational / Other\n\n**Verifiability levels**:\n- **Strict**: Exactly testable in code\n- **Heuristic**: Approximate, requires judgment\n- **Non-verifiable**: Documentation/assumption only—cannot assert from code\n\nFor vague high-level statements (e.g., \"should scale well\"), still record them but mark as `Heuristic` or `Non-verifiable`. Treat these separately from strict requirements in the report.\n\n### Step 3: Identify Implementation Files\n\nFind all code related to the ADR implementation, starting narrow and expanding as needed:\n\n#### Start from PR Diff\n\n1. List all files changed in the PR\n2. Filter to files likely related to the ADR by:\n   - Matching ADR title keywords, endpoint paths, or key terms\n   - File location (service/module that owns the feature)\n\n#### Expand if Necessary\n\nOnly if needed, broaden search beyond PR files:\n\n- Use `finder` to locate implementations based on ADR keywords\n- Use `Grep` for specific API endpoints, struct names, or patterns\n- Include supporting modules that PR files depend on if behavior is non-local\n\n#### Check All Artifact Types\n\nCheck for all implementation artifacts, not just application code:\n\n- API/router handlers\n- Domain/service logic\n- Configuration and feature flags\n- Infrastructure-as-code or deployment configs\n- Documentation and API specs (if ADR requires them)\n- Test files (unit, integration, e2e)\n\n#### Monorepo Hint\n\nIn monorepos, narrow search to the service or package that owns the ADR''s domain before broadening to the whole repo.\n\n### Step 4: Deep Analysis with Oracle\n\n**CRITICAL**: Use the oracle tool for the compliance analysis. This is a complex research task requiring expert reasoning.\n\nCall the oracle with:\n- **task**: \"Validate implementation compliance against ADR\"\n- **context**: Include:\n  - The full ADR text\n  - The structured requirements table from Step 2\n  - List of implementation files found\n- **files**: All relevant implementation files (as JSON array)\n\n#### Oracle Prompt Template\n\n```\nTask: Validate that the implementation in these files correctly adheres to ADR-XXXX (<title>)\n\nContext:\nADR-XXXX specifies:\n[Paste structured requirements table here]\n\nPlease:\n1. For each requirement in the table, determine:\n   - Status: PASS / FAIL / UNKNOWN\n   - Evidence: file path(s) and line number(s)\n   - Reasoning: brief justification (1–3 sentences)\n\n2. Highlight any potential conflicts with other ADRs (if visible).\n\n3. Identify any tests that validate or should validate these requirements.\n\n4. Explicitly call out any requirements that cannot be verified with the provided files (mark as UNKNOWN).\n\nFiles: [\"path/to/handler.rs\", \"path/to/types.rs\", \"path/to/tests.rs\"]\n```\n\n#### Handling Large Files\n\nIf implementation files are large:\n\n- Prefer including only the relevant sections (handlers, functions, types) instead of entire files\n- If you must split files, clearly label chunks (e.g., `handler.rs [lines 1–200]`)\n- Ensure each code snippet is accompanied by its file path and line range for traceability\n\n### Step 5: Report Findings\n\nStructure the compliance report:\n\n```markdown\n## ADR Compliance Report: ADR-XXXX\n\n### Summary\n[COMPLIANT / PARTIAL / NON-COMPLIANT]\n\n### Requirements Checklist\n- [ ] ADR-XXXX-R1 – [PASS/FAIL/UNKNOWN] – Evidence: [file:line or \"Not found\"]\n- [ ] ADR-XXXX-R2 – [PASS/FAIL/UNKNOWN] – Evidence: [file:line]\n...\n\n### Deviations Found\n1. **[Deviation]**: Description\n   - Expected: (from ADR)\n   - Actual: (in code)\n   - File: [link to file:line]\n   - Severity: [Critical/Major/Minor]\n\n### Assumptions & Limitations\n- List any assumptions made (e.g., \"Assume auth middleware enforces header globally\")\n- Note any missing context or code that prevented full verification\n\n### Recommendations\n- Actionable fixes for any deviations\n\n### Files Reviewed\n- [List of all files analyzed with links]\n```\n\n#### Result States\n\n- **PASS**: Requirement is demonstrably satisfied with evidence\n- **FAIL**: Requirement is violated or missing\n- **UNKNOWN**: Requirement cannot be verified from provided code (config not present, depends on external systems, ADR too vague)\n\n#### Severity Definitions\n\n- **Critical**: Violates core decision or breaks contract (API shape, required fields, major constraints)\n- **Major**: Violates important but non-fatal aspects (performance safeguards, logging, observability)\n- **Minor**: Style, minor deviations, or missing documentation that do not change core behavior\n\n## Edge Cases & Failure Modes\n\n### Partial Implementation PRs\n\nIf the PR intentionally implements only part of an ADR:\n\n- Note this in the summary: \"Partial implementation of ADR-XXXX per PR scope.\"\n- Mark unimplemented requirements as `NOT-IN-SCOPE` (if user confirms) or `UNKNOWN`\n\n### Contradictory ADRs\n\nIf a requirement appears to conflict with another ADR:\n\n- Call this out in \"Deviations Found\" as an **Architectural Conflict**\n- Recommend reconciling the ADRs rather than the implementation alone\n\n### Superseded or Deprecated ADRs\n\n- **Superseded**: Validate against the superseding ADR instead\n- **Deprecated**: Do not enforce; treat analysis as historical/contextual only\n\n## ADR Location\n\nADRs are stored in: `doc/adr/`\n\nFormat: `XXXX-<short-name>.md` (e.g., `0052-metrics-lookup-for-tag-values.md`)\n\n## ADR Structure Reference\n\nEach ADR typically contains:\n\n- **Title**: `# N. <decision title>`\n- **Date**: When the decision was made\n- **Status**: Proposed, Accepted, Deprecated, Superseded\n- **Supersedes/Superseded by**: References to related ADRs (if any)\n- **Context**: Problem and constraints\n- **Decision**: The architectural choice\n- **Consequences**: Trade-offs and outcomes\n\n## Tips for Effective Validation\n\n1. **Be Literal**: Check exact API paths, field names, types\n2. **Check Edge Cases**: ADRs often mention error handling or limitations\n3. **Verify Consequences**: If ADR says \"expensive call\", look for rate limiting/guards\n4. **Test Coverage**: Verify tests exist for ADR requirements\n5. **Look for Superseded ADRs**: An ADR may update a previous decision\n6. **Scope to PR First**: Start narrow from the diff, expand only as needed\n7. **Use UNKNOWN Honestly**: Don''t claim PASS without evidence; don''t claim FAIL without proof\n"},"lastSynced":"2026-03-08T02:03:10.548Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring precise Architecture Decision Records validation and compliance checks","zh":"适用于需要精确架构决策记录验证和合规性检查的代码审查代理","ja":"コードレビューエージェントが正確なアーキテクチャ決定レコードの検証とコンプライアンスチェックを必要とする場合に最適","ko":"코드 리뷰 에이전트가 정확한 아키텍처 결정 기록 검증 및 규정 준수 확인을 필요로 할 때 적합","es":"Ideal para Agentes de Revisión de Código que requieren una validación precisa de Registros de Decisiones de Arquitectura y controles de cumplimiento","fr":"Idéal pour les Agents de Révision de Code nécessitant une validation précise des Enregistrements de Décision d''Architecture et des contrôles de conformité","de":"Ideal für Code-Review-Agents, die eine präzise Validierung von Architektur-Entscheidungsprotokollen und Konformitätsprüfungen erfordern","pt":"Ideal para Agentes de Revisão de Código que exigem validação precisa de Registros de Decisões de Arquitetura e verificações de conformidade","ru":"Идеально подходит для агентов проверки кода, требующих точной проверки записей об архитектурных решениях и проверок соответствия","ar":"مثالي لعميل مراجعة الكود الذي يتطلب التحقق الدقيق من سجلات قرارات الهندسة المعمارية والتحقق من الامتثال"},"recommendation":{"en":"Empowers agents to validate PR code against Architecture Decision Records, ensuring adherence to documented architectural decisions using ADR specifications and protocol checks, and identifies deviations from accepted architecture","zh":"赋予代理验证PR代码与架构决策记录的能力，确保遵守记录的架构决策使用ADR规范和协议检查，并找出与接受的架构的偏差","ja":"エージェントがPRコードをアーキテクチャ決定レコードに対して検証する能力を付与し、ADR仕様とプロトコルチェックを使用して文書化されたアーキテクチャ決定への遵守を確保し、受け入れられたアーキテクチャからの偏差を特定する","ko":"에이전트가 PR 코드를 아키텍처 결정 기록에 대해 검증할 수 있는 기능을 부여하여 ADR 사양 및 프로토콜 검사를 사용하여 문서화된 아키텍처 결정에 대한 준수를 보장하고 수락된 아키텍처에서 발생하는 편차를 식별","es":"Habilita a los agentes a validar el código de las solicitudes de extracción contra los Registros de Decisiones de Arquitectura, asegurando el cumplimiento de las decisiones arquitectónicas documentadas utilizando especificaciones y protocolos de comprobación de ADR, e identifica desviaciones de la arquitectura aceptada","fr":"Permet aux agents de valider le code des demandes d''extraction contre les Enregistrements de Décision d''Architecture, en garantissant le respect des décisions architecturales documentées en utilisant les spécifications et les protocoles de vérification de l''ADR, et identifie les écarts par rapport à l''architecture acceptée","de":"Ermächtigt Agenten, den Code von Pull-Requests gegen Architektur-Entscheidungsprotokolle zu validieren, um die Einhaltung dokumentierter Architektur-Entscheidungen unter Verwendung von ADR-Spezifikationen und Protokollprüfungen sicherzustellen und Abweichungen von der akzeptierten Architektur zu identifizieren","pt":"Habilita os agentes a validar o código de PR contra Registros de Decisões de Arquitetura, garantindo a adesão às decisões arquiteturais documentadas usando especificações ADR e verificações de protocolo, e identifica desvios da arquitetura aceita","ru":"Наделяет агентов возможностью проверять код PR против записей об архитектурных решениях, обеспечивая соблюдение задокументированных архитектурных решений с помощью спецификаций ADR и проверок протокола, и выявляет отклонения от принятой архитектуры","ar":"يتمكن العميل من التحقق من 코드 PR مقابل سجلات قرارات الهندسة المعمارية، وضمان الالتزام بالقرارات الهندسية المعمارية الموثقة باستخدام مواصفات ADR والتحقق من بروتوكولها، وتحديد الانحرافات عن الهندسة المعمارية المقبولة"},"useCases":{"en":["Validating pull requests against ADRs for compliance","Checking code changes for alignment with documented architectural decisions","Reviewing implementation details against ADR specifications","Identifying deviations from accepted architecture in code reviews"],"zh":["验证拉取请求与ADR的合规性","检查代码更改是否与记录的架构决策一致","审查实现细节是否与ADR规范一致","在代码审查中找出与接受的架构的偏差"],"ja":["ADRとのコンプライアンスに対するプルリクエストの検証","コード変更が文書化されたアーキテクチャ決定と一致するかどうかの確認","実装詳細がADR仕様と一致するかどうかの確認","コードレビューで受け入れられたアーキテクチャからの偏差を特定"],"ko":["ADR와의 규정 준수에 대한 풀 리퀘스트 검증","코드 변경이 문서화된 아키텍처 결정과 일치하는지 확인","구현 세부 정보가 ADR 사양과 일치하는지 확인","코드 리뷰에서 수락된 아키텍처에서 발생하는 편차를 식별"],"es":["Validar solicitudes de extracción contra ADR para cumplimiento","Comprobar los cambios de código para la alineación con las decisiones arquitectónicas documentadas","Revisar los detalles de implementación contra las especificaciones de ADR","Identificar desviaciones de la arquitectura aceptada en las revisiones de código"],"fr":["Valider les demandes d''extraction contre les ADR pour la conformité","Vérifier les modifications de code pour l''alignement sur les décisions architecturales documentées","Réviser les détails d''implémentation contre les spécifications de l''ADR","Identifier les écarts par rapport à l''architecture acceptée lors de la révision de code"],"de":["Überprüfen von Pull-Requests gegen Architektur-Entscheidungsprotokolle für Konformität","Prüfen von Code-Änderungen auf Übereinstimmung mit dokumentierten Architektur-Entscheidungen","Überprüfen von Implementierungsdetails gegen ADR-Spezifikationen","Identifizieren von Abweichungen von der akzeptierten Architektur bei Code-Reviews"],"pt":["Validar solicitações de pull contra ADRs para conformidade","Verificar alterações de código para alinhamento com decisões arquiteturais documentadas","Revisar detalhes de implementação contra especificações ADR","Identificar desvios da arquitetura aceita em revisões de código"],"ru":["Проверять запросы на включение против записей об архитектурных решениях для соответствия","Проверять изменения кода на соответствие задокументированным архитектурным решениям","Просматривать детали реализации против спецификаций ADR","Выявлять отклонения от принятой архитектуры при проверке кода"],"ar":["التحقق من الطلبات السحابية مقابل سجلات قرارات الهندسة المعمارية للامتثال","التحقق من تغييرات الكود للتوجيه مع القرارات الهندسية المعمارية الموثقة","مراجعة تفاصيل التنفيذ مقابل مواصفات ADR","التحديد الانحرافات عن الهندسة المعمارية المقبولة في مراجعات الكود"]},"limitations":{"en":["Requires ADRs to be stored under a specific directory (e.g., `doc`)","Assumes PR code and related implementations are accessible for analysis"],"zh":["需要ADR存储在特定目录下（例如，`doc`）","假设PR代码和相关实现可用于分析"],"ja":["ADRを特定のディレクトリ（例：`doc`）に格納する必要がある","PRコードと関連する実装が分析のためにアクセス可能であることを前提とする"],"ko":["ADR를 특정 디렉토리 (`doc` 등) 아래에 저장해야 함","PR 코드 및 관련 구현이 분석을 위해 접근 가능하다고 가정"],"es":["Requiere que los ADR estén almacenados en un directorio específico (por ejemplo, `doc`)","Supone que el código de la solicitud de extracción y las implementaciones relacionadas estén accesibles para el análisis"],"fr":["Exige que les ADR soient stockés dans un répertoire spécifique (par exemple, `doc`)","Suppose que le code de la demande d''extraction et les implémentations associées soient accessibles pour l''analyse"],"de":["Erfordert, dass ADR in einem bestimmten Verzeichnis (z. B. `doc`) gespeichert werden","Geht davon aus, dass der Code des Pull-Requests und die damit verbundenen Implementierungen für die Analyse zugänglich sind"],"pt":["Exige que os ADRs sejam armazenados em um diretório específico (por exemplo, `doc`)","Pressupõe que o código PR e as implementações relacionadas estejam acessíveis para análise"],"ru":["Требует, чтобы записи об архитектурных решениях хранились в определенном каталоге (например, `doc`)","Предполагает, что код PR и связанные с ним реализации доступны для анализа"],"ar":["يتطلب أن يتم تخزين سجلات قرارات الهندسة المعمارية في دليل محدد (على سبيل المثال، `doc`)","يفترض أن الكود PR والتنفيذات المرتبطة به متاحان للتحليل"]},"version":4},"contentHash":"85697f527217e0b293668d59f9329249fe7172d6d84e7fb89aa506689721430b","qualityScore":60}');
