INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('axiomhq/validating-adr-compliance/validating-adr-compliance', 'validating-adr-compliance', 'axiomhq', 'validating-adr-compliance', 'community', 'validating-adr-compliance axiomhq validating-adr-compliance community The validating-adr-compliance skill validates PR code against Architecture Decision Records, ensuring implementations adhere to documented architectural decisions, benefiting developers and architects. 验证ADR合规性，确保代码和实现符合架构决策记录 ADRコンプライアンスを検証し、コードと実装がアーキテクチャ設計レコードに準拠していることを確認する ADR 규정 준수를 검증하여 코드와 구현이 아키텍처 결정 레코드에 따라 구현되는지 확인합니다 Valida el código PR contra ADRs y verifica la implementación de decisiones arquitectónicas Validez le code PR contre les ADRs et vérifiez la mise en œuvre des décisions d''architecture Überprüfen Sie den PR-Code gegen ADRs und validieren Sie die Umsetzung von Architekturentscheidungen Valida o código PR contra Registros de Decisões de Arquitetura para garantir a conformidade Проверяет код PR на соответствие Архитектурным Решениям يحقق في مطابقة код PR للقرارات المعمارية how to use validating-adr-compliance validating-adr-compliance setup guide ADR compliance validation validating-adr-compliance alternative validating-adr-compliance vs architecture analysis tools validating-adr-compliance install what is validating-adr-compliance validating-adr-compliance for AI agents Architecture Decision Records compliance ADR合规性验证 AIエージェント 代码审查 架构决策记录 Oracle 自动化验证 Validates PR code against Architecture Decision Records (ADRs) stored under `doc` Uses oracle for deep analysis of implementation compliance Checks code changes for alignment with documented architectural decisions Reviews implementation details against ADR specifications Identifies deviations from accepted architecture validating-adr-compliance is a skill that checks PR code and related implementations against Architecture Decision Records for compliance, using oracle for deep analysis.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dermatologist/dhti/start-dhti', 'community', 'dermatologist', 'dhti', 'dermatologist/dhti', 'start-dhti', 0, 0, 60, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:21.679Z', '78f7a58826637ca0be4b3192042bcf1e8e226d87acadb37523bc44243e5c33d9', '{"id":"dermatologist/dhti/start-dhti","name":"start-dhti","description":{"en":"The start-dhti skill enables developers to rapidly prototype GenAI healthcare applications with backend and frontend components, utilizing Node.js and Docker for efficient development.","zh":"start-dhti 是一个用于 Gen AI 医疗应用的参考架构和技能平台，用于快速搭建和测试应用","ja":"start-dhti は Gen AI ヘルスケアアプリケーションのための参考アーキテクチャとスキルプラットフォームであり、迅速なプロトタイピングとテストに使用される","ko":"start-dhti는 Gen AI 의료 애플리케이션을 위한 참조 아키텍처 및 스킬 플랫폼으로 빠른 프로토 타이핑 및 테스트에 사용","es":"start-dhti es una arquitectura de referencia para Gen AI en salud que permite a los desarrolladores crear aplicaciones de salud con tecnologías de vanguardia","fr":"start-dhti est une architecture de référence pour la Gen AI dans le domaine de la santé qui permet aux développeurs de créer des applications de santé avec des technologies de pointe","de":"start-dhti ist eine Referenzarchitektur für Gen AI im Gesundheitswesen, die es Entwicklern ermöglicht, Gesundheitsanwendungen mit SpitzenTechnologien zu erstellen","pt":"O start-dhti é uma plataforma de habilidades para codificação de vibração e arquitetura de referência para Inteligência Artificial na saúde.","ru":"Start-dhti - это платформа навыков для вибро-кодирования и эталонная архитектура для ИИ в здравоохранении.","ar":"start-dhti هو منصة لمهارات البرمجة السريعة وتقنية مرجعية للذكاء الاصطناعي في مجال الرعاية الصحية."},"seo":{"title":{"en":"start-dhti: Rapid GenAI Healthcare Prototyping Setup Guid...","zh":"start-dhti 安装指南：快速搭建 Gen AI 医疗应用","ja":"start-dhti セットアップガイド：Gen AI ヘルスケアアプリケーションの迅速なプロトタイピング","ko":"start-dhti 설정 가이드: Gen AI 의료 애플리케이션 빠른 프로토 타이핑","es":"Configuración de start-dhti: Guía de inicio para desarrol...","fr":"Mise en route de start-dhti : Guide de démarrage pour les...","de":"Start-dhti-Setup: Einrichtungsleitfaden für Entwickler vo...","pt":"Guia de Configuração do start-dhti para Desenvolvedores","ru":"Настройка start-dhti: Руководство для разработчиков ИИ Аг...","ar":"دليل إعداد start-dhti للبرمجة السريعة مع أدوات الذكاء الا..."},"description":{"en":"Unlock efficient GenAI healthcare app development with start-dhti - discover how to set up a fully functional DHTI server and start prototyping today!","zh":"使用 start-dhti 技能快速搭建 Gen AI 医疗应用，包括安装 elixirs 和 conches，以及设置 DHTI 开发服务器","ja":"start-dhti スキルを使用して Gen AI ヘルスケアアプリケーションを迅速にプロトタイピングし、elixirs と conches のインストール、DHTI 開発サーバーの設定を行う","ko":"start-dhti 스킬을 사용하여 Gen AI 의료 애플리케이션을 빠르게 프로토 타이핑하고 elixirs 및 conches 설치, DHTI 개발 서버 설정","es":"Aprende a configurar start-dhti para desarrollar aplicaciones de Gen AI en salud con Node.js, Docker y Docker Compose","fr":"Découvrez comment configurer start-dhti pour développer des applications de Gen AI en santé avec Node.js, Docker et Docker Compose","de":"Erfahren Sie, wie Sie start-dhti einrichten, um Gen-AI-Gesundheitsanwendungen mit Node.js, Docker und Docker Compose zu entwickeln","pt":"Aprenda a configurar o start-dhti para prototipagem rápida de aplicações de saúde com Inteligência Artificial","ru":"Узнайте, как настроить start-dhti для быстрого прототипирования приложений здравоохранения с ИИ Агентами","ar":"اكتشف كيفية إعداد start-dhti لبرمجة سريعة لتطبيقات الرعاية الصحية مع أدوات الذكاء الاصطناعي"},"definition":{"en":"start-dhti is a reference architecture for Gen AI in healthcare and a skill platform for vibe coding, facilitating the installation of elixirs and conches for testing and prototyping.","zh":"start-dhti 是一个用于快速搭建和测试 Gen AI 医疗应用的技能平台","ja":"start-dhti は Gen AI ヘルスケアアプリケーションのためのスキルプラットフォームであり、迅速なプロトタイピングとテストに使用される","ko":"start-dhti는 Gen AI 의료 애플리케이션을 위한 스킬 플랫폼으로 빠른 프로토 타이핑 및 테스트에 사용","es":"start-dhti es una plataforma de habilidades para el desarrollo de aplicaciones de Gen AI en salud","fr":"start-dhti est une plateforme de compétences pour le développement d''applications de Gen AI dans le domaine de la santé","de":"start-dhti ist eine Skill-Plattform für die Entwicklung von Gen-AI-Gesundheitsanwendungen","pt":"O start-dhti é uma plataforma de habilidades para desenvolvedores que necessitam de prototipagem rápida de aplicações de saúde com Inteligência Artificial.","ru":"Start-dhti - это платформа навыков для разработчиков, которым необходима быстрая прототипизация приложений здравоохранения с ИИ.","ar":"start-dhti هو منصة لمهارات البرمجة السريعة لتطبيقات الرعاية الصحية مع أدوات الذكاء الاصطناعي للبرمجة السريعة."},"features":{"en":["Installs elixirs and conches created by other skills for seamless integration","Sets up a fully functional DHTI development server for testing and prototyping using Node.js and Docker","Rapidly prototypes GenAI healthcare applications with both backend and frontend components","Utilizes Docker and Docker Compose for efficient containerization and deployment","Requires Node.js (>= 18.0.0) for compatibility and optimal performance"],"zh":["安装 elixirs 和 conches","设置 DHTI 开发服务器","快速搭建 Gen AI 医疗应用","支持 Node.js (>= 18.0.0)","支持 Docker 和 Docker Compose","提供快速的应用测试和原型开发"],"ja":["elixirs と conches のインストール","DHTI 開発サーバーの設定","Gen AI ヘルスケアアプリケーションの迅速なプロトタイピング","Node.js (>= 18.0.0) のサポート","Docker と Docker Compose のサポート","迅速なアプリケーションのテストとプロトタイピング"],"ko":["elixirs 및 conches 설치","DHTI 개발 서버 설정","Gen AI 의료 애플리케이션 빠른 프로토 타이핑","Node.js (>= 18.0.0) 지원","Docker 및 Docker Compose 지원","빠른 애플리케이션 테스트 및 프로토 타이핑"],"es":["Instalación de elixires y conchas creadas por otras habilidades","Configuración de un servidor de desarrollo DHTI completo para pruebas y prototipos","Desarrollo rápido de aplicaciones de Gen AI en salud con componentes backend y frontend","Compatibilidad con Node.js (>= 18.0.0)","Integración con Docker y Docker Compose"],"fr":["Installation d''élixirs et de coquilles créés par d''autres compétences","Configuration d''un serveur de développement DHTI complet pour les tests et les prototypes","Développement rapide d''applications de Gen AI en santé avec des composants backend et frontend","Compatibilité avec Node.js (>= 18.0.0)","Intégration avec Docker et Docker Compose"],"de":["Installation von Elixiren und Muscheln, die von anderen Fähigkeiten erstellt wurden","Einrichtung eines vollständigen DHTI-Entwicklungsservers für Tests und Prototypen","Schnelle Entwicklung von Gen-AI-Gesundheitsanwendungen mit Backend- und Frontend-Komponenten","Kompatibilität mit Node.js (>= 18.0.0)","Integration mit Docker und Docker Compose"],"pt":["Instalação de elixires e conchas criados por outras habilidades","Configuração de um servidor de desenvolvimento DHTI completo para testes e prototipagem","Prototipagem rápida de aplicações de saúde com Inteligência Artificial com componentes backend e frontend","Requisitos de Node.js (>= 18.0.0) e Docker e Docker Compose","Espaço em disco suficiente para imagens Docker"],"ru":["Установка эликсиров и ракушек, созданных другими навыками","Настройка полноценного сервера разработки DHTI для тестирования и прототипирования","Быстрая прототипизация приложений здравоохранения с ИИ с компонентами backend и frontend","Требования к Node.js (>= 18.0.0) и Docker и Docker Compose","Достаточное место на диске для образов Docker"],"ar":["تثبيت المركبات والصواري التي أنشأها مهارات أخرى","إعداد خادم تطوير DHTI كامل للاختبارات والبرمجة السريعة","برمجة سريعة لتطبيقات الرعاية الصحية مع أدوات الذكاء الاصطناعي مع مكونات الخلفية والأمامية","متطلبات Node.js (>= 18.0.0) و Docker و Docker Compose","مساحة قرص كافية لصور Docker"]},"keywords":{"en":["how to use start-dhti","start-dhti setup guide","GenAI healthcare application development","DHTI development server","start-dhti alternative","start-dhti vs other GenAI platforms","installing start-dhti","start-dhti and Node.js","Docker for start-dhti deployment"],"zh":["start-dhti","Gen AI 医疗应用","elixirs","conches","DHTI 开发服务器","Node.js","Docker","Docker Compose","AIエージェント","医疗应用开发"],"ja":["start-dhti","Gen AI ヘルスケアアプリケーション","elixirs","conches","DHTI 開発サーバー","Node.js","Docker","Docker Compose","AIエージェント","ヘルスケアアプリケーション開発"],"ko":["start-dhti","Gen AI 의료 애플리케이션","elixirs","conches","DHTI 개발 서버","Node.js","Docker","Docker Compose","AI 에이전트","의료 애플리케이션 개발"],"es":["start-dhti","Gen AI en salud","desarrollo de aplicaciones de salud","Node.js","Docker","Docker Compose","elixires","conchas","servidor de desarrollo DHTI"],"fr":["start-dhti","Gen AI dans le domaine de la santé","développement d''applications de santé","Node.js","Docker","Docker Compose","élixirs","coquilles","serveur de développement DHTI"],"de":["start-dhti","Gen AI im Gesundheitswesen","Entwicklung von Gesundheitsanwendungen","Node.js","Docker","Docker Compose","Elixire","Muscheln","DHTI-Entwicklungsserver"],"pt":["start-dhti","Inteligência Artificial na saúde","prototipagem rápida","desenvolvimento de aplicações de saúde","Node.js","Docker","Docker Compose","elixires","conchas","servidor de desenvolvimento DHTI"],"ru":["start-dhti","ИИ в здравоохранении","быстрая прототипизация","разработка приложений здравоохранения","Node.js","Docker","Docker Compose","эликсир","ракушки","сервер разработки DHTI"],"ar":["start-dhti","الذكاء الاصطناعي في مجال الرعاية الصحية","البرمجة السريعة","تطوير تطبيقات الرعاية الصحية","Node.js","Docker","Docker Compose","المركبات","الصواري","خادم تطوير DHTI"]}},"owner":"dermatologist","repo":"dhti","repoPath":"dermatologist/dhti","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"start-dhti","description":"This skill enables AI agents to orchestrate the DHTI development workflow by installing elixirs and conches, and starting a fully functional DHTI server with all components installed using Docker.","bodyPreview":"## When to Use This Skill\n\nUse this skill when you need to:\n- Install elixirs and conches created by other skills\n- Set up a fully functional DHTI development server for testing and prototyping\n- Rapidly prototype GenAI healthcare applications with both backend and frontend components\n\n## Prerequisites\n\nBefore using this skill, ensure you have:\n- Node.js (>= 18.0.0) installed\n- Docker and Docker Compose installed and running\n- Sufficient disk space for Docker images\n\n## Instructions\nYou are a DH","body":"## When to Use This Skill\n\nUse this skill when you need to:\n- Install elixirs and conches created by other skills\n- Set up a fully functional DHTI development server for testing and prototyping\n- Rapidly prototype GenAI healthcare applications with both backend and frontend components\n\n## Prerequisites\n\nBefore using this skill, ensure you have:\n- Node.js (>= 18.0.0) installed\n- Docker and Docker Compose installed and running\n- Sufficient disk space for Docker images\n\n## Instructions\nYou are a DHTI orchestration agent working to create a complete GenAI healthcare application. Follow these instructions sequentially.\nThe user conversation may provide context on the work you have done in the past. Always internalize that and reuse it where possible.\n\n### Phase 1: Environment Setup\n\n1. **Verify Prerequisites:**\n   - Check that Node.js and Docker are installed\n   - Verify Docker is running: `docker ps`\n\n2. **Directory Structure**\n\n```\nworkspace/\n└── dhti-elixir/\n    └── packages/\n        └── <name>/                # Your generated elixir package\n            ├── notes/todo.md          # Your detailed TODO list and plan\n            ├── src/dhti_elixir_<name>/   # Main code for the elixir\n            │   ├── chain.py              # Main chain implementation\n            │   ├── bootstrap.py          # Bootstrap/configuration file\n            │   ├── README.md             # Documentation for your elixir\n            │   └── (other files, e.g., __init__.py, utils.py)\n            ├── pyproject.toml            # Add new dependencies here\n            └── tests/\n                └── test_chain.py         # Example test file for chain.py\n└── openmrs-esm-dhti/\n    └── packages/\n        └── esm-dhti-<name>/           # Your generated elixir package\n            ├── notes/todo.md          # Your detailed TODO list and plan\n            ├── src/   # Main code for the conch with multiple subdirectories.\n            ├── package.json          # Update dependencies and metadata here\n            └── README.md             # Documentation for your conch\n```\n\n### Phase 2: Set Up DHTI Infrastructure\n\n5. **Create Docker Compose Configuration:**\n   ```bash\n   npx dhti-cli compose add -m langserve\n   ```\n\n   This creates a Docker Compose configuration with:\n   - LangServe (GenAI backend)\n   - Other necessary infrastructure\n\n   Optionally add additional modules as needed:\n   - `-m ollama` for local LLM hosting\n   - `-m langfuse` for monitoring\n   - `-m redis` for vector store\n   - `-m neo4j` for graph utilities\n   - `-m cqlFhir` for CQL support\n   - `-m mcpFhir` for MCP server\n\n6. **Verify Compose Configuration:**\n   ```bash\n   npx dhti-cli compose read\n   ```\n\n### Phase 3: Install Elixir from Local Directory (If Applicable)\n\n7. **Install the Generated Elixir:**\n   - Install the elixir from `workspace` directory in the current path.\n   - If workspace directory does not exist, use the path provided in the original user prompt.\n   - Use the `-l` flag to specify the directory.\n   - Use -n flag with the elixir''s project name (starting with `dhti-elixir-`)\n\n   ```bash\n   npx dhti-cli elixir install -l <elixir-path> -n <elixir-name>\n   ```\n\n   Example:\n   ```bash\n   npx dhti-cli elixir install -l workspace/dhti-elixir/packages/glycemic_advisor -n glycemic_advisor\n   ```\n\n8. **Build Elixir Docker Image:**\n   ```bash\n   npx dhti-cli docker -n dhti/genai-test:1.0 -t elixir\n   ```\n\n   Replace `dhti` with your Docker Hub username or registry name if available from the original user prompt.\n\n### Phase 4: Install Conch from Local Directory (If Applicable)\n\n9. **Install the Generated Conch:**\n   - Install the conch from `workspace` directory in the current path.\n   - If workspace directory does not exist, use the path provided in the original user prompt.\n   - Use the  `-l` flag to install the conch from the directory.\n   - Use -n flag with the conch''s project name (starting with `openmrs-esm-dhti-`)\n\n   ```bash\n   npx dhti-cli conch install -l <conch-path> -n <conch-name>\n   ```\n\n   Example:\n   ```bash\n   npx dhti-cli conch install -l workspace/openmrs-esm-dhti/packages/esm-glycemic-advisor -n esm-glycemic-advisor\n   ```\n\n### Hot Reload / Dev Sync (If Applicable)\n\nUse these commands to sync work-in-progress code/assets into running containers. This is ideal for UI tweaks and elixir logic changes that don''t alter dependencies.\n\n- Elixir dev sync\n\n```bash\nnpx dhti-cli elixir dev -d <<workspace>>/dhti-elixir/packages/<<elixir-name>> -n <<elixir-name>> -c dhti-langserve-1\n```\n\nNote: If dependencies change (e.g., `requirements.txt` or `pyproject.toml`), rebuild the image instead of using dev sync.\n\n- Conch dev sync\n\n```bash\nnpx dhti-cli conch dev -d <<workspace>>/openmrs-esm-dhti/packages/<<conch-name>> -n <<conch-name>> -c dhti-frontend-1\n```\n\nTip: Clear your browser cache if assets look stale after syncing.\n\n- Update runtime bootstrap\n\n```bash\nnpx dhti-cli docker bootstrap -f <<workspace>>/bootstrap.py -c dhti-langserve-1\n```\nWhen run for the first time, this command will copy the bootstrap file into the langserve container to workspace.\nSubsequent runs will sync changes from the local bootstrap file to the container, allowing you to update runtime configurations without rebuilding the image. This is especially useful for tweaking model settings, tool configurations, or other parameters defined in the bootstrap file during development.\n\n### Phase 5: Start DHTI Server\n\n11. **Start All Services:**\n    ```bash\n    npx dhti-cli docker -u\n    ```\n\n### Phase 6: Decide whether to use OpenMRS or CDS-Hooks container.\n\nIf a conch is installed, then you should use OpenMRS container to see the conch in action. If no conch is installed, you can choose to use CDS-Hooks container to test the elixir functionality.\n\n#### If using OpenMRS container:\n```\nnpx dhti-cli conch install # if you have not performed this step before.\nnpx dhti-cli conch start -s packages/<<conch-name>>\n```\n\nExample:\n```\nnpx dhti-cli conch install # if you have not performed this step before.\nnpx dhti-cli conch start -s packages/esm-chatbot-agent\n```\n\n   - Login to OpenMRS with at `http://localhost:8080/openmrs/spa/home`\n     - Username: `admin`\n     - Password: `Admin123`\n\nYou may include multiple conches with multiple -s flags to start them at the same time.\n\n12. **Wait for Services to Initialize:**\n    - Wait 2-3 minutes for all services to fully start\n    - Monitor logs: `docker compose logs -f`\n\n13. **Hand off with the following instructions:**\n    - Navigate to `http://localhost:8080/openmrs/spa/home`\n    - Login credentials:\n      - Username: `admin`\n      - Password: `Admin123`\n\n#### If using CDS-Hooks container:\n\n* First kill any running processes on port 8080 to free it up for CDS-Hooks container.\nThen start the CDS-Hooks container with the elixir.\n```\nnpx dhti-cli elixir start -n <<elixir-name>> &\n```\n\nExample:\n```\nnpx dhti-cli elixir start -n glycemic_advisor &\n```\n\nNOTE the `Application link` in the output rather than the final display link.\n\n12. **Wait for Services to Initialize:**\n   - Wait 2-3 minutes for all services to fully start\n   - Monitor logs: `docker compose logs -f`\n\n13. **Hand off with the following instructions:**\n   - Request the user to run `npx dhti-cli elixir start -n <<elixir-name>>` to start the CDS-Hooks container with the elixir.\n   - Display the `Application link`: <<application-link>>\n   - Request to open application link in browser to access it.\n\n### Phase 9: Clean Up (If Needed)\n\n18. **Cleanup Instructions:**\n    - Provide commands to stop and remove containers:\n      ```bash\n      npx dhti-cli docker -d\n      ```\n    - Document how to restart the server\n    - Explain how to rebuild images after changes\n\n### Development Mode (Optional)\n\n\n## Dry-Run Mode\n\nBefore making any changes, use the `--dry-run` flag to preview actions:\n\n```bash\nnpx dhti-cli compose add -m openmrs -m langserve --dry-run\nnpx dhti-cli elixir install -l <path> -n <name> --dry-run\nnpx dhti-cli conch install -l <path> -n <name> --dry-run\n```\n\n## Troubleshooting\n\nCommon issues and solutions:\n\n1. **Docker containers fail to start:**\n   - Check Docker is running: `docker ps`\n   - Verify port availability (80, 8080, 8000)\n   - Check Docker logs: `docker compose logs <service-name>`\n\n2. **Elixir installation fails:**\n   - Verify the path exists and is accessible\n   - Check that the elixir project structure is correct\n   - Ensure pyproject.toml exists in the elixir directory\n\n3. **Conch installation fails:**\n   - Verify the path exists and is accessible\n   - Check that routes.json exists in the conch directory\n   - Ensure the conch follows OpenMRS ESM structure\n\n4. **OpenMRS not accessible:**\n   - Wait longer for initialization (3-5 minutes)\n   - Check nginx gateway logs\n   - Verify all containers are running: `docker ps`\n\n## Notes\n\n- Always use dry-run mode first to verify commands\n- Generated projects can be version controlled and shared\n- Docker images can be pushed to registries for deployment\n- The skill creates a complete, production-ready DHTI application\n- The user conversation may provide context on the work you have done in the past. Always internalize that and reuse it where possible.\n\n"},"lastSynced":"2026-03-08T02:03:21.679Z","agentAnalysis":{"suitability":{"en":"Perfect for GenAI Healthcare Agents needing rapid prototyping of backend and frontend applications with Node.js and Docker","zh":"非常适合需要使用 Node.js 和 Docker 进行后端和前端应用程序快速原型设计的 GenAI 医疗代理","ja":"GenAI ヘルスケア エージェントが Node.js と Docker を使用してバックエンドとフロントエンドのアプリケーションを迅速にプロトタイプ化する必要がある場合に最適","ko":"Node.js와 Docker를 사용하여 백엔드 및 프론트엔드 애플리케이션을 빠르게 프로토 타입화해야 하는 GenAI 헬스케어 에이전트에 적합","es":"Perfecto para agentes de atención médica de GenAI que necesitan prototipado rápido de aplicaciones de backend y frontend con Node.js y Docker","fr":"Parfait pour les agents de soins de santé GenAI ayant besoin d''un prototypage rapide d''applications backend et frontend avec Node.js et Docker","de":"Perfekt für GenAI-Gesundheitsagenten, die ein schnelles Prototyping von Backend- und Frontend-Anwendungen mit Node.js und Docker benötigen","pt":"Perfeito para Agentes de Saúde GenAI que necessitam de prototipagem rápida de aplicações backend e frontend com Node.js e Docker","ru":"Идеально для агентов GenAI Healthcare, которым необходима быстрая прототипизация приложений backend и frontend с помощью Node.js и Docker","ar":"مثالي لعميل GenAI الصحي الذي يحتاج إلى إنشاء نموذج أولي سريع لتطبيقات الخلفية والأمامية باستخدام Node.js و Docker"},"recommendation":{"en":"Empowers agents to rapidly prototype GenAI healthcare applications with both backend and frontend components, utilizing Node.js and Docker for efficient development, and enabling the installation of elixirs and conches created by other skills","zh":"赋予代理快速原型化 GenAI 医疗应用程序的能力，具有后端和前端组件，利用 Node.js 和 Docker 进行高效开发，并允许安装由其他技能创建的 elixirs 和 conches","ja":"エージェントが Node.js と Docker を使用して効率的に開発を行い、他のスキルによって作成された elixirs と conches をインストールできるようにすることで、GenAI ヘルスケア アプリケーションを迅速にプロトタイプ化できるようにする","ko":"에이전트가 Node.js와 Docker를 사용하여 효율적으로 개발을 진행하고 다른 스킬에 의해 생성된 elixirs와 conches를 설치할 수 있도록 함으로써 GenAI 헬스케어 애플리케이션을 빠르게 프로토 타입화할 수 있는 능력을 부여","es":"Habilita a los agentes a prototipar rápidamente aplicaciones de atención médica de GenAI con componentes backend y frontend, utilizando Node.js y Docker para un desarrollo eficiente, y permitiendo la instalación de elixires y conchas creadas por otras habilidades","fr":"Permet aux agents de prototyper rapidement des applications de soins de santé GenAI avec des composants backend et frontend, en utilisant Node.js et Docker pour un développement efficace, et en permettant l''installation d''elixirs et de coquillages créés par d''autres compétences","de":"Ermöglicht es Agenten, GenAI-Gesundheitsanwendungen mit Backend- und Frontend-Komponenten schnell zu prototypen, indem sie Node.js und Docker für eine effiziente Entwicklung nutzen und die Installation von Elixiern und Muscheln ermöglichen, die von anderen Fähigkeiten erstellt wurden","pt":"Habilita os agentes a criar rapidamente aplicações de saúde GenAI com componentes backend e frontend, utilizando Node.js e Docker para desenvolvimento eficiente, e permitindo a instalação de elixires e conchas criados por outras habilidades","ru":"Позволяет агентам быстро создавать приложения для здравоохранения GenAI с компонентами backend и frontend, используя Node.js и Docker для эффективного развития, и позволяя устанавливать эликсиры и ракушки, созданные другими навыками","ar":"يعزز العملاء إنشاء تطبيقات صحية سريعة من GenAI مع مكونات خلفية وأمامية، باستخدام Node.js و Docker من أجل تنمية فعالة، وتمكين تثبيت المركبات والصواني التي أنشأها مهارات أخرى"},"useCases":{"en":["Installing elixirs and conches for customized healthcare applications","Setting up a fully functional DHTI development server for testing and prototyping","Rapidly prototyping GenAI healthcare applications with integrated backend and frontend components"],"zh":["为自定义医疗应用程序安装 elixirs 和 conches","设置一个完全功能的 DHTI 开发服务器用于测试和原型设计","使用集成的后端和前端组件快速原型化 GenAI 医疗应用程序"],"ja":["カスタム医療アプリケーション用の elixirs と conches をインストール","テストおよびプロトタイプ化用の完全に機能する DHTI 開発サーバーを設定","バックエンドとフロントエンドのコンポーネントを統合して GenAI 医療アプリケーションを迅速にプロトタイプ化"],"ko":["사용자 지정 의료 애플리케이션을 위한 elixirs 및 conches 설치","테스트 및 프로토 타입화용 완전한 기능을 갖춘 DHTI 개발 서버 설정","백엔드 및 프론트엔드 구성 요소를 통합하여 GenAI 헬스케어 애플리케이션을 빠르게 프로토 타입화"],"es":["Instalación de elixires y conchas para aplicaciones de atención médica personalizadas","Configuración de un servidor de desarrollo DHTI completamente funcional para pruebas y prototipado","Prototipado rápido de aplicaciones de atención médica de GenAI con componentes backend y frontend integrados"],"fr":["Installation d''elixirs et de coquillages pour des applications de soins de santé personnalisées","Configuration d''un serveur de développement DHTI entièrement fonctionnel pour les tests et le prototypage","Prototypage rapide d''applications de soins de santé GenAI avec des composants backend et frontend intégrés"],"de":["Installation von Elixiern und Muscheln für benutzerdefinierte Gesundheitsanwendungen","Einrichtung eines voll funktionsfähigen DHTI-Entwicklungsservers für Tests und Prototyping","Schnelles Prototyping von GenAI-Gesundheitsanwendungen mit integrierten Backend- und Frontend-Komponenten"],"pt":["Instalar elixires e conchas para aplicações de saúde personalizadas","Configurar um servidor de desenvolvimento DHTI totalmente funcional para testes e prototipagem","Criar rapidamente aplicações de saúde GenAI com componentes backend e frontend integrados"],"ru":["Установка эликсиров и ракушек для индивидуальных приложений здравоохранения","Настройка полностью функционального сервера разработки DHTI для тестирования и прототипизации","Быстрое создание приложений для здравоохранения GenAI с интегрированными компонентами backend и frontend"],"ar":["تثبيت المركبات والصواني لتطبيقات صحية مخصصة","ضبط خادم تطوير DHTI كامل الوظائف للاختبار وإنشاء النماذج الأولية","إنشاء سريع لتطبيقات صحية من GenAI مع مكونات خلفية وأمامية متكاملة"]},"limitations":{"en":["Requires Node.js (>= 18.0.0) installation","Docker and Docker Compose must be installed and running","Sufficient disk space for Docker images is necessary"],"zh":["需要安装 Node.js (>= 18.0.0)","Docker 和 Docker Compose 必须安装并运行","Docker 镜像需要足够的磁盘空间"],"ja":["Node.js (>= 18.0.0) のインストールが必要","Docker と Docker Compose がインストールされ、実行されている必要がある","Docker イメージに十分なディスク容量が必要"],"ko":["Node.js(>= 18.0.0) 설치 필요","Docker 및 Docker Compose 설치 및 실행 필요","Docker 이미지에 대한 충분한 디스크 공간 필요"],"es":["Se requiere la instalación de Node.js (>= 18.0.0)","Docker y Docker Compose deben estar instalados y en ejecución","Se requiere espacio en disco suficiente para imágenes de Docker"],"fr":["L''installation de Node.js (>= 18.0.0) est requise","Docker et Docker Compose doivent être installés et en cours d''exécution","Un espace disque suffisant pour les images Docker est nécessaire"],"de":["Die Installation von Node.js (>= 18.0.0) ist erforderlich","Docker und Docker Compose müssen installiert und ausgeführt werden","Ausreichend Festplattenspeicher für Docker-Images ist notwendig"],"pt":["Requer instalação do Node.js (>= 18.0.0)","Docker e Docker Compose devem ser instalados e em execução","Espaço em disco suficiente para imagens Docker é necessário"],"ru":["Требуется установка Node.js (>= 18.0.0)","Docker и Docker Compose должны быть установлены и запущены","Необходимо достаточное место на диске для образов Docker"],"ar":["يتطلب تثبيت Node.js (>= 18.0.0)","يجب تثبيت Docker و Docker Compose و تشغيلها","يتطلب مساحة قرص كافية لصور Docker"]},"version":4},"contentHash":"78f7a58826637ca0be4b3192042bcf1e8e226d87acadb37523bc44243e5c33d9","qualityScore":60}');
