INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dermatologist/dhti/start-dhti', 'start-dhti', 'dermatologist', 'dhti', 'community', 'start-dhti dermatologist dhti community The start-dhti skill enables developers to rapidly prototype GenAI healthcare applications with backend and frontend components, utilizing Node.js and Docker for efficient development. start-dhti 是一个用于 Gen AI 医疗应用的参考架构和技能平台，用于快速搭建和测试应用 start-dhti は Gen AI ヘルスケアアプリケーションのための参考アーキテクチャとスキルプラットフォームであり、迅速なプロトタイピングとテストに使用される start-dhti는 Gen AI 의료 애플리케이션을 위한 참조 아키텍처 및 스킬 플랫폼으로 빠른 프로토 타이핑 및 테스트에 사용 start-dhti es una arquitectura de referencia para Gen AI en salud que permite a los desarrolladores crear aplicaciones de salud con tecnologías de vanguardia start-dhti est une architecture de référence pour la Gen AI dans le domaine de la santé qui permet aux développeurs de créer des applications de santé avec des technologies de pointe start-dhti ist eine Referenzarchitektur für Gen AI im Gesundheitswesen, die es Entwicklern ermöglicht, Gesundheitsanwendungen mit SpitzenTechnologien zu erstellen O start-dhti é uma plataforma de habilidades para codificação de vibração e arquitetura de referência para Inteligência Artificial na saúde. Start-dhti - это платформа навыков для вибро-кодирования и эталонная архитектура для ИИ в здравоохранении. start-dhti هو منصة لمهارات البرمجة السريعة وتقنية مرجعية للذكاء الاصطناعي في مجال الرعاية الصحية. how to use start-dhti start-dhti setup guide GenAI healthcare application development DHTI development server start-dhti alternative start-dhti vs other GenAI platforms installing start-dhti start-dhti and Node.js Docker for start-dhti deployment start-dhti Gen AI 医疗应用 elixirs conches DHTI 开发服务器 Node.js Docker Docker Compose AIエージェント 医疗应用开发 Installs elixirs and conches created by other skills for seamless integration Sets up a fully functional DHTI development server for testing and prototyping using Node.js and Docker Rapidly prototypes GenAI healthcare applications with both backend and frontend components Utilizes Docker and Docker Compose for efficient containerization and deployment Requires Node.js (>= 18.0.0) for compatibility and optimal performance start-dhti is a reference architecture for Gen AI in healthcare and a skill platform for vibe coding, facilitating the installation of elixirs and conches for testing and prototyping.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('noviadi/agent-loop/writing-verify-script', 'community', 'noviadi', 'agent-loop', 'noviadi/agent-loop', 'writing-verify-script', 0, 0, 60, '2026-03-08T01:57:15.341Z', '2026-03-08T02:03:28.225Z', 'c2185471c0bb08ec288fbc301da6c038408197d106707259c7c82357765f9991', '{"id":"noviadi/agent-loop/writing-verify-script","name":"writing-verify-script","description":{"en":"The writing-verify-script skill creates a standardized entry point for project validation, providing a single command to run quality checks. It benefits developers by streamlining implementation planning.","zh":"创建 ./scripts/verify.sh 以运行所有质量检查，包括测试、linting、格式化和类型检查","ja":"検証スクリプトの作成方法を学び、テスト、linting、フォーマット、型チェックなどの品質チェックを実行する","ko":"검증 스크립트 작성 방법을 학습하고 테스트, linting, 형식화, 유형 확인 등을 실행합니다","es":"El script de verificación de proyecto es un punto de entrada estandarizado para la validación de proyectos, que ejecuta comprobaciones de calidad como tests, linting y verificación de tipos","fr":"Le script de vérification de projet est un point d''entrée standardisé pour la validation de projets, qui exécute des vérifications de qualité comme des tests, du linting et une vérification de types","de":"Das Projektverifizierungsskript ist ein standardisierter Einstiegspunkt für die Validierung von Projekten, der Qualitätsprüfungen wie Tests, Linting und Typüberprüfung ausführt","pt":"O writing-verify-script é uma ferramenta para criar scripts de verificação personalizados. Ele fornece uma forma padrão de executar testes, linting, formatação e verificação de tipo.","ru":"ИИ Агенты writing-verify-script - это инструмент для создания собственных скриптов проверки. Он предоставляет стандартный способ запуска тестов, линтинга, форматирования и проверки типов.","ar":"writing-verify-script هو أداة لإنشاء برامج نصية للتحقق المخصصة. يوفر طريقة قياسية لتشغيل الاختبارات والتنسيق والتحقق من النوع"},"seo":{"title":{"en":"writing-verify-script: Setup Guide for AI Agents | AI Age...","zh":"写入验证脚本Setup Guide - AIエージェント","ja":"検証スクリプトの書き方 Best Practices - AIエージェント","ko":"검증 스크립트 작성 가이드 - AI Tools","es":"Guía de configuración de script de verificación de proyecto","fr":"Guide de mise en place d''un script de vérification de projet","de":"Einrichtungsleitfaden für Projektverifizierungsskript","pt":"Guia de Configuração do writing-verify-script","ru":"ИИ Агенты: Настройка writing-verify-script","ar":"إعداد كتابة البرامج النصية للتحقق"},"description":{"en":"Learn how to create a standardized verification script for project validation. Discover the benefits of using ./scripts/verify.sh for quality checks and impl...","zh":"学习如何创建 ./scripts/verify.sh 以运行所有质量检查，包括测试、linting、格式化和类型检查","ja":"検証スクリプトの作成方法を学び、テスト、linting、フォーマット、型チェックなどの品質チェックを実行する","ko":"검증 스크립트 작성 방법을 학습하고 테스트, linting, 형식화, 유형 확인 등 모든 품질 확인을 실행하십시오","es":"Aprende a crear un script de verificación de proyecto para ejecutar comprobaciones de calidad como tests, linting y verificación de tipos","fr":"Découvrez comment créer un script de vérification de projet pour exécuter des vérifications de qualité comme des tests, du linting et une vérification de types","de":"Erfahren Sie, wie Sie ein Projektverifizierungsskript erstellen, um Qualitätsprüfungen wie Tests, Linting und Typüberprüfung auszuführen","pt":"Aprenda a criar um script de verificação personalizado com o writing-verify-script. Descubra como integrar testes, linting e verificação de tipo em um único ...","ru":"Узнайте, как создать собственный скрипт проверки с помощью writing-verify-script. Интегрируйте тесты, линтинг и проверку типов в одну команду.","ar":"تعرف على كيفية إنشاء برنامج نصي للتحقق المخصص باستخدام writing-verify-script. اكتشف كيفية دمج الاختبارات والتنسيق والتحقق من النوع في أمر واحد"},"definition":{"en":"writing-verify-script is a skill that defines how to create a verification script, a prerequisite for implementation planning, providing a single command for quality checks.","zh":"验证脚本是项目验证的标准化入口点","ja":"検証スクリプトはプロジェクトの検証の標準化されたエントリーポイントです","ko":"검증 스크립트는 프로젝트 검증의 표준화된 入口점입니다","es":"Un script de verificación de proyecto es un archivo que ejecuta comprobaciones de calidad para garantizar la calidad del código","fr":"Un script de vérification de projet est un fichier qui exécute des vérifications de qualité pour garantir la qualité du code","de":"Ein Projektverifizierungsskript ist eine Datei, die Qualitätsprüfungen ausführt, um die Codequalität zu gewährleisten","pt":"O writing-verify-script é um script que executa testes, linting, formatação e verificação de tipo em um projeto.","ru":"ИИ Агенты writing-verify-script - это скрипт, который запускает тесты, линтинг, форматирование и проверку типов в проекте.","ar":"writing-verify-script هو برنامج نصي يقوم بتشغيل الاختبارات والتنسيق والتحقق من النوع في مشروع"},"features":{"en":["Creates a standardized entry point for project validation using ./scripts/verify.sh","Runs all quality checks, including tests, linting, formatting, and type checking","Provides a single command for implementation planning","Supports project-specific tools, such as linters, formatters, and type checkers","Returns an exit code of 0 for success or non-zero for failure"],"zh":["运行所有质量检查，包括测试、linting、格式化和类型检查","提供单一命令以运行所有检查","支持项目特定的工具，如测试、linter、formatter和type checker","返回退出代码0（成功）或非零值（失败）","适用于实现规划的前置条件"],"ja":["テスト、linting、フォーマット、型チェックなどのすべての品質チェックを実行する","すべてのチェックを実行するための単一のコマンドを提供する","プロジェクト固有のツール、たとえばテスト、linter、formatter、型チェッカーをサポートする","終了コード0（成功）または非ゼロ値（失敗）を返す","実装計画の前提条件として利用可能"],"ko":["테스트, linting, 형식화, 유형 확인 등 모든 품질 확인을 실행","모든 확인을 실행하기 위한 단일 명령을 제공","프로젝트 특정 도구를 지원합니다. 예를 들어 테스트, linter, formatter, 유형 확인기","종료 코드 0(성공) 또는 非零 值(실패)를 반환","구현 계획의 전제 조건으로 사용 가능"],"es":["Ejecuta comprobaciones de calidad como tests, linting y verificación de tipos","Punto de entrada estandarizado para la validación de proyectos","Compatible con herramientas de proyecto específicas","Sale con código de éxito o error","Se puede ejecutar con un solo comando"],"fr":["Exécute des vérifications de qualité comme des tests, du linting et une vérification de types","Point d''entrée standardisé pour la validation de projets","Compatible avec des outils de projet spécifiques","Sortie avec code de succès ou d''erreur","Peut être exécuté avec une seule commande"],"de":["Führt Qualitätsprüfungen wie Tests, Linting und Typüberprüfung aus","Standardisierter Einstiegspunkt für die Validierung von Projekten","Kompatibel mit projektspezifischen Tools","Gibt Erfolgs- oder Fehlercode aus","Kann mit einem einzigen Befehl ausgeführt werden"],"pt":["Executa testes personalizados","Integra linting e formatação de código","Verifica tipo de dados em tempo de execução","Fornecer saída de sucesso ou erro (Exit 0 ou Exit 1)","Compatível com projetos de diferentes tecnologias"],"ru":["Выполняет пользовательские тесты","Интегрирует линтинг и форматирование кода","Проверяет тип данных во время выполнения","Предоставляет выход успешного или ошибочного выполнения (Exit 0 или Exit 1)","Совместим с проектами на разных технологиях"],"ar":["يعمل الاختبارات المخصصة","يدمج التنسيق والتنسيق التلقائي للكود","يتحقق من نوع البيانات في وقت التشغيل","يوفر إخراج ناجح أو خطأ (Exit 0 أو Exit 1)","متوافق مع مشاريع تقنيات مختلفة"]},"keywords":{"en":["how to use writing-verify-script","what is writing-verify-script","writing-verify-script alternative","writing-verify-script setup guide","writing-verify-script install","implementation planning with writing-verify-script","quality checks with writing-verify-script","writing-verify-script vs other validation tools"],"zh":["AIエージェント","验证脚本","质量检查","测试","linting","格式化","类型检查","项目验证","实现规划"],"ja":["AIエージェント","検証スクリプト","品質チェック","テスト","linting","フォーマット","型チェック","プロジェクト検証","実装計画"],"ko":["AI Tools","검증 스크립트","품질 확인","테스트","linting","형식화","유형 확인","프로젝트 검증","구현 계획"],"es":["script de verificación de proyecto","herramientas de calidad de código","tests automatizados","linting","verificación de tipos","desarrollo de software","Herramientas de AI como Agentes de Inteligencia Artificial","integración continua"],"fr":["script de vérification de projet","outils de qualité de code","tests automatisés","linting","vérification de types","développement de logiciels","Outils d''IA comme Agents d''Intelligence Artificielle","intégration continue"],"de":["Projektverifizierungsskript","Werkzeuge für Codequalität","automatisierte Tests","Linting","Typüberprüfung","Softwareentwicklung","KI-Tools wie künstliche Intelligenz Agenten","kontinuierliche Integration"],"pt":["writing-verify-script","script de verificação","testes personalizados","linting","formatação de código","verificação de tipo","Exit 0","Exit 1","desenvolvimento de software"],"ru":["ИИ Агенты","writing-verify-script","скрипт проверки","пользовательские тесты","линтинг","форматирование кода","проверка типов","Exit 0","Exit 1","разработка программного обеспечения"],"ar":["كتابة البرامج النصية للتحقق","برنامج نصي للتحقق","اختبارات مخصصة","تنسيق","تنسيق تلقائي للكود","التحقق من النوع","Exit 0","Exit 1","تطوير البرمجيات"]}},"owner":"noviadi","repo":"agent-loop","repoPath":"noviadi/agent-loop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.341Z","topics":[],"category":"community","skillMd":{"name":"writing-verify-script","description":"Creates ./scripts/verify.sh, a standardized verification script that runs tests, linting, formatting, and type checking. Use when setting up a new project, creating CI/CD pipelines, or when ./scripts/verify.sh is missing.","bodyPreview":"# Writing the Verification Script\n\nThis document defines how to create `./scripts/verify.sh`, the standardized entry point for project validation.\n\n## Overview\n\nThe verification script is a **prerequisite** for implementation planning. It provides a single command that runs all quality checks (tests, linting, formatting, type checking) regardless of the underlying toolchain.\n\n```\n./scripts/verify.sh\n    ↓\n[Project-specific tools: tests, linter, formatter, type checker]\n    ↓\nExit 0 (success) or","body":"# Writing the Verification Script\n\nThis document defines how to create `./scripts/verify.sh`, the standardized entry point for project validation.\n\n## Overview\n\nThe verification script is a **prerequisite** for implementation planning. It provides a single command that runs all quality checks (tests, linting, formatting, type checking) regardless of the underlying toolchain.\n\n```\n./scripts/verify.sh\n    ↓\n[Project-specific tools: tests, linter, formatter, type checker]\n    ↓\nExit 0 (success) or non-zero (failure)\n```\n\n## Why a Wrapper Script?\n\n| Benefit | Description |\n|---------|-------------|\n| **Consistency** | Same command across all projects |\n| **Discoverability** | Agents and humans know where to look |\n| **Composability** | Can run multiple tools in sequence |\n| **CI alignment** | Script can be reused in CI pipelines |\n\n## Script Requirements\n\n### Location\n\nAlways: `./scripts/verify.sh`\n\n### Behavior\n\n1. Run all quality checks in sequence\n2. Exit with code 0 if all pass\n3. Exit with non-zero code on first failure\n4. Print clear output indicating what''s running\n\n### Checks to Include\n\n| Check Type | Purpose | Examples |\n|------------|---------|----------|\n| **Tests** | Verify behavior | `cargo test`, `npm test`, `go test`, `pytest` |\n| **Linting** | Catch bugs/style issues | `cargo clippy`, `eslint`, `golangci-lint`, `flake8` |\n| **Formatting** | Ensure consistent style | `cargo fmt --check`, `prettier --check`, `gofmt`, `black --check` |\n| **Type checking** | Catch type errors | `tsc --noEmit`, `mypy`, `pyright` |\n\nNot all projects need all checks. Include what''s relevant.\n\n### Script Constraints\n\nThe script must be:\n\n| Constraint | Reason |\n|------------|--------|\n| **Non-interactive** | No prompts, confirmations, or user input; must run unattended |\n| **Fail-fast** | Exit on first failure (`set -e`); don''t continue after errors |\n| **CI-safe** | Must work in CI environments without local dependencies |\n| **Deterministic** | Same code state → same result; no flaky tests |\n| **No network dependency** | Unless explicitly documented; offline-first |\n\n**Recommended additions:**\n- Print tool versions at start (helps debug CI vs local differences)\n- Use `set -euo pipefail` for strict error handling\n- Treat warnings as errors where applicable (e.g., `cargo clippy -- -D warnings`)\n\n## Examples by Project Type\n\n### Rust\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"==> Running tests...\"\ncargo test\n\necho \"==> Running clippy...\"\ncargo clippy -- -D warnings\n\necho \"==> Checking formatting...\"\ncargo fmt --check\n\necho \"==> All checks passed!\"\n```\n\n### Node.js / TypeScript\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"==> Type checking...\"\nnpm run typecheck  # or: npx tsc --noEmit\n\necho \"==> Running tests...\"\nnpm test\n\necho \"==> Linting...\"\nnpm run lint  # or: npx eslint .\n\necho \"==> Checking formatting...\"\nnpx prettier --check .\n\necho \"==> All checks passed!\"\n```\n\n### Go\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"==> Running tests...\"\ngo test ./...\n\necho \"==> Running linter...\"\ngolangci-lint run\n\necho \"==> Checking formatting...\"\ntest -z \"$(gofmt -l .)\" || { echo \"Files need formatting\"; exit 1; }\n\necho \"==> All checks passed!\"\n```\n\n### Python\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"==> Running tests...\"\npytest\n\necho \"==> Type checking...\"\nmypy .\n\necho \"==> Linting...\"\nflake8\n\necho \"==> Checking formatting...\"\nblack --check .\n\necho \"==> All checks passed!\"\n```\n\n### Multi-language / Monorepo\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\necho \"==> Backend (Rust)...\"\n(cd backend && cargo test && cargo clippy -- -D warnings)\n\necho \"==> Frontend (TypeScript)...\"\n(cd frontend && npm test && npm run lint)\n\necho \"==> All checks passed!\"\n```\n\n## Script Template\n\n```bash\n#!/usr/bin/env bash\nset -euo pipefail\n\n# Verify script for [PROJECT_NAME]\n# Runs all quality checks required before committing code.\n\necho \"==> Running tests...\"\n# TODO: Add test command\n\necho \"==> Running linter...\"\n# TODO: Add lint command\n\necho \"==> Checking formatting...\"\n# TODO: Add format check command\n\necho \"==> All checks passed!\"\n```\n\n## Creating the Script\n\n1. Create `scripts/` directory if it doesn''t exist\n2. Create `verify.sh` using the template above\n3. Fill in project-specific commands\n4. Make executable: `chmod +x scripts/verify.sh`\n5. Test it: `./scripts/verify.sh`\n6. Commit the script\n\n## Prerequisite for Plan Writing\n\nBefore running gap analysis or writing `plans/IMPLEMENTATION_PLAN.md`:\n\n1. Check if `./scripts/verify.sh` exists\n2. If missing, **stop and notify**:\n   ```\n   ⚠️ Verification script not found.\n\n   Before creating an implementation plan, create ./scripts/verify.sh\n   See docs/writing-verify-script.md for instructions.\n   ```\n3. Once the script exists and passes, proceed with plan writing\n\n## Checklist\n\nBefore using the verification script:\n\n**Setup:**\n- [ ] Script exists at `./scripts/verify.sh`\n- [ ] Script is executable (`chmod +x`)\n- [ ] Script uses `set -euo pipefail`\n\n**Checks included:**\n- [ ] Runs tests\n- [ ] Runs linter (if project has one)\n- [ ] Checks formatting (if project has formatter)\n- [ ] Runs type checker (if applicable)\n\n**Constraints met:**\n- [ ] Non-interactive (no prompts or user input)\n- [ ] Fails fast on first error\n- [ ] CI-safe (no local-only dependencies)\n- [ ] Deterministic (no flaky behavior)\n- [ ] Exits 0 on success, non-zero on failure\n"},"lastSynced":"2026-03-08T02:03:28.225Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined project validation and quality checks through a standardized entry point","zh":"适用于需要通过标准化入口简化项目验证和质量检查的开发代理","ja":"開発エージェントがプロジェクトの検証と品質チェックをストリームライン化するために標準化されたエントリーポイントを必要とする場合に最適","ko":"프로젝트의 검증 및 품질 확인을 표준화된 진입점을 통해 간소화해야 하는 개발 에이전트에 적합","es":"Ideal para Agentes de Desarrollo que requieren una validación de proyecto y verificación de calidad simplificadas a través de un punto de entrada estandarizado","fr":"Idéal pour les agents de développement nécessitant une validation de projet et des vérifications de qualité simplifiées via un point d''entrée standardisé","de":"Ideal für Entwicklungsmittel, die eine vereinfachte Projektvalidierung und Qualitätsprüfung durch einen standardisierten Einstiegspunkt erfordern","pt":"Ideal para Agentes de Desenvolvimento que requerem validação de projeto simplificada e verificações de qualidade através de um ponto de entrada padronizado","ru":"Идеально подходит для Development Agents, требующих упрощенной проверки проекта и контроля качества через стандартизированную точку входа","ar":"مثالي لوكلاء التطوير التي تتطلب التحقق من المشروع المبسط وفحوصات الجودة من خلال نقطة دخول قياسية"},"recommendation":{"en":"Empowers agents to run comprehensive quality checks including tests, linting, formatting, and type checking, providing a single command for project validation through the verify.sh script, supporting tools like linters, formatters, and type checkers","zh":"赋予代理运行全面质量检查的能力，包括测试、linting、格式化和类型检查，通过verify.sh脚本提供单一命令用于项目验证，支持诸如linters、格式化工具和类型检查器等工具","ja":"エージェントが包括的な品質チェックを実行する能力を提供し、テスト、linting、フォーマット、タイプチェックを含み、verify.shスクリプトを通じてプロジェクトの検証用の単一のコマンドを提供し、linters、フォーマッタ、タイプチェッカーなどのツールをサポート","ko":"에이전트가 포괄적인 품질 확인을 실행할 수 있는 능력을 제공하며, 테스트, 린팅, 형식 지정 및 유형 확인을 포함하며 verify.sh 스크립트를 통해 프로젝트 확인을 위한 단일 명령을 제공하며 린터, 형식 지정 도구 및 유형 확인기 등의 도구를 지원","es":"Habilita a los agentes a ejecutar verificaciones de calidad exhaustivas, incluidas pruebas, linting, formato y verificación de tipos, proporcionando un solo comando para la validación del proyecto a través del script verify.sh, que admite herramientas como linters, formateadores y verificadores de tipos","fr":"Permet aux agents d''exécuter des vérifications de qualité exhaustives, y compris des tests, du linting, du formatage et de la vérification de types, en fournissant une seule commande pour la validation du projet via le script verify.sh, qui prend en charge des outils tels que des linters, des formateurs et des vérificateurs de types","de":"Ermächtigt die Agenten, umfassende Qualitätsprüfungen durchzuführen, einschließlich Tests, Linting, Formatierung und Typprüfung, und bietet einen einzigen Befehl für die Projektvalidierung über das Skript verify.sh, das Tools wie Linter, Formatter und Typprüfer unterstützt","pt":"Capacita os agentes a executar verificações de qualidade abrangentes, incluindo testes, linting, formatação e verificação de tipos, fornecendo um único comando para validação do projeto através do script verify.sh, suportando ferramentas como linters, formatters e type checkers","ru":"Позволяет агентам запускать комплексные проверки качества, включая тесты, линтинг, форматирование и проверку типов, предоставляя единую команду для проверки проекта через скрипт verify.sh, поддерживая такие инструменты, как linters, formatters и type checkers","ar":"يمكّن الوكلاء من تشغيل فحوصات جودة شاملة تشمل الاختبارات، والتلميع، والتنسيق، والتحقق من الأنواع، مما يوفر أمرًا واحدًا للتحقق من صحة المشروع من خلال نص verify.sh، مع دعم أدوات مثل linters و formatters و type checkers"},"useCases":{"en":["Automating project validation","Streamlining implementation planning","Running quality checks for tests, linting, and formatting"],"zh":["自动化项目验证","简化实施规划","运行测试、linting和格式化的质量检查"],"ja":["プロジェクトの検証を自動化","実装計画を簡素化","テスト、linting、フォーマットの品質チェックを実行"],"ko":["프로젝트 확인을 자동화","구현 계획을 단순화","테스트, 린팅 및 형식 지정에 대한 품질 확인을 실행"],"es":["Automatización de la validación de proyectos","Optimización de la planificación de la implementación","Ejecución de verificaciones de calidad para pruebas, linting y formato"],"fr":["Automatisation de la validation de projets","Optimisation de la planification de la mise en œuvre","Exécution de vérifications de qualité pour des tests, du linting et du formatage"],"de":["Automatisierung der Projektvalidierung","Optimierung der Implementierungsplanung","Ausführung von Qualitätsprüfungen für Tests, Linting und Formatierung"],"pt":["Automatização da validação de projetos","Simplificação do planejamento de implementação","Execução de verificações de qualidade para testes, linting e formatação"],"ru":["Автоматизация проверки проекта","Упрощение планирования реализации","Запуск проверок качества для тестов, линтинга и форматирования"],"ar":["أتمتة التحقق من صحة المشروع","تبسيط تخطيط التنفيذ","تشغيل فحوصات الجودة للاختبارات، والتلميع، والتنسيق"]},"limitations":{"en":["Requires implementation of ./scripts/verify.sh","Dependent on project-specific tools and toolchains"],"zh":["需要实现./scripts/verify.sh","依赖于项目特定的工具和工具链"],"ja":["./scripts/verify.shの実装が必要","プロジェクト固有のツールやツールチェーンに依存"],"ko":["./scripts/verify.sh의 구현이 필요","프로젝트 특정 도구 및 도구 체인에 의존"],"es":["Requiere la implementación de ./scripts/verify.sh","Dependiente de herramientas y cadenas de herramientas específicas del proyecto"],"fr":["Nécessite la mise en œuvre de ./scripts/verify.sh","Dépendante d''outils et de chaînes d''outils spécifiques au projet"],"de":["Erfordert die Implementierung von ./scripts/verify.sh","Abhängig von projektspezifischen Tools und Werkzeugketten"],"pt":["Requer a implementação de ./scripts/verify.sh","Dependente de ferramentas e toolchains específicas do projeto"],"ru":["Требует реализации ./scripts/verify.sh","Зависит от специфичных для проекта инструментов и toolchains"],"ar":["يتطلب تنفيذ ./scripts/verify.sh","يعتمد على أدوات وسلاسل الأدوات الخاصة بالمشروع"]},"version":4},"contentHash":"c2185471c0bb08ec288fbc301da6c038408197d106707259c7c82357765f9991","qualityScore":60}');
