INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('noviadi/agent-loop/writing-verify-script', 'writing-verify-script', 'noviadi', 'agent-loop', 'community', 'writing-verify-script noviadi agent-loop community The writing-verify-script skill creates a standardized entry point for project validation, providing a single command to run quality checks. It benefits developers by streamlining implementation planning. 创建 ./scripts/verify.sh 以运行所有质量检查，包括测试、linting、格式化和类型检查 検証スクリプトの作成方法を学び、テスト、linting、フォーマット、型チェックなどの品質チェックを実行する 검증 스크립트 작성 방법을 학습하고 테스트, linting, 형식화, 유형 확인 등을 실행합니다 El script de verificación de proyecto es un punto de entrada estandarizado para la validación de proyectos, que ejecuta comprobaciones de calidad como tests, linting y verificación de tipos Le script de vérification de projet est un point d''entrée standardisé pour la validation de projets, qui exécute des vérifications de qualité comme des tests, du linting et une vérification de types Das Projektverifizierungsskript ist ein standardisierter Einstiegspunkt für die Validierung von Projekten, der Qualitätsprüfungen wie Tests, Linting und Typüberprüfung ausführt O writing-verify-script é uma ferramenta para criar scripts de verificação personalizados. Ele fornece uma forma padrão de executar testes, linting, formatação e verificação de tipo. ИИ Агенты writing-verify-script - это инструмент для создания собственных скриптов проверки. Он предоставляет стандартный способ запуска тестов, линтинга, форматирования и проверки типов. writing-verify-script هو أداة لإنشاء برامج نصية للتحقق المخصصة. يوفر طريقة قياسية لتشغيل الاختبارات والتنسيق والتحقق من النوع how to use writing-verify-script what is writing-verify-script writing-verify-script alternative writing-verify-script setup guide writing-verify-script install implementation planning with writing-verify-script quality checks with writing-verify-script writing-verify-script vs other validation tools AIエージェント 验证脚本 质量检查 测试 linting 格式化 类型检查 项目验证 实现规划 Creates a standardized entry point for project validation using ./scripts/verify.sh Runs all quality checks, including tests, linting, formatting, and type checking Provides a single command for implementation planning Supports project-specific tools, such as linters, formatters, and type checkers Returns an exit code of 0 for success or non-zero for failure writing-verify-script is a skill that defines how to create a verification script, a prerequisite for implementation planning, providing a single command for quality checks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shakefu/contextium/skill-improver', 'community', 'shakefu', 'contextium', 'shakefu/contextium', 'skill-improver', 0, 0, 60, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:31.398Z', '806ad7df61e9910ad3e2e1807d39cb98b1ebdb9c86c01fa63c47652f3fd38ab7', '{"id":"shakefu/contextium/skill-improver","name":"skill-improver","description":{"en":"The skill-improver is designed for developers to improve existing Claude skills by researching current best practices and analyzing existing skills against them. It benefits developers looking to optimize their skills.","zh":"Skill Improver是一种AI工具，用于研究当前最佳实践并改进现有技能。它通过分析现有技能和生成改进建议来工作","ja":"Skill Improverは、Web検索によるベストプラクティスの調査と既存スキルの分析を通じて、AIエージェントのスキルを改善するツールです","ko":"스킬 개선 방법을 제공하는 Skill Improver는 웹 검색을 통한 최적의 방법 연구와 기존 스킬 분석을 통해 스킬을 개선하는 도구입니다","es":"Skill Improver es una habilidad que mejora las habilidades existentes de Claude mediante la investigación de mejores prácticas y la aplicación de recomendaciones de mejora","fr":"Skill Improver est une compétence qui améliore les compétences existantes de Claude en recherchant les meilleures pratiques et en appliquant des recommandations d''amélioration","de":"Skill Improver ist eine Fähigkeit, die die bestehenden Fähigkeiten von Claude durch die Recherche von Best Practices und die Anwendung von Verbesserungsvorschlägen verbessert","pt":"O Skill Improver é uma ferramenta que pesquisa as melhores práticas atuais e melhora habilidades de agente de IA existentes.","ru":"Skill Improver - это инструмент, который исследует текущие лучшие практики и улучшает существующие навыки ИИ агентов.","ar":"مهارات تحسين الوكيل الذكي هي أداة تبحث عن أفضل الممارسات الحالية وتحسن مهارات الوكيل الذكي الحالية."},"seo":{"title":{"en":"Skill-Improver: Best Practices Setup Guide | AI Agent Skill","zh":"AI工具技能改进指南 - Skill Improver","ja":"AIエージェントのスキル改善