INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shakefu/contextium/skill-improver', 'skill-improver', 'shakefu', 'contextium', 'community', 'skill-improver shakefu contextium community The skill-improver is designed for developers to improve existing Claude skills by researching current best practices and analyzing existing skills against them. It benefits developers looking to optimize their skills. Skill Improver是一种AI工具，用于研究当前最佳实践并改进现有技能。它通过分析现有技能和生成改进建议来工作 Skill Improverは、Web検索によるベストプラクティスの調査と既存スキルの分析を通じて、AIエージェントのスキルを改善するツールです 스킬 개선 방법을 제공하는 Skill Improver는 웹 검색을 통한 최적의 방법 연구와 기존 스킬 분석을 통해 스킬을 개선하는 도구입니다 Skill Improver es una habilidad que mejora las habilidades existentes de Claude mediante la investigación de mejores prácticas y la aplicación de recomendaciones de mejora Skill Improver est une compétence qui améliore les compétences existantes de Claude en recherchant les meilleures pratiques et en appliquant des recommandations d''amélioration Skill Improver ist eine Fähigkeit, die die bestehenden Fähigkeiten von Claude durch die Recherche von Best Practices und die Anwendung von Verbesserungsvorschlägen verbessert O Skill Improver é uma ferramenta que pesquisa as melhores práticas atuais e melhora habilidades de agente de IA existentes. Skill Improver - это инструмент, который исследует текущие лучшие практики и улучшает существующие навыки ИИ агентов. مهارات تحسين الوكيل الذكي هي أداة تبحث عن أفضل الممارسات الحالية وتحسن مهارات الوكيل الذكي الحالية. how to use skill-improver what is skill-improver skill-improver setup guide skill-improver alternative improving Claude skills with skill-improver skill-improver best practices skill-improver install skill-improver vs other AI skills AI工具 技能改进 最佳实践 SKILL.md CLI命令行工具 AI开发 技能开发 Identifies target skills and their domains using ls -la .claude/skills/<skill-name>/ command Researches current best practices via web search Analyzes existing skills against best practices Generates improvement recommendations Applies improvements if requested skill-improver is a technical skill that researches current best practices and improves existing Claude skills through analysis and recommendations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SHAJAR5110/Hackathon-II-phase2/libraries-dependencies-mastery', 'community', 'SHAJAR5110', 'Hackathon-II-phase2', 'SHAJAR5110/Hackathon-II-phase2', 'libraries-dependencies-mastery', 0, 0, 60, '2026-03-08T01:57:15.344Z', '2026-03-08T02:03:32.934Z', '399667d2e1165e93aa704de922ec3f40d594f175e62abae8a6192e75a65f2fe0', '{"id":"SHAJAR5110/Hackathon-II-phase2/libraries-dependencies-mastery","name":"libraries-dependencies-mastery","description":{"en":"libraries-dependencies-mastery provides complete mastery of essential libraries for modern full-stack applications, benefiting developers who work with Next.js, React, and TypeScript. This skill covers setup, configuration, and integration patterns.","zh":"本技能提供现代Web开发必备库的掌握，包括Next.js、React、TypeScript、Tailwind CSS、Firebase等","ja":"このスキルでは、Next.js、React、TypeScript、Tailwind CSS、FirebaseなどのモダンWeb開発ライブラリの統合と設定をマスターします","ko":"이 스킬은 최신 웹 개발 라이브러리인 Next.js, React, TypeScript, Tailwind CSS, Firebase 등의 마스터를 제공합니다","es":"Domina las bibliotecas y dependencias esenciales para aplicaciones web full-stack con esta habilidad","fr":"Maîtrisez les bibliothèques et dépendances essentielles pour les applications web full-stack avec cette compétence","de":"Meistern Sie die wesentlichen Bibliotheken und Abhängigkeiten für Full-Stack-Webanwendungen mit dieser Fähigkeit","pt":"Desenvolva habilidades em bibliotecas modernas de desenvolvimento web, incluindo Next.js, React, TypeScript e mais","ru":"Развивайте навыки в современных библиотеках веб-разработки, включая Next.js, React, TypeScript и другие","ar":"طور مهاراتك في المكتبات الحديثة لتنمية الويب، بما في ذلك Next.js و React و TypeScript وغيرها"},"seo":{"title":{"en":"libraries-dependencies-mastery: Mastering Next.js, React,...","zh":"AIエージェント库依赖掌握：Next.js和React集成指南","ja":"AIエージェントのライブラリと依存関係のマスター：Next.jsとReactのベストプラクティス","ko":"AI 에이전트 라이브러리 의존성 마스터: Next.js와 React 설정 가이드","es":"Guía de configuración de bibliotecas y dependencias para ...","fr":"Guide de mise en place des bibliothèques et dépendances p...","de":"Einrichtungsleitfaden für Bibliotheken und Abhängigkeiten...","pt":"Domine Bibliotecas e Dependências: Guia de Configuração","ru":"ИИ Агенты для Освоения Библиотек и Зависимостей: Лучшие П...","ar":"إتقان المكتبات والاعتماديات: دليل الإعداد"},"description":{"en":"Unlock expert-level web development with libraries-dependencies-mastery. Learn setup, configuration, and integration patterns for Next.js, React, and TypeScr...","zh":"提升您的现代Web开发技能，学习Next.js、React、TypeScript、Tailwind CSS等库的集成和配置","ja":"最新のWeb開発ライブラリとツールをマスターし、Next.js、React、TypeScript、Tailwind CSSなどの統合と設定を学びましょう","ko":"최신 웹 개발 라이브러리와 도구를 마스터하고, Next.js, React, TypeScript, Tailwind CSS 등의 통합과 설정을 배우세요","es":"Aprende a dominar las bibliotecas esenciales para aplicaciones web full-stack con Next.js, React, TypeScript y más","fr":"Maîtrisez les bibliothèques essentielles pour les applications web full-stack avec Next.js, React, TypeScript et plus","de":"Erfahren Sie, wie Sie die wesentlichen Bibliotheken für Full-Stack-Webanwendungen mit Next.js, React, TypeScript und mehr meistern","pt":"Aprenda a configurar e integrar bibliotecas essenciais como Next.js, React e TypeScript para criar aplicações full-stack modernas","ru":"Освойте настройку и интеграцию библиотек như Next.js, React и TypeScript для создания современных полнофункциональных приложений","ar":"تعلم كيفية تكوين وتكامل المكتبات الأساسية مثل Next.js و React و TypeScript لإنشاء تطبيقات كاملة النطاق الحديثة"},"definition":{"en":"libraries-dependencies-mastery is a skill that provides expertise in modern web development libraries, including Next.js, React, TypeScript, and more, for building scalable and efficient full-stack applications.","zh":"库依赖掌握是指对现代Web开发库的集成、配置和优化的能力","ja":"ライブラリと依存関係のマスターとは、モダンWeb開発ライブラリの統合、設定、最適化能力のこと","ko":"라이브러리 의존성 마스터는 최신 웹 개발 라이브러리의 통합, 설정, 최적화를 의미합니다","es":"La maestría de bibliotecas y dependencias es la capacidad de configurar e integrar bibliotecas como Next.js y React","fr":"La maîtrise des bibliothèques et dépendances est la capacité de configurer et d''intégrer des bibliothèques comme Next.js et React","de":"Die Meisterschaft von Bibliotheken und Abhängigkeiten ist die Fähigkeit, Bibliotheken wie Next.js und React zu konfigurieren und zu integrieren","pt":"Bibliotecas e Dependências é uma habilidade que fornece domínio sobre bibliotecas essenciais para aplicações full-stack","ru":"Библиотеки и Зависимости - это навык, который обеспечивает освоение необходимых библиотек для полнофункциональных приложений","ar":"المكتبات والاعتماديات هي مهارة توفر إتقان المكتبات الأساسية للتطبيقات الكاملة النطاق"},"features":{"en":["Setup and configuration of Next.js for server-side rendering","Integration of React with State Management tools like Zustand and Redux Toolkit","Implementation of Tailwind CSS for customizable UI components","Configuration of Firebase for real-time database and authentication","Usage of react-hook-form and Zod for robust form validation","Implementation of Stripe for secure payment processing"],"zh":["Next.js和React的集成","TypeScript和Tailwind CSS的配置","Firebase和State Management的设置","Forms和UI/UX的优化","Payments和Stripe的集成"],"ja":["Next.jsとReactの統合","TypeScriptとTailwind CSSの設定","FirebaseとState Managementの設定","FormsとUI/UXの最適化","PaymentsとStripeの統合"],"ko":["Next.js와 React의 통합","TypeScript와 Tailwind CSS의 설정","Firebase와 State Management의 설정","Forms와 UI/UX의 최적화","Payments와 Stripe의 통합"],"es":["Configuración de Next.js para aplicaciones web escalables","Integración de React con TypeScript para una mayor seguridad de tipos","Uso de Tailwind CSS para un diseño de UI/UX personalizable","Implementación de Firebase para una infraestructura de backend escalable","Gestión de estado con Zustand y Redux Toolkit para aplicaciones complejas","Integración de Stripe para pagos seguros en aplicaciones web"],"fr":["Configuration de Next.js pour des applications web évolutives","Intégration de React avec TypeScript pour une sécurité de types accrue","Utilisation de Tailwind CSS pour un design de UI/UX personnalisable","Mise en œuvre de Firebase pour une infrastructure de backend évolutives","Gestion d''état avec Zustand et Redux Toolkit pour des applications complexes","Intégration de Stripe pour des paiements sécurisés dans les applications web"],"de":["Konfiguration von Next.js für skalierbare Webanwendungen","Integration von React mit TypeScript für eine höhere Typsicherheit","Verwendung von Tailwind CSS für ein anpassbares UI/UX-Design","Implementierung von Firebase für eine skalierbare Backend-Infrastruktur","Zustandsverwaltung mit Zustand und Redux Toolkit für komplexe Anwendungen","Integration von Stripe für sichere Zahlungen in Webanwendungen"],"pt":["Integração com Next.js","Desenvolvimento com React","Tipagem com TypeScript","Estilização com Tailwind CSS","Gerenciamento de Estado com Zustand e Redux Toolkit"],"ru":["Интеграция с Next.js","Разработка с React","Типизация с TypeScript","Стилизация с Tailwind CSS","Управление состоянием с Zustand и Redux Toolkit"],"ar":["تكامل مع Next.js","تطوير مع React","تنميط مع TypeScript","تصميم مع Tailwind CSS","إدارة الحالة مع Zustand و Redux Toolkit"]},"keywords":{"en":["how to use libraries-dependencies-mastery","libraries-dependencies-mastery vs webpack","libraries-dependencies-mastery setup guide","what is libraries-dependencies-mastery","libraries-dependencies-mastery alternative to create-react-app","libraries-dependencies-mastery install with npm","libraries-dependencies-mastery tutorial for beginners","libraries-dependencies-mastery best practices for React development","libraries-dependencies-mastery and TypeScript integration","libraries-dependencies-mastery for full-stack development"],"zh":["AIエージェント库依赖","Next.js集成","React配置","TypeScript设置","Tailwind CSS优化","Firebase集成","State Management设置","Forms优化","UI/UX设计"],"ja":["AIエージェントのライブラリと依存関係","Next.js統合","React設定","TypeScript設定","Tailwind CSS最適化","Firebase統合","State Management設定","Forms最適化","UI/UXデザイン"],"ko":["AI 에이전트 라이브러리 의존성","Next.js 통합","React 설정","TypeScript 설정","Tailwind CSS 최적화","Firebase 통합","State Management 설정","Forms 최적화","UI/UX 디자인"],"es":["bibliotecas de JavaScript","dependencias de Node.js","Next.js tutorial","React y TypeScript","Tailwind CSS ejemplo","Firebase y backend","Zustand y Redux Toolkit","Stripe y pagos en línea","desarrollo web full-stack","herramientas de desarrollo web"],"fr":["bibliothèques JavaScript","dépendances Node.js","tutoriel Next.js","React et TypeScript","exemple Tailwind CSS","Firebase et backend","Zustand et Redux Toolkit","Stripe et paiements en ligne","développement web full-stack","outils de développement web"],"de":["JavaScript-Bibliotheken","Node.js-Abhängigkeiten","Next.js-Tutorial","React und TypeScript","Tailwind-CSS-Beispiel","Firebase und Backend","Zustand und Redux Toolkit","Stripe und Online-Zahlungen","Full-Stack-Webentwicklung","Webentwicklungstools"],"pt":["bibliotecas de desenvolvimento web","dependências de aplicações full-stack","Next.js","React","TypeScript","Tailwind CSS","Zustand","Redux Toolkit"],"ru":["библиотеки веб-разработки","зависимости полнофункциональных приложений","Next.js","React","TypeScript","Tailwind CSS","Zustand","Redux Toolkit"],"ar":["مكتبات تطور الويب","اعتماديات تطبيقات كاملة النطاق","Next.js","React","TypeScript","Tailwind CSS","Zustand","Redux Toolkit"]}},"owner":"SHAJAR5110","repo":"Hackathon-II-phase2","repoPath":"SHAJAR5110/Hackathon-II-phase2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.344Z","topics":[],"category":"community","skillMd":{"name":"libraries-dependencies-mastery","description":"Complete mastery of essential modern web development libraries and dependencies. Cover Next.js, React, TypeScript, Tailwind CSS, Firebase, Zustand, redux-toolkit, react-hook-form, Zod, shadcn/ui, lucide-react, Stripe, and more. Learn setup, integration patterns, advanced usage, performance optimization, troubleshooting, common pitfalls, and version management. Includes quick reference guides, in-depth tutorials, complete examples for e-commerce and SaaS, configuration files, type definitions, error handling, and production patterns. Master how libraries work together and solve real-world challenges.","bodyPreview":"# Libraries & Dependencies Mastery\n\n## Overview\n\nYou are an expert in modern web development libraries and their integration. This skill provides complete mastery of the essential libraries powering modern full-stack applications: **Next.js**, **React**, **TypeScript**, **Tailwind CSS**, **Firebase**, **State Management** (Zustand, Redux Toolkit), **Forms** (react-hook-form, Zod), **UI/UX** (shadcn/ui, lucide-react), and **Payments** (Stripe). Learn setup, configuration, integration patterns, ad","body":"# Libraries & Dependencies Mastery\n\n## Overview\n\nYou are an expert in modern web development libraries and their integration. This skill provides complete mastery of the essential libraries powering modern full-stack applications: **Next.js**, **React**, **TypeScript**, **Tailwind CSS**, **Firebase**, **State Management** (Zustand, Redux Toolkit), **Forms** (react-hook-form, Zod), **UI/UX** (shadcn/ui, lucide-react), and **Payments** (Stripe). Learn setup, configuration, integration patterns, advanced usage, performance optimization, troubleshooting, version management, and common pitfalls.\n\n## Core Library Mastery\n\n### 1. Next.js 13+ Complete Mastery\n\n**Setup & Configuration:**\n- Installation and project initialization\n- tsconfig.json configuration for strict TypeScript\n- next.config.js customization\n- Environment variables (.env, .env.local, .env.production)\n- Path aliases (@/ imports)\n- Monorepo setup with workspaces\n\n**App Router (Next.js 13+):**\n- File-based routing structure\n- Route segments and dynamic routes ([id], [...slug])\n- Route groups and layouts ((auth), (dashboard))\n- Parallel routes and intercepting routes\n- Loading states and error boundaries\n- Not found and error.js pages\n- Middleware and request handling\n- Route handlers (GET, POST, PUT, DELETE, PATCH)\n- Server Components vs Client Components\n- Suspense and streaming\n- Data fetching patterns (fetch, cache tags)\n- Revalidation strategies (ISR, on-demand)\n\n**Performance Optimization:**\n- Image optimization with next/image\n- Font optimization\n- Script optimization and loading strategies\n- Dynamic imports with React.lazy\n- Code splitting and bundle analysis\n- CSS optimization and minification\n- Compression and gzip\n- CDN configuration\n\n**Common Pitfalls & Solutions:**\n- Hydration mismatches (Server vs Client)\n- Using client-only features in Server Components\n- Incorrect caching strategies\n- Image optimization issues\n- Font loading performance\n- Dynamic routes not rendering statically\n- Environment variable scope\n\n**Troubleshooting Guide:**\n```\nIssue: \"Cannot find module\" in builds\nSolution: Check tsconfig paths, clear .next folder, rebuild\n\nIssue: Hydration mismatch error\nSolution: Use dynamic imports, wrap client code, check useEffect\n\nIssue: Images not optimizing\nSolution: Use next/image, configure domains, check sizes\n\nIssue: Build time too long\nSolution: Analyze with `next/bundle-analyzer`, use dynamic imports\n\nIssue: Environment variables undefined\nSolution: Prefix with NEXT_PUBLIC_ for client, restart dev server\n```\n\n**Version Management:**\n- Upgrading from Pages Router to App Router\n- Breaking changes between versions\n- Migration guides\n- Beta features and deprecations\n- Staying updated with releases\n\n---\n\n### 2. React 18+ Complete Mastery\n\n**Hooks Deep Dive:**\n- useState: State management, state updates, batching\n- useEffect: Side effects, cleanup, dependencies, common pitfalls\n- useContext: Context creation, avoiding prop drilling\n- useReducer: Complex state logic, reducer patterns\n- useCallback: Memoization, dependency arrays\n- useMemo: Expensive computations, memory management\n- useRef: DOM access, persistent values, .current\n- useLayoutEffect: DOM layout measurements\n- useTransition: Concurrent rendering, isPending state\n- useDeferredValue: Value debouncing, input optimization\n- useId: Unique identifiers, accessibility\n- useImperativeHandle: Custom instance values\n\n**Component Patterns:**\n- Functional components with hooks\n- Custom hooks development and reusability\n- Compound components\n- Render props pattern\n- Higher-order components\n- Provider pattern\n- Controlled vs uncontrolled components\n- Composition over inheritance\n\n**Performance Optimization:**\n- React.memo for preventing rerenders\n- useCallback with dependencies\n- useMemo for expensive operations\n- Lazy loading with React.lazy and Suspense\n- Code splitting strategies\n- List rendering with keys (importance of stable keys)\n- Avoiding unnecessary renders\n- Profiler API for performance measurement\n\n**Concurrent Features:**\n- Suspense boundaries\n- useTransition for non-blocking updates\n- useDeferredValue for value debouncing\n- Streaming and progressive rendering\n- Automatic batching of state updates\n\n**Common Pitfalls & Solutions:**\n- Missing dependency in useEffect\n- Stale closures in hooks\n- Memory leaks in useEffect\n- Infinite loops with useEffect\n- Using hooks conditionally\n- Not returning cleanup functions\n- Incorrect memo dependencies\n- State batching confusion\n\n**Troubleshooting Guide:**\n```\nIssue: Infinite loop in useEffect\nSolution: Check dependencies, add return cleanup function\n\nIssue: Stale state in callback\nSolution: Include state in dependencies or use useCallback\n\nIssue: Memory leak warning\nSolution: Add cleanup function to useEffect, unsubscribe\n\nIssue: Component rerending unnecessarily\nSolution: Use React.memo, useCallback, useMemo\n\nIssue: Hydration error with useId\nSolution: Use proper key prop, wrap in Suspense\n```\n\n---\n\n### 3. TypeScript Complete Mastery\n\n**Fundamentals:**\n- Primitive types (string, number, boolean, null, undefined)\n- Union types and intersection types\n- Type literals and literal types\n- Enums and const assertions\n- Type aliases vs interfaces\n- Extending types and interfaces\n- Optional properties (?) and nullish coalescing (??)\n\n**Advanced Types:**\n- Generic types and constraints\n- Conditional types (extends ? :)\n- Mapped types (Record, Partial, Required, etc.)\n- Utility types (Pick, Omit, Exclude, Extract, etc.)\n- Discriminated unions for exhaustive checking\n- Type guards and type predicates (is keyword)\n- Const type parameters\n- Template literal types\n\n**React + TypeScript:**\n- Component prop typing\n- Event handler typing\n- Ref typing with Ref<HTMLInputElement>\n- useState with initial values and TypeScript\n- useReducer with typed actions\n- useContext with typed values\n- Custom hook typing\n- Children prop typing\n\n**Common Patterns:**\n```typescript\n// Discriminated union\ntype Action = \n  | { type: ''ADD''; payload: Item }\n  | { type: ''REMOVE''; payload: string };\n\n// Generic component\nfunction List<T extends { id: string }>(props: { items: T[] }) {}\n\n// Type guard\nfunction isString(value: unknown): value is string {\n  return typeof value === ''string'';\n}\n\n// Utility type usage\ntype User = { name: string; age: number; email: string };\ntype UserPreview = Pick<User, ''name'' | ''age''>;\n```\n\n**Configuration:**\n- tsconfig.json strict mode\n- CompilerOptions for strict type checking\n- Path mapping and aliases\n- Module resolution settings\n- Declaration file generation\n\n**Common Pitfalls & Solutions:**\n- Type inference failures\n- Type assertion misuse\n- Any type overuse\n- Incorrect generic constraints\n- Missing type definitions\n- Circular type dependencies\n\n**Troubleshooting Guide:**\n```\nIssue: Type ''X'' is not assignable to type ''Y''\nSolution: Check property names, use type assertion carefully, review interfaces\n\nIssue: Cannot find name ''X''\nSolution: Check imports, verify tsconfig paths, check node_modules\n\nIssue: Property ''X'' doesn''t exist on type ''Y''\nSolution: Check types, update interfaces, verify external package types\n\nIssue: Generic type ''T'' is too complex\nSolution: Add constraints, break into simpler types, use keyof\n```\n\n---\n\n### 4. Tailwind CSS Complete Mastery\n\n**Core Concepts:**\n- Utility-first CSS methodology\n- JIT (Just-In-Time) compilation\n- Responsive design with breakpoints (sm, md, lg, xl, 2xl)\n- Hover, focus, and other state variants\n- Dark mode implementation (class and prefers-color-scheme)\n- Custom configuration (colors, spacing, fonts)\n- Arbitrary values ([width: 343px])\n- CSS layers and specificity\n\n**Configuration & Customization:**\n```javascript\n// tailwind.config.ts\nimport type { Config } from ''tailwindcss''\n\nexport default {\n  content: [\n    ''./app/**/*.{js,ts,jsx,tsx}'',\n    ''./components/**/*.{js,ts,jsx,tsx}'',\n  ],\n  theme: {\n    extend: {\n      colors: {\n        primary: ''#your-color'',\n      },\n      spacing: {\n        ''128'': ''32rem'',\n      },\n    },\n  },\n  plugins: [],\n} satisfies Config\n```\n\n**Advanced Patterns:**\n- Responsive design strategies\n- Component extraction with @apply\n- Conditional styling with clsx/classnames\n- Dark mode toggling\n- Custom plugins\n- CSS variables integration\n- Animation and transition utilities\n- Theme switching with CSS custom properties\n\n**Performance Optimization:**\n- Purging unused styles in production\n- Content configuration for tree-shaking\n- CSS size analysis\n- Critical CSS inline optimization\n- Lazy loading stylesheets\n- CSS compression\n\n**Common Pitfalls & Solutions:**\n- Utility conflicts and specificity issues\n- Unresponsive images with Tailwind sizing\n- Dark mode not working properly\n- Build process including unused classes\n- Custom color not applying\n- Conflicting CSS and Tailwind classes\n\n**Troubleshooting Guide:**\n```\nIssue: Styles not applying in production\nSolution: Check content paths, rebuild, check purge config\n\nIssue: Dark mode not toggling\nSolution: Set darkMode: ''class'' in config, add class to html\n\nIssue: Custom colors not available\nSolution: Update tailwind.config.ts theme.extend.colors\n\nIssue: Build size too large\nSolution: Verify content paths, use JIT, remove unused plugins\n\nIssue: Responsive styles not working\nSolution: Use correct breakpoint prefix (sm:, md:), check cascade\n```\n\n---\n\n### 5. Firebase Complete Mastery\n\n**Setup & Configuration:**\n```typescript\n// lib/firebase.ts\nimport { initializeApp } from ''firebase/app'';\nimport { getAuth } from ''firebase/auth'';\nimport { getFirestore } from ''firebase/firestore'';\nimport { getStorage } from ''firebase/storage'';\n\nconst firebaseConfig = {\n  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY,\n  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,\n  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,\n  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,\n  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,\n  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID,\n};\n\nconst app = initializeApp(firebaseConfig);\nexport const auth = getAuth(app);\nexport const db = getFirestore(app);\nexport const storage = getStorage(app);\n```\n\n**Authentication:**\n- Email/password signup and signin\n- OAuth providers (Google, GitHub, Facebook)\n- User profile management\n- Custom claims for authorization\n- Session persistence\n- Token refresh and expiration\n- MFA setup and verification\n- Anonymous authentication\n\n**Firestore Database:**\n- Collection references and document references\n- CRUD operations (create, read, update, delete)\n- Real-time listeners with cleanup\n- Batch writes and transactions\n- Query operations (where, orderBy, limit)\n- Pagination with startAt/endAt\n- Subcollections vs root collections\n- Data modeling and normalization\n\n**Cloud Storage:**\n- File upload with progress tracking\n- Download URLs and signed URLs\n- File deletion and management\n- Access control and security rules\n- Image optimization strategies\n- Resumable uploads for large files\n\n**Offline Persistence:**\n- Local caching configuration\n- Sync with server on reconnection\n- Offline-first strategies\n- Conflict resolution\n\n**Common Pitfalls & Solutions:**\n- Security rules blocking access\n- Missing .onSnapshot cleanup\n- Querying with unstable data\n- Creating too many subcollections\n- Not validating data before writes\n- Inconsistent authentication state\n- Storage rules preventing uploads\n\n**Troubleshooting Guide:**\n```\nIssue: \"Permission denied\" errors\nSolution: Check Security Rules, verify auth state, check custom claims\n\nIssue: onSnapshot not updating\nSolution: Verify listener attached, check firestore rules, cleanup properly\n\nIssue: File upload failing\nSolution: Check storage rules, verify file path, check bucket permissions\n\nIssue: Auth state undefined on refresh\nSolution: Wait for onAuthStateChanged before rendering, use loading state\n\nIssue: Realtime listener consuming quota\nSolution: Limit listeners, use oncemore, implement cleanup\n```\n\n---\n\n### 6. State Management: Zustand & Redux Toolkit\n\n**Zustand Complete:**\n```typescript\n// store/cartStore.ts\nimport { create } from ''zustand'';\nimport { persist } from ''zustand/middleware'';\n\ninterface CartState {\n  items: CartItem[];\n  addItem: (item: CartItem) => void;\n  removeItem: (id: string) => void;\n  getTotal: () => number;\n}\n\nexport const useCartStore = create<CartState>()(\n  persist(\n    (set, get) => ({\n      items: [],\n      addItem: (item) => set(state => ({\n        items: [...state.items, item]\n      })),\n      removeItem: (id) => set(state => ({\n        items: state.items.filter(i => i.id !== id)\n      })),\n      getTotal: () => {\n        return get().items.reduce((sum, item) => \n          sum + item.price * item.quantity, 0\n        );\n      },\n    }),\n    { name: ''cart-storage'' }\n  )\n);\n```\n\n**Redux Toolkit Complete:**\n```typescript\n// store/cartSlice.ts\nimport { createSlice, PayloadAction } from ''@reduxjs/toolkit'';\n\ninterface CartState {\n  items: CartItem[];\n}\n\nconst cartSlice = createSlice({\n  name: ''cart'',\n  initialState: { items: [] },\n  reducers: {\n    addItem: (state, action: PayloadAction<CartItem>) => {\n      state.items.push(action.payload);\n    },\n    removeItem: (state, action: PayloadAction<string>) => {\n      state.items = state.items.filter(i => i.id !== action.payload);\n    },\n  },\n});\n\nexport const { addItem, removeItem } = cartSlice.actions;\nexport default cartSlice.reducer;\n```\n\n**Comparison & When to Use:**\n- Zustand: Lightweight, minimal boilerplate, easier for beginners\n- Redux Toolkit: More powerful, better DevTools, larger apps\n- Integration with other libraries\n- Performance considerations\n\n**Common Pitfalls & Solutions:**\n- Mutating state directly in Zustand\n- Not using persist middleware properly\n- Redux selector performance issues\n- Unnecessary renders from store changes\n- DevTools not working\n\n**Troubleshooting Guide:**\n```\nIssue: State not persisting in Zustand\nSolution: Add persist middleware, check localStorage, verify name prop\n\nIssue: Redux component not updating\nSolution: Check selector, verify dispatch called, check middleware\n\nIssue: Store data undefined on mount\nSolution: Use loading state, wait for hydration, check persist\n\nIssue: Memory leaks from listeners\nSolution: Return unsubscribe function, cleanup in useEffect\n```\n\n---\n\n### 7. Forms: react-hook-form + Zod\n\n**react-hook-form Setup:**\n```typescript\nimport { useForm } from ''react-hook-form'';\nimport { zodResolver } from ''@hookform/resolvers/zod'';\nimport { z } from ''zod'';\n\nconst schema = z.object({\n  email: z.string().email(),\n  password: z.string().min(8),\n});\n\ntype FormData = z.infer<typeof schema>;\n\nfunction LoginForm() {\n  const { register, handleSubmit, formState: { errors } } = useForm<FormData>({\n    resolver: zodResolver(schema),\n  });\n\n  return (\n    <form onSubmit={handleSubmit(onSubmit)}>\n      <input {...register(''email'')} />\n      {errors.email && <span>{errors.email.message}</span>}\n    </form>\n  );\n}\n```\n\n**Zod Validation:**\n```typescript\n// Complete validation schema\nconst userSchema = z.object({\n  name: z.string().min(2).max(50),\n  email: z.string().email(),\n  age: z.number().min(18).max(120),\n  password: z.string().min(8),\n  confirmPassword: z.string(),\n  terms: z.boolean().refine(val => val === true),\n}).refine(data => data.password === data.confirmPassword, {\n  message: \"Passwords don''t match\",\n  path: [\"confirmPassword\"],\n});\n```\n\n**Advanced Patterns:**\n- Multi-step forms with validation\n- Dynamic field arrays\n- Conditional field rendering\n- Async validation (checking email availability)\n- Custom validators\n- Nested object validation\n- File upload validation\n- Form submission handling\n\n**Common Pitfalls & Solutions:**\n- Form not submitting with validation errors\n- Async validation causing delays\n- Zod schema not matching form structure\n- Field array complexity\n- Custom validation logic errors\n- Form reset not working\n- File upload validation failing\n\n**Troubleshooting Guide:**\n```\nIssue: Form submitting even with errors\nSolution: Check handleSubmit usage, verify resolver setup\n\nIssue: Async validation taking too long\nSolution: Add debounce, implement caching, optimize backend\n\nIssue: Zod error: \"Expected object, received undefined\"\nSolution: Verify schema matches form data structure\n\nIssue: Dynamic fields not validating\nSolution: Use z.array() properly, update schema dynamically\n\nIssue: File validation not working\nSolution: Use refine/superRefine, check file type validation\n```\n\n---\n\n### 8. UI/UX: shadcn/ui & lucide-react\n\n**shadcn/ui Setup & Usage:**\n```typescript\n// Using pre-built components\nimport { Button } from ''@/components/ui/button'';\nimport { Input } from ''@/components/ui/input'';\nimport { Card } from ''@/components/ui/card'';\n\nexport function MyComponent() {\n  return (\n    <Card>\n      <Input placeholder=\"Enter text\" />\n      <Button>Submit</Button>\n    </Card>\n  );\n}\n```\n\n**Available Components:**\n- Buttons (variants, sizes, states)\n- Input fields and forms\n- Cards and containers\n- Modals and dialogs\n- Dropdowns and menus\n- Tabs and accordions\n- Data tables and lists\n- Alerts and notifications\n- Progress indicators\n- Navigation components\n- Tooltips and popovers\n\n**lucide-react Icons:**\n```typescript\nimport { Heart, ShoppingCart, Menu, X } from ''lucide-react'';\n\nexport function IconExample() {\n  return (\n    <>\n      <Heart size={24} />\n      <ShoppingCart className=\"text-blue-600\" />\n      <Menu strokeWidth={1.5} />\n    </>\n  );\n}\n```\n\n**Customization & Theming:**\n- Tailwind CSS integration\n- Color customization\n- Size variants\n- Animation options\n- Dark mode support\n- Custom component wrappers\n\n**Common Pitfalls & Solutions:**\n- Component styling conflicts\n- Icon size inconsistencies\n- Accessibility issues\n- Theme not applying\n- Custom styling overriding defaults\n\n**Troubleshooting Guide:**\n```\nIssue: shadcn/ui component styles not applying\nSolution: Check Tailwind config, verify CSS import, check className conflicts\n\nIssue: Icons not showing or sizing incorrectly\nSolution: Specify size prop, check import path, verify CSS classes\n\nIssue: Dark mode not working with components\nSolution: Set darkMode in tailwind.config, wrap with provider\n\nIssue: Component variants not working\nSolution: Check component prop names, verify version compatibility\n```\n\n---\n\n### 9. Payments: Stripe Integration\n\n**Stripe Setup:**\n```typescript\nimport Stripe from ''stripe'';\n\nconst stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);\n\n// Create payment intent\nconst paymentIntent = await stripe.paymentIntents.create({\n  amount: 1000, // in cents\n  currency: ''usd'',\n  payment_method_types: [''card''],\n});\n```\n\n**Client-Side Integration:**\n```typescript\nimport { loadStripe } from ''@stripe/js'';\nimport { CardElement, useStripe, useElements } from ''@stripe/react-stripe-js'';\n\nconst stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_KEY!);\n\nfunction PaymentForm() {\n  const stripe = useStripe();\n  const elements = useElements();\n\n  const handleSubmit = async (e) => {\n    const { paymentIntent } = await stripe.confirmCardPayment(\n      clientSecret,\n      { payment_method: { card: elements.getElement(CardElement) } }\n    );\n  };\n\n  return (\n    <Elements stripe={stripePromise}>\n      <CardElement />\n      <button onClick={handleSubmit}>Pay</button>\n    </Elements>\n  );\n}\n```\n\n**Webhooks & Server-Side:**\n- Payment intent creation\n- Webhook event handling\n- Subscription management\n- Customer management\n- Invoice generation\n- Refund processing\n\n**Common Pitfalls & Solutions:**\n- Missing publishable key environment variable\n- Webhook signature verification failing\n- Race conditions with payment status\n- PCI compliance violations\n- Testing with wrong API keys\n- Missing error handling\n- Race conditions in webhook processing\n\n**Troubleshooting Guide:**\n```\nIssue: \"publishable key not found\" error\nSolution: Check NEXT_PUBLIC_STRIPE_KEY env var, restart dev server\n\nIssue: Webhook verification failing\nSolution: Use correct webhook secret, check signature encoding\n\nIssue: Payment processing twice\nSolution: Implement idempotency keys, add retry logic, check order status\n\nIssue: Test card not working\nSolution: Use Stripe test cards (4242424242424242), check mode (test/live)\n```\n\n---\n\n### 10. Other Essential Libraries\n\n**react-hot-toast:**\n```typescript\nimport toast from ''react-hot-toast'';\n\n// Success toast\ntoast.success(''Order placed successfully!'');\n\n// Error toast\ntoast.error(''Payment failed'');\n\n// Custom toast\ntoast((t) => (\n  <div>\n    Custom message\n    <button onClick={() => toast.dismiss(t.id)}>Dismiss</button>\n  </div>\n));\n```\n\n**axios vs fetch:**\n```typescript\n// axios - automatic JSON handling, interceptors\nimport axios from ''axios'';\nconst response = await axios.get(''/api/products'');\n\n// fetch - native, no dependencies\nconst response = await fetch(''/api/products'');\nconst data = await response.json();\n```\n\n**clsx/classnames:**\n```typescript\nimport clsx from ''clsx'';\n\nconst buttonClass = clsx(\n  ''px-4 py-2 rounded'',\n  variant === ''primary'' && ''bg-blue-600 text-white'',\n  variant === ''secondary'' && ''bg-gray-200 text-gray-900'',\n  isLoading && ''opacity-50 cursor-not-allowed''\n);\n```\n\n---\n\n## Integration Patterns: Libraries Working Together\n\n### E-Commerce Example\n```typescript\n// Components use shadcn/ui + lucide-react\n// Forms use react-hook-form + Zod\n// State with Zustand + persist\n// API calls with axios\n// Payments with Stripe\n// Database with Firebase\n// Styling with Tailwind CSS\n// Routing with Next.js\n```\n\n### SaaS Example\n```typescript\n// Next.js for routing + SSR\n// React for components\n// TypeScript for type safety\n// Firebase Auth + Firestore\n// Redux Toolkit for complex state\n// Tailwind + shadcn/ui for UI\n// react-hook-form for user forms\n// Stripe for subscriptions\n```\n\n---\n\n## Dependency Management\n\n**package.json Best Practices:**\n- Version pinning strategies\n- Semantic versioning\n- Peer dependencies\n- Dev vs production dependencies\n- Monorepo workspaces\n- Script automation\n\n**Updating Dependencies:**\n```bash\n# Check outdated packages\nnpm outdated\n\n# Update specific package\nnpm install package@latest\n\n# Update all patch versions\nnpm update\n\n# Check for vulnerabilities\nnpm audit\nnpm audit fix\n```\n\n**Common Issues:**\n- Peer dependency conflicts\n- Incompatible version combinations\n- Breaking changes during updates\n- Node version compatibility\n- Platform-specific issues\n\n---\n\n## Performance Optimization Across Libraries\n\n**Bundle Size Reduction:**\n- Dynamic imports with Next.js\n- Tree shaking with TypeScript\n- Removing unused Tailwind classes\n- Code splitting with React.lazy\n- Analyzing with bundle-analyzer\n\n**Runtime Performance:**\n- React memo and callbacks\n- Zustand selector optimization\n- Redux reselect usage\n- Lazy image loading with next/image\n- Request deduplication with axios interceptors\n\n**Database Performance:**\n- Firestore query optimization\n- Collection indexing\n- Batch operations\n- Caching strategies\n\n---\n\n## When to Use This Skill\n\n✅ Understanding how to set up each library properly\n✅ Learning integration patterns between libraries\n✅ Troubleshooting library-specific issues\n✅ Optimizing performance with libraries\n✅ Upgrading and managing dependencies\n✅ Finding solutions to common pitfalls\n✅ Learning best practices for each library\n✅ Making choices between similar libraries (Zustand vs Redux)\n✅ Quick reference for library syntax and APIs\n✅ Deep diving into advanced usage\n\n---\n\n## Quick Reference vs Deep Learning\n\n**This skill includes:**\n- ⚡ Quick lookup tables and syntax reference\n- 📚 In-depth tutorials and explanations\n- 🔧 Configuration file templates\n- 🐛 Troubleshooting guides\n- 🚀 Performance tips\n- ⚠️ Common pitfalls and solutions\n- 🔄 Integration patterns\n- 📊 Comparison guides\n- 💡 Real-world examples\n- 🎯 Best practices\n\n---\n\n## Resources & References\n\n### Quick Reference Guides\n- **next-js-quick-ref.md** - Commands, config, routing\n- **react-hooks-reference.md** - All hooks with examples\n- **typescript-quick-ref.md** - Common patterns, syntax\n- **tailwind-utilities-ref.md** - All utility classes\n- **firebase-methods-ref.md** - All Firebase methods\n- **zod-validators-ref.md** - All Zod validators\n- **stripe-api-ref.md** - Stripe API methods\n\n### In-Depth Guides\n- **next-js-advanced.md** - Advanced patterns, optimization\n- **react-performance.md** - Rendering optimization\n- **typescript-advanced.md** - Complex types, patterns\n- **tailwind-advanced.md** - Custom plugins, design systems\n- **firebase-patterns.md** - Architecture patterns\n- **zustand-vs-redux.md** - Comparison and when to use\n- **form-validation-deep.md** - Complex validation patterns\n- **stripe-complete.md** - Full Stripe implementation\n\n### Troubleshooting & Common Issues\n- **common-errors.md** - Error messages and solutions\n- **dependency-conflicts.md** - Resolving version conflicts\n- **performance-issues.md** - Identifying and fixing slowness\n- **type-errors.md** - TypeScript error solutions\n- **build-issues.md** - Next.js build troubleshooting\n\n### Integration Examples\n- **ecommerce-integration.md** - Complete e-commerce setup\n- **saas-integration.md** - SaaS platform setup\n- **authentication-flows.md** - Auth integration patterns\n- **payment-integration.md** - Payment processing setup\n\n---\n\n## Technology Stack Details\n\n**Versions Covered:**\n- Next.js 13+\n- React 18+\n- TypeScript 4.5+\n- Tailwind CSS 3+\n- Firebase SDK (latest)\n- Zustand 4+\n- Redux Toolkit 1.9+\n- react-hook-form 7+\n- Zod 3+\n- Stripe (latest)\n\n**Upgrade Paths:**\n- Next.js 12 → 13 → 14\n- React 17 → 18\n- Tailwind CSS 2 → 3\n- TypeScript updates and breaking changes\n- Firebase SDK v8 → v9 (modular SDK)\n\n---\n\nThis comprehensive skill gives you complete mastery of the essential libraries and how they work together!"},"lastSynced":"2026-03-08T02:03:32.934Z","agentAnalysis":{"suitability":{"en":"Perfect for Full-Stack Agents needing mastery of modern web development libraries like Next.js, React, and TypeScript.","zh":"非常适合需要掌握现代 Web 开发库的全栈代理商，如 Next.js、React 和 TypeScript。","ja":"Next.js、React、TypeScript などの最新の Web 開発ライブラリをマスターする必要があるフルスタックエージェントに最適です。","ko":"Next.js, React, TypeScript 등의 현대 웹 개발 라이브러리를 마스터하는 것이 필요한 풀스택 에이전트에게 완벽합니다.","es":"Perfecto para Agentes Full-Stack que necesitan dominar bibliotecas de desarrollo web modernas como Next.js, React y TypeScript.","fr":"Parfait pour les agents Full-Stack qui ont besoin de maîtriser les bibliothèques de développement web modernes comme Next.js, React et TypeScript.","de":"Perfekt für Full-Stack-Agents, die die Beherrschung moderner Webentwicklungsbibliotheken wie Next.js, React und TypeScript benötigen.","pt":"Perfeito para Agentes Full-Stack que necessitam de domínio de bibliotecas de desenvolvimento web modernas como Next.js, React e TypeScript.","ru":"Идеально подходит для агентов Full-Stack, которым требуется освоение современных библиотек веб-разработки, таких как Next.js, React и TypeScript.","ar":"مثالي للوكلاء الكاملين الذين يحتاجون إلى إتقان مكتبات التطوير الإلكتروني الحديثة مثل Next.js و React و TypeScript."},"recommendation":{"en":"Empowers agents to seamlessly integrate and configure essential libraries such as Tailwind CSS, Firebase, and State Management tools like Zustand and Redux Toolkit, while also handling forms with react-hook-form and Zod, and enabling efficient UI/UX with shadcn/ui and lucide-react, including secure payment processing with Stripe.","zh":"赋予代理商无缝集成和配置必备库的能力，例如 Tailwind CSS、Firebase 和状态管理工具如 Zustand 和 Redux Toolkit，同时处理 react-hook-form 和 Zod 的表单，并通过 shadcn/ui 和 lucide-react 启用高效的 UI/UX，包括使用 Stripe 进行安全的支付处理。","ja":"Tailwind CSS、Firebase、Zustand、Redux Toolkit などの必須ライブラリをシームレスに統合・設定する能力をエージェントに与え、react-hook-form と Zod でフォームを処理し、shadcn/ui と lucide-react で効率的な UI/UX を可能にし、Stripe を使用した安全な決済処理を有効にします。","ko":"에이전트에게 Tailwind CSS, Firebase, Zustand 및 Redux Toolkit 등의 필수 라이브러리를 무결점으로 통합하고 구성할 수 있는 능력을 부여하고, react-hook-form 및 Zod를 사용한 폼 처리 및 shadcn/ui 및 lucide-react를 사용한 효율적인 UI/UX를 활성화하고, Stripe를 사용한 보안 결제 처리를 가능하게 합니다.","es":"Habilita a los agentes a integrar y configurar bibliotecas esenciales como Tailwind CSS, Firebase y herramientas de gestión de estado como Zustand y Redux Toolkit, además de manejar formularios con react-hook-form y Zod, y permitir una interfaz de usuario/UX eficiente con shadcn/ui y lucide-react, incluyendo un procesamiento de pago seguro con Stripe.","fr":"Permet aux agents d''intégrer et de configurer des bibliothèques essentielles comme Tailwind CSS, Firebase et des outils de gestion d''état comme Zustand et Redux Toolkit, tout en gérant les formulaires avec react-hook-form et Zod, et en permettant une interface utilisateur/UX efficace avec shadcn/ui et lucide-react, y compris un traitement de paiement sécurisé avec Stripe.","de":"Ermöglicht es den Agenten, wesentliche Bibliotheken wie Tailwind CSS, Firebase und Statusverwaltungstools wie Zustand und Redux Toolkit nahtlos zu integrieren und zu konfigurieren, sowie Formulare mit react-hook-form und Zod zu bearbeiten und eine effiziente Benutzeroberfläche/Benutzererfahrung mit shadcn/ui und lucide-react zu ermöglichen, einschließlich sicheren Zahlungsverarbeitung mit Stripe.","pt":"Habilita os agentes a integrar e configurar bibliotecas essenciais, como Tailwind CSS, Firebase e ferramentas de Gerenciamento de Estado, como Zustand e Redux Toolkit, além de lidar com formulários com react-hook-form e Zod, e permitir UI/UX eficientes com shadcn/ui e lucide-react, incluindo processamento de pagamento seguro com Stripe.","ru":"Наделяет агентов возможностью бесшовно интегрировать и настраивать важные библиотеки, такие как Tailwind CSS, Firebase и инструменты управления состоянием, такие как Zustand и Redux Toolkit, а также обрабатывать формы с react-hook-form и Zod, и обеспечивать эффективный UI/UX с shadcn/ui и lucide-react, включая безопасную обработку платежей с Stripe.","ar":"تمكين الوكلاء من دمج وتكوين المكتبات الأساسية مثل Tailwind CSS و Firebase وأدوات إدارة الحالة مثل Zustand و Redux Toolkit، بالإضافة إلى التعامل مع النماذج مع react-hook-form و Zod، وتمكين واجهة المستخدم الفعالة مع shadcn/ui و lucide-react، بما في ذلك معالجة الدفع الآمنة مع Stripe."},"useCases":{"en":["Configuring Next.js and React for scalable applications","Integrating Firebase for real-time database management","Implementing secure payment gateways with Stripe"],"zh":["为可扩展应用程序配置 Next.js 和 React","集成 Firebase 进行实时数据库管理","使用 Stripe 实现安全的支付网关"],"ja":["スケーラブルなアプリケーション用に Next.js と React を設定する","リアルタイムデータベース管理用に Firebase を統合する","Stripe を使用して安全な決済ゲートウェイを実装する"],"ko":["확장 가능한 애플리케이션을 위한 Next.js 및 React 설정","실시간 데이터베이스 관리를 위한 Firebase 통합","Stripe를 사용한 보안 결제 게이트웨이 구현"],"es":["Configuración de Next.js y React para aplicaciones escalables","Integración de Firebase para la gestión de bases de datos en tiempo real","Implementación de pasarelas de pago seguras con Stripe"],"fr":["Configuration de Next.js et React pour des applications scalables","Intégration de Firebase pour la gestion de bases de données en temps réel","Mise en œuvre de passerelles de paiement sécurisées avec Stripe"],"de":["Konfiguration von Next.js und React für skalierbare Anwendungen","Integration von Firebase für die Verwaltung von Echtzeit-Datenbanken","Implementierung sicherer Zahlungs-Gateways mit Stripe"],"pt":["Configurando Next.js e React para aplicações escaláveis","Integrando Firebase para gerenciamento de banco de dados em tempo real","Implementando gateways de pagamento seguros com Stripe"],"ru":["Настройка Next.js и React для масштабируемых приложений","Интеграция Firebase для управления базой данных в реальном времени","Реализация безопасных платежных шлюзов с Stripe"],"ar":["تكوين Next.js و React لتطبيقات قابلة للتوسيع","دمج Firebase لإدارة قواعد البيانات في الوقت الفعلي","تنفيذ بوابات دفع آمنة مع Stripe"]},"limitations":{"en":["Requires familiarity with TypeScript and JavaScript","Specific to modern web development frameworks and libraries"],"zh":["需要熟悉 TypeScript 和 JavaScript","仅适用于现代 Web 开发框架和库"],"ja":["TypeScript と JavaScript に慣れていないと使用できない","モダン Web 開発フレームワークとライブラリに特化している"],"ko":["TypeScript 및 JavaScript에 익숙하지 않으면 사용할 수 없음","최신 웹 개발 프레임워크 및 라이브러리 전용"],"es":["Requiere familiaridad con TypeScript y JavaScript","Específico para frameworks y bibliotecas de desarrollo web modernas"],"fr":["Nécessite une connaissance de TypeScript et JavaScript","Spécifique aux frameworks et bibliothèques de développement web modernes"],"de":["Benötigt Vertrautheit mit TypeScript und JavaScript","Spezifisch für moderne Webentwicklungs-Frameworks und -Bibliotheken"],"pt":["Requer familiaridade com TypeScript e JavaScript","Específico para frameworks e bibliotecas de desenvolvimento web modernas"],"ru":["Требуется знание TypeScript и JavaScript","Конкретно для современных фреймворков и библиотек веб-разработки"],"ar":["يتطلب معرفة بالنوع النصي و JavaScript","محدد لاطار عمل التطوير الإلكتروني الحديث ومكتباته"]},"version":4},"contentHash":"399667d2e1165e93aa704de922ec3f40d594f175e62abae8a6192e75a65f2fe0","qualityScore":60}');
