INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SHAJAR5110/Hackathon-II-phase2/libraries-dependencies-mastery', 'libraries-dependencies-mastery', 'SHAJAR5110', 'Hackathon-II-phase2', 'community', 'libraries-dependencies-mastery SHAJAR5110 Hackathon-II-phase2 community libraries-dependencies-mastery provides complete mastery of essential libraries for modern full-stack applications, benefiting developers who work with Next.js, React, and TypeScript. This skill covers setup, configuration, and integration patterns. 本技能提供现代Web开发必备库的掌握，包括Next.js、React、TypeScript、Tailwind CSS、Firebase等 このスキルでは、Next.js、React、TypeScript、Tailwind CSS、FirebaseなどのモダンWeb開発ライブラリの統合と設定をマスターします 이 스킬은 최신 웹 개발 라이브러리인 Next.js, React, TypeScript, Tailwind CSS, Firebase 등의 마스터를 제공합니다 Domina las bibliotecas y dependencias esenciales para aplicaciones web full-stack con esta habilidad Maîtrisez les bibliothèques et dépendances essentielles pour les applications web full-stack avec cette compétence Meistern Sie die wesentlichen Bibliotheken und Abhängigkeiten für Full-Stack-Webanwendungen mit dieser Fähigkeit Desenvolva habilidades em bibliotecas modernas de desenvolvimento web, incluindo Next.js, React, TypeScript e mais Развивайте навыки в современных библиотеках веб-разработки, включая Next.js, React, TypeScript и другие طور مهاراتك في المكتبات الحديثة لتنمية الويب، بما في ذلك Next.js و React و TypeScript وغيرها how to use libraries-dependencies-mastery libraries-dependencies-mastery vs webpack libraries-dependencies-mastery setup guide what is libraries-dependencies-mastery libraries-dependencies-mastery alternative to create-react-app libraries-dependencies-mastery install with npm libraries-dependencies-mastery tutorial for beginners libraries-dependencies-mastery best practices for React development libraries-dependencies-mastery and TypeScript integration libraries-dependencies-mastery for full-stack development AIエージェント库依赖 Next.js集成 React配置 TypeScript设置 Tailwind CSS优化 Firebase集成 State Management设置 Forms优化 UI/UX设计 Setup and configuration of Next.js for server-side rendering Integration of React with State Management tools like Zustand and Redux Toolkit Implementation of Tailwind CSS for customizable UI components Configuration of Firebase for real-time database and authentication Usage of react-hook-form and Zod for robust form validation Implementation of Stripe for secure payment processing libraries-dependencies-mastery is a skill that provides expertise in modern web development libraries, including Next.js, React, TypeScript, and more, for building scalable and efficient full-stack applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('parcadei/Continuous-Claude-v3/slash-commands', 'community', 'parcadei', 'Continuous-Claude-v3', 'parcadei/Continuous-Claude-v3', 'slash-commands', 0, 0, 60, '2026-03-08T01:57:15.346Z', '2026-03-08T02:03:36.726Z', '1aae27e0a28f91b54971da43f17b86d935808f90de928b1ee908724d18425075', '{"id":"parcadei/Continuous-Claude-v3/slash-commands","name":"slash-commands","description":{"en":"The slash-commands skill enables context management for Claude Code, allowing developers to maintain state via ledgers and handoffs. It supports MCP execution without context pollution and agent orchestration with isolated context windows.","zh":"slash-commands提供上下文管理和MCP执行功能，帮助开发者创建高效的AI代理","ja":"Slash Commandsはコンテキスト管理とMCP実行機能を提供し、開発者が効率的なAIエージェントを作成するのに役立ちます","ko":"slash-commands는 컨텍스트 관리와 MCP 실행 기능을 제공하여 개발자가 효율적인 AI 에이전트를 만들 수 있도록 도와줍니다","es":"Los comandos de barra permiten una gestión de contexto eficaz en Claude Code, con capacidades como la ejecución de MCP sin contaminación de contexto y la orquestación de agentes con ventanas de contexto aisladas","fr":"Les commandes de barre permettent une gestion de contexte efficace dans Claude Code, avec des capacités telles que l''exécution de MCP sans pollution de contexte et l''orchestration d''agents avec des fenêtres de contexte isolées","de":"Die Slash-Befehle ermöglichen eine effiziente Kontextverwaltung in Claude Code, mit Fähigkeiten wie der Ausführung von MCP ohne Kontextverunreinigung und der Orchestrierung von Agents mit isolierten Kontextfenstern","pt":"Comandos de barra para gerenciar contextos em Claude Code, com suporte a hooks e ledgers para manter o estado","ru":"Команды слэш для управления контекстами в Claude Code, с поддержкой хуков и бухгалтерских книг для сохранения состояния","ar":"أوامر 斜线 لإدارة السياقات في Claude Code، مع دعم hooks و ledgers للاحتفاظ بالحالة"},"seo":{"title":{"en":"slash-commands: Context Management Setup Guide | AI Agent...","zh":"slash-commands 设置指南：上下文管理和MCP执行","ja":"Slash Commands 導入ガイド：コンテキスト管理とMCP実行","ko":"slash-commands 설정 가이드: 컨텍스트 관리와 MCP 실행","es":"Guía de configuración de comandos de barra para agentes d...","fr":"Guide de mise en place des commandes de barre pour les ou...","de":"Einrichtungsleitfaden für Slash-Befehle für KI-Agents","pt":"Guia de Configuração de Comandos de Barra para Ferramenta...","ru":"Настройка ИИ Агентов: Руководство по Командам Слэш","ar":"دليل إعداد أوامر 斜线 للوكلاء الذكيين"},"description":{"en":"Unlock efficient context management with slash-commands. Learn how to create and use user-triggered prompts with our expert guide and maximize your AI agent''...","zh":"了解slash-commands的上下文管理和MCP执行功能，实现高效的AI代理开发","ja":"Slash Commandsのコンテキスト管理とMCP実行機能を学び、効率的なAIエージェント開発を実現","ko":"slash-commands의 컨텍스트 관리와 MCP 실행 기능을 익히고 효율적인 AI 에이전트 개발을 구현","es":"Aprende a crear y utilizar comandos de barra con la sintaxis /command-name para una gestión de contexto eficaz en Claude Code","fr":"Découvrez comment créer et utiliser des commandes de barre avec la syntaxe /command-name pour une gestion de contexte efficace dans Claude Code","de":"Erfahren Sie, wie Sie Slash-Befehle mit der Syntax /command-name erstellen und verwenden, um eine effiziente Kontextverwaltung in Claude Code zu ermöglichen","pt":"Aprenda a criar e usar comandos de barra com sintaxe /command-name para gerenciar contextos em Claude Code","ru":"Узнайте, как создавать и использовать команды слэш с синтаксисом /command-name для управления контекстами в Claude Code","ar":"تعلم كيفية إنشاء واستخدام أوامر 斜线 بناء الجملة /command-name لإدارة السياقات في Claude Code"},"definition":{"en":"slash-commands is a context management system for AI agents, utilizing ledgers and handoffs to maintain state and prevent context pollution.","zh":"slash-commands是一种提供上下文管理和MCP执行功能的AI代理技能","ja":"Slash Commandsはコンテキスト管理とMCP実行機能を提供するAIエージェントのスキルです","ko":"slash-commands는 컨텍스트 관리와 MCP 실행 기능을 제공하는 AI 에이전트의 스킬입니다","es":"Un comando de barra es una instrucción que utiliza la sintaxis /command-name para realizar acciones específicas en Claude Code","fr":"Une commande de barre est une instruction qui utilise la syntaxe /command-name pour effectuer des actions spécifiques dans Claude Code","de":"Ein Slash-Befehl ist eine Anweisung, die die Syntax /command-name verwendet, um bestimmte Aktionen in Claude Code auszuführen","pt":"Comandos de barra são comandos de usuário que gerenciam contextos em Claude Code","ru":"Команды слэш - это команды пользователя, которые управляют контекстами в Claude Code","ar":"أوامر 斜线 هي أوامر المستخدم التي تدير السياقات في Claude Code"},"features":{"en":["Create and use user-triggered prompts with `/command-name` syntax","Utilize built-in commands like `/clear`, `/compact`, and `/config` for conversation management","Execute MCP without context pollution using isolated context windows","Orchestrate agents with handoffs and ledgers for efficient state management","Reference files and use bash in commands for enhanced functionality"],"zh":["上下文管理","MCP执行","Hooks状态维护","Ledgers和Handoffs支持","隔离的上下文窗口"],"ja":["コンテキスト管理","MCP実行","Hooks状態維持","LedgersとHandoffs対応","隔離されたコンテキストウィンドウ"],"ko":["컨텍스트 관리","MCP 실행","Hooks 상태 유지","Ledgers와 Handoffs 지원","격리된 컨텍스트 창"],"es":["Creación de comandos de barra personalizados con la sintaxis /command-name","Ejecución de MCP sin contaminación de contexto","Orquestación de agentes con ventanas de contexto aisladas","Uso de referencias de archivo en comandos","Compatibilidad con la sintaxis de bash"],"fr":["Création de commandes de barre personnalisées avec la syntaxe /command-name","Exécution de MCP sans pollution de contexte","Orchestration d''agents avec des fenêtres de contexte isolées","Utilisation de références de fichier dans les commandes","Compatibilité avec la syntaxe de bash"],"de":["Erstellung benutzerdefinierter Slash-Befehle mit der Syntax /command-name","Ausführung von MCP ohne Kontextverunreinigung","Orchestrierung von Agents mit isolierten Kontextfenstern","Verwendung von Dateireferenzen in Befehlen","Kompatibilität mit der bash-Syntax"],"pt":["Criação de comandos de barra com sintaxe /command-name","Suporte a hooks para manter o estado","Uso de ledgers para gerenciar contextos","Execução de MCP sem poluição de contexto","Orquestração de agentes com janelas de contexto isoladas"],"ru":["Создание команд слэш с синтаксисом /command-name","Поддержка хуков для сохранения состояния","Использование бухгалтерских книг для управления контекстами","Выполнение MCP без загрязнения контекста","Оркестровка агентов с изолированными контекстными окнами"],"ar":["إنشاء أوامر 斜线 ببناء الجملة /command-name","دعم hooks للاحتفاظ بالحالة","استخدام ledgers لتدبير السياقات","تنفيذ MCP بدون تلوث السياق","توجيه الوكلاء مع نوافذ سياق معزولة"]},"keywords":{"en":["how to use slash-commands","slash-commands setup guide","context management for AI agents","slash-commands vs skills","install slash-commands","what is slash-commands","slash-commands alternative","using slash-commands with Claude Code","slash-commands for MCP execution","efficient context management with slash-commands"],"zh":["slash-commands","AI代理","上下文管理","MCP执行","Hooks","Ledgers","Handoffs","隔离的上下文窗口"],"ja":["Slash Commands","AIエージェント","コンテキスト管理","MCP実行","Hooks","Ledgers","Handoffs","隔離されたコンテキストウィンドウ"],"ko":["slash-commands","AI 에이전트","컨텍스트 관리","MCP 실행","Hooks","Ledgers","Handoffs","격리된 컨텍스트 창"],"es":["comandos de barra","agentes de IA","Claude Code","gestión de contexto","MCP","orchestación de agentes","referencias de archivo","bash"],"fr":["commandes de barre","outils d''IA","Claude Code","gestion de contexte","MCP","orchestration d''agents","références de fichier","bash"],"de":["Slash-Befehle","KI-Agents","Claude Code","Kontextverwaltung","MCP","Orchestrierung von Agents","Dateireferenzen","bash"],"pt":["comandos de barra","ferramentas de ia","claude code","gerenciamento de contexto","hooks","ledgers","mcp","orquestração de agentes"],"ru":["команды слэш","ии агенты","claude code","управление контекстами","хуки","бухгалтерские книги","mcp","оркестровка агентов"],"ar":["أوامر 斜线","الوكلاء الذكيين","claude code","إدارة السياقات","hooks","ledgers","mcp","توجيه الوكلاء"]}},"owner":"parcadei","repo":"Continuous-Claude-v3","repoPath":"parcadei/Continuous-Claude-v3","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.346Z","topics":[],"category":"community","skillMd":{"name":"slash-commands","description":"Create and use Claude Code slash commands - quick prompts, bash execution, file references","bodyPreview":"# Slash Commands Reference\n\nCreate and use user-triggered prompts with `/command-name` syntax.\n\n## When to Use\n\n- \"How do I create a slash command?\"\n- \"What slash commands are available?\"\n- \"Add bash to my command\"\n- \"Use file references in commands\"\n- \"Slash commands vs skills\"\n\n## Built-in Commands\n\n| Command | Purpose |\n|---------|---------|\n| `/clear` | Clear conversation history |\n| `/compact` | Compact conversation with focus |\n| `/config` | Open settings interface |\n| `/cost` | Show token","body":"# Slash Commands Reference\n\nCreate and use user-triggered prompts with `/command-name` syntax.\n\n## When to Use\n\n- \"How do I create a slash command?\"\n- \"What slash commands are available?\"\n- \"Add bash to my command\"\n- \"Use file references in commands\"\n- \"Slash commands vs skills\"\n\n## Built-in Commands\n\n| Command | Purpose |\n|---------|---------|\n| `/clear` | Clear conversation history |\n| `/compact` | Compact conversation with focus |\n| `/config` | Open settings interface |\n| `/cost` | Show token usage |\n| `/agents` | Manage sub-agents |\n| `/mcp` | Manage MCP servers |\n| `/memory` | Edit CLAUDE.md files |\n| `/model` | Select AI model |\n| `/review` | Request code review |\n| `/resume` | Resume session |\n| `/help` | Get usage help |\n\n## Creating Commands\n\n### Project Commands\n```bash\nmkdir -p .claude/commands\ncat > .claude/commands/optimize.md << ''EOF''\n---\ndescription: Analyze code for performance issues\n---\n\nReview this code for:\n- Performance bottlenecks\n- Memory leaks\n- Caching opportunities\nEOF\n```\n\n### Personal Commands\n```bash\nmkdir -p ~/.claude/commands\ncat > ~/.claude/commands/review.md << ''EOF''\n---\ndescription: Security-focused code review\n---\n\nCheck for vulnerabilities:\n- Input validation\n- SQL injection\n- XSS risks\nEOF\n```\n\n## Command File Format\n\n```yaml\n---\ndescription: Brief description for /help\nallowed-tools: [Bash, Read, Write]  # Optional\nargument-hint: \"[file] [type]\"       # Optional\n---\n\nYour markdown instructions here.\nUse $1, $2 for arguments or $ARGUMENTS for all.\n```\n\n## Bash Execution\n\nRun bash before loading prompt with `!` prefix:\n\n```yaml\n---\nallowed-tools: Bash(git:*), Bash(grep:*)\ndescription: Git commit helper\n---\n\nCurrent status: !`git status`\nStaged changes: !`git diff --staged`\nRecent commits: !`git log --oneline -5`\n\nBased on these changes, suggest a commit message.\n```\n\n**Rules:**\n- Must declare `allowed-tools: Bash(...)` in frontmatter\n- Use backticks: `` !`command` ``\n- Output is included in Claude''s context\n\n## File References\n\nInclude files with `@` prefix:\n\n```markdown\nReview against @.claude/STYLE_GUIDE.md\n\nCompare:\n- @src/old.js\n- @src/new.js\n\nRefactor files matching @src/**/*.util.ts\n```\n\n## Arguments\n\n```yaml\n---\nargument-hint: \"[pr-number] [priority]\"\n---\n\nReview PR #$1 with priority: $2\n\n# Or use all arguments:\nFix issue #$ARGUMENTS\n```\n\n**Usage:**\n```bash\n/review-pr 456 high\n# $1 = \"456\", $2 = \"high\"\n```\n\n## Namespacing\n\nOrganize with subdirectories:\n\n```\n.claude/commands/\n├── frontend/\n│   └── component.md    → /component (project:frontend)\n└── backend/\n    └── endpoint.md     → /endpoint (project:backend)\n```\n\n## MCP Slash Commands\n\nMCP servers expose prompts as commands:\n\n```bash\n/mcp__github__list_prs\n/mcp__github__pr_review 456\n/mcp__jira__create_issue \"Bug\" high\n```\n\n## Slash Commands vs Skills\n\n| Aspect | Slash Commands | Skills |\n|--------|----------------|--------|\n| Invocation | Explicit: `/command` | Auto-discovered |\n| Files | Single .md file | Directory with SKILL.md |\n| Use Case | Quick prompts | Complex workflows |\n\n**Use slash commands for:** Frequently typed prompts, simple templates\n**Use skills for:** Complex workflows, multiple files, auto-discovery\n\n## Example: Complete Git Commit Command\n\n```yaml\n---\ndescription: Generate semantic commit message\nallowed-tools: Bash(git:*), Read\nargument-hint: \"[type]\"\n---\n\n# Semantic Commit Generator\n\nStaged files: !`git diff --name-only --cached`\n\nDiff preview:\n!`git diff --cached | head -100`\n\nGenerate a conventional commit message.\nType: $1 (feat/fix/docs/style/refactor/perf/test/chore)\n\nFormat: `<type>(<scope>): <subject>`\n```\n\n**Usage:** `/commit feat`\n"},"lastSynced":"2026-03-08T02:03:36.726Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code needing advanced context management via ledgers and handoffs","zh":"适合需要高级上下文管理（通过账本和交接）的AI代理，如Claude Code","ja":"Claude Codeなどの、高度なコンテキスト管理（レジャーとハンドオフを介して）を必要とするAIエージェントに適しています","ko":"Claude Code와 같은 고급 컨텍스트 관리(레저 및 핸드오버를 통해)를 필요한 AI 에이전트에 적합합니다","es":"Perfecto para agentes de IA como Claude Code que necesitan una gestión avanzada de contexto a través de registros y transferencias","fr":"Parfait pour les agents d''IA comme Claude Code nécessitant une gestion avancée du contexte via des registres et des passes","de":"Perfekt für KI-Agents wie Claude Code, die eine erweiterte Kontextverwaltung über Registrierungen und Übergaben benötigen","pt":"Perfeito para Agentes de IA como Claude Code que necessitam de gerenciamento avançado de contexto via ledgers e handoffs","ru":"Идеально подходит для агентов ИИ, таких как Claude Code, требующих расширенного управления контекстом через ведgers и handoffs","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude Code الذي يحتاج إلى إدارة سياق متقدمة من خلال سجلات وحوافظ"},"recommendation":{"en":"Empowers agents to execute MCP without context pollution and manage state using isolated context windows, supporting user-triggered prompts with `/command-name` syntax and built-in commands like `/clear`, `/compact`, and `/config`","zh":"赋予代理执行MCP而不污染上下文，并使用孤立的上下文窗口管理状态，支持用户触发的提示以`/command-name`语法，并内置命令如`/clear`、`/compact`和`/config`","ja":"エージェントにコンテキスト汚染なくMCPを実行し、分離されたコンテキストウィンドウを使用して状態を管理することを可能にし、`/command-name`構文でのユーザー起因のプロンプトと、`/clear`、`/compact`、`/config`などの組み込みコマンドをサポート","ko":"에이전트가 컨텍스트 오염 없이 MCP를 실행하고 분리된 컨텍스트 창을 사용하여 상태를 관리할 수 있도록 하며 `/command-name` 구문으로 사용자 트리거 프로ンプ트와 `/clear`, `/compact`, `/config` 등의 내장 명령어를 지원합니다","es":"Habilita a los agentes a ejecutar MCP sin contaminación de contexto y gestionar el estado utilizando ventanas de contexto aisladas, con soporte para prompts desencadenados por el usuario con la sintaxis `/command-name` y comandos integrados como `/clear`, `/compact` y `/config`","fr":"Permet aux agents d''exécuter MCP sans pollution de contexte et de gérer l''état en utilisant des fenêtres de contexte isolées, en prenant en charge les invites déclenchées par l''utilisateur avec la syntaxe `/command-name` et des commandes intégrées comme `/clear`, `/compact` et `/config`","de":"Ermöglicht es Agents, MCP ohne Kontextverschmutzung auszuführen und den Zustand mithilfe isolierter Kontextfenster zu verwalten, mit Unterstützung für benutzer ausgelöste Prompts mit der Syntax `/command-name` und integrierte Befehle wie `/clear`, `/compact` und `/config`","pt":"Habilita os agentes a executar MCP sem poluição de contexto e gerenciar estado usando janelas de contexto isoladas, suportando prompts acionados pelo usuário com sintaxe `/command-name` e comandos internos como `/clear`, `/compact` e `/config`","ru":"Позволяет агентам выполнять MCP без загрязнения контекста и управлять состоянием с помощью изолированных контекстных окон, поддерживая пользовательские команды с синтаксисом `/command-name` и встроенные команды, такие как `/clear`, `/compact` и `/config`","ar":"تمكن الوكلاء من تنفيذ MCP دون تلوث السياق وإدارة الحالة باستخدام نوافذ سياق معزولة ، ودعم الدفعات التي ي.triggerها المستخدم بنفس الصيغة `/command-name` والأوامر المدمجة مثل `/clear` ، `/compact` و `/config`"},"useCases":{"en":["Creating custom slash commands for user interactions","Managing conversation history with `/clear` and `/compact`","Configuring agent settings with `/config`"],"zh":["为用户交互创建自定义斜杠命令","使用`/clear`和`/compact`管理对话历史","使用`/config`配置代理设置"],"ja":["ユーザーインタラクション用のカスタムスラッシュコマンドを作成する","`/clear`と`/compact`を使用して会話履歴を管理する","`/config`を使用してエージェント設定を構成する"],"ko":["사용자 상호 작용을 위한 사용자 지정 슬래시 명령을 생성하는 것","`/clear` 및 `/compact`를 사용하여 대화 기록을 관리하는 것","`/config`를 사용하여 에이전트 설정을 구성하는 것"],"es":["Creación de comandos personalizados con barra para interacciones de usuario","Gestión del historial de conversación con `/clear` y `/compact`","Configuración de la configuración del agente con `/config`"],"fr":["Création de commandes personnalisées avec barre pour les interactions utilisateur","Gestion de l''historique de conversation avec `/clear` et `/compact`","Configuration des paramètres de l''agent avec `/config`"],"de":["Erstellen von benutzerdefinierten Befehlen mit Schrägstrich für Benutzerinteraktionen","Verwaltung der Konversationshistorie mit `/clear` und `/compact`","Konfiguration der Agenteneinstellungen mit `/config`"],"pt":["Criação de comandos personalizados para interações do usuário","Gerenciamento do histórico de conversa com `/clear` e `/compact`","Configuração de configurações do agente com `/config`"],"ru":["Создание пользовательских команд для взаимодействия с пользователем","Управление историей разговора с помощью `/clear` и `/compact`","Настройка параметров агента с помощью `/config`"],"ar":["إنشاء أوامر مخصصة للتفاعلات المستخدم","إدارة تاريخ المحادثة مع `/clear` و `/compact`","تكوين إعدادات الوكيل باستخدام `/config`"]},"limitations":{"en":["Requires Claude Code integration","Context management limited to ledgers and handoffs"],"zh":["需要Claude Code集成","上下文管理仅限于账本和交接"],"ja":["Claude Codeの統合が必要","コンテキスト管理はレジャーとハンドオフに限定"],"ko":["Claude Code 통합이 필요","컨텍스트 관리는 레저 및 핸드오버로 제한"],"es":["Requiere integración con Claude Code","La gestión del contexto está limitada a registros y transferencias"],"fr":["Nécessite une intégration avec Claude Code","La gestion du contexte est limitée aux registres et aux passes"],"de":["Erfordert Integration mit Claude Code","Die Kontextverwaltung ist auf Registrierungen und Übergaben beschränkt"],"pt":["Requer integração com Claude Code","Gerenciamento de contexto limitado a ledgers e handoffs"],"ru":["Требует интеграции с Claude Code","Управление контекстом ограничено ведgers и handoffs"],"ar":["يتطلب تكامل مع Claude Code","إدارة السياق محدودة للسجلات والتحويلات"]},"version":4},"contentHash":"1aae27e0a28f91b54971da43f17b86d935808f90de928b1ee908724d18425075","qualityScore":60}');
