INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('parcadei/Continuous-Claude-v3/slash-commands', 'slash-commands', 'parcadei', 'Continuous-Claude-v3', 'community', 'slash-commands parcadei Continuous-Claude-v3 community The slash-commands skill enables context management for Claude Code, allowing developers to maintain state via ledgers and handoffs. It supports MCP execution without context pollution and agent orchestration with isolated context windows. slash-commands提供上下文管理和MCP执行功能，帮助开发者创建高效的AI代理 Slash Commandsはコンテキスト管理とMCP実行機能を提供し、開発者が効率的なAIエージェントを作成するのに役立ちます slash-commands는 컨텍스트 관리와 MCP 실행 기능을 제공하여 개발자가 효율적인 AI 에이전트를 만들 수 있도록 도와줍니다 Los comandos de barra permiten una gestión de contexto eficaz en Claude Code, con capacidades como la ejecución de MCP sin contaminación de contexto y la orquestación de agentes con ventanas de contexto aisladas Les commandes de barre permettent une gestion de contexte efficace dans Claude Code, avec des capacités telles que l''exécution de MCP sans pollution de contexte et l''orchestration d''agents avec des fenêtres de contexte isolées Die Slash-Befehle ermöglichen eine effiziente Kontextverwaltung in Claude Code, mit Fähigkeiten wie der Ausführung von MCP ohne Kontextverunreinigung und der Orchestrierung von Agents mit isolierten Kontextfenstern Comandos de barra para gerenciar contextos em Claude Code, com suporte a hooks e ledgers para manter o estado Команды слэш для управления контекстами в Claude Code, с поддержкой хуков и бухгалтерских книг для сохранения состояния أوامر 斜线 لإدارة السياقات في Claude Code، مع دعم hooks و ledgers للاحتفاظ بالحالة how to use slash-commands slash-commands setup guide context management for AI agents slash-commands vs skills install slash-commands what is slash-commands slash-commands alternative using slash-commands with Claude Code slash-commands for MCP execution efficient context management with slash-commands slash-commands AI代理 上下文管理 MCP执行 Hooks Ledgers Handoffs 隔离的上下文窗口 Create and use user-triggered prompts with `/command-name` syntax Utilize built-in commands like `/clear`, `/compact`, and `/config` for conversation management Execute MCP without context pollution using isolated context windows Orchestrate agents with handoffs and ledgers for efficient state management Reference files and use bash in commands for enhanced functionality slash-commands is a context management system for AI agents, utilizing ledgers and handoffs to maintain state and prevent context pollution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('storyblok/monoblok/review-and-qa', 'community', 'storyblok', 'monoblok', 'storyblok/monoblok', 'review-and-qa', 0, 0, 60, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.051Z', '1f162cf045b1c210d22d246554552879964daf9521a08103f6dfad436e2516dd', '{"id":"storyblok/monoblok/review-and-qa","name":"review-and-qa","description":{"en":"The review-and-qa skill enables developers to review code changes and perform QA reviews. It benefits developers by ensuring high-quality code.","zh":"Review-and-QA是一种代码审查和测试工具，帮助开发者优化代码质量和功能","ja":"Review-and-QAはコードレビューとテストのツールで、開発者のコード品質と機能を最適化する","ko":"Review-and-QA는 코드 리뷰와 테스트 도구로 개발者の 코드 품질과 기능을 최적화합니다","es":"La revisión y pruebas de QA son fundamentales para garantizar la calidad del código en Storyblok OSS. Nuestra guía te ayudará a configurar un proceso de revisión efectivo.","fr":"La revue de code et les tests de QA sont essentiels pour assurer la qualité du code dans Storyblok OSS. Notre guide vous aidera à configurer un processus de revue efficace.","de":"Code-Review und QA-Tests sind entscheidend für die Sicherstellung der Codequalität in Storyblok OSS. Unsere Anleitung hilft Ihnen bei der Einrichtung eines effektiven Überprüfungsprozesses.","pt":"O Review e QA de código é uma habilidade que ajuda a garantir a qualidade do código, com análise de mudanças e criação de casos de teste manuais.","ru":"Проверка и контроль качества кода - это навык, который помогает обеспечить качество кода, с анализом изменений и созданием ручных тестовых случаев.","ar":"مراجعة وضمان الجودة هي مهارة تساعد على ضمان جودة الكود، مع تحليل التغييرات وإنشاء حالات اختبار يدوية"},"seo":{"title":{"en":"review-and-qa: Code Review and QA Setup Guide | AI Agent ...","zh":"Review-and-QA Setup Guide: 代码审查和测试","ja":"Review-and-QAベストプラクティス: コードレビューとテスト","ko":"Review-and-QA 가이드: 코드 리뷰와 테스트","es":"Guía de configuración de revisión y pruebas de QA para St...","fr":"Guide de configuration de l''examen et de la QA pour Story...","de":"Einrichtungsleitfaden für Code-Review und QA-Tests in Sto...","pt":"Guia de Configuração para Revisão e QA de Código","ru":"ИИ Агенты: Руководство по Настройке Review и QA","ar":"دليل إعداد وكيل إقتراح لمراجعة وضمان الجودة"},"description":{"en":"Master code quality with review-and-qa. Learn how to perform two-phase reviews and create manual test cases. Get started now!","zh":"了解Review-and-QA的技术细节，优化代码审查和测试流程，提升开发效率","ja":"Review-and-QAのテクニカルな詳細を学び、コードレビューとテストのプロセスを最適化する","ko":"Review-and-QA의 기술 세부 사항을 학습하고 코드 리뷰 및 테스트 프로세스를 최적화하십시오","es":"Aprende a implementar una revisión de código y pruebas de QA efectivas en Storyblok OSS con nuestra guía paso a paso","fr":"Découvrez comment mettre en œuvre une revue de code et des tests de QA efficaces dans Storyblok OSS avec notre guide étape par étape","de":"Erfahren Sie, wie Sie eine effektive Code-Review und QA-Tests in Storyblok OSS implementieren, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Review e QA de código com o Storyblok OSS monorepo e melhore a qualidade do seu código","ru":"Узнайте, как настроить проверку и контроль качества кода с помощью Storyblok OSS monorepo и улучшить качество вашего кода","ar":"تعلم كيفية إعداد وكيل مراجعة وضمان الجودة باستخدام Storyblok OSS monorepo وتحسين جودة كودك"},"definition":{"en":"review-and-qa is a skill that performs two-phase reviews, including code review and QA review, to ensure high-quality code changes.","zh":"Review-and-QA是一种代码审查和测试工具，用于优化代码质量和功能","ja":"Review-and-QAはコードレビューとテストのツールで、コード品質と機能を最適化する","ko":"Review-and-QA는 코드 리뷰와 테스트 도구로 코드 품질과 기능을 최적화하는 것입니다","es":"La revisión y pruebas de QA es un proceso de dos fases que implica la revisión de código y la creación de casos de prueba manuales","fr":"La revue de code et les tests de QA sont un processus en deux phases qui implique la revue de code et la création de cas de test manuels","de":"Code-Review und QA-Tests sind ein zweiphasiger Prozess, der die Code-Überprüfung und die Erstellung manueller Testfälle umfasst","pt":"O que é Review e QA de código? É uma análise de mudanças de código para garantir a qualidade e criar casos de teste manuais.","ru":"Что такое проверка и контроль качества кода? Это анализ изменений кода для обеспечения качества и создания ручных тестовых случаев.","ar":"ما هي مراجعة وضمان الجودة؟ هي تحليل التغييرات في الكود لضمان الجودة وإنشاء حالات اختبار يدوية"},"features":{"en":["Performs code review to analyze code quality, architecture, and best practices","Creates manual test cases to validate behavior during QA review","Enforces a PR checklist for all pull requests","Requires small diffs and tests for new functionality","Supports bug fixes with regression tests","Analyzes code changes for logical consistency"],"zh":["代码审查：检查代码质量和架构","测试用例创建：验证代码行为","小型差异：确保每个PR只包含一个逻辑变化","测试包含：新功能和bug修复都包含测试","两阶段审查：代码审查和测试审查"],"ja":["コードレビュー：コード品質とアーキテクチャを確認","テストケース作成：コードの動作を検証","小さな差異：各PRが1つの論理変化のみを含むことを確認","テストの包含：新機能とバグ修正にテストを含める","2段階のレビュー：コードレビューとテストレビュー"],"ko":["코드 리뷰：코드 품질과 아키텍처를 확인","테스트 케이스 생성：코드 동작을 검증","작은 차이：각 PR이 1개의 논리적 변경만 포함하는지 확인","테스트 포함：새로운 기능과 버그 수정에 테스트를 포함","2단계 리뷰：코드 리뷰와 테스트 리뷰"],"es":["Revisión de código para garantizar la calidad y los estándares","Creación de casos de prueba manuales para validar el comportamiento","Uso de una lista de verificación de PR para asegurar la coherencia","Revisión de la arquitectura y las mejores prácticas","Inclusión de pruebas para nueva funcionalidad y correcciones de errores"],"fr":["Revue de code pour assurer la qualité et les normes","Création de cas de test manuels pour valider le comportement","Utilisation d''une liste de vérification de PR pour assurer la cohérence","Revue de l''architecture et des meilleures pratiques","Inclusion de tests pour la nouvelle fonctionnalité et les corrections de bogues"],"de":["Code-Review zur Gewährleistung von Qualität und Standards","Erstellung manueller Testfälle zur Überprüfung des Verhaltens","Verwendung einer PR-Checkliste zur Sicherstellung der Konsistenz","Überprüfung der Architektur und der besten Praktiken","Einbeziehung von Tests für neue Funktionalitäten und Fehlerkorrekturen"],"pt":["Análise de mudanças de código","Criação de casos de teste manuais","Verificação de qualidade de código","Uso do Storyblok OSS monorepo","Suporte à revisão de código em duas fases"],"ru":["Анализ изменений кода","Создание ручных тестовых случаев","Проверка качества кода","Использование Storyblok OSS monorepo","Поддержка двухфазной проверки кода"],"ar":["تحليل التغييرات في الكود","إنشاء حالات اختبار يدوية","فحص جودة الكود","استخدام Storyblok OSS monorepo","دعم مراجعة الكود في مرحلتين"]},"keywords":{"en":["how to use review-and-qa","review-and-qa setup guide","review-and-qa alternative","review-and-qa vs code review tools","what is review-and-qa","review-and-qa install","review-and-qa for developers","code review best practices","QA review process"],"zh":["AIエージェント","代码审查工具","测试工具","代码质量优化","功能测试","Review-and-QA","代码审查最佳实践","测试用例创建"],"ja":["AIエージェント","コードレビューツール","テストツール","コード品質最適化","機能テスト","Review-and-QA","コードレビューベストプラクティス","テストケース作成"],"ko":["AI 에이전트","코드 리뷰 도구","테스트 도구","코드 품질 최적화","기능 테스트","Review-and-QA","코드 리뷰 베스트 프랙티스","테스트 케이스 생성"],"es":["revisión de código","pruebas de QA","Storyblok OSS","guía de configuración","mejores prácticas de código","casos de prueba manuales","lista de verificación de PR","Herramientas de AI para desarrolladores"],"fr":["revue de code","tests de QA","Storyblok OSS","guide de configuration","meilleures pratiques de code","cas de test manuels","liste de vérification de PR","Outils d''IA pour développeurs"],"de":["Code-Review","QA-Tests","Storyblok OSS","Einrichtungsleitfaden","Beste Praktiken für Code","manuelle Testfälle","PR-Checkliste","KI-Tools für Entwickler"],"pt":["review e qa de código","storyblok oss monorepo","análise de mudanças de código","criação de casos de teste manuais","qualidade de código","desenvolvimento de software","revisão de código"],"ru":["проверка и контроль качества кода","storyblok oss monorepo","анализ изменений кода","создание ручных тестовых случаев","качество кода","разработка программного обеспечения","проверка кода"],"ar":["مراجعة وضمان الجودة","storyblok oss monorepo","تحليل التغييرات في الكود","إنشاء حالات اختبار يدوية","جودة الكود","تطوير البرمجيات","مراجعة الكود"]}},"owner":"storyblok","repo":"monoblok","repoPath":"storyblok/monoblok","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"review-and-qa","description":"Review the changes for <commit|branch|pr> and create a QA review plan","bodyPreview":"# Review Changes\n\nReview the changes for: $ARGUMENTS.\n\n## Instructions\n\nPerform a two-phase review:\n\n1. **Code review** - Review quality, architecture, and best practices.\n2. **QA review** - Create manual test cases to validate behavior.\n\n## Phase 1: Code review\n\nAnalyze the code changes for:\n\n## PR checklist\n\n### Required for all PRs\n\n- [ ] **Small diff** - One logical change. If the PR does multiple things, split it.\n- [ ] **Tests included** - New functionality has tests. Bug fixes have regres","body":"# Review Changes\n\nReview the changes for: $ARGUMENTS.\n\n## Instructions\n\nPerform a two-phase review:\n\n1. **Code review** - Review quality, architecture, and best practices.\n2. **QA review** - Create manual test cases to validate behavior.\n\n## Phase 1: Code review\n\nAnalyze the code changes for:\n\n## PR checklist\n\n### Required for all PRs\n\n- [ ] **Small diff** - One logical change. If the PR does multiple things, split it.\n- [ ] **Tests included** - New functionality has tests. Bug fixes have regression tests.\n- [ ] **No secrets** - No tokens, passwords, or credentials in the code.\n\n### If user-facing changes\n\n- [ ] **Docs updated** - The README or relevant documentation reflects the change.\n- [ ] **Examples work** - Code examples in the documentation are tested and copy-paste ready.\n- [ ] **Error messages helpful** - New errors explain what went wrong and how to fix it.\n\n### If breaking changes\n\n- [ ] **Migration notes** - Provide clear before and after examples showing how to upgrade.\n- [ ] **Changelog entry** - Follow conventional commits for release notes.\n- [ ] **Deprecation warnings** - If keeping an old API temporarily, warn users.\n\n### If adding dependencies\n\n- [ ] **Justified** - No existing solution exists in the codebase.\n- [ ] **License compatible** - Use MIT or a compatible license.\n- [ ] **Maintained** - Use an active project with recent updates.\n- [ ] **Size reasonable** - Avoid adding significant bundle weight.\n\n### Quality and clean code\n\n- [ ] Functions are small and single-purpose.\n- [ ] Variable and function names are descriptive.\n- [ ] No dead code or commented-out blocks exist.\n- [ ] No magic numbers exist (use constants).\n- [ ] Error messages are helpful.\n\n### Architecture and design\n\n- [ ] Changes fit existing patterns in the codebase.\n- [ ] No unnecessary coupling exists between modules.\n- [ ] Proper separation of concerns exists (actions vs. commands vs. utils).\n- [ ] Types and interfaces are defined appropriately.\n\n### Reusability and centralization\n\n- [ ] Duplicated logic is extracted to shared utilities.\n- [ ] Existing helpers are used where applicable.\n- [ ] New utilities are generic enough for reuse.\n- [ ] Constants are centralized (not scattered).\n\n### Best practices\n\n- [ ] Async and await are used consistently (no mixed patterns).\n- [ ] Errors are propagated correctly (not swallowed).\n- [ ] Edge cases are handled (null, empty, invalid input).\n- [ ] No security issues exist (injection, secrets exposure).\n\n### Output format (code review)\n\n```markdown\n## Code review summary\n\n[LGTM / Needs changes / Blocking issues]\n\n## Issues found\n\n### [Critical/Major/Minor]: Issue title\n\n**File:** `path/to/file.ts:123`\n**Problem:** Description.\n**Suggestion:** How to fix.\n```\n\n## Phase 2: QA review\n\n### Test case structure\n\nRefer to the [Test Plan Template](./templates/test-plan.md) and the [Test Plan Example](./examples/assets-test-plan.md) for test plan structure guidance.\n\n### Coverage requirements\n\nCreate test cases for:\n\n1. **Happy path** - Normal successful operation.\n2. **Negative cases** - Invalid input, unauthorized access, and missing data.\n3. **Edge cases** - Empty input, large input, and special characters.\n4. **Error recovery** - What happens when things fail mid-operation.\n"},"lastSynced":"2026-03-08T02:03:39.051Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing comprehensive PR analysis and QA testing capabilities.","zh":"适用于需要全面PR分析和QA测试能力的代码审查代理。","ja":"コードレビューエージェントが包括的なPR分析とQAテスト機能を必要とする場合に最適です。","ko":"코드 리뷰 에이전트가 포괄적인 PR 분석 및 QA 테스트 기능을 필요로 할 때 적합합니다.","es":"Ideal para agentes de revisión de código que necesitan un análisis de PR comprehensivo y capacidades de prueba de QA.","fr":"Idéal pour les agents de révision de code nécessitant une analyse de PR complète et des capacités de test de QA.","de":"Ideal für Code-Review-Agents, die eine umfassende PR-Analyse und QA-Testfunktionen benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de análise de PR abrangente e capacidades de teste de QA.","ru":"Идеально для агентов кодового обзора, требующих всестороннего анализа PR и возможностей тестирования QA.","ar":"مثالي للوكلاء المراجعة الكودية الذين يحتاجون إلى تحليل شاملا ل.PR وخصائص اختبار جودة التأكد"},"recommendation":{"en":"Empowers agents to perform thorough two-phase reviews, including code quality analysis and manual test case creation, ensuring high-quality code through small diffs and included tests.","zh":"赋予代理执行彻底的两阶段审查，包括代码质量分析和手动测试用例创建，确保通过小的差异和包含的测试来实现高质量的代码。","ja":"エージェントが包括的な2段階のレビューを実行できるようにし、コード品質分析と手動テストケースの作成を含め、高品質のコードを小さな差分と含まれるテストを通じて保証します。","ko":"에이전트가 철저한 2단계 리뷰를 수행할 수 있도록 하여 코드 품질 분석 및 수동 테스트 케이스 생성을 포함하여 작은 차이 및 포함된 테스트를 통해 높은 품질의 코드를 보장합니다.","es":"Habilita a los agentes a realizar revisiones exhaustivas de dos fases, incluyendo análisis de calidad de código y creación de casos de prueba manuales, garantizando un código de alta calidad a través de pequeñas diferencias y pruebas incluidas.","fr":"Permet aux agents d''effectuer des révisions approfondies en deux phases, notamment l''analyse de la qualité du code et la création de cas de test manuels, garantissant un code de haute qualité grâce à de petites différences et des tests inclus.","de":"Ermächtigt die Agenten, gründliche Zwei-Phasen-Überprüfungen durchzuführen, einschließlich Code-Qualitätsanalyse und manueller Erstellung von Testfällen, um einen hochwertigen Code durch kleine Diffs und enthaltene Tests sicherzustellen.","pt":"Habilita os agentes a realizar revisões em duas fases abrangentes, incluindo análise de qualidade de código e criação de casos de teste manuais, garantindo código de alta qualidade por meio de pequenas diferenças e testes incluídos.","ru":"Наделяет агентов возможностью проводить тщательные двухфазные обзоры, включая анализ качества кода и создание ручных тестовых случаев, обеспечивающих высококачественный код посредством небольших изменений и включенных тестов.","ar":"يتمكن الوكلاء من إجراء مراجعات شاملة في مرحلتين، بما في ذلك تحليل جودة الكود وإنشاء حالات اختبار يدوية، مما يضمن كود عالي الجودة من خلال اختلافات صغيرة واختبارات شاملة"},"useCases":{"en":["Automating code reviews for pull requests","Generating manual test cases for new functionality","Validating bug fix regressions"],"zh":["自动化pull请求的代码审查","为新功能生成手动测试用例","验证bug修复回归"],"ja":["プルリクエストのコードレビューの自動化","新機能の手動テストケースの生成","バグ修正のリグレッションの検証"],"ko":["풀 요청의 코드 리뷰 자동화","새 기능에 대한 수동 테스트 케이스 생성","버그 수정 회귀 검증"],"es":["Automatización de revisiones de código para solicitudes de extracción","Generación de casos de prueba manuales para nueva funcionalidad","Validación de regresiones de correcciones de errores"],"fr":["Automatisation des révisions de code pour les demandes d''extraction","Génération de cas de test manuels pour la nouvelle fonctionnalité","Validation des régressions de correction de bogues"],"de":["Automatisierung von Code-Reviews für Pull-Requests","Erstellung manueller Testfälle für neue Funktionalitäten","Validierung von Fehlerrückständen"],"pt":["Automatizar revisões de código para solicitações de pull","Gerar casos de teste manuais para nova funcionalidade","Validar regressões de correções de bugs"],"ru":["Автоматизировать обзор кода для запросов на включение","Генерировать ручные тестовые случаи для новой функциональности","Проверять регрессии исправлений ошибок"],"ar":["تحسين مراجعة الكود تلقائيا لسحب الطلبات","توليد حالات اختبار يدوية للوظائف الجديدة","التحقق من Регрессии إصلاح العيوب"]},"limitations":{"en":["Requires access to code repository","Limited to reviewing code changes, not entire codebase"],"zh":["需要访问代码仓库","仅限于审查代码更改，而不是整个代码库"],"ja":["コードリポジトリへのアクセスが必要","コードの変更のみをレビューし、コード全体ではない"],"ko":["코드 저장소에 대한 액세스가 필요","코드 변경만을 리뷰하며 전체 코드베이스는 아님"],"es":["Requiere acceso al repositorio de código","Limitado a la revisión de cambios de código, no de toda la base de código"],"fr":["Nécessite un accès au référentiel de code","Limité à la révision des modifications de code, et non de l''ensemble de la base de code"],"de":["Erfordert Zugriff auf das Code-Repository","Begrenzt auf die Überprüfung von Code-Änderungen, nicht auf den gesamten Codebestand"],"pt":["Requer acesso ao repositório de código","Limitado à revisão de alterações de código, não à base de código inteira"],"ru":["Требует доступа к хранилищу кода","Ограничен обзором изменений кода, а не всего кода"],"ar":["يتطلب الوصول إلى مستودع الكود","محدود بالمراجعة التغييرات في الكود، وليس كامل قاعدة الكود"]},"version":4},"contentHash":"1f162cf045b1c210d22d246554552879964daf9521a08103f6dfad436e2516dd","qualityScore":60}');
