INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('storyblok/monoblok/review-and-qa', 'review-and-qa', 'storyblok', 'monoblok', 'community', 'review-and-qa storyblok monoblok community The review-and-qa skill enables developers to review code changes and perform QA reviews. It benefits developers by ensuring high-quality code. Review-and-QA是一种代码审查和测试工具，帮助开发者优化代码质量和功能 Review-and-QAはコードレビューとテストのツールで、開発者のコード品質と機能を最適化する Review-and-QA는 코드 리뷰와 테스트 도구로 개발者の 코드 품질과 기능을 최적화합니다 La revisión y pruebas de QA son fundamentales para garantizar la calidad del código en Storyblok OSS. Nuestra guía te ayudará a configurar un proceso de revisión efectivo. La revue de code et les tests de QA sont essentiels pour assurer la qualité du code dans Storyblok OSS. Notre guide vous aidera à configurer un processus de revue efficace. Code-Review und QA-Tests sind entscheidend für die Sicherstellung der Codequalität in Storyblok OSS. Unsere Anleitung hilft Ihnen bei der Einrichtung eines effektiven Überprüfungsprozesses. O Review e QA de código é uma habilidade que ajuda a garantir a qualidade do código, com análise de mudanças e criação de casos de teste manuais. Проверка и контроль качества кода - это навык, который помогает обеспечить качество кода, с анализом изменений и созданием ручных тестовых случаев. مراجعة وضمان الجودة هي مهارة تساعد على ضمان جودة الكود، مع تحليل التغييرات وإنشاء حالات اختبار يدوية how to use review-and-qa review-and-qa setup guide review-and-qa alternative review-and-qa vs code review tools what is review-and-qa review-and-qa install review-and-qa for developers code review best practices QA review process AIエージェント 代码审查工具 测试工具 代码质量优化 功能测试 Review-and-QA 代码审查最佳实践 测试用例创建 Performs code review to analyze code quality, architecture, and best practices Creates manual test cases to validate behavior during QA review Enforces a PR checklist for all pull requests Requires small diffs and tests for new functionality Supports bug fixes with regression tests Analyzes code changes for logical consistency review-and-qa is a skill that performs two-phase reviews, including code review and QA review, to ensure high-quality code changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('robynsmith/claude-code-skills-demo/handoff', 'community', 'robynsmith', 'claude-code-skills-demo', 'robynsmith/claude-code-skills-demo', 'handoff', 0, 0, 60, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.562Z', '88d69927dc3d55ed9f757da9ec2e5dfa634ccf7781812af05777c6a127897b3c', '{"id":"robynsmith/claude-code-skills-demo/handoff","name":"handoff","description":{"en":"The handoff skill captures the current session context to ensure continuity across sessions and after auto-compaction, benefiting developers working with Claude Code. It provides session continuity and productivity commands.","zh":"Handoff 技术实现 AIエージェント会话连续性和生产力命令，通过捕获当前会话上下文","ja":"Handoff スキルは AIエージェントのセッション連続性と生産性コマンドを実現する、現在のセッションコンテキストをキャプチャする","ko":"Handoff 기능은 AI 에이전트 세션 연속성과 생산성 명령을 제공하며 현재 세션 컨텍스트를 캡처합니다","es":"La función de handoff permite la continuidad de sesión y la productividad en Claude Code, mediante la captura del contexto de la sesión actual","fr":"La fonction de handoff permet la continuité de session et la productivité dans Claude Code, en capturant le contexte de la session en cours","de":"Die Handoff-Funktion ermöglicht die Sitzungsfortsetzung und Produktivität in Claude Code, indem sie den aktuellen Sitzungskontext erfasst","pt":"O handoff é uma habilidade que captura o contexto da sessão atual para garantir a continuidade da sessão. Ele fornece comandos de automação de fluxo de trabalho para melhorar a produtividade","ru":"Handoff - это навык, который захватывает контекст текущей сессии для обеспечения непрерывности сессии. Он предоставляет команды автоматизации рабочего процесса для повышения производительности","ar":"Handoff هو مهارة تقوم بتقاط سياق الجلسة الحالية لضمان استمرارية الجلسة. إنه يوفر أوامر تلقيم الجلسات لتحسين الإنتاجية"},"seo":{"title":{"en":"handoff: Session Continuity Setup Guide | AI Agent Skill","zh":"Handoff 技术设置指南 - AIエージェント会话连续性","ja":"Handoff スキルセットアップガイド - AIエージェントのセッション連続性","ko":"Handoff 기능 설정 가이드 - AI 에이전트 세션 연속성","es":"Guía de Configuración de Handoff para Agentes de IA","fr":"Guide de Configuration de Handoff pour Outils d''IA","de":"Handoff-Setup-Anleitung für KI-Agents","pt":"Guia de Configuração do Handoff: Automação de Fluxo de Tr...","ru":"ИИ Агенты: Настройка Handoff для Продуктивности","ar":"دليل إعداد Handoff: تلقيم الجلسات وتحسين الإنتاجية"},"description":{"en":"Discover how to ensure seamless session continuity with handoff. Learn how to capture session context and automate workflows with our expert guide.","zh":"了解 Handoff 技术的功能和优势，实现 AIエージェント会话连续性和生产力命令","ja":"Handoff スキルの機能と利点を学び、AIエージェントのセッション連続性と生産性コマンドを実現する","ko":"Handoff 기능의 특징과 장점을 알아보고 AI 에이전트 세션 연속성과 생산성 명령을 구현하세요","es":"Aprende a configurar la función de handoff para agentes de IA y mejora la continuidad de sesión y la productividad en Claude Code","fr":"Découvrez comment configurer la fonction de handoff pour les outils d''IA et améliorer la continuité de session et la productivité dans Claude Code","de":"Erfahren Sie, wie Sie die Handoff-Funktion für KI-Agents konfigurieren und die Sitzungsfortsetzung und Produktivität in Claude Code verbessern","pt":"Aprenda a configurar o handoff para garantir a continuidade da sessão e aumentar a produtividade com comandos de automação de fluxo de trabalho","ru":"Узнайте, как настроить handoff для обеспечения непрерывности сессии и повышения производительности с помощью команд автоматизации рабочего процесса","ar":"تعرف على كيفية إعداد Handoff لضمان استمرارية الجلسة وتحسين الإنتاجية باستخدام أوامر تلقيم الجلسات"},"definition":{"en":"handoff is a session continuity skill that captures the current session context to ensure seamless workflow automation and agent orchestration.","zh":"Handoff 技术是实现 AIエージェント会话连续性的方法，通过捕获当前会话上下文","ja":"Handoff スキルは AIエージェントのセッション連続性を実現する方法で、現在のセッションコンテキストをキャプチャする","ko":"Handoff 기능은 AI 에이전트 세션 연속성을 제공하는 방법으로 현재 세션 컨텍스트를 캡처합니다","es":"Handoff es una función que captura el contexto de la sesión actual para garantizar la continuidad después de la compactación automática","fr":"Handoff est une fonction qui capture le contexte de la session en cours pour assurer la continuité après la compactation automatique","de":"Handoff ist eine Funktion, die den aktuellen Sitzungskontext erfasst, um die Fortsetzung nach der automatischen Compactation zu gewährleisten","pt":"O handoff é uma habilidade que captura o contexto da sessão para garantir a continuidade","ru":"Handoff - это навык, который захватывает контекст сессии для обеспечения непрерывности","ar":"Handoff هو مهارة تقوم بتقاط سياق الجلسة لضمان الاستمرارية"},"features":{"en":["Checks for uncommitted changes using `git status`","Creates a comprehensive session handoff document","Offers to commit changes or continue with handoff","Runs `git status` to inform users of uncommitted changes","Provides options to commit changes now or continue with handoff","Ensures session continuity across sessions and after auto-compaction"],"zh":["捕获当前会话上下文","实现会话连续性","支持 Git 状态检查","提供提交更改选项","支持会话自动压缩","增强生产力命令"],"ja":["現在のセッションコンテキストをキャプチャする","セッション連続性を実現する","Git 状態チェックをサポートする","変更をコミットするオプションを提供する","セッション自動圧縮をサポートする","生産性コマンドを強化する"],"ko":["현재 세션 컨텍스트를 캡처한다","세션 연속성을 제공한다","Git 상태检查을 지원한다","변경을 커밋하는 옵션을 제공한다","세션 자동 압축을 지원한다","생산성 명령을 강화한다"],"es":["Captura del contexto de la sesión actual","Verificación de cambios no comprometidos con git status","Opción para comprometer cambios o continuar con el handoff","Compatibilidad con Claude Code","Automatización del flujo de trabajo de IA","Orquestación de agentes"],"fr":["Capture du contexte de la session en cours","Vérification des changements non commités avec git status","Option pour commités les changements ou continuer avec le handoff","Compatibilité avec Claude Code","Automatisation du flux de travail d''IA","Orchestration d''agents"],"de":["Erfassung des aktuellen Sitzungskontexts","Überprüfung von nicht committeten Änderungen mit git status","Option zum Commiten von Änderungen oder Fortsetzen des Handoffs","Kompatibilität mit Claude Code","Automatisierung des IA-Workflows","Orchestrierung von Agents"],"pt":["Captura do contexto da sessão atual","Comandos de automação de fluxo de trabalho","Verificação de alterações não commitadas com git status","Opção de commitar alterações antes do handoff","Continuidade da sessão após auto-compaction"],"ru":["Захват контекста текущей сессии","Команды автоматизации рабочего процесса","Проверка незафиксированных изменений с помощью git status","Возможность зафиксировать изменения перед handoff","Непрерывность сессии после авто-сжатия"],"ar":["تقاط سياق الجلسة الحالية","أوامر تلقيم الجلسات","فحص التغييرات غير الملتزمة مع git status","خيار الالتزام بالتغييرات قبل الحدوف","استمرارية الجلسة بعد الضغط التلقائي"]},"keywords":{"en":["how to use handoff","what is handoff","handoff alternative","handoff vs claude code","handoff install","handoff setup guide","session continuity with handoff","automating workflows with handoff","claude code handoff skill"],"zh":["Handoff 技术","AIエージェント会话连续性","生产力命令","Git 状态检查","会话自动压缩","AI 工具","会话管理","生产力优化"],"ja":["Handoff スキル","AIエージェントのセッション連続性","生産性コマンド","Git 状態チェック","セッション自動圧縮","AI エージェント","セッション管理","生産性最適化"],"ko":["Handoff 기능","AI 에이전트 세션 연속성","생산성 명령","Git 상태检查","세션 자동 압축","AI 툴","세션 관리","생산성 최적화"],"es":["handoff","agentes de IA","continuidad de sesión","productividad","Claude Code","automatización de flujo de trabajo","orquestación de agentes","git status","configuración de handoff"],"fr":["handoff","outils d''IA","continuité de session","productivité","Claude Code","automatisation du flux de travail","orchestration d''agents","git status","configuration de handoff"],"de":["handoff","KI-Agents","Sitzungsfortsetzung","Produktivität","Claude Code","Automatisierung des IA-Workflows","Orchestrierung von Agents","git status","Handoff-Konfiguration"],"pt":["handoff","automação de fluxo de trabalho","produtividade","git status","commitar alterações","continuidade da sessão"," Claude Code","AI Agents","Ferramentas de desenvolvimento"],"ru":["handoff","автоматизация рабочего процесса","производительность","git status","зафиксировать изменения","непрерывность сессии","Claude Code","ИИ Агенты","Инструменты разработки"],"ar":["handoff","تلقيم الجلسات","إنتاجية","git status","الالتزام بالتغييرات","استمرارية الجلسة","Claude Code","وكلاء الذكاء الاصطناعي","أدوات التطوير"]}},"owner":"robynsmith","repo":"claude-code-skills-demo","repoPath":"robynsmith/claude-code-skills-demo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.349Z","topics":[],"category":"community","skillMd":{"name":"handoff","description":"Capture session context before ending or compaction","bodyPreview":"# Session Handoff Skill\n\nCaptures the current session context to ensure continuity across sessions and after auto-compaction.\n\n## Instructions\n\nWhen this skill is invoked, create a comprehensive session handoff document:\n\n1. **Check for uncommitted changes**:\n   - Run `git status` to check for uncommitted changes\n   - If there are uncommitted changes, inform the user and ask if they want to:\n     - Commit the changes now (offer to help create the commit)\n     - Continue with handoff anyway (chan","body":"# Session Handoff Skill\n\nCaptures the current session context to ensure continuity across sessions and after auto-compaction.\n\n## Instructions\n\nWhen this skill is invoked, create a comprehensive session handoff document:\n\n1. **Check for uncommitted changes**:\n   - Run `git status` to check for uncommitted changes\n   - If there are uncommitted changes, inform the user and ask if they want to:\n     - Commit the changes now (offer to help create the commit)\n     - Continue with handoff anyway (changes will be documented but not committed)\n     - Cancel the handoff to commit manually first\n   - If working tree is clean, proceed to step 2\n\n2. **Determine the date and time**:\n   - Use today''s date in YYYY-MM-DD format\n   - Use bash command `date ''+%I:%M %p''` to get the current time (e.g., \"09:33 AM\")\n   - Use bash command `date ''+%A''` to get the day of week if helpful for context\n\n3. **Create the handoff file**:\n   - Location: `contexts/_LifeOS/handoff/session-handoff-YYYY-MM-DD.md`\n   - If a file for today already exists, read it first and append with a new timestamp section\n   - Format session header as: `## Session N (Day Period - HH:MM AM/PM)` where Day Period is descriptive (e.g., \"Morning\", \"Afternoon\", \"Evening\", \"Early Morning\")\n\n4. **Capture the following sections**:\n\n   ### Session Summary\n   - Brief overview of what was accomplished in this session\n   - Main topics discussed or worked on\n   - Time range if relevant\n\n   ### Key Decisions Made\n   - Important choices and why they were made\n   - Architectural decisions\n   - Approach selections\n   - What was chosen and what was rejected\n\n   ### Code Changes\n   - List files modified with specific line numbers when relevant (use format `file.ts:123`)\n   - Brief description of what changed and why\n   - Any patterns or conventions established\n   - New files created\n\n   ### Open Questions & Blockers\n   - Unresolved questions\n   - Things that need investigation\n   - Blockers preventing progress\n   - Edge cases to consider\n\n   ### Next Steps\n   - Concrete action items as a checklist using `- [ ]` format\n   - Priorities for next session\n   - Follow-up tasks\n\n   ### Context for Next Session\n   - Important background that would be lost in compaction\n   - Links to relevant files or resources\n   - Any special considerations\n   - Current working directory or focus area\n\n5. **Format guidelines**:\n   - Use clear markdown headings\n   - Be specific with file references (include line numbers)\n   - Keep it concise but complete\n   - Use bullet points and checklists\n   - Include timestamps for multiple sessions in one day\n\n6. **Commit and push the handoff**:\n   - Add the handoff file to git staging\n   - Commit with message format: \"Add Session N handoff: [brief summary]\"\n   - Push to remote to ensure context is backed up\n   - Confirm to the user what was committed and pushed\n   - Show a brief summary of what was documented\n\n## Example Output Format\n\n```markdown\n# Session Handoff - 2026-01-11\n\n## Session 1 (Morning - 9:00 AM)\n\n### Session Summary\n\nResearched Claude Code session management strategies and created comprehensive documentation. Set up handoff infrastructure for future session continuity.\n\n### Key Decisions Made\n\n- **Storage location**: Decided to store session context in `contexts/_LifeOS/handoff/` following existing PARA structure\n- **Skill creation**: Chose to create a reusable `/handoff` skill rather than manual process\n- **Naming convention**: Will use `session-handoff-YYYY-MM-DD.md` format\n\n### Code Changes\n\n- Created `contexts/tech/3_resources/ai-learnings/Claude Code Session Management.md`\n  - Comprehensive guide to session management\n  - Community resources and best practices\n  - References to GitHub repos and tools\n\n- Created `contexts/_LifeOS/handoff/README.md`\n  - Explains purpose of handoff folder\n  - Documents naming conventions\n  - Links to related resources\n\n- Updated `CLAUDE.md:32` and `CLAUDE.md:56`\n  - Added handoff folder documentation\n  - Mentioned `/handoff` skill usage\n\n- Updated `contexts/tech/3_resources/ai-learnings/README.md:17-18`\n  - Added new session management topic\n\n- Created `.claude/skills/handoff/SKILL.md`\n  - Custom skill for session handoff automation\n  - Follows PARA methodology\n\n### Open Questions & Blockers\n\nNone currently\n\n### Next Steps\n\n- [ ] Test the `/handoff` skill in practice\n- [ ] Consider creating additional skills for common workflows (journal entry, learning log, etc.)\n- [ ] Explore community skill repositories for other useful tools\n- [ ] Review wshobson/commands and claude-code-showcase repos\n\n### Context for Next Session\n\nThis session focused on meta-work: improving the Claude Code workflow itself. The repository is a personal knowledge management system using PARA methodology, primarily for Obsidian notes. The handoff system is now in place to preserve context across sessions and auto-compaction events.\n```\n\n## Implementation Notes\n\n- This skill follows the PARA methodology for personal knowledge management\n- Session handoff files are stored in `_LifeOS/handoff/` as they''re related to daily workflow\n- The skill can be invoked simply by typing `/handoff` in Claude Code\n- Multiple sessions in one day append to the same file with new timestamp sections\n- The handoff is automatically committed and pushed to remote for backup\n- The handoff file serves as input for the next session to recover full context\n- Pushing ensures context is preserved even if local machine fails or user switches machines\n"},"lastSynced":"2026-03-08T02:03:44.562Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents like Claude Code needing session continuity and productivity commands across multiple sessions.","zh":"适合需要会话连续性和多会话生产力命令的开发者代理，如 Claude Code。","ja":"Claude Code のようなセッションの連続性と複数のセッションにわたる生産性コマンドが必要な開発者エージェントに最適です。","ko":"클라우드 코드와 같은 세션 연속성 및 여러 세션에 걸친 생산성 명령이 필요한 개발자 에이전트에 적합합니다.","es":"Ideal para Agentes de Desarrollador como Claude Code que necesitan continuidad de sesión y comandos de productividad a través de varias sesiones.","fr":"Idéal pour les agents de développement comme Claude Code nécessitant une continuité de session et des commandes de productivité à travers plusieurs sessions.","de":"Ideal für Entwickleragenten wie Claude Code, die eine Sitzungskontinuität und Produktivitätsbefehle über mehrere Sitzungen benötigen.","pt":"Ideal para Agentes de Desenvolvedor como Claude Code que necessitam de continuidade de sessão e comandos de produtividade em várias sessões.","ru":"Идеально подходит для агентов-разработчиков, таких как Claude Code, которым необходима непрерывность сеанса и команды производительности на нескольких сеансах.","ar":"مثالي للوكلاء المطورين مثل Claude Code الذين يحتاجون إلى استمرار الجلسة وأوامر الإنتاجية عبر عدة جلسات."},"recommendation":{"en":"Empowers agents to capture and preserve the current session context, ensuring seamless continuity after auto-compaction, and provides Git-based version control through commands like `git status` to manage uncommitted changes.","zh":"赋予代理捕获和保留当前会话上下文的能力，确保在自动压缩后实现无缝连续性，并通过像 `git status` 这样的命令提供基于 Git 的版本控制以管理未提交的更改。","ja":"エージェントに現在のセッションコンテキストをキャプチャして保存する能力を与え、自動圧縮後の無断連続性を保証し、`git status` のようなコマンドを使用して未コミットの変更を管理するための Git ベースのバージョン管理を提供します。","ko":"에이전트가 현재 세션 컨텍스트를 캡처하고 저장할 수 있는 기능을 제공하여 자동圧縮 이후의 무중단 연속성을 보장하며, `git status`와 같은 명령을 통해 커밋되지 않은 변경 사항을 관리하기 위한 Git 기반 버전 관리를 제공합니다.","es":"Habilita a los agentes a capturar y preservar el contexto de la sesión actual, asegurando una continuidad fluida después de la compactación automática, y proporciona un control de versiones basado en Git a través de comandos como `git status` para gestionar cambios no confirmados.","fr":"Permet aux agents de capturer et de préserver le contexte de session actuel, assurant une continuité fluide après la compaction automatique, et fournit un contrôle de version basé sur Git via des commandes comme `git status` pour gérer les modifications non validées.","de":"Ermöglicht es Agenten, den aktuellen Sitzungskontext zu erfassen und zu bewahren, eine nahtlose Kontinuität nach der automatischen Kompaktabilität sicherzustellen und bietet eine Git-basierte Versionskontrolle durch Befehle wie `git status`, um nicht committete Änderungen zu verwalten.","pt":"Habilita os agentes a capturar e preservar o contexto da sessão atual, garantindo uma continuidade sem interrupções após a compactação automática, e fornece controle de versão baseado em Git por meio de comandos como `git status` para gerenciar alterações não commitadas.","ru":"Позволяет агентам捕урить и сохранить текущий контекст сеанса, обеспечивая бесшовную непрерывность после автоматической компактации, и предоставляет контроль версий на основе Git через команды như `git status` для управления незафиксированными изменениями.","ar":"تمكين الوكلاء من التقاط الحفاظ على سياق الجلسة الحالية، وضمان الاستمرارية بدون انقطاع بعد التركيب التلقائي، وتوفر التحكم في الإصدارات المستندة إلى Git من خلال أوامر مثل `git status` لإدارة التغييرات غير الملتزمة."},"useCases":{"en":["Automating session handoffs to maintain developer productivity","Generating comprehensive session handoff documents","Debugging uncommitted changes using Git status checks"],"zh":["自动执行会话交接以维持开发者生产力","生成全面会话交接文档","使用 Git 状态检查调试未提交的更改"],"ja":["開発者の生産性を維持するためにセッションのハンドオーバーを自動化する","包括的なセッションハンドオーバードキュメントを生成する","Git の状態チェックを使用してコミットされていない変更をデバッグする"],"ko":["개발자 생산성을 유지하기 위해 세션 핸드오버를 자동화하는 것","전체 세션 핸드오버 문서를 생성하는 것","Git 상태 확인을 사용하여 커밋되지 않은 변경 사항을 디버깅하는 것"],"es":["Automatizar la transferencia de sesiones para mantener la productividad del desarrollador","Generar documentos de transferencia de sesión completos","Depurar cambios no confirmados mediante controles de estado de Git"],"fr":["Automatiser les transferts de sessions pour maintenir la productivité du développeur","Générer des documents de transfert de session complets","Déboguer les modifications non validées à l''aide de vérifications d''état Git"],"de":["Automatisieren von Sitzungsübergaben, um die Produktivität des Entwicklers aufrechtzuerhalten","Erstellen von umfassenden Sitzungsübergabedokumenten","Fehlerbehebung von nicht committeten Änderungen mithilfe von Git-Statusprüfungen"],"pt":["Automatizar a transferência de sessões para manter a produtividade do desenvolvedor","Gerar documentos abrangentes de transferência de sessão","Depurar alterações não commitadas usando verificações de status do Git"],"ru":["Автоматизировать передачу сеансов для поддержания производительности разработчика","Генерировать полные документы передачи сеанса","Отлаживать незафиксированные изменения с помощью проверок статуса Git"],"ar":["توفير جلسات تلقائي للحفاظ على إنتاجية المطور","توليد مستندات شاملة لنقل الجلسة","تصحيح الأخطاء في التغييرات غير الملتزمة باستخدام فحوصات حالة Git"]},"limitations":{"en":["Requires Git installation for version control","Limited to developer environments with auto-compaction"],"zh":["需要 Git 安装以实现版本控制","仅限于具有自动压缩的开发环境"],"ja":["バージョン管理のために Git のインストールが必要","自動圧縮を備えた開発環境のみに限定される"],"ko":["버전 관리를 위해 Git 설치가 필요함","자동 압축을 갖춘 개발 환경에만 제한됨"],"es":["Requiere la instalación de Git para el control de versiones","Limitado a entornos de desarrollo con compactación automática"],"fr":["Nécessite l''installation de Git pour le contrôle de version","Limité aux environnements de développement avec compaction automatique"],"de":["Benötigt eine Git-Installation für die Versionskontrolle","Eingeschränkt auf Entwicklerumgebungen mit automatischer Kompaktabilität"],"pt":["Requer instalação do Git para controle de versão","Limitado a ambientes de desenvolvedor com compactação automática"],"ru":["Требуется установка Git для контроля версий","Ограничен разработчиками сред с автоматической компактацией"],"ar":["يتطلب تركيب Git للتحكم في الإصدارات","محدود بالبيئات التطويرية التي لديها تركيب tự động"]},"version":4},"contentHash":"88d69927dc3d55ed9f757da9ec2e5dfa634ccf7781812af05777c6a127897b3c","qualityScore":60}');
