INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('robynsmith/claude-code-skills-demo/handoff', 'handoff', 'robynsmith', 'claude-code-skills-demo', 'community', 'handoff robynsmith claude-code-skills-demo community The handoff skill captures the current session context to ensure continuity across sessions and after auto-compaction, benefiting developers working with Claude Code. It provides session continuity and productivity commands. Handoff 技术实现 AIエージェント会话连续性和生产力命令，通过捕获当前会话上下文 Handoff スキルは AIエージェントのセッション連続性と生産性コマンドを実現する、現在のセッションコンテキストをキャプチャする Handoff 기능은 AI 에이전트 세션 연속성과 생산성 명령을 제공하며 현재 세션 컨텍스트를 캡처합니다 La función de handoff permite la continuidad de sesión y la productividad en Claude Code, mediante la captura del contexto de la sesión actual La fonction de handoff permet la continuité de session et la productivité dans Claude Code, en capturant le contexte de la session en cours Die Handoff-Funktion ermöglicht die Sitzungsfortsetzung und Produktivität in Claude Code, indem sie den aktuellen Sitzungskontext erfasst O handoff é uma habilidade que captura o contexto da sessão atual para garantir a continuidade da sessão. Ele fornece comandos de automação de fluxo de trabalho para melhorar a produtividade Handoff - это навык, который захватывает контекст текущей сессии для обеспечения непрерывности сессии. Он предоставляет команды автоматизации рабочего процесса для повышения производительности Handoff هو مهارة تقوم بتقاط سياق الجلسة الحالية لضمان استمرارية الجلسة. إنه يوفر أوامر تلقيم الجلسات لتحسين الإنتاجية how to use handoff what is handoff handoff alternative handoff vs claude code handoff install handoff setup guide session continuity with handoff automating workflows with handoff claude code handoff skill Handoff 技术 AIエージェント会话连续性 生产力命令 Git 状态检查 会话自动压缩 AI 工具 会话管理 生产力优化 Checks for uncommitted changes using `git status` Creates a comprehensive session handoff document Offers to commit changes or continue with handoff Runs `git status` to inform users of uncommitted changes Provides options to commit changes now or continue with handoff Ensures session continuity across sessions and after auto-compaction handoff is a session continuity skill that captures the current session context to ensure seamless workflow automation and agent orchestration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('specvital/specvital.github.io/adr-write', 'community', 'specvital', 'specvital.github.io', 'specvital/specvital.github.io', 'adr-write', 0, 0, 60, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.825Z', '2b49e1f6e1ac1e9a21ff7ea6d2daa32f7d67c98683ffe41a3b2869dbb30862b4', '{"id":"specvital/specvital.github.io/adr-write","name":"adr-write","description":{"en":"The adr-write skill generates complete ADR documents by researching GitHub commits/PRs and applying the ADR template, benefiting developers and project maintainers.","zh":"adr-write是一种基于GitHub Pages的ADR文档生成工具，能够根据 adr-candidates.md 自动生成ADR文档","ja":"adr-writeはGitHub Pagesに基づくADR文書生成ツールで、adr-candidates.mdからADR文書を自動生成できます","ko":"adr-write는 GitHub Pages 기반의 ADR 문서 생성 도구로 adr-candidates.md에서 ADR 문서를 자동 생성할 수 있습니다","es":"adr-write es una herramienta para generar documentos ADR basados en candidatos descubiertos en GitHub. Permite la colaboración multiagente para crear documentación de alta calidad.","fr":"adr-write est un outil pour générer des documents ADR basés sur des candidats découverts sur GitHub. Il permet la collaboration multi-agent pour créer une documentation de haute qualité.","de":"adr-write ist ein Tool zum Erstellen von ADR-Dokumenten basierend auf auf GitHub entdeckten Kandidaten. Es ermöglicht die Multi-Agenten-Kollaboration zur Erstellung hochwertiger Dokumentationen.","pt":"O adr-write é uma ferramenta que gera documentos ADR completos com base em commits e PRs do GitHub, utilizando um modelo de colaboração multi-agente.","ru":"adr-write - это инструмент, который создает полные документы ADR на основе коммитов и PR GitHub, используя многоагентный пайплайн сотрудничества.","ar":"adr-write هي أداة لتوليد مستندات ADR كاملة بالاعتماد على التعليقات والطلبات السحابية على جيثب، وتستخدم أنابيب تعاون متعدد الوكلاء."},"seo":{"title":{"en":"adr-write: Automated ADR Document Generation | AI Agent S...","zh":"adr-write Setup Guide: 基于GitHub Pages的ADR文档生成","ja":"adr-write セットアップガイド: GitHub Pagesに基づくADR文書の生成","ko":"adr-write 설정 가이드: GitHub Pages 기반의 ADR 문서 생성","es":"Guía de configuración de adr-write para documentación de ADR","fr":"Configurer adr-write pour la documentation ADR","de":"Einrichtungsleitfaden für adr-write zur ADR-Dokumentation","pt":"adr-write: Guia de Configuração de Documentos ADR","ru":"adr-write: Настройка шаблонов документов ADR","ar":"adr-write: دليل إعداد مستندات ADR"},"description":{"en":"Discover how to automate ADR document creation with adr-write. Learn how to research GitHub commits/PRs and apply ADR templates with this AI agent skill.","zh":"了解adr-write的功能和特点，包括GitHub Pages托管和ADR文档生成","ja":"adr-writeの機能と特徴を学びます。GitHub PagesホスティングとADR文書生成を含みます","ko":"adr-write의 기능과 특징을 알아보세요. GitHub Pages 호스팅과 ADR 문서 생성을 포함합니다","es":"Descubre cómo configurar adr-write para generar documentos ADR completos a partir de candidatos descubiertos en GitHub","fr":"Découvrez comment configurer adr-write pour générer des documents ADR complets à partir de candidats découverts sur GitHub","de":"Erfahren Sie, wie Sie adr-write einrichten, um vollständige ADR-Dokumente aus entdeckten Kandidaten auf GitHub zu erstellen","pt":"Aprenda a configurar o adr-write para gerar documentos ADR completos com base em commits e PRs do GitHub","ru":"Узнайте, как настроить adr-write для создания полных документов ADR на основе коммитов и PR GitHub","ar":"تعرف على كيفية إعداد adr-write لإنشاء مستندات ADR كاملة بالاعتماد على التعليقات والطلبات السحابية على جيثب"},"definition":{"en":"adr-write is a GitHub Pages-hosted AI agent skill that automates the creation of ADR documents based on discovered candidates from adr-candidates.md.","zh":"adr-write是一种AI工具，用于生成ADR文档","ja":"adr-writeはAIエージェントで、ADR文書を生成するために使用されます","ko":"adr-write는 AI 도구로 ADR 문서를 생성하는 데 사용됩니다","es":"adr-write es una herramienta de AI para generar documentos de Arquitectura de Decisiones Registradas (ADR)","fr":"adr-write est un outil d''IA pour générer des documents d''Architecture de Décisions Enregistrées (ADR)","de":"adr-write ist ein AI-Tool zum Erstellen von Dokumenten für die Architektur registrierter Entscheidungen (ADR)","pt":"adr-write é uma ferramenta de código aberto que gera documentos ADR","ru":"adr-write - это открытое программное обеспечение для создания документов ADR","ar":"adr-write هي أداة مفتوحة المصدر لإنشاء مستندات ADR"},"features":{"en":["Generates complete ADR documents by researching GitHub commits/PRs","Applies ADR template to create standardized documents","Utilizes user input from $ARGUMENTS to inform document creation","Supports multi-agent collaboration pipeline for streamlined workflows","Hosted on GitHub Pages for easy access and documentation"],"zh":["基于GitHub Pages的ADR文档生成","支持adr-candidates.md文件","自动生成ADR文档","多Agent协作管道","GitHub Commits/PRs研究"],"ja":["GitHub Pagesに基づくADR文書生成","adr-candidates.mdファイルのサポート","ADR文書の自動生成","マルチエージェントコラボレーションパイプライン","GitHub Commits/PRsの調査"],"ko":["GitHub Pages 기반의 ADR 문서 생성","adr-candidates.md 파일 지원","ADR 문서 자동 생성","多エージェント 협업 파이프라인","GitHub Commits/PRs 조사"],"es":["Generación de documentos ADR completos","Colaboración multiagente para documentación de alta calidad","Integración con GitHub para descubrir candidatos","Aplicación de plantillas de ADR para documentación consistente","Procesamiento de commits y solicitudes de extracción de GitHub"],"fr":["Génération de documents ADR complets","Collaboration multi-agent pour une documentation de haute qualité","Intégration avec GitHub pour découvrir des candidats","Application de modèles de ADR pour une documentation cohérente","Traitement des commits et des demandes d''extraction de GitHub"],"de":["Erstellung vollständiger ADR-Dokumente","Multi-Agenten-Kollaboration für hochwertige Dokumentationen","Integration mit GitHub zum Entdecken von Kandidaten","Anwendung von ADR-Vorlagen für konsistente Dokumentationen","Verarbeitung von GitHub-Commits und Pull-Requests"],"pt":["Geração de documentos ADR completos","Pesquisa de commits e PRs do GitHub","Utilização de modelo de colaboração multi-agente","Integração com GitHub Pages","Suporte a entrada de usuário personalizada"],"ru":["Создание полных документов ADR","Поиск коммитов и PR GitHub","Использование многоагентного пайплайна сотрудничества","Интеграция с GitHub Pages","Поддержка индивидуальной настройки пользовательского ввода"],"ar":["إنشاء مستندات ADR كاملة","البحث عن التعليقات والطلبات السحابية على جيثب","استخدام أنابيب تعاون متعدد الوكلاء","التكامل مع صفحات جيثب","دعم الإدخال المخصص للمستخدم"]},"keywords":{"en":["how to use adr-write","adr-write setup guide","what is adr-write","adr-write alternative","adr-write vs manual documentation","adr-write install","automated ADR document generation","GitHub Pages integration","ADR template application"],"zh":["adr-write","ADR文档生成","GitHub Pages","adr-candidates.md","AI工具","自动化文档生成","多Agent协作"],"ja":["adr-write","ADR文書生成","GitHub Pages","adr-candidates.md","AIエージェント","自動化文書生成","マルチエージェントコラボレーション"],"ko":["adr-write","ADR 문서 생성","GitHub Pages","adr-candidates.md","AI 도구","자동화 문서 생성","多エージェント 협업"],"es":["adr-write","herramientas de AI para documentación","generación de documentos ADR","colaboración multiagente","integración con GitHub","plantillas de ADR","commits de GitHub","solicitudes de extracción de GitHub"],"fr":["adr-write","outils d''IA pour la documentation","génération de documents ADR","collaboration multi-agent","intégration avec GitHub","modèles de ADR","commits de GitHub","demandes d''extraction de GitHub"],"de":["adr-write","AI-Tools für Dokumentationen","Erstellung von ADR-Dokumenten","Multi-Agenten-Kollaboration","Integration mit GitHub","ADR-Vorlagen","GitHub-Commits","GitHub-Pull-Requests"],"pt":["adr-write","documentos ADR","GitHub","collaboration pipeline","ferramenta de código aberto","geração de documentos","pesquisa de commits","integração com GitHub Pages"],"ru":["adr-write","документы ADR","GitHub","многоагентный пайплайн","открытое программное обеспечение","создание документов","поиск коммитов","интеграция с GitHub Pages","ИИ Агенты"],"ar":["adr-write","مستندات ADR","جيثب","أنابيب تعاون متعدد الوكلاء","أداة مفتوحة المصدر","إنشاء مستندات","البحث عن التعليقات","التكامل مع صفحات جيثب","أدوات الذكاء الاصطناعي"]}},"owner":"specvital","repo":"specvital.github.io","repoPath":"specvital/specvital.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.349Z","topics":[],"category":"community","skillMd":{"name":"adr-write","description":"Write ADR document from discovered candidates with GitHub context research","bodyPreview":"# ADR Write Command\n\nWrite ADR documents based on discovered candidates from `adr-candidates.md`.\n\n## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding.\n\n---\n\n## Overview\n\nGenerate complete ADR documents by researching GitHub commits/PRs and applying the ADR template.\n\n**Multi-Agent Collaboration Pipeline**:\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│                    ADR Writing Pipeline                          │\n├──────","body":"# ADR Write Command\n\nWrite ADR documents based on discovered candidates from `adr-candidates.md`.\n\n## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding.\n\n---\n\n## Overview\n\nGenerate complete ADR documents by researching GitHub commits/PRs and applying the ADR template.\n\n**Multi-Agent Collaboration Pipeline**:\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│                    ADR Writing Pipeline                          │\n├─────────────────────────────────────────────────────────────────┤\n│  Phase 1: specvital-specialist                                   │\n│    → Search related commits/PRs via GitHub API                   │\n│    → Extract decision context and rationale                      │\n│    → Identify options that were considered                       │\n├─────────────────────────────────────────────────────────────────┤\n│  Phase 2: product-strategist                                     │\n│    → Analyze decision trade-offs                                 │\n│    → Evaluate consequences (positive/negative)                   │\n│    → Structure options comparison                                │\n├─────────────────────────────────────────────────────────────────┤\n│  Phase 3: Write ADR Documents                                    │\n│    → Generate English version (docs/en/adr/)                     │\n│    → Generate Korean version (docs/ko/adr/)                      │\n│    → Update all required index files                             │\n│    → Update sidebar configuration                                │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Input Interpretation\n\n### Numeric Reference\n\nReference candidates by number from `adr-candidates.md`:\n\n```bash\n/adr-write 1          # Platform Level candidate #1\n/adr-write core/1     # Core repository candidate #1\n/adr-write worker/1   # Worker repository candidate #1\n```\n\n### Natural Language\n\nDescribe what ADR to write:\n\n```bash\n/adr-write billing and quota system\n/adr-write write the AI spec document generation ADR\n/adr-write domain hints extraction for core repository\n```\n\n### Parsing Logic\n\n1. **Numeric only** (e.g., `1`, `2`): Match Platform Level candidate by number\n2. **Prefixed numeric** (e.g., `core/1`, `web/2`): Match repository-level candidate\n3. **Natural language**: Search candidate titles and descriptions for best match\n\n---\n\n## Execution Flow\n\n### Phase 0: Load Candidate Information\n\nRead `adr-candidates.md` and identify the target ADR:\n\n```\n1. Parse user input to identify candidate\n2. Extract from adr-candidates.md:\n   - Title\n   - Target location (e.g., /en/adr/13-xxx.md)\n   - Related repositories\n   - Complexity and priority\n3. Determine ADR number and file paths\n```\n\n**File Path Determination**:\n\n| Candidate Type | English Path                         | Korean Path                          |\n| -------------- | ------------------------------------ | ------------------------------------ |\n| Platform Level | `docs/en/adr/{num}-{slug}.md`        | `docs/ko/adr/{num}-{slug}.md`        |\n| Core           | `docs/en/adr/core/{num}-{slug}.md`   | `docs/ko/adr/core/{num}-{slug}.md`   |\n| Worker         | `docs/en/adr/worker/{num}-{slug}.md` | `docs/ko/adr/worker/{num}-{slug}.md` |\n| Web            | `docs/en/adr/web/{num}-{slug}.md`    | `docs/ko/adr/web/{num}-{slug}.md`    |\n\n---\n\n### Phase 1: Context Research (specvital-specialist)\n\n**Task tool invocation**:\n\n```\nTask(subagent_type=\"specvital-specialist\", prompt=\"\"\"\nResearch GitHub context for ADR: {candidate_title}\n\n**Target Repositories**: {related_repos}\n\n**Research Tasks**:\n\n1. **Search Related Commits**\n   - Use gh CLI or GitHub MCP to search commits\n   - Keywords: {extracted_keywords}\n   - Timeframe: Last 90 days\n   - Command: `gh search commits \"{keyword}\" --repo specvital/{repo} --limit 20`\n\n2. **Search Related PRs**\n   - Find PRs that introduced or modified this feature\n   - Command: `gh pr list --repo specvital/{repo} --search \"{keyword}\" --state all --limit 10`\n\n3. **Extract Decision Context**\n   For each relevant commit/PR:\n   - What problem was being solved?\n   - What approach was taken?\n   - Any alternatives mentioned in discussions?\n\n4. **Output Format**\n```\n\n## Relevant Commits\n\n- {commit_sha}: {message} - {date}\n\n## Relevant PRs\n\n- #{pr_number}: {title} - {state}\n\n## Context Summary\n\n- Problem: ...\n- Decision: ...\n- Alternatives mentioned: ...\n\n```\n\"\"\")\n```\n\n---\n\n### Phase 2: Decision Analysis (product-strategist)\n\n**Task tool invocation**:\n\n```\nTask(subagent_type=\"product-strategist\", prompt=\"\"\"\nAnalyze the architectural decision for ADR: {candidate_title}\n\n**Input**: Context from Phase 1\n\n**Analysis Tasks**:\n\n1. **Structure the Context**\n   - What was the problem/need?\n   - Why was a decision required?\n   - What constraints existed?\n\n2. **Identify Options**\n   Based on commits/PRs and common patterns:\n   - Option A (selected): What was chosen and why\n   - Option B: What alternatives existed\n   - Option C: Any other approaches considered\n\n3. **Evaluate Consequences**\n   For the selected option:\n   - Positive outcomes (benefits, improvements)\n   - Negative outcomes (trade-offs, limitations)\n   - Technical implications\n\n4. **Output Format**\n   Structured content ready for ADR template sections:\n   - Context section content\n   - Decision section content\n   - Options Considered section content\n   - Consequences section content\n\"\"\")\n```\n\n---\n\n### Phase 3: Write ADR Documents\n\nGenerate both English and Korean versions following the template.\n\n**ADR Template Structure**:\n\n```markdown\n---\ntitle: { Title }\ndescription: ADR for {brief description}\n---\n\n# ADR-{num}: {Title}\n\n> [Korean Version](/ko/adr/{path}) OR 🇰🇷 [한국어 버전](/ko/adr/{path})\n\n| Date       | Author    | Repos            |\n| ---------- | --------- | ---------------- |\n| YYYY-MM-DD | @{author} | {repo1}, {repo2} |\n\n## Context\n\n{Problem situation and why a decision was needed}\n\n## Decision\n\n{The decision made and its rationale}\n\n## Options Considered\n\n### Option A: {Name} (Selected)\n\n{Description, pros, cons}\n\n### Option B: {Name}\n\n{Description, pros, cons}\n\n## Consequences\n\n**Positive:**\n\n- {Benefit 1}\n- {Benefit 2}\n\n**Negative:**\n\n- {Trade-off 1}\n- {Trade-off 2}\n\n## References\n\n- [Related ADR](/en/adr/XX-related.md)\n- [Related PR](https://github.com/specvital/{repo}/pull/{num})\n```\n\n---\n\n## Post-Write Updates (CRITICAL)\n\nAfter writing ADR documents, you **MUST** update all required files per CLAUDE.md rules.\n\n### For Platform Level ADR (e.g., `adr/13-xxx.md`)\n\nUpdate **6 files**:\n\n```\n☐ docs/en/index.md           ← Homepage ADR links section\n☐ docs/ko/index.md           ← Homepage ADR links section\n☐ docs/en/adr/index.md       ← ADR overview\n☐ docs/ko/adr/index.md       ← ADR overview\n☐ docs/.vitepress/config.mts ← Sidebar navigation\n```\n\n### For Repository Level ADR (e.g., `adr/core/16-xxx.md`)\n\nUpdate **6 files**:\n\n```\n☐ docs/en/index.md                 ← Homepage ADR links section\n☐ docs/ko/index.md                 ← Homepage ADR links section\n☐ docs/en/adr/index.md             ← ADR overview (repository section)\n☐ docs/ko/adr/index.md             ← ADR overview (repository section)\n☐ docs/en/adr/{category}/index.md  ← Category index\n☐ docs/ko/adr/{category}/index.md  ← Category index\n☐ docs/.vitepress/config.mts       ← Sidebar navigation\n```\n\n---\n\n## Language Rules\n\n### English Version (`/en/`)\n\n- Write entirely in English\n- Use technical terminology appropriately\n- Clear, concise prose\n\n### Korean Version (`/ko/`)\n\n- Write entirely in Korean\n- **MUST use noun-ending style** (명사형 종결)\n- **NEVER use verb-ending style** (동사 종결어미 금지)\n\n**Korean Style Examples**:\n\n| ✅ Correct                   | ❌ Incorrect                         |\n| ---------------------------- | ------------------------------------ |\n| 데이터 무결성 검증           | 데이터 무결성을 검증합니다           |\n| API 호출 최소화              | API 호출이 최소화됩니다              |\n| 정적 분석 기반 테스트 카운트 | 정적 분석을 통해 테스트를 카운트한다 |\n\n---\n\n## Key Rules\n\n### Must Do\n\n- Load candidate info from `adr-candidates.md`\n- Research actual GitHub commits/PRs for context\n- Follow ADR template structure exactly\n- Generate both English and Korean versions\n- Update ALL required index files (check CLAUDE.md for complete list)\n- Update sidebar in `config.mts`\n- Use noun-ending style for Korean\n\n### Must Not Do\n\n- Skip GitHub research (must base on actual commits)\n- Write only one language version\n- Forget to update index files\n- Use verb endings in Korean documents\n- Guess content without evidence from commits/PRs\n\n---\n\n## Output Summary\n\nAfter completion, report:\n\n```\n## ADR Written\n\n| Item | Value |\n|------|-------|\n| Title | {ADR Title} |\n| Number | ADR-{num} |\n| English | docs/en/adr/{path} |\n| Korean | docs/ko/adr/{path} |\n\n## Files Updated\n\n- [x] docs/en/adr/{path} (created)\n- [x] docs/ko/adr/{path} (created)\n- [x] docs/en/index.md\n- [x] docs/ko/index.md\n- [x] docs/en/adr/index.md\n- [x] docs/ko/adr/index.md\n- [x] docs/.vitepress/config.mts\n\n## Source References\n\n- {commit_sha}: {message}\n- PR #{num}: {title}\n```\n\n---\n\n## Usage Examples\n\n```bash\n# Write Platform Level candidate #1 (Billing and Quota)\n/adr-write 1\n\n# Write Core repository candidate #1\n/adr-write core/1\n\n# Natural language - matches \"AI-Based Spec Document Generation Pipeline\"\n/adr-write AI spec generation\n\n# Natural language with context\n/adr-write write the billing ADR, focus on quota tracking aspects\n```\n\n---\n\n## Related Commands\n\n- `/adr-discover`: Discover ADR candidates\n- `/document-business-rule`: Business rule documentation\n- `/commit`: Commit message generation\n\n## Related Agents\n\n- `specvital-specialist`: GitHub context research\n- `product-strategist`: Decision analysis and trade-offs\n- `prompt-engineer`: Document quality optimization\n- `claude-code-specialist`: Command and workflow optimization\n\n---\n\n## Execution\n\nNow execute the workflow:\n\n1. **Parse $ARGUMENTS**: Identify target candidate from `adr-candidates.md`\n2. **Phase 1**: Invoke Task(specvital-specialist) for GitHub research\n3. **Phase 2**: Invoke Task(product-strategist) for decision analysis\n4. **Phase 3**: Write ADR documents (English + Korean)\n5. **Update Index Files**: Per CLAUDE.md requirements\n6. **Report**: Summary of created/updated files\n"},"lastSynced":"2026-03-08T02:03:44.825Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated ADR document generation from GitHub commits and PRs.","zh":"适合需要自动从 GitHub 提交和 PR 生成 ADR 文档的开发代理。","ja":"GitHub のコミットと PR から自動的に ADR ドキュメントを生成する必要がある開発エージェントに適しています。","ko":"GitHub 커밋 및 PR에서 자동으로 ADR 문서를 생성해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan generación automática de documentos ADR a partir de confirmaciones y solicitudes de extracción de GitHub.","fr":"Parfait pour les Agents de Développement ayant besoin d''une génération automatisée de documents ADR à partir de validations et de demandes de tirage GitHub.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Erstellung von ADR-Dokumenten aus GitHub-Commits und -Pull-Requests benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de geração automática de documentos ADR a partir de commits e PRs do GitHub.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированная генерация документов ADR из коммитов и PR GitHub.","ar":"مثالي لعمليات تطوير الوكلاء التي تحتاج إلى توليد مستندات ADR آليا من التعليقات والطلبات السحابية على GitHub."},"recommendation":{"en":"Empowers agents to generate complete ADR documents by researching GitHub commits/PRs and applying the ADR template, leveraging Markdown files like `adr-candidates.md` and supporting multi-agent collaboration pipelines.","zh":"赋予代理生成完整的 ADR 文档的能力，通过研究 GitHub 提交/PR 并应用 ADR 模板，利用 Markdown 文件，如 `adr-candidates.md` ，并支持多代理协作流水线。","ja":"エージェントが GitHub のコミット/PR を調査し、ADR テンプレートを適用して、完全な ADR ドキュメントを生成できるようにします。また、`adr-candidates.md` のような Markdown ファイルを利用し、多エージェントのコラボレーション パイプラインをサポートします。","ko":"에이전트가 GitHub 커밋/PR를 조사하고 ADR 템플릿을 적용하여 완전한 ADR 문서를 생성할 수 있도록 합니다. 또한 `adr-candidates.md`와 같은 Markdown 파일을 사용하고 다중 에이전트 협업 파이프라인을 지원합니다.","es":"Habilita a los agentes a generar documentos ADR completos investigando confirmaciones y solicitudes de extracción de GitHub y aplicando la plantilla ADR, aprovechando archivos Markdown como `adr-candidates.md` y admitiendo tuberías de colaboración multiagente.","fr":"Permet aux agents de générer des documents ADR complets en recherchant les validations et les demandes de tirage GitHub, et en appliquant le modèle ADR, en exploitant les fichiers Markdown tels que `adr-candidates.md` et en prenant en charge les pipelines de collaboration multiagent.","de":"Ermächtigt die Agenten, vollständige ADR-Dokumente zu erstellen, indem sie GitHub-Commits und -Pull-Requests recherchieren und die ADR-Vorlage anwenden, indem sie Markdown-Dateien wie `adr-candidates.md` nutzen und Multiagenten-Kollaborationspipelines unterstützen.","pt":"Habilita os agentes a gerar documentos ADR completos pesquisando commits/PRs do GitHub e aplicando o modelo de ADR, utilizando arquivos Markdown como `adr-candidates.md` e suportando pipelines de colaboração multiagente.","ru":"Наделяет агентов возможностью генерировать полные документы ADR, исследуя коммиты/PR GitHub и применяя шаблон ADR, используя файлы Markdown, такие как `adr-candidates.md`, и поддерживая đaагентные pipelines сотрудничества.","ar":"تمكن الوكلاء من إنتاج مستندات ADR كاملة من خلال البحث في التعليقات والطلبات السحابية على GitHub وتطبيق قالب ADR ، واستخدام ملفات Markdown مثل `adr-candidates.md` ودعم أنابيب تعاون متعددة الوكلاء."},"useCases":{"en":["Automating ADR document creation from GitHub data","Generating ADR documents based on discovered candidates","Researching and applying ADR templates for project maintainers"],"zh":["从 GitHub 数据自动创建 ADR 文档","根据发现的候选项生成 ADR 文档","研究和应用 ADR 模板用于项目维护者"],"ja":["GitHub データから ADR ドキュメントを自動生成する","発見された候補に基づいて ADR ドキュメントを生成する","プロジェクトメンテナ向けに ADR テンプレートを研究し適用する"],"ko":["GitHub 데이터에서 ADR 문서를 자동 생성하는 것","발견된 후보에 따라 ADR 문서를 생성하는 것","프로젝트 유지 관리자를 위한 ADR 템플릿을 연구하고 적용하는 것"],"es":["Automatización de la creación de documentos ADR a partir de datos de GitHub","Generación de documentos ADR en función de candidatos descubiertos","Investigación y aplicación de plantillas ADR para responsables de proyectos"],"fr":["Automatisation de la création de documents ADR à partir de données GitHub","Génération de documents ADR en fonction de candidats découverts","Recherche et application de modèles ADR pour les responsables de projet"],"de":["Automatisierung der Erstellung von ADR-Dokumenten aus GitHub-Daten","Generierung von ADR-Dokumenten basierend auf entdeckten Kandidaten","Recherche und Anwendung von ADR-Vorlagen für Projektverantwortliche"],"pt":["Automatizar a criação de documentos ADR a partir de dados do GitHub","Gerar documentos ADR com base em candidatos descobertos","Pesquisar e aplicar modelos de ADR para mantenedores de projetos"],"ru":["Автоматизировать создание документов ADR из данных GitHub","Генерировать документы ADR на основе обнаруженных кандидатов","Изучать и применять шаблоны ADR для поддержки проектов"],"ar":["أتمتة إنشاء مستندات ADR من بيانات GitHub","توليد مستندات ADR بناء على مرشحين مكتشفين","البحث وتطبيق قوالب ADR لمحافظي المشاريع"]},"limitations":{"en":["Requires access to GitHub commits and PRs","Needs `adr-candidates.md` file for candidate discovery"],"zh":["需要访问 GitHub 提交和 PR","需要 `adr-candidates.md` 文件进行候选项发现"],"ja":["GitHub のコミットと PR にアクセスする必要がある","`adr-candidates.md` ファイルが候補の発見に必要である"],"ko":["GitHub 커밋 및 PR에 액세스해야 함","`adr-candidates.md` 파일이 후보 항목 발견에 필요함"],"es":["Requiere acceso a confirmaciones y solicitudes de extracción de GitHub","Necesita el archivo `adr-candidates.md` para la detección de candidatos"],"fr":["Nécessite un accès aux validations et aux demandes de tirage GitHub","Nécessite le fichier `adr-candidates.md` pour la détection des candidats"],"de":["Benötigt Zugriff auf GitHub-Commits und -Pull-Requests","Benötigt die Datei `adr-candidates.md` für die Kandidatenerkennung"],"pt":["Requer acesso a commits e PRs do GitHub","Necessita do arquivo `adr-candidates.md` para descoberta de candidatos"],"ru":["Требует доступа к коммитам и PR GitHub","Требует файла `adr-candidates.md` для обнаружения кандидатов"],"ar":["يتطلب الوصول إلى التعليقات والطلبات السحابية على GitHub","يحتاج إلى ملف `adr-candidates.md` لاكتشاف المرشحين"]},"version":4},"contentHash":"2b49e1f6e1ac1e9a21ff7ea6d2daa32f7d67c98683ffe41a3b2869dbb30862b4","qualityScore":60}');
