INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('specvital/specvital.github.io/adr-write', 'adr-write', 'specvital', 'specvital.github.io', 'community', 'adr-write specvital specvital.github.io community The adr-write skill generates complete ADR documents by researching GitHub commits/PRs and applying the ADR template, benefiting developers and project maintainers. adr-write是一种基于GitHub Pages的ADR文档生成工具，能够根据 adr-candidates.md 自动生成ADR文档 adr-writeはGitHub Pagesに基づくADR文書生成ツールで、adr-candidates.mdからADR文書を自動生成できます adr-write는 GitHub Pages 기반의 ADR 문서 생성 도구로 adr-candidates.md에서 ADR 문서를 자동 생성할 수 있습니다 adr-write es una herramienta para generar documentos ADR basados en candidatos descubiertos en GitHub. Permite la colaboración multiagente para crear documentación de alta calidad. adr-write est un outil pour générer des documents ADR basés sur des candidats découverts sur GitHub. Il permet la collaboration multi-agent pour créer une documentation de haute qualité. adr-write ist ein Tool zum Erstellen von ADR-Dokumenten basierend auf auf GitHub entdeckten Kandidaten. Es ermöglicht die Multi-Agenten-Kollaboration zur Erstellung hochwertiger Dokumentationen. O adr-write é uma ferramenta que gera documentos ADR completos com base em commits e PRs do GitHub, utilizando um modelo de colaboração multi-agente. adr-write - это инструмент, который создает полные документы ADR на основе коммитов и PR GitHub, используя многоагентный пайплайн сотрудничества. adr-write هي أداة لتوليد مستندات ADR كاملة بالاعتماد على التعليقات والطلبات السحابية على جيثب، وتستخدم أنابيب تعاون متعدد الوكلاء. how to use adr-write adr-write setup guide what is adr-write adr-write alternative adr-write vs manual documentation adr-write install automated ADR document generation GitHub Pages integration ADR template application adr-write ADR文档生成 GitHub Pages adr-candidates.md AI工具 自动化文档生成 多Agent协作 Generates complete ADR documents by researching GitHub commits/PRs Applies ADR template to create standardized documents Utilizes user input from $ARGUMENTS to inform document creation Supports multi-agent collaboration pipeline for streamlined workflows Hosted on GitHub Pages for easy access and documentation adr-write is a GitHub Pages-hosted AI agent skill that automates the creation of ADR documents based on discovered candidates from adr-candidates.md.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Sunalamye/Naki/mcp-tool-writer', 'community', 'Sunalamye', 'Naki', 'Sunalamye/Naki', 'mcp-tool-writer', 0, 0, 60, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:47.144Z', '46b058b90c2beae57dfc5e3c7445e89404e67a3aa52eed3b2f1a5ea781209f55', '{"id":"Sunalamye/Naki/mcp-tool-writer","name":"mcp-tool-writer","description":{"en":"The mcp-tool-writer skill helps developers create and modify MCP tools for the Naki project using Swift and Core ML. It benefits developers working on AI-powered projects.","zh":"mcp-tool-writer 是一个使用 Swift 和 Core ML 实现的 MCP 工具创建和修改的技能，支持 Protocol-based 架构","ja":"mcp-tool-writer は、Swift と Core ML を使用して MCP ツールを作成および変更するスキルです。Protocol-based アーキテクチャをサポートしています","ko":"mcp-tool-writer는 Swift와 Core ML을 사용하여 MCP 도구를 생성하고 수정하는 스킬로, Protocol-based 아키텍처를 지원합니다","es":"mcp-tool-writer es una herramienta para crear y modificar herramientas MCP con arquitectura basada en protocolos","fr":"mcp-tool-writer est un outil pour créer et modifier des outils MCP avec une architecture basée sur les protocoles","de":"mcp-tool-writer ist ein Tool zum Erstellen und Modifizieren von MCP-Tools mit einer protokollbasierten Architektur","pt":"O mcp-tool-writer é uma ferramenta para criar e modificar ferramentas MCP com arquitetura baseada em protocolos e Swift. Aprenda a configurá-la para o seu projeto.","ru":"Mcp-tool-writer - это инструмент для создания и изменения инструментов MCP с помощью архитектуры, основанной на протоколах, и ИИ Агентов. Узнайте, как настроить его для своего проекта.","ar":"mcp-tool-writer هي أداة لإنشاء وتعديل أدوات MCP باستخدام هندسة بروتوكول قائم على Swift. اكتشف كيفية إعدادها لمشروعك."},"seo":{"title":{"en":"mcp-tool-writer: Setup Guide for AI Agents | AI Agent Skill","zh":"mcp-tool-writer 设计指南：Swift 和 Core ML 实现","ja":"mcp-tool-writer セットアップガイド：Swift と Core ML を使用した AI エージェント","ko":"mcp-tool-writer 설정 가이드: Swift와 Core ML을 사용한 AI 도구","es":"Guía de configuración de mcp-tool-writer para desarrollad...","fr":"Guide de mise en place de mcp-tool-writer pour les dévelo...","de":"Einrichtungsleitfaden für mcp-tool-writer-Entwickler","pt":"Guia de Configuração do mcp-tool-writer para Desenvolvedores","ru":"Настройка mcp-tool-writer: Руководство для Разработчиков ...","ar":"دليل إعداد mcp-tool-writer للطورين - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to leverage mcp-tool-writer for Naki project development. Learn to create and modify MCP tools with Protocol-based architecture and Core ML.","zh":"了解 mcp-tool-writer 的技术细节和功能，实现 Swift 和 Core ML 的 MCP 工具创建和修改","ja":"mcp-tool-writer の技術的詳細と機能を学び、Swift と Core ML を使用した MCP ツールの作成と変更を実現します","ko":"mcp-tool-writer의 기술적 세부 사항과 기능을 학습하고, Swift와 Core ML을 사용한 MCP 도구 생성 및 수정을 구현합니다","es":"Aprenda a utilizar mcp-tool-writer con Swift y Core ML para crear herramientas MCP personalizadas","fr":"Découvrez comment utiliser mcp-tool-writer avec Swift et Core ML pour créer des outils MCP personnalisés","de":"Erfahren Sie, wie Sie mcp-tool-writer mit Swift und Core ML verwenden, um benutzerdefinierte MCP-Tools zu erstellen","pt":"Aprenda a configurar o mcp-tool-writer para criar e modificar ferramentas MCP com arquitetura baseada em protocolos e Swift","ru":"Узнайте, как настроить mcp-tool-writer для создания и изменения инструментов MCP с помощью архитектуры, основанной на протоколах, и ИИ Агентов","ar":"اكتشف كيفية إعداد mcp-tool-writer لإنشاء وتعديل أدوات MCP باستخدام هندسة بروتوكول قائم على Swift"},"definition":{"en":"mcp-tool-writer is a skill that enables the creation and modification of Model Context Protocol tools for the Naki project using a Protocol-based architecture.","zh":"mcp-tool-writer 是一个用于创建和修改 MCP 工具的技能，使用 Swift 和 Core ML 实现","ja":"mcp-tool-writer は、MCP ツールを作成および変更するためのスキルです。Swift と Core ML を使用して実現しています","ko":"mcp-tool-writer는 MCP 도구를 생성하고 수정하기 위한 스킬로, Swift와 Core ML을 사용하여 구현합니다","es":"mcp-tool-writer es una herramienta de código abierto que utiliza Swift y Core ML para crear herramientas MCP personalizadas","fr":"mcp-tool-writer est un outil open source qui utilise Swift et Core ML pour créer des outils MCP personnalisés","de":"mcp-tool-writer ist ein Open-Source-Tool, das Swift und Core ML verwendet, um benutzerdefinierte MCP-Tools zu erstellen","pt":"O mcp-tool-writer é uma ferramenta de código aberto para criar e modificar ferramentas MCP","ru":"Mcp-tool-writer - это открытый инструмент для создания и изменения инструментов MCP","ar":"mcp-tool-writer هي أداة مفتوحة المصدر لإنشاء وتعديل أدوات MCP"},"features":{"en":["Utilizes Protocol-based architecture for MCP tool development","Supports Swift and Core ML for AI-powered projects","Creates and modifies MCP tools using MCPTool.swift and MCPContext.swift","Leverages MCPToolRegistry.swift for tool registration","Follows MCP 调用规则 for testing and development"],"zh":["支持 Protocol-based 架构","使用 Swift 和 Core ML 实现","MCP 工具创建和修改","支持 async/await","MCPTool.swift 和 MCPContext.swift 文件支持"],"ja":["Protocol-based アーキテクチャをサポート","Swift と Core ML を使用して実現","MCP ツールの作成と変更","async/await をサポート","MCPTool.swift と MCPContext.swift ファイルをサポート"],"ko":["Protocol-based 아키텍처 지원","Swift와 Core ML을 사용하여 구현","MCP 도구 생성 및 수정","async/await 지원","MCPTool.swift와 MCPContext.swift 파일 지원"],"es":["Arquitectura basada en protocolos","Soporte para Swift y Core ML","Creación y modificación de herramientas MCP","Registro de herramientas MCP","Ejecución de contextos asíncronos"],"fr":["Architecture basée sur les protocoles","Prise en charge de Swift et Core ML","Création et modification d''outils MCP","Enregistrement d''outils MCP","Exécution de contextes asynchrones"],"de":["Protokollbasierte Architektur","Unterstützung für Swift und Core ML","Erstellung und Modifizierung von MCP-Tools","Registrierung von MCP-Tools","Ausführung von asynchronen Kontexten"],"pt":["Criação e modificação de ferramentas MCP com arquitetura baseada em protocolos","Implementação em Swift","Suporte a async/await","Registro de ferramentas MCP com MCPToolRegistry","Definição de protocolos com MCPTool.swift","Suporte a execução de contextos com MCPContext.swift"],"ru":["Создание и изменение инструментов MCP с помощью архитектуры, основанной на протоколах","Реализация на Swift","Поддержка async/await","Регистрация инструментов MCP с помощью MCPToolRegistry","Определение протоколов с помощью MCPTool.swift","Поддержка выполнения контекстов с помощью MCPContext.swift"],"ar":["إنشاء وتعديل أدوات MCP باستخدام هندسة بروتوكول قائم على Swift","تنفيذ بلغة Swift","دعم async/await","تسجيل أدوات MCP مع MCPToolRegistry","تعريف البروتوكولات مع MCPTool.swift","دعم تنفيذ السياقات مع MCPContext.swift"]},"keywords":{"en":["how to use mcp-tool-writer","mcp-tool-writer setup guide","mcp-tool-writer alternative","mcp-tool-writer vs Core ML","what is mcp-tool-writer","mcp-tool-writer install for Naki project"],"zh":["mcp-tool-writer","Swift","Core ML","MCP 工具","Protocol-based 架构","AI 工具","Swift开发","Core ML开发"],"ja":["mcp-tool-writer","Swift","Core ML","MCP ツール","Protocol-based アーキテクチャ","AI エージェント","Swift開発","Core ML開発"],"ko":["mcp-tool-writer","Swift","Core ML","MCP 도구","Protocol-based 아키텍처","AI 도구","Swift 개발","Core ML 개발"],"es":["mcp-tool-writer","herramientas MCP","Swift","Core ML","arquitectura basada en protocolos","desarrollo de herramientas MCP","registro de herramientas MCP","ejecución de contextos asíncronos","Agentes de inteligencia artificial"],"fr":["mcp-tool-writer","outils MCP","Swift","Core ML","architecture basée sur les protocoles","développement d''outils MCP","enregistrement d''outils MCP","exécution de contextes asynchrones","Agents d''intelligence artificielle"],"de":["mcp-tool-writer","MCP-Tools","Swift","Core ML","protokollbasierte Architektur","Entwicklung von MCP-Tools","Registrierung von MCP-Tools","Ausführung von asynchronen Kontexten","Künstliche Intelligenz-Agenten"],"pt":["mcp-tool-writer","ferramentas MCP","arquitetura baseada em protocolos","Swift","async/await","MCPToolRegistry","MCPTool.swift","MCPContext.swift","desenvolvimento de software"],"ru":["mcp-tool-writer","инструменты MCP","архитектура, основанная на протоколах","Swift","async/await","MCPToolRegistry","MCPTool.swift","MCPContext.swift","разработка программного обеспечения","ИИ Агенты"],"ar":["mcp-tool-writer","أدوات MCP","هندسة بروتوكول قائم على Swift","Swift","async/await","MCPToolRegistry","MCPTool.swift","MCPContext.swift","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"Sunalamye","repo":"Naki","repoPath":"Sunalamye/Naki","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"mcp-tool-writer","description":"Create, modify, and manage MCP tools for the Naki mahjong AI assistant. Use when adding new MCP tools, modifying existing tools, or fixing tool-related issues. This skill understands the Protocol-based MCPTool architecture.","bodyPreview":"# Naki MCP Tool Writer\n\nBase directory: {baseDir}\n\n<IMPORTANT>\n**MCP 調用規則**: 測試新建的 MCP 工具時，使用 `/naki-mcp-proxy` skill 調用。\n</IMPORTANT>\n\nThis skill helps create and modify MCP (Model Context Protocol) tools for the Naki project using the Protocol-based architecture.\n\n## Architecture Overview\n\nNaki uses a Protocol-based MCP architecture:\n\n```\ncommand/Services/MCP/\n├── MCPTool.swift          - Protocol 定義 + Schema 類型\n├── MCPContext.swift       - 執行上下文 (async/await 支持)\n├── MCPToolRegistry.swift  - 工","body":"# Naki MCP Tool Writer\n\nBase directory: {baseDir}\n\n<IMPORTANT>\n**MCP 調用規則**: 測試新建的 MCP 工具時，使用 `/naki-mcp-proxy` skill 調用。\n</IMPORTANT>\n\nThis skill helps create and modify MCP (Model Context Protocol) tools for the Naki project using the Protocol-based architecture.\n\n## Architecture Overview\n\nNaki uses a Protocol-based MCP architecture:\n\n```\ncommand/Services/MCP/\n├── MCPTool.swift          - Protocol 定義 + Schema 類型\n├── MCPContext.swift       - 執行上下文 (async/await 支持)\n├── MCPToolRegistry.swift  - 工具註冊表 (單例)\n├── MCPHandler.swift       - MCP 協議處理器\n└── Tools/\n    ├── SystemTools.swift  - 系統類工具 (get_status, get_help, get_logs, clear_logs)\n    ├── BotTools.swift     - Bot 控制工具 (bot_status, bot_trigger, bot_ops, bot_deep, bot_chi, bot_pon, bot_sync)\n    ├── GameTools.swift    - 遊戲狀態工具 (game_state, game_hand, game_ops, game_discard, game_action)\n    └── UITools.swift      - UI 操作工具 (execute_js, detect, explore, test_indicators, click, calibrate, ui_names_*)\n```\n\n## Current Registered Tools (47 total)\n\n| Category | Count | Examples |\n|----------|-------|----------|\n| System | 4 | `get_status`, `get_help`, `get_logs`, `clear_logs` |\n| Bot | 7 | `bot_status`, `bot_trigger`, `bot_ops`, `bot_deep`, `bot_chi`, `bot_pon`, `bot_sync` |\n| Game | 6 | `game_state`, `game_hand`, `game_ops`, `game_discard`, `game_action`, `game_emoji` |\n| Highlight | 6 | `highlight_tile`, `highlight_status`, `show_recommendations`, `hide_highlight` |\n| Emoji | 4 | `game_emoji`, `game_emoji_list`, `game_emoji_random` |\n| Lobby | 9 | `lobby_status`, `lobby_navigate`, `lobby_start_match`, `lobby_cancel_match` |\n| UI | 11 | `execute_js`, `detect`, `explore`, `click`, `calibrate`, `ui_names_*` |\n\nSee `/naki-mcp-proxy` for complete tool catalog.\n\n## How to Create a New MCP Tool\n\n### Step 1: Define the Tool Struct\n\nCreate a new struct implementing `MCPTool` protocol in the appropriate `Tools/*.swift` file:\n\n```swift\nstruct MyNewTool: MCPTool {\n    // 1. 工具名稱 (唯一標識符)\n    static let name = \"my_new_tool\"\n\n    // 2. 工具描述 (給 AI 看的說明)\n    static let description = \"描述這個工具做什麼，何時使用\"\n\n    // 3. 輸入參數 Schema\n    static let inputSchema = MCPInputSchema(\n        properties: [\n            \"param1\": .string(\"參數1的描述\"),\n            \"param2\": .integer(\"參數2的描述\")\n        ],\n        required: [\"param1\"]  // 必填參數\n    )\n\n    // 4. 上下文 (用於訪問 JS、Bot 等)\n    private let context: MCPContext\n\n    init(context: MCPContext) {\n        self.context = context\n    }\n\n    // 5. 執行邏輯\n    func execute(arguments: [String: Any]) async throws -> Any {\n        guard let param1 = arguments[\"param1\"] as? String else {\n            throw MCPToolError.missingParameter(\"param1\")\n        }\n\n        // 執行邏輯...\n\n        return [\"success\": true, \"result\": \"...\"]\n    }\n}\n```\n\n### Step 2: Register the Tool\n\n在 `MCPToolRegistry.swift:142-182` 的 `registerBuiltInTools()` 方法中添加：\n\n```swift\nregister(MyNewTool.self)\n```\n\n**注意**: Tools 列表會自動從 Registry 生成，無需手動維護 JSON 檔案。\n\n## Input Schema Types\n\n```swift\n// 無參數\nstatic let inputSchema = MCPInputSchema.empty\n\n// 有參數\nstatic let inputSchema = MCPInputSchema(\n    properties: [\n        \"stringParam\": .string(\"字串參數描述\"),\n        \"intParam\": .integer(\"整數參數描述\"),\n        \"numberParam\": .number(\"數字參數描述\"),\n        \"boolParam\": .boolean(\"布林參數描述\"),\n        \"objectParam\": .object(\"物件參數描述\")\n    ],\n    required: [\"stringParam\"]  // 必填參數列表\n)\n```\n\n## Context API\n\n工具可以通過 `context` 訪問以下功能（定義在 `MCPContext.swift:15-38`）：\n\n```swift\n// 執行 JavaScript（async/await）\nlet result = try await context.executeJavaScript(\"return document.title\")\n\n// 獲取 Bot 狀態\nlet status = context.getBotStatus()\n\n// 觸發自動打牌\ncontext.triggerAutoPlay()\n\n// 日誌操作\nlet logs = context.getLogs()\ncontext.clearLogs()\ncontext.log(\"記錄訊息\")\n\n// 服務器埠號\nlet port = context.serverPort\n```\n\n## ⚠️ JavaScript 執行注意事項\n\n**重要**：`context.executeJavaScript()` 必須使用 `return` 語句才能正確返回值！\n\n```swift\n// ✅ 正確：使用 return 語句\nlet title = try await context.executeJavaScript(\"return document.title\")\nlet sum = try await context.executeJavaScript(\"return 1 + 1\")\nlet json = try await context.executeJavaScript(\"return JSON.stringify({a:1})\")\n\n// ❌ 錯誤：沒有 return，結果為 nil\nlet title = try await context.executeJavaScript(\"document.title\")  // 返回 nil！\n```\n\n**常見模式**：\n\n```swift\n// 調用遊戲 API 並返回 JSON\nlet script = \"return JSON.stringify(window.__nakiGameAPI.getGameState())\"\nlet result = try await context.executeJavaScript(script)\n\n// 執行操作並返回布林值\nlet script = \"return window.__nakiGameAPI.discardTile(0)\"\nlet success = try await context.executeJavaScript(script) as? Bool ?? false\n\n// 檢查 API 是否存在\nlet script = \"return typeof window.__nakiGameAPI !== ''undefined''\"\nlet exists = try await context.executeJavaScript(script) as? Bool ?? false\n```\n\n## Error Handling\n\n使用 `MCPToolError`（定義在 `MCPTool.swift:129-147`）處理錯誤：\n\n```swift\nthrow MCPToolError.missingParameter(\"paramName\")\nthrow MCPToolError.invalidParameter(\"paramName\", expected: \"string\")\nthrow MCPToolError.executionFailed(\"原因描述\")\nthrow MCPToolError.notAvailable(\"資源名稱\")\n```\n\n## Tool Categories & File Locations\n\n| Category | File | When to Add Here |\n|----------|------|-----------------|\n| 系統 | `SystemTools.swift` | Server status, logs, help |\n| Bot | `BotTools.swift` | Bot control, AI inference |\n| 遊戲 | `GameTools.swift` | Game state, hand, actions |\n| UI | `UITools.swift` | JS execution, clicks, detection |\n\n## Checklist for New Tools\n\n- [ ] 定義唯一的 `name`（snake_case 格式）\n- [ ] 寫清楚的 `description`（給 AI 理解，包含何時使用）\n- [ ] 定義正確的 `inputSchema`\n- [ ] 實現 `execute()` 方法（async throws）\n- [ ] 處理所有錯誤情況（使用 MCPToolError）\n- [ ] 在 `MCPToolRegistry.swift:142-182` 中註冊\n- [ ] 構建測試通過\n- [ ] 使用 MCP 工具測試功能\n\n## Testing\n\n構建並測試：\n\n```bash\n# 構建\nxcodebuild build -project Naki.xcodeproj -scheme Naki\n\n# 啟動應用後，使用 MCP 工具測試\nmcp__naki__<tool_name>\n```\n\n## Reference Documentation\n\nFor detailed specifications and more examples, see:\n- [Protocol Reference](references/reference.md) - Complete MCPTool protocol, context API, schema types, and code examples\n"},"lastSynced":"2026-03-08T02:03:47.144Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents working with Swift and Core ML, needing to create and modify MCP tools for the Naki project.","zh":"适用于使用 Swift 和 Core ML 的 AI Agent，需要为 Naki 项目创建和修改 MCP 工具。","ja":"Swift と Core ML を使用する AI エージェントに適しています。Naki プロジェクト用の MCP ツールを作成および変更する必要があります。","ko":"Swift와 Core ML을 사용하는 AI 에이전트에게 적합합니다. Naki 프로젝트를 위한 MCP 도구를 생성하고 수정해야 합니다.","es":"Ideal para agentes de IA que trabajan con Swift y Core ML, que necesitan crear y modificar herramientas MCP para el proyecto Naki.","fr":"Idéal pour les agents IA qui travaillent avec Swift et Core ML, ayant besoin de créer et de modifier des outils MCP pour le projet Naki.","de":"Ideal für KI-Agents, die mit Swift und Core ML arbeiten und MCP-Tools für das Naki-Projekt erstellen und ändern müssen.","pt":"Ideal para Agentes de IA que trabalham com Swift e Core ML, precisando criar e modificar ferramentas MCP para o projeto Naki.","ru":"Идеально для агентов ИИ, работающих со Swift и Core ML, которым необходимо создавать и изменять инструменты MCP для проекта Naki.","ar":"مثالية لعمليات الوكيل الذكي التي تعمل مع Swift و Core ML، تحتاج إلى إنشاء وتعديل أدوات MCP لمشروع Naki."},"recommendation":{"en":"Empowers agents to develop and modify MCP tools using Protocol-based architecture, leveraging Swift and Core ML for AI-powered projects, and utilizing the MCPTool.swift, MCPContext.swift, and MCPToolRegistry.swift components.","zh":"赋予代理开发和修改 MCP 工具的能力，使用基于协议的架构，利用 Swift 和 Core ML 进行 AI 驱动的项目，并使用 MCPTool.swift、MCPContext.swift 和 MCPToolRegistry.swift 组件。","ja":"エージェントに、Protocol ベースのアーキテクチャを使用して MCP ツールを開発および変更する能力を付与し、Swift と Core ML を使用して AI ドリブンのプロジェクトを実現し、MCPTool.swift、MCPContext.swift、MCPToolRegistry.swift コンポーネントを利用します。","ko":"에이전트에게 MCP 도구를 개발하고 수정할 수 있는 능력을 부여하여, 프로토콜 기반 아키텍처를 사용하고, Swift와 Core ML을 사용하여 AI 주도 프로젝트를 구현하며, MCPTool.swift, MCPContext.swift, MCPToolRegistry.swift 컴포넌트를 활용합니다.","es":"Habilita a los agentes a desarrollar y modificar herramientas MCP utilizando arquitectura basada en Protocol, aprovechando Swift y Core ML para proyectos con IA, y utilizando los componentes MCPTool.swift, MCPContext.swift y MCPToolRegistry.swift.","fr":"Permet aux agents de développer et de modifier des outils MCP en utilisant une architecture basée sur Protocol, en exploitant Swift et Core ML pour des projets alimentés par l''IA, et en utilisant les composants MCPTool.swift, MCPContext.swift et MCPToolRegistry.swift.","de":"Ermächtigt die Agents, MCP-Tools zu entwickeln und zu ändern, indem sie eine protokollbasierte Architektur nutzen, Swift und Core ML für KI-gesteuerte Projekte ausnutzen und die Komponenten MCPTool.swift, MCPContext.swift und MCPToolRegistry.swift verwenden.","pt":"Habilita os agentes a desenvolver e modificar ferramentas MCP usando arquitetura baseada em Protocolo, aproveitando Swift e Core ML para projetos impulsionados por IA, e utilizando os componentes MCPTool.swift, MCPContext.swift e MCPToolRegistry.swift.","ru":"Наделяет агентов возможностью разработки и изменения инструментов MCP с использованием архитектуры, основанной на протоколах, используя Swift и Core ML для проектов, основанных на ИИ, и использует компоненты MCPTool.swift, MCPContext.swift и MCPToolRegistry.swift.","ar":"تمكن الوكيل من تطوير وتعديل أدوات MCP باستخدام هندسة قائم على البروتوكول، واستخدام Swift و Core ML لمشاريع مدفوعة بالذكاء الاصطناعي، واستخدام مكونات MCPTool.swift و MCPContext.swift و MCPToolRegistry.swift."},"useCases":{"en":["Creating custom MCP tools for Naki projects","Modifying existing MCP tools using Swift and Core ML","Developing AI-powered applications with MCP tools"],"zh":["为 Naki 项目创建自定义的 MCP 工具","使用 Swift 和 Core ML 修改现有的 MCP 工具","使用 MCP 工具开发 AI 驱动的应用程序"],"ja":["Naki プロジェクト用のカスタム MCP ツールを作成する","Swift と Core ML を使用して既存の MCP ツールを変更する","MCP ツールを使用して AI ドリブンのアプリケーションを開発する"],"ko":["Naki 프로젝트를 위한 사용자 지정 MCP 도구를 생성한다","Swift와 Core ML을 사용하여 기존 MCP 도구를 수정한다","MCP 도구를 사용하여 AI 주도 애플리케이션을 개발한다"],"es":["Crear herramientas MCP personalizadas para proyectos Naki","Modificar herramientas MCP existentes utilizando Swift y Core ML","Desarrollar aplicaciones con IA con herramientas MCP"],"fr":["Créer des outils MCP personnalisés pour les projets Naki","Modifier des outils MCP existants en utilisant Swift et Core ML","Développer des appli